+        pointerTrigger = trigger;
+        event.preventDefault();
+      });
+
+      trigger.addEventListener('click', () => {
+        if (pointerTrigger !== trigger && !isOpen(menu)) {
+          enterOnOpen.add(menu);
+        }
+        pointerTrigger = null;
+      });
+
+      // Preview on focus for both top-level menubar triggers and submenu triggers
+      trigger.addEventListener('focus', event => {
+        if (windowBlurred) return;
+        if (suppressPreview.has(trigger)) {
+          suppressPreview.delete(trigger);
+          return;
+        }
+        if (event.relatedTarget && menu.contains(event.relatedTarget)) return;
+        if (!isOpen(menu)) {
+          menu.showPopover({ source: trigger });
+        }
+      });
+
+      // Hide a previewed menu on blur unless focus moved into it
+      trigger.addEventListener('blur', event => {
+        clearTimeout(hoverPreviewTimer);
+        if (!isOpen(menu)) return;
+        if (event.relatedTarget && (menu.contains(event.relatedTarget) || event.relatedTarget === trigger)) {
+          return;
+        }
+        menu.hidePopover();
+      });
