+        const label = item.textContent.trim();
+
+        const closeRootAndRestore = () => {
+          if (!rootMenu || !rootTrigger) return;
+          suppressPreview.add(rootTrigger);
+          rootTrigger.focus({ focusVisible: !fromPointer, preventScroll: true });
