+  <script>
+    const breadcrumbList = document.getElementById('breadcrumb-list');
+    const cards = document.querySelectorAll('.card');
+
+    function renderBreadcrumbs(activeItem) {
+      const trail = [
+        { label: 'Home', href: '/' },
+        { label: 'Menu', href: '/menu' },
+        { label: 'Seasonal Favorites', href: '/menu/seasonal' }
+      ];
+      if (activeItem) {
+        trail.push(activeItem);
+      }
+
+      breadcrumbList.replaceChildren(
+        ...trail.map((step, index) => {
+          const li = document.createElement('li');
+          const a = document.createElement('a');
+          a.href = step.href;
+          a.textContent = step.label;
+          if (index === trail.length - 1) {
+            a.setAttribute('aria-current', 'page');
+          } else if (activeItem) {
+            a.addEventListener('click', (event) => {
+              event.preventDefault();
+              cards.forEach((card) => { card.hidden = false; });
+              renderBreadcrumbs(null);
+            });
+          }
+          li.appendChild(a);
+          return li;
+        })
+      );
+    }
+
+    document.querySelectorAll('.card .btn[data-item-title]').forEach((btn) => {
+      btn.addEventListener('click', (event) => {
+        event.preventDefault();
+        const selectedCard = btn.closest('.card');
+        cards.forEach((card) => {
+          card.hidden = card !== selectedCard;
+        });
+        renderBreadcrumbs({
+          label: btn.dataset.itemTitle,
+          href: btn.dataset.itemHref
+        });
+      });
+    });
+  </script>
+
