+          topBlends.sort((a, b) => b.cuppingScore - a.cuppingScore);
+          if (topBlends.length > 24) {
+            topBlends.pop();
+          }
+        }
+
+        if (performance.now() >= deadline) {
+          yieldsCount++;
+          updateProgressUI(processed, total, yieldsCount, performance.now() - startTime);
+          if ('scheduler' in window && 'yield' in window.scheduler) {
+            await scheduler.yield();
+          } else {
+            await new Promise(resolve => setTimeout(resolve, 0));
+          }
+          deadline = performance.now() + 50;
+        }
+      }
+
+      const totalElapsed = performance.now() - startTime;
+      updateProgressUI(total, total, yieldsCount, totalElapsed);
+
+      metricAcidity.textContent = (sumAcidity / total).toFixed(2);
+      metricBody.textContent = (sumBody / total).toFixed(2);
+      metricSweetness.textContent = (sumSweetness / total).toFixed(2);
+      metricBitterness.textContent = (sumBitterness / total).toFixed(2);
+      metricTopScore.textContent = topBlends[0] ? topBlends[0].cuppingScore.toFixed(1) : '--';
+
+      lastTopBlends = topBlends;
+      renderTopBlends(lastTopBlends, HIGHLIGHT_NOTES[noteIndex]);
+    }
+
+    runBtn.addEventListener('click', async () => {
+      const batchSize = Number(batchSelect.value) || 5000;
+      const roastProfile = roastSelect.value;
+      const brewMethod = brewSelect.value;
+      const waterTemp = Number(waterTempInput.value) || 93;
+
+      runBtn.disabled = true;
+      runBtn.textContent = 'Simulating Batch...';
+      statusText.textContent = 'Preparing recipe batch...';
+
+      try {
+        const recipes = generateRecipeBatch(batchSize, roastProfile, brewMethod, waterTemp);
+        await processRecipeBatch(recipes);
+      } finally {
+        runBtn.disabled = false;
+        runBtn.textContent = 'Run Batch Simulation';
+      }
+    });
+  </script>
