+  <script>
+    (function () {
+      let accumulatedForegroundTimeMs = 0;
+      let foregroundStartTime = document.visibilityState === 'visible' ? performance.now() : null;
+
+      function handleVisibilityChange(event) {
+        const now = performance.now();
+        const isVisible = event && event.type === 'pagehide'
+          ? false
+          : document.visibilityState === 'visible';
+
+        if (isVisible) {
+          if (foregroundStartTime === null) {
+            foregroundStartTime = now;
+          }
+        } else {
+          if (foregroundStartTime !== null) {
+            accumulatedForegroundTimeMs += now - foregroundStartTime;
+            foregroundStartTime = null;
+          }
+        }
+      }
+
+      document.addEventListener('visibilitychange', handleVisibilityChange);
+      window.addEventListener('pagehide', handleVisibilityChange);
+      window.addEventListener('pageshow', handleVisibilityChange);
+
+      /**
+       * Calculates the total time (in milliseconds) the page has spent in the foreground.
+       * @returns {number} Total foreground time in milliseconds.
+       */
+      function calculateTotalForegroundTime() {
+        if (document.visibilityState === 'visible' && foregroundStartTime !== null) {
+          return accumulatedForegroundTimeMs + (performance.now() - foregroundStartTime);
+        }
+        return accumulatedForegroundTimeMs;
+      }
+
+      window.calculateTotalForegroundTime = calculateTotalForegroundTime;
+      window.getTotalForegroundTime = calculateTotalForegroundTime;
+    })();
