+  <script>
+    const orderItems = [];
+    const orderSummary = document.getElementById('order-summary');
+    const supportsHas = CSS.supports('selector(:has(*))');
+
+    document.querySelectorAll('.card').forEach((card) => {
+      if (!supportsHas) {
+        if (card.querySelector('img')) {
+          card.classList.add('has-image');
+        }
+        const syncSelectedState = () => {
+          card.querySelectorAll('.size-option').forEach((label) => {
+            const radio = label.querySelector('input[type="radio"]');
+            label.classList.toggle('is-selected', Boolean(radio && radio.checked));
+          });
+          const largeRadio = card.querySelector('input[value="large"]');
+          card.classList.toggle('is-large-selected', Boolean(largeRadio && largeRadio.checked));
+        };
+        syncSelectedState();
+        card.addEventListener('change', syncSelectedState);
+      }
+
+      const form = card.querySelector('.order-form');
+      if (!form) return;
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const formData = new FormData(form);
+        const drink = formData.get('drink');
+        const size = String(formData.get('size') || 'medium');
+        const formattedSize = size.charAt(0).toUpperCase() + size.slice(1);
+
+        orderItems.push({ drink, size: formattedSize });
+
+        const statusOutput = form.querySelector('.order-status');
+        if (statusOutput) {
+          statusOutput.textContent = `Added ${formattedSize} ${drink} to your order.`;
+        }
+
+        if (!supportsHas) {
+          card.classList.add('is-ordered');
+        }
+
+        if (orderSummary) {
+          const count = orderItems.length;
+          orderSummary.textContent = `Order (${count} ${count === 1 ? 'item' : 'items'}): ${orderItems.map((item) => `${item.size} ${item.drink}`).join(', ')}`;
+        }
+      });
+    });
