+            publicKeyBytes: pkBytes,
+            pkHash: pkHash,
+            zSeed: zSeed
+          }
+        };
+      }
+
+      // Internal deterministic CPA encryption used by both Encapsulate and FO-Verify
+      async function mlKem768EncryptDeterministic(pkBytes, msg32, rCoins) {
+        const rho = pkBytes.subarray(0, 32);
+        const tVec = unpackPolyVec(pkBytes.subarray(32, 32 + MLKEM_K * 384));
+
+        const A = [];
+        for (let i = 0; i < MLKEM_K; i++) {
+          A[i] = [];
+          for (let j = 0; j < MLKEM_K; j++) {
+            A[i][j] = await sampleUniformPoly(rho, i, j);
+          }
+        }
+
+        const rVec = [];
+        const e1Vec = [];
+        for (let i = 0; i < MLKEM_K; i++) {
+          rVec.push(await sampleCBDPoly(rCoins, i));
+          e1Vec.push(await sampleCBDPoly(rCoins, i + MLKEM_K));
+        }
+        const e2 = await sampleCBDPoly(rCoins, 2 * MLKEM_K);
+
+        // u = A^T * r + e1
+        const uVec = [];
+        for (let i = 0; i < MLKEM_K; i++) {
+          let acc = new Int16Array(MLKEM_N);
+          for (let j = 0; j < MLKEM_K; j++) {
+            acc = polyAdd(acc, polyMul(A[j][i], rVec[j]));
+          }
+          uVec.push(polyAdd(acc, e1Vec[i]));
+        }
+
+        // v = t^T * r + e2 + encode(m)
+        let v = new Int16Array(MLKEM_N);
+        for (let i = 0; i < MLKEM_K; i++) {
+          v = polyAdd(v, polyMul(tVec[i], rVec[i]));
+        }
+        v = polyAdd(v, e2);
+        v = polyAdd(v, encodeMsgToPoly(msg32));
+
+        return concatBytes(packPolyVec(uVec), packPoly(v)); // 1152 + 384 = 1536 bytes
+      }
+
+      async function mlKem768Encapsulate(pkBytes) {
+        const rawEntropy = webCrypto.getRandomValues(new Uint8Array(32));
+        const m = await sha256(rawEntropy);
+        const pkHash = await sha256(pkBytes);
+        const kBar = await sha256(concatBytes(m, pkHash, new Uint8Array([0x10])));
+        const rCoins = await sha256(concatBytes(m, pkHash, new Uint8Array([0x20])));
+
+        const ciphertext = await mlKem768EncryptDeterministic(pkBytes, m, rCoins);
+        const ctHash = await sha256(ciphertext);
+        const sharedSecret = await sha256(concatBytes(kBar, ctHash));
+
+        return {
+          ciphertext,
+          sharedSecret
+        };
+      }
+
+      async function mlKem768Decapsulate(ciphertext, secretKey) {
+        const uVec = unpackPolyVec(ciphertext.subarray(0, MLKEM_K * 384));
+        const v = unpackPoly(ciphertext.subarray(MLKEM_K * 384, (MLKEM_K + 1) * 384));
+
+        // s^T * u
+        let sTu = new Int16Array(MLKEM_N);
+        for (let i = 0; i < MLKEM_K; i++) {
+          sTu = polyAdd(sTu, polyMul(secretKey.sVec[i], uVec[i]));
+        }
+
+        // w = v - s^T * u
+        const w = polySub(v, sTu);
+        const mPrime = decodePolyToMsg(w);
+
+        const kBarPrime = await sha256(concatBytes(mPrime, secretKey.pkHash, new Uint8Array([0x10])));
+        const rCoinsPrime = await sha256(concatBytes(mPrime, secretKey.pkHash, new Uint8Array([0x20])));
+
+        // Fujisaki-Okamoto CCA2 re-encryption check
+        const ctPrime = await mlKem768EncryptDeterministic(secretKey.publicKeyBytes, mPrime, rCoinsPrime);
+        const ctHash = await sha256(ciphertext);
+
+        let diff = 0;
+        if (ctPrime.length !== ciphertext.length) {
+          diff = 1;
+        } else {
+          for (let i = 0; i < ciphertext.length; i++) {
+            diff |= (ctPrime[i] ^ ciphertext[i]);
+          }
+        }
+
+        if (diff === 0) {
+          return await sha256(concatBytes(kBarPrime, ctHash));
+        } else {
+          // Implicit rejection on tampered KEM ciphertext
+          return await sha256(concatBytes(secretKey.zSeed, ctHash));
+        }
+      }
+
+      // ============================================================================
+      // HKDF-SHA-256 & AES-256-GCM Authenticated Encryption Engine
+      // ============================================================================
+      async function deriveAesGcmKeyFromSharedSecret(ikmBytes, saltBytes, infoStr) {
+        const hkdfBaseKey = await subtle.importKey(
+          'raw',
+          ikmBytes,
+          { name: 'HKDF' },
+          false,
+          ['deriveKey', 'deriveBits']
+        );
+
+        const infoBytes = textEncoder.encode(infoStr);
+        const aesKey = await subtle.deriveKey(
+          {
+            name: 'HKDF',
+            hash: 'SHA-256',
+            salt: saltBytes,
+            info: infoBytes
+          },
+          hkdfBaseKey,
+          { name: 'AES-GCM', length: 256 },
+          false,
+          ['encrypt', 'decrypt']
+        );
+
+        const fingerprintBits = await subtle.deriveBits(
+          {
+            name: 'HKDF',
+            hash: 'SHA-256',
+            salt: saltBytes,
+            info: textEncoder.encode(infoStr + '|fingerprint')
+          },
+          hkdfBaseKey,
+          256
+        );
+
+        return {
+          aesKey,
+          sharedSecretFingerprint: bytesToHex(new Uint8Array(fingerprintBits)).slice(0, 32)
+        };
+      }
+
+      // ============================================================================
+      // Application State & Courier Keypair Management
+      // ============================================================================
+      let courierState = null;
+      let establishedSession = null;
+      let activeEnvelope = null;
+      const encryptedVault = [];
+
+      async function generateCourierKeys() {
+        // 1. Classical ECDH NIST P-256 Keypair via Web Crypto API
+        const ecdhKeyPair = await subtle.generateKey(
+          { name: 'ECDH', namedCurve: 'P-256' },
+          true,
+          ['deriveBits']
+        );
+        const ecdhPubRaw = new Uint8Array(await subtle.exportKey('raw', ecdhKeyPair.publicKey));
+
+        // 2. Post-Quantum ML-KEM-768 Keypair
+        const mlKemKeyPair = await mlKem768Keygen();
+
+        // 3. Combined Courier Key ID
+        const combinedDigest = await sha256(concatBytes(ecdhPubRaw, mlKemKeyPair.publicKeyBytes));
+        const keyId = 'DG-COURIER-' + bytesToHex(combinedDigest).slice(0, 12).toUpperCase();
+
+        courierState = {
+          keyId,
+          ecdhKeyPair,
+          ecdhPubRaw,
+          mlKemKeyPair,
+          createdAt: new Date().toISOString()
+        };
+
+        establishedSession = null;
+        updateCourierKeyUI();
+        return courierState;
+      }
+
+      // Establish shared secret via selected KEM / Key Agreement suite
+      async function establishSharedSecret(suite) {
+        if (!courierState) {
+          await generateCourierKeys();
+        }
+        const targetCourier = courierState;
+
+        const selectedSuite = suite || document.getElementById('kem-suite-select').value;
+        const hkdfSalt = webCrypto.getRandomValues(new Uint8Array(16));
+        const hkdfInfo = `DailyGrind-DeliveryNote-AEAD-v1|${selectedSuite}|${targetCourier.keyId}`;
+
+        let ecdhEphemeralPubB64 = null;
+        let pqCiphertextB64 = null;
+        let ecdhSharedBytes = new Uint8Array(0);
+        let pqSharedBytes = new Uint8Array(0);
+
+        if (selectedSuite === 'HYBRID_P256_MLKEM768' || selectedSuite === 'CLASSICAL_ECDH_P256') {
+          // Ephemeral-Static ECDH P-256 Key Agreement
+          const ephemeralEcdh = await subtle.generateKey(
+            { name: 'ECDH', namedCurve: 'P-256' },
+            true,
+            ['deriveBits']
+          );
+          const ephemeralPubRaw = new Uint8Array(await subtle.exportKey('raw', ephemeralEcdh.publicKey));
+          const sharedBits = await subtle.deriveBits(
+            { name: 'ECDH', public: targetCourier.ecdhKeyPair.publicKey },
+            ephemeralEcdh.privateKey,
+            256
+          );
+          ecdhSharedBytes = new Uint8Array(sharedBits);
+          ecdhEphemeralPubB64 = bytesToBase64(ephemeralPubRaw);
+        }
+
+        if (selectedSuite === 'HYBRID_P256_MLKEM768' || selectedSuite === 'PQ_MLKEM768') {
+          // Post-Quantum ML-KEM-768 Key Encapsulation
+          const kemResult = await mlKem768Encapsulate(targetCourier.mlKemKeyPair.publicKeyBytes);
+          pqSharedBytes = kemResult.sharedSecret;
+          pqCiphertextB64 = bytesToBase64(kemResult.ciphertext);
+        }
+
+        // Hybrid Combiner IKM = ss_ecdh || ss_pq
+        const combinedIkm = concatBytes(ecdhSharedBytes, pqSharedBytes);
+        const { aesKey, sharedSecretFingerprint } = await deriveAesGcmKeyFromSharedSecret(
+          combinedIkm,
+          hkdfSalt,
+          hkdfInfo
+        );
+
+        establishedSession = {
+          suite: selectedSuite,
+          recipientKeyId: targetCourier.keyId,
+          ecdhEphemeralPubB64,
+          pqCiphertextB64,
+          hkdfSaltB64: bytesToBase64(hkdfSalt),
+          hkdfInfo,
+          aesKey,
+          sharedSecretFingerprint,
+          establishedAt: new Date().toISOString()
+        };
+
+        document.getElementById('shared-secret-fp').textContent =
+          `SHA256:${sharedSecretFingerprint} (${selectedSuite})`;
+
+        return establishedSession;
+      }
+
+      // Encrypt customer delivery note using established (or fresh) hybrid shared secret & AES-256-GCM
+      async function encryptDeliveryNote(options = {}) {
+        const suite = options.suite || document.getElementById('kem-suite-select').value;
+        const orderId = (options.orderId ?? document.getElementById('order-id-input').value).trim() || 'DG-2026-0001';
+        const dropoffZone = (options.dropoffZone ?? document.getElementById('dropoff-zone-input').value).trim() || 'Standard Drop-off';
+        const expiryPolicy = options.expiryPolicy || document.getElementById('expiry-policy-select').value;
+        const plaintext = options.plaintext ?? document.getElementById('delivery-note-input').value;
+
+        if (!plaintext || !plaintext.trim()) {
+          showStatus('encrypt-status-banner', 'Please enter a delivery note to encrypt.', 'error');
+          throw new Error('Delivery note plaintext cannot be empty');
+        }
+
+        // Always establish a fresh ephemeral encapsulation or use matching session
+        const session = await establishSharedSecret(suite);
+
+        // 96-bit (12-byte) CSPRNG IV for AES-256-GCM
+        const iv = webCrypto.getRandomValues(new Uint8Array(12));
+
+        // Contextual Associated Data (AAD) authenticated by AES-GCM tag
+        const aadObject = {
+          v: 1,
+          orderId,
+          dropoffZone,
+          expiryPolicy,
+          recipientKeyId: session.recipientKeyId,
+          suite: session.suite
+        };
+        const aadJson = JSON.stringify(aadObject);
+        const aadBytes = textEncoder.encode(aadJson);
+        const plaintextBytes = textEncoder.encode(plaintext);
+
+        // Web Crypto AES-256-GCM returns ciphertext || 128-bit (16-byte) authTag
+        const encryptedBuffer = await subtle.encrypt(
+          {
+            name: 'AES-GCM',
+            iv: iv,
+            additionalData: aadBytes,
+            tagLength: 128
+          },
+          session.aesKey,
+          plaintextBytes
+        );
+
+        const encryptedBytes = new Uint8Array(encryptedBuffer);
+        const ciphertextOnly = encryptedBytes.subarray(0, encryptedBytes.length - 16);
+        const authTagOnly = encryptedBytes.subarray(encryptedBytes.length - 16);
+
+        const envelope = {
+          version: '1.0-PQ-AEAD',
+          algorithm: {
+            kem: session.suite,
+            kdf: 'HKDF-SHA-256',
+            aead: 'AES-256-GCM',
+            tagLengthBits: 128
+          },
+          recipientKeyId: session.recipientKeyId,
+          encapsulation: {
+            ecdhEphemeralPublicKey: session.ecdhEphemeralPubB64,
+            mlKem768CiphertextPreview: session.pqCiphertextB64
+              ? session.pqCiphertextB64.slice(0, 64) + '... (' + base64ToBytes(session.pqCiphertextB64).length + ' bytes)'
+              : null,
+            mlKem768Ciphertext: session.pqCiphertextB64,
+            hkdfSalt: session.hkdfSaltB64,
+            hkdfInfo: session.hkdfInfo,
+            sharedSecretFingerprint: session.sharedSecretFingerprint
+          },
+          associatedData: aadObject,
+          aeadPayload: {
+            iv: bytesToBase64(iv),
+            ciphertext: bytesToBase64(ciphertextOnly),
+            authTag: bytesToBase64(authTagOnly)
+          },
+          createdAt: new Date().toISOString()
+        };
+
+        activeEnvelope = envelope;
+        encryptedVault.unshift( JSON.parse(JSON.stringify(envelope)) );
+        renderEnvelopeDisplay(envelope);
+        renderVaultList();
+
+        showStatus(
+          'encrypt-status-banner',
+          `Encrypted with ${session.suite} + AES-256-GCM. Shared secret (${session.sharedSecretFingerprint.slice(0, 12)}...) encapsulated for ${session.recipientKeyId}.`,
+          'success'
+        );
+
+        return envelope;
+      }
+
+      // Courier Decryption: Decapsulate shared secret from envelope & verify AES-256-GCM tag + AAD
+      async function decryptDeliveryEnvelope(envelopeToDecrypt) {
+        const env = envelopeToDecrypt || activeEnvelope;
+        if (!env) {
+          showStatus('decrypt-status-banner', 'No encrypted envelope available to decrypt.', 'error');
+          throw new Error('No encrypted envelope available');
+        }
+
+        if (!courierState || env.recipientKeyId !== courierState.keyId) {
+          showStatus(
+            'decrypt-status-banner',
+            `Key mismatch: Envelope was encapsulated for ${env.recipientKeyId}, but active courier key is ${courierState ? courierState.keyId : 'none'}.`,
+            'error'
+          );
+          document.getElementById('decrypted-result-box').classList.remove('visible');
+          throw new Error('Recipient key ID mismatch');
+        }
+
+        const suite = env.algorithm.kem;
+        let ecdhSharedBytes = new Uint8Array(0);
+        let pqSharedBytes = new Uint8Array(0);
+
+        if (suite === 'HYBRID_P256_MLKEM768' || suite === 'CLASSICAL_ECDH_P256') {
+          const ephemPubBytes = base64ToBytes(env.encapsulation.ecdhEphemeralPublicKey);
+          const ephemPubKey = await subtle.importKey(
+            'raw',
+            ephemPubBytes,
+            { name: 'ECDH', namedCurve: 'P-256' },
+            false,
+            []
+          );
+          const derivedBits = await subtle.deriveBits(
+            { name: 'ECDH', public: ephemPubKey },
+            courierState.ecdhKeyPair.privateKey,
+            256
+          );
+          ecdhSharedBytes = new Uint8Array(derivedBits);
+        }
+
+        if (suite === 'HYBRID_P256_MLKEM768' || suite === 'PQ_MLKEM768') {
+          const pqCtBytes = base64ToBytes(env.encapsulation.mlKem768Ciphertext);
+          pqSharedBytes = await mlKem768Decapsulate(pqCtBytes, courierState.mlKemKeyPair.secretKey);
+        }
+
+        const combinedIkm = concatBytes(ecdhSharedBytes, pqSharedBytes);
+        const hkdfSalt = base64ToBytes(env.encapsulation.hkdfSalt);
+        const { aesKey, sharedSecretFingerprint } = await deriveAesGcmKeyFromSharedSecret(
+          combinedIkm,
+          hkdfSalt,
+          env.encapsulation.hkdfInfo
+        );
+
+        const iv = base64ToBytes(env.aeadPayload.iv);
+        const ciphertextBytes = base64ToBytes(env.aeadPayload.ciphertext);
+        const authTagBytes = base64ToBytes(env.aeadPayload.authTag);
+        const combinedCiphertextAndTag = concatBytes(ciphertextBytes, authTagBytes);
+        const aadBytes = textEncoder.encode(JSON.stringify(env.associatedData));
+
+        try {
+          const decryptedBuffer = await subtle.decrypt(
+            {
+              name: 'AES-GCM',
+              iv: iv,
+              additionalData: aadBytes,
+              tagLength: 128
+            },
+            aesKey,
+            combinedCiphertextAndTag
+          );
+
+          const plaintext = textDecoder.decode(decryptedBuffer);
+          showStatus(
+            'decrypt-status-banner',
+            `Decapsulation & AES-256-GCM authentication succeeded! Derived secret fingerprint: ${sharedSecretFingerprint.slice(0, 16)}...`,
+            'success'
+          );
+
+          const resultBox = document.getElementById('decrypted-result-box');
+          document.getElementById('decrypted-aad-meta').textContent =
+            `Verified AAD — Order: ${env.associatedData.orderId} | Drop-off: ${env.associatedData.dropoffZone} | Suite: ${suite} | TTL: ${env.associatedData.expiryPolicy}`;
+          document.getElementById('decrypted-plaintext-content').textContent = plaintext;
+          resultBox.classList.add('visible');
+
+          return {
+            verified: true,
+            plaintext,
+            sharedSecretFingerprint,
+            associatedData: env.associatedData
+          };
+        } catch (err) {
+          document.getElementById('decrypted-result-box').classList.remove('visible');
+          showStatus(
+            'decrypt-status-banner',
+            'AEAD Authentication Failed (AES-256-GCM tag or AAD mismatch)! Ciphertext or metadata was tampered with.',
+            'error'
+          );
+          throw new Error('AES-GCM authentication failed: ' + (err && err.message ? err.message : 'Tag mismatch'));
+        }
+      }
+
+      // Flip a bit in the active envelope's ciphertext to demonstrate AEAD tamper detection
+      function simulateCiphertextTampering() {
+        if (!activeEnvelope) {
+          showStatus('decrypt-status-banner', 'Encrypt a delivery note first before simulating tampering.', 'info');
+          return null;
+        }
+        const ctBytes = base64ToBytes(activeEnvelope.aeadPayload.ciphertext);
