+          checkCalendar.getUTCMonth() + 1 !== month ||
+          checkCalendar.getUTCDate() !== day
+        ) {
+          return {
+            valid: false,
+            reason: 'calendar',
+            message: `Invalid calendar date: ${dateStr} does not exist.`
+          };
+        }
+
+        // Validate hostTz is recognized by Intl
+        try {
+          new Intl.DateTimeFormat('en-US', { timeZone: hostTz });
