+        const wallAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
+
+        // Probe offsets around wallAsUtc (-36h to +36h) to capture all possible offsets on transition day
+        const probePoints = [
+          wallAsUtc - 36 * 3600000,
+          wallAsUtc - 18 * 3600000,
+          wallAsUtc - 6 * 3600000,
+          wallAsUtc,
+          wallAsUtc + 6 * 3600000,
+          wallAsUtc + 18 * 3600000,
+          wallAsUtc + 36 * 3600000
+        ];
