+        matchingUtcInstants.sort((a, b) => a - b);
+
+        // If no UTC instant produces the requested local wall-clock time in hostTz,
+        // the time falls inside a Daylight Saving Time spring-forward gap!
+        if (matchingUtcInstants.length === 0) {
+          const offsetBefore = getTimeZoneOffsetMs(wallAsUtc - 12 * 3600000, hostTz);
+          const offsetAfter = getTimeZoneOffsetMs(wallAsUtc + 12 * 3600000, hostTz);
+          const abbrBefore = getTimeZoneAbbreviation(wallAsUtc - 12 * 3600000, hostTz);
+          const abbrAfter = getTimeZoneAbbreviation(wallAsUtc + 12 * 3600000, hostTz);
+
+          return {
+            valid: false,
+            reason: 'dst-gap',
+            message: `Invalid Time Rejected (Daylight Saving Time Transition): ${timeStr.slice(0, 5)} on ${dateStr} does not exist in ${hostTz}. Clocks spring forward from ${abbrBefore} (${formatUtcOffset(offsetBefore)}) to ${abbrAfter} (${formatUtcOffset(offsetAfter)}), skipping this hour.`
+          };
+        }
+
+        return {
+          valid: true,
+          utcMs: matchingUtcInstants[0],
+          ambiguous: matchingUtcInstants.length > 1,
+          allMatches: matchingUtcInstants,
+          hostParts: { year, month, day, hour, minute }
+        };
+      }
+
+      // Format target card data for a given UTC instant and target timezone
+      function formatZoneCardData(utcMs, targetZone, hostParts) {
+        const parts = getWallClockParts(utcMs, targetZone.tz);
+        const hh = String(parts.hour).padStart(2, '0');
+        const mm = String(parts.minute).padStart(2, '0');
+        const time24 = `${hh}:${mm}`;
+
+        const period = parts.hour >= 12 ? 'PM' : 'AM';
+        const hour12Num = parts.hour % 12 === 0 ? 12 : parts.hour % 12;
+        const time12 = `${hour12Num}:${mm} ${period}`;
+        const time12Padded = `${String(hour12Num).padStart(2, '0')}:${mm} ${period}`;
+
+        const isoDate = `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
+
+        const readableDate = new Intl.DateTimeFormat('en-US', {
+          timeZone: targetZone.tz,
+          weekday: 'short',
+          month: 'short',
+          day: 'numeric',
+          year: 'numeric'
+        }).format(new Date(utcMs));
+
+        // Calculate calendar day difference vs host date
+        const hostDateUtc = Date.UTC(hostParts.year, hostParts.month - 1, hostParts.day);
+        const targetDateUtc = Date.UTC(parts.year, parts.month - 1, parts.day);
+        const dayDiff = Math.round((targetDateUtc - hostDateUtc) / 86400000);
+
+        let dayDiffLabel = 'Same Day';
+        let dayDiffClass = 'shift-same';
+        if (dayDiff === 1) {
+          dayDiffLabel = '+1 Day (Next Day)';
+          dayDiffClass = 'shift-next';
+        } else if (dayDiff === -1) {
+          dayDiffLabel = '-1 Day (Prev Day)';
+          dayDiffClass = 'shift-prev';
+        } else if (dayDiff > 1) {
+          dayDiffLabel = `+${dayDiff} Days`;
+          dayDiffClass = 'shift-next';
+        } else if (dayDiff < -1) {
+          dayDiffLabel = `${dayDiff} Days`;
+          dayDiffClass = 'shift-prev';
+        }
+
+        const offsetMs = getTimeZoneOffsetMs(utcMs, targetZone.tz);
+        const offsetStr = formatUtcOffset(offsetMs);
+        const abbr = getTimeZoneAbbreviation(utcMs, targetZone.tz);
+        const dstInfo = getDstStatus(utcMs, targetZone.tz, parts.year);
+
+        let tastingWindow = 'Standard Cupping Session';
+        if (parts.hour >= 8 && parts.hour < 12) {
+          tastingWindow = 'Morning Sensory Peak (Ideal Cupping)';
+        } else if (parts.hour >= 12 && parts.hour < 17) {
+          tastingWindow = 'Afternoon Roastery Flight';
+        } else if (parts.hour >= 17 && parts.hour < 21) {
+          tastingWindow = 'Evening Espresso & Decaf Tasting';
+        } else {
+          tastingWindow = 'Late Night / Early Owl Roastery Slot';
+        }
+
+        return {
+          ...targetZone,
+          time24,
+          time12,
+          time12Padded,
+          isoDate,
+          readableDate,
+          dayDiff,
+          dayDiffLabel,
