+          hostSummaryValue.textContent = `${dateStr || '--'} ${timeStr || '--'} (Rejected - DST Gap)`;
+          utcReferenceBadge.textContent = 'UTC: Invalid Host Time (DST Transition)';
+
+          grid.innerHTML = `
