+
+        if (ambiguous) {
+          statusBanner.className = 'status-banner warning';
+          statusBanner.textContent = `Note: ${timeStr} on ${dateStr} occurs twice in ${hostTz} due to a Daylight Saving Time fall-back transition. Showing conversions for the first occurrence (${hostAbbr}, ${hostOffset}).`;
