+          statusBanner.textContent = '';
+        }
+
+        const utcParts = getWallClockParts(utcMs, 'UTC');
+        const utcIsoDate = `${utcParts.year}-${String(utcParts.month).padStart(2, '0')}-${String(utcParts.day).padStart(2, '0')}`;
+        const utcTime24 = `${String(utcParts.hour).padStart(2, '0')}:${String(utcParts.minute).padStart(2, '0')}`;
+        utcReferenceBadge.textContent = `UTC: ${utcIsoDate} ${utcTime24} UTC`;
+
+        hostSummaryLabel.textContent = `Host: ${hostTz} (${hostAbbr})`;
+        hostSummaryValue.textContent = `${dateStr} · ${timeStr.slice(0, 5)} (${hostOffset})`;
+
+        // Ensure the selected hostTz is also represented if not already in TARGET_ZONES
+        const zonesToRender = [...TARGET_ZONES];
+        if (!zonesToRender.some((z) => z.tz === hostTz)) {
+          const cityLabel = hostTz.includes('/') ? hostTz.split('/').pop().replace(/_/g, ' ') : hostTz;
+          zonesToRender.unshift({
+            city: cityLabel,
+            country: 'Selected Host Zone',
+            tz: hostTz,
+            roastery: 'Host Cupping Station'
+          });
+        }
+
+        const cardsHtml = zonesToRender
+          .map((zone) => {
+            const data = formatZoneCardData(utcMs, zone, hostParts);
+            const isHost = data.tz === hostTz;
+            const isTokyo = data.tz === 'Asia/Tokyo';
+
+            let dstBadgeClass = 'badge-std';
+            if (data.dstInfo.isDst) {
+              dstBadgeClass = 'badge-dst-active';
+            } else if (!data.dstInfo.observesDst) {
+              dstBadgeClass = 'badge-no-dst';
+            }
+
+            const time12Display =
+              data.time12 === data.time12Padded
+                ? data.time12
+                : `${data.time12} (${data.time12Padded})`;
+
+            return `
+              <article class="card ${isHost ? 'is-host-zone' : ''} ${isTokyo ? 'is-tokyo-zone' : ''}" data-tz="${data.tz}" data-city="${data.city}">
+                <div>
+                  <div class="card-top">
+                    <div class="city-info">
+                      <h3>${data.city}, ${data.country}</h3>
+                      <div class="tz-id">${data.tz}</div>
+                    </div>
+                    <div class="badges-col">
+                      ${isHost ? '<span class="badge badge-host">Host Zone</span>' : ''}
+                      <span class="badge ${dstBadgeClass}">${data.dstInfo.label}</span>
+                    </div>
+                  </div>
+
+                  <div class="card-time-box">
+                    <div class="converted-time-primary">
+                      <span class="time-24h">${data.time24}</span>
+                      <span class="converted-time-12h">${time12Display}</span>
+                    </div>
+                    <div class="converted-date-line">
+                      <span>${data.readableDate} (${data.isoDate})</span>
+                      <span class="day-shift-tag ${data.dayDiffClass}">${data.dayDiffLabel}</span>
+                    </div>
+                  </div>
+                </div>
+
+                <div>
+                  <div class="card-footer-meta">
+                    <span class="offset-pill">${data.abbr} · ${data.offsetStr}</span>
+                    <span>${data.roastery}</span>
+                  </div>
+                  <div class="tasting-note">${data.tastingWindow}</div>
+                </div>
+              </article>
+            `;
+          })
+          .join('');
+
+        grid.innerHTML = cardsHtml;
+      }
+
+      populateAdditionalTimeZones();
+
+      // Attach listeners for both input and change events on all three controls
+      [dateInput, timeInput, hostTzSelect].forEach((el) => {
+        el.addEventListener('input', renderCoordinator);
+        el.addEventListener('change', renderCoordinator);
+      });
+
+      // Attach preset buttons
+      document.querySelectorAll('.preset-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          dateInput.value = btn.getAttribute('data-date');
+          timeInput.value = btn.getAttribute('data-time');
+          hostTzSelect.value = btn.getAttribute('data-tz');
+          renderCoordinator();
+        });
+      });
+
+      // Initial render
+      renderCoordinator();
+    })();
+  </script>
 </body>

