+    const canvas = document.getElementById('render-canvas');
+    const ctx = canvas.getContext('2d');
+    const randomizeBtn = document.getElementById('randomize-btn');
+    const resetBtn = document.getElementById('reset-btn');
+    const samplesSelect = document.getElementById('samples-select');
+    const statusOutput = document.getElementById('render-status');
+    const metricsSpan = document.getElementById('render-metrics');
+    const paletteList = document.getElementById('sphere-palette');
+
+    const worker = new Worker(new URL('./worker.js', import.meta.url), {
+      type: 'module',
+    });
+
+    let requestCounter = 0;
+    let completedRenders = 0;
+    let isRendering = false;
+    let queuedJob = null;
+
+    function updatePaletteUI(sphereColors) {
+      if (!Array.isArray(sphereColors)) return;
+      const items = sphereColors.map((sphere) => {
+        const li = document.createElement('li');
+        li.className = 'palette-item';
+
+        const left = document.createElement('div');
+        left.className = 'swatch-info';
+
+        const swatch = document.createElement('span');
+        swatch.className = 'color-swatch';
+        swatch.style.backgroundColor = sphere.hex;
+        swatch.setAttribute('aria-hidden', 'true');
+
+        const nameSpan = document.createElement('span');
+        nameSpan.className = 'sphere-name';
+        nameSpan.textContent = sphere.name;
+
+        left.append(swatch, nameSpan);
+
+        const metaSpan = document.createElement('span');
+        metaSpan.className = 'sphere-meta';
+        metaSpan.textContent = `${sphere.material} • ${sphere.hex}`;
+
+        li.append(left, metaSpan);
+        return li;
+      });
+
+      paletteList.replaceChildren(...items);
+    }
+
+    function dispatchRenderJob(options = {}) {
+      const samples = Number.parseInt(samplesSelect.value, 10) || 4;
+      const job = {
+        type: 'render',
+        width: canvas.width,
+        height: canvas.height,
+        samples,
+        randomize: Boolean(options.randomize),
+        reset: Boolean(options.reset),
+        seed: ((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0) || 1,
+        requestId: ++requestCounter,
+      };
+
+      if (isRendering) {
+        queuedJob = job;
+        return;
+      }
+
+      isRendering = true;
+      canvas.dataset.status = 'rendering';
+      statusOutput.textContent = job.randomize
+        ? 'Path tracing with randomized sphere colors…'
+        : 'Path tracing scene in WebAssembly…';
+      worker.postMessage(job);
+    }
+
+    worker.addEventListener('message', (event) => {
+      const data = event.data;
+      if (!data) return;
+
+      if (data.type === 'rendered') {
+        const imageData = new ImageData(data.pixels, data.width, data.height);
+        ctx.putImageData(imageData, 0, 0);
+
+        completedRenders += 1;
+        canvas.dataset.status = 'complete';
+        canvas.dataset.renderCount = String(completedRenders);
+        statusOutput.textContent = `✓ Render #${completedRenders} complete (${data.elapsedMs} ms)`;
+        metricsSpan.textContent = `${data.width} × ${data.height} px • ${data.samples * 4} spp • ${data.elapsedMs} ms`;
+
+        updatePaletteUI(data.sphereColors);
+
+        isRendering = false;
+        if (queuedJob) {
+          const nextJob = queuedJob;
+          queuedJob = null;
+          isRendering = true;
+          canvas.dataset.status = 'rendering';
+          worker.postMessage(nextJob);
+        }
+      } else if (data.type === 'error') {
+        isRendering = false;
+        canvas.dataset.status = 'error';
+        statusOutput.textContent = `✕ Render error: ${data.message}`;
+      }
+    });
+
+    randomizeBtn.addEventListener('click', () => {
+      dispatchRenderJob({ randomize: true });
+    });
+
+    resetBtn.addEventListener('click', () => {
+      dispatchRenderJob({ reset: true });
+    });
+
+    samplesSelect.addEventListener('change', () => {
+      dispatchRenderJob({ randomize: false });
+    });
+
+    // Run initial path trace on load
