+import initSmallpt from './smallpt.js';
+
+const wasmPromise = initSmallpt();
+
+const SPHERE_METADATA = [
+  { index: 0, name: 'Left Wall Sphere', material: 'DIFF' },
+  { index: 1, name: 'Right Wall Sphere', material: 'DIFF' },
+  { index: 2, name: 'Back Wall Sphere', material: 'DIFF' },
+  { index: 4, name: 'Floor Sphere', material: 'DIFF' },
+  { index: 5, name: 'Ceiling Sphere', material: 'DIFF' },
+  { index: 6, name: 'Mirror Sphere', material: 'SPEC' },
+  { index: 7, name: 'Glass Sphere', material: 'REFR' },
+];
+
+function readSpherePalette(wasm) {
+  const count = 9;
+  const byteLength = count * 3 * Float64Array.BYTES_PER_ELEMENT;
+  const colorPtr = wasm._malloc(byteLength);
+  try {
+    wasm._get_sphere_colors(colorPtr);
+    const floats = new Float64Array(
+      wasm.HEAPU8.buffer,
+      colorPtr,
+      count * 3,
+    ).slice();
+
+    return SPHERE_METADATA.map((meta) => {
+      const base = meta.index * 3;
+      const r = Math.round(Math.min(1, Math.max(0, floats[base])) * 255);
+      const g = Math.round(Math.min(1, Math.max(0, floats[base + 1])) * 255);
+      const b = Math.round(Math.min(1, Math.max(0, floats[base + 2])) * 255);
+      const hex = `#${[r, g, b].map((v) => v.toString(16).padStart(2, '0')).join('')}`.toUpperCase();
+      return {
+        ...meta,
+        r,
+        g,
+        b,
+        hex,
+      };
+    });
+  } finally {
+    wasm._free(colorPtr);
+  }
+}
+
+self.addEventListener('message', async (event) => {
+  const {
+    type = 'render',
+    width = 240,
+    height = 180,
+    samples = 2,
+    randomize = false,
+    reset = false,
+    seed = Date.now() >>> 0,
+    customColors = null,
+    requestId = 0,
+  } = event.data ?? {};
+
+  if (type !== 'render') return;
+
+  try {
+    const wasm = await wasmPromise;
+
+    if (reset) {
+      wasm._reset_colors();
+    } else if (randomize) {
+      wasm._randomize_colors(seed >>> 0);
+    }
+
+    if (Array.isArray(customColors)) {
+      for (const item of customColors) {
+        if (
+          item &&
+          typeof item.index === 'number' &&
+          typeof item.r === 'number' &&
+          typeof item.g === 'number' &&
+          typeof item.b === 'number'
+        ) {
+          wasm._set_sphere_color(item.index, item.r, item.g, item.b);
+        }
