+  <script>
+    (function () {
+      const SPHERE_METADATA = [
+        { index: 0, name: 'Left Sphere (Wall)', material: 'DIFF' },
+        { index: 1, name: 'Right Sphere (Wall)', material: 'DIFF' },
+        { index: 2, name: 'Back Sphere (Wall)', material: 'DIFF' },
+        { index: 4, name: 'Bottom Sphere (Floor)', material: 'DIFF' },
+        { index: 5, name: 'Top Sphere (Ceiling)', material: 'DIFF' },
+        { index: 6, name: 'Mirror Sphere', material: 'SPEC' },
+        { index: 7, name: 'Glass Sphere', material: 'REFR' }
+      ];
+
+      const canvas = document.getElementById('render-canvas');
+      const ctx = canvas.getContext('2d');
+      const randomizeBtn = document.getElementById('randomize-btn');
+      const resetLink = document.getElementById('reset-colors-link');
+      const resolutionSelect = document.getElementById('resolution-select');
+      const samplesSelect = document.getElementById('samples-select');
+      const statusBadge = document.getElementById('wasm-status');
+      const renderStats = document.getElementById('render-stats');
+      const runCounterEl = document.getElementById('run-counter');
+      const progressFill = document.getElementById('progress-fill');
+      const swatchesContainer = document.getElementById('sphere-swatches');
+
+      let wasmExports = null;
+      let rafId = null;
+      let runNumber = 0;
+      let currentPass = 0;
+      let targetPasses = 8;
+      let renderStartTime = 0;
+
+      function toDisplayByte(linearVal) {
+        const clamped = Math.max(0, Math.min(1, linearVal));
+        return Math.min(255, Math.max(0, Math.floor(Math.pow(clamped, 1 / 2.2) * 255 + 0.5)));
+      }
+
+      function rgbToHex(r, g, b) {
+        const toHex = (n) => n.toString(16).padStart(2, '0').toUpperCase();
+        return '#' + toHex(r) + toHex(g) + toHex(b);
+      }
+
+      function updateSwatchesUI() {
+        if (!wasmExports) return;
+        swatchesContainer.innerHTML = '';
+        for (const item of SPHERE_METADATA) {
+          const rLin = wasmExports.get_sphere_color_channel(item.index, 0);
+          const gLin = wasmExports.get_sphere_color_channel(item.index, 1);
+          const bLin = wasmExports.get_sphere_color_channel(item.index, 2);
+
+          const r = toDisplayByte(rLin);
+          const g = toDisplayByte(gLin);
+          const b = toDisplayByte(bLin);
+          const hex = rgbToHex(r, g, b);
+
+          const row = document.createElement('div');
+          row.className = 'swatch-item';
+          row.dataset.sphereIndex = String(item.index);
+          row.dataset.sphereColor = hex;
+          row.innerHTML = `
+            <div class="swatch-left">
+              <span class="swatch-color" style="background-color: ${hex};"></span>
+              <span>${item.name}</span>
+            </div>
+            <span class="swatch-hex">${hex}</span>
+          `;
+          swatchesContainer.appendChild(row);
+        }
+      }
+
+      function getSelectedResolution() {
+        const [w, h] = resolutionSelect.value.split('x').map(Number);
+        return { w: w || 240, h: h || 180 };
+      }
+
+      function drawFramebufferToCanvas(ptr, w, h) {
+        if (canvas.width !== w || canvas.height !== h) {
+          canvas.width = w;
+          canvas.height = h;
+        }
+        const byteCount = w * h * 4;
+        const pixels = new Uint8ClampedArray(wasmExports.memory.buffer, ptr, byteCount);
+        const imageData = new ImageData(new Uint8ClampedArray(pixels), w, h);
+        ctx.putImageData(imageData, 0, 0);
+      }
+
+      function executeRenderPassSync(w, h) {
+        const seed = ((runNumber * 2654435761) ^ (currentPass * 2246822519)) >>> 0;
+        const ptr = wasmExports.render_pass(w, h, 1, seed);
+        currentPass += 1;
+        drawFramebufferToCanvas(ptr, w, h);
+
+        const totalSpp = currentPass * 4;
+        const elapsedMs = Math.round(performance.now() - renderStartTime);
+        const pct = Math.min(100, Math.round((currentPass / targetPasses) * 100));
+        progressFill.style.width = pct + '%';
+        renderStats.textContent = `${w}×${h} | ${totalSpp} spp (${currentPass}/${targetPasses} passes) | ${elapsedMs} ms`;
+      }
+
+      function scheduleRemainingPasses(w, h) {
+        if (rafId !== null) {
+          cancelAnimationFrame(rafId);
+          rafId = null;
+        }
+        if (currentPass >= targetPasses) {
+          statusBadge.textContent = 'Render Complete (Wasm)';
+          return;
+        }
+        statusBadge.textContent = `Rendering in Wasm (${ Math.round((currentPass / targetPasses) * 100) }%)...`;
+        rafId = requestAnimationFrame(() => {
+          rafId = null;
+          executeRenderPassSync(w, h);
+          scheduleRemainingPasses(w, h);
+        });
+      }
+
+      function startNewRender({ randomize = false, reset = false } = {}) {
+        if (!wasmExports) return;
+        if (rafId !== null) {
+          cancelAnimationFrame(rafId);
+          rafId = null;
+        }
+
+        runNumber += 1;
+        if (reset) {
+          wasmExports.reset_sphere_colors();
+          runCounterEl.textContent = `Run #${runNumber} (Classic Colors)`;
+        } else if (randomize) {
+          const seed = ((Date.now() & 0xFFFFFFFF) ^ (Math.floor(Math.random() * 0xFFFFFFFF)) ^ (runNumber * 0x9E3779B9)) >>> 0;
+          wasmExports.randomize_sphere_colors(seed);
+          runCounterEl.textContent = `Run #${runNumber} (Randomized Colors)`;
+        } else {
+          runCounterEl.textContent = `Run #${runNumber} (Classic Cornell Box)`;
+        }
+
+        updateSwatchesUI();
+
+        const { w, h } = getSelectedResolution();
+        targetPasses = parseInt(samplesSelect.value, 10) || 8;
+        currentPass = 0;
+        renderStartTime = performance.now();
+
+        wasmExports.clear_accumulation(w, h);
+        // Perform the first pass synchronously so the canvas immediately displays the rendered output
+        executeRenderPassSync(w, h);
+        scheduleRemainingPasses(w, h);
+      }
+
+      async function loadSmallptWasm() {
+        try {
+          const response = await fetch('./smallpt.wasm');
+          if (!response.ok) {
+            throw new Error(`HTTP ${response.status}`);
+          }
+          if (WebAssembly.instantiateStreaming) {
+            try {
+              const result = await WebAssembly.instantiateStreaming(response, {});
+              return result.instance.exports;
+            } catch (_) {
+              const fallbackResp = await fetch('./smallpt.wasm');
+              const bytes = await fallbackResp.arrayBuffer();
+              const result = await WebAssembly.instantiate(bytes, {});
+              return result.instance.exports;
+            }
+          } else {
+            const bytes = await response.arrayBuffer();
+            const result = await WebAssembly.instantiate(bytes, {});
+            return result.instance.exports;
+          }
+        } catch (err) {
+          if (window.SMALLPT_WASM_BASE64) {
+            const binaryString = atob(window.SMALLPT_WASM_BASE64);
+            const bytes = new Uint8Array(binaryString.length);
+            for (let i = 0; i < binaryString.length; i++) {
+              bytes[i] = binaryString.charCodeAt(i);
+            }
+            const result = await WebAssembly.instantiate(bytes.buffer, {});
+            return result.instance.exports;
+          }
+          throw err;
+        }
+      }
+
+      randomizeBtn.addEventListener('click', () => {
+        startNewRender({ randomize: true });
+      });
+
+      resetLink.addEventListener('click', () => {
+        startNewRender({ reset: true });
+      });
+
+      resolutionSelect.addEventListener('change', () => {
+        startNewRender({ randomize: false });
+      });
+
+      samplesSelect.addEventListener('change', () => {
+        const { w, h } = getSelectedResolution();
+        targetPasses = parseInt(samplesSelect.value, 10) || 8;
+        scheduleRemainingPasses(w, h);
+      });
+
+      // Expose helper API on window for programmatic inspection
+      window.smallptApp = {
+        getExports: () => wasmExports,
+        randomizeAndRender: () => startNewRender({ randomize: true }),
+        resetAndRender: () => startNewRender({ reset: true })
+      };

+      loadSmallptWasm()
+        .then((exports) => {
+          wasmExports = exports;
+          if (typeof wasmExports.__wasm_call_ctors === 'function') {
+            wasmExports.__wasm_call_ctors();
+          }
+          startNewRender({ randomize: false });
+        })
+        .catch((err) => {
+          console.error('Failed to initialize smallpt.wasm:', err);
+          statusBadge.textContent = 'Wasm Load Error';
+        });
+    })();
+  </script>
