+#!/usr/bin/env bash
+set -euo pipefail
+
+# 1. Compile C++ source to an object file
+em++ -c src/wasm/smallpt.cpp -o src/wasm/smallpt.o -O3 -flto -Werror -Wall
+
+# 2. Link into an ES6 WebAssembly module targeting a Web Worker
+em++ src/wasm/smallpt.o -o src/wasm/smallpt.js \
+  -O3 -flto \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_render_frame,_randomize_sphere_colors,_reset_default_colors,_get_sphere_palette,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8 \
+  --closure=1
+
+# 3. Copy generated Wasm + loader + worker to public/wasm/ for direct browser/worker serving
+mkdir -p public/wasm
+cp src/wasm/smallpt.js src/wasm/smallpt.wasm src/wasm/smallpt.worker.js public/wasm/
