+import React, { useEffect, useRef, useState, useCallback } from 'react';
+
+interface PaletteSwatch {
+  label: string;
+  hex: string;
+  rgb: string;
+}
+
+interface WorkerResponse {
+  type: 'rendered' | 'error';
+  requestId: number;
+  pixels?: Uint8ClampedArray;
+  width?: number;
+  height?: number;
+  samples?: number;
+  elapsedMs?: number;
+  palette?: PaletteSwatch[];
+  randomized?: boolean;
+  seed?: number;
+  message?: string;
+}
+
+const DEFAULT_WIDTH = 320;
+const DEFAULT_HEIGHT = 240;
+const DEFAULT_SAMPLES = 16;
+
+export default function SmallptPathTracer() {
+  const canvasRef = useRef<HTMLCanvasElement | null>(null);
+  const workerRef = useRef<Worker | null>(null);
+  const requestIdRef = useRef<number>(0);
+
+  const [isRendering, setIsRendering] = useState<boolean>(true);
+  const [samples, setSamples] = useState<number>(DEFAULT_SAMPLES);
+  const [elapsedMs, setElapsedMs] = useState<number | null>(null);
+  const [renderCount, setRenderCount] = useState<number>(0);
+  const [palette, setPalette] = useState<PaletteSwatch[]>([]);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [lastSeed, setLastSeed] = useState<number | null>(null);
+
+  const triggerRender = useCallback(
+    (opts: { randomize?: boolean; resetDefault?: boolean; customSamples?: number } = {}) => {
+      if (!workerRef.current) return;
+      const nextRequestId = ++requestIdRef.current;
+      const seedArray = new Uint32Array(1);
+      crypto.getRandomValues(seedArray);
+      const seed = seedArray[0] || ((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0);
+
+      setIsRendering(true);
+      setErrorMessage(null);
+
+      workerRef.current.postMessage({
+        requestId: nextRequestId,
+        width: DEFAULT_WIDTH,
+        height: DEFAULT_HEIGHT,
+        samples: opts.customSamples ?? samples,
+        randomize: Boolean(opts.randomize),
+        resetDefault: Boolean(opts.resetDefault),
+        seed,
+      });
+    },
+    [samples]
+  );
+
+  useEffect(() => {
+    const worker = new Worker(
+      new URL('../wasm/smallpt.worker.js', import.meta.url),
+      { type: 'module' }
+    );
+    workerRef.current = worker;
+
+    worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
+      const data = event.data;
+      if (data.type === 'error') {
+        setErrorMessage(data.message || 'WebAssembly path tracer failed to render.');
+        setIsRendering(false);
+        return;
+      }
+
+      if (data.type === 'rendered' && data.pixels && data.width && data.height) {
+        const canvas = canvasRef.current;
+        if (canvas) {
+          const ctx = canvas.getContext('2d');
+          if (ctx) {
+            const clamped =
+              data.pixels instanceof Uint8ClampedArray
+                ? data.pixels
+                : new Uint8ClampedArray(data.pixels);
+            const imageData = new ImageData(clamped, data.width, data.height);
+            ctx.putImageData(imageData, 0, 0);
+          }
+        }
+        setElapsedMs(data.elapsedMs ?? null);
+        setPalette(data.palette ?? []);
+        if (data.randomized && data.seed !== undefined) {
+          setLastSeed(data.seed);
+        } else if (!data.randomized) {
+          setLastSeed(null);
+        }
+        setRenderCount((prev) => prev + 1);
+        setIsRendering(false);
+      }
+    };
+
+    // Initial render with classic Cornell Box colors
+    const initialRequestId = ++requestIdRef.current;
+    worker.postMessage({
+      requestId: initialRequestId,
+      width: DEFAULT_WIDTH,
+      height: DEFAULT_HEIGHT,
+      samples: DEFAULT_SAMPLES,
+      randomize: false,
+      resetDefault: true,
+      seed: 1,
+    });
+
+    return () => {
+      worker.terminate();
+      workerRef.current = null;
+    };
+  }, []);
+
+  const handleRandomizeColors = () => {
+    triggerRender({ randomize: true });
+  };
+
+  const handleResetDefault = () => {
+    triggerRender({ randomize: false, resetDefault: true });
+  };
+
+  const handleSamplesChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
+    const nextSamples = Number(e.target.value);
+    setSamples(nextSamples);
+    triggerRender({ randomize: false, customSamples: nextSamples });
+  };
+
+  return (
+    <section
+      id="smallpt-wasm-section"
+      aria-label="smallpt WebAssembly Path Tracer"
+      style={{ contain: 'layout style paint' }}
+      className="bg-slate-900 text-white rounded-xl shadow-lg border border-slate-800 p-6 md:p-8 my-6"
+    >
+      <div className="flex flex-col lg:flex-row gap-8 items-center">
+        {/* Left column: Canvas Output */}
+        <div className="relative flex-shrink-0 w-full max-w-[420px] aspect-[4/3] bg-black rounded-lg overflow-hidden border border-slate-700 shadow-inner flex items-center justify-center">
+          <canvas
+            id="smallpt-canvas"
+            ref={canvasRef}
+            width={DEFAULT_WIDTH}
+            height={DEFAULT_HEIGHT}
+            className="w-full h-full object-contain"
+          />
+          {isRendering && (
+            <div
+              role="status"
+              aria-live="polite"
+              className="absolute inset-0 bg-slate-950/60 backdrop-blur-[2px] flex flex-col items-center justify-center gap-2 text-amber-300 text-sm font-medium"
+            >
+              <div className="w-7 h-7 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />
+              <span>Tracing paths in WebAssembly ({samples} spp)…</span>
+            </div>
+          )}
+        </div>
+
+        {/* Right column: Controls, Description & Sphere Palette */}
+        <div className="flex-1 flex flex-col justify-between w-full">
+          <div>
+            <div className="inline-flex items-center gap-2 px-2.5 py-1 rounded-full bg-amber-500/15 text-amber-300 text-xs font-semibold tracking-wider uppercase mb-3">
+              <span>Interactive Lab • C++ to WebAssembly</span>
+            </div>
+            <h2 className="text-2xl md:text-3xl font-brand text-white leading-tight">
+              smallpt Global Illumination Path Tracer
+            </h2>
+            <p className="mt-2 text-slate-300 text-sm md:text-base leading-relaxed">
+              Kevin Beason&apos;s open-source 99-line C++ Monte Carlo path tracer compiled to{' '}
+              <code className="text-amber-300 font-mono text-xs bg-slate-800 px-1.5 py-0.5 rounded">
+                smallpt.wasm
+              </code>{' '}
+              with Emscripten (<code className="text-slate-300 font-mono text-xs">-O3 -flto</code>) and executed off the main thread inside a Web Worker. Features diffuse, mirror specular, and dielectric glass refraction with soft area lighting.
+            </p>
+          </div>
+
+          {errorMessage && (
+            <div className="mt-4 p-3 rounded-lg bg-red-900/50 border border-red-700 text-red-200 text-sm">
+              {errorMessage}
+            </div>
+          )}
+
+          {/* Action Buttons & Quality Selector */}
+          <div className="mt-6 flex flex-wrap items-center gap-3">
+            <button
+              id="randomize-colors-btn"
+              type="button"
+              onClick={handleRandomizeColors}
+              disabled={isRendering}
+              className="px-5 py-2.5 rounded-lg bg-amber-400 hover:bg-amber-300 disabled:bg-amber-500/50 text-slate-950 font-semibold text-sm shadow transition-colors cursor-pointer disabled:cursor-wait"
+            >
+              Randomize Sphere Colors
+            </button>
+
+            <button
+              id="reset-colors-btn"
+              type="button"
+              onClick={handleResetDefault}
+              disabled={isRendering}
+              className="px-4 py-2.5 rounded-lg bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-slate-200 font-medium text-sm border border-slate-700 transition-colors cursor-pointer"
+            >
+              Reset Classic Box
+            </button>
+
+            <label className="flex items-center gap-2 text-xs text-slate-300 ml-auto">
+              <span>Quality:</span>
+              <select
+                aria-label="Samples per pixel"
+                value={samples}
+                onChange={handleSamplesChange}
+                disabled={isRendering}
+                className="bg-slate-800 border border-slate-700 text-white rounded px-2.5 py-1.5 text-xs font-medium"
+              >
+                <option value={8}>8 SPP (Fast)</option>
+                <option value={16}>16 SPP (Default)</option>
+                <option value={32}>32 SPP (Detailed)</option>
+                <option value={64}>64 SPP (High Quality)</option>
+              </select>
+            </label>
+          </div>
+
+          {/* Active Sphere Colors Palette */}
+          {palette.length > 0 && (
+            <div className="mt-5 pt-4 border-t border-slate-800">
+              <div className="flex items-center justify-between text-xs text-slate-400 mb-2">
+                <span>Active Scene Sphere Colors (from Wasm Memory)</span>
+                {lastSeed !== null && (
+                  <span className="font-mono text-amber-300/90">Seed #{lastSeed.toString(16).toUpperCase()}</span>
+                )}
+              </div>
+              <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
+                {palette.map((item) => (
+                  <div
+                    key={item.label}
+                    className="flex items-center gap-2 bg-slate-800/80 border border-slate-700/70 rounded px-2 py-1.5"
+                  >
+                    <span
+                      className="w-3.5 h-3.5 rounded-full border border-white/20 flex-shrink-0"
+                      style={{ backgroundColor: item.rgb }}
+                    />
+                    <div className="truncate">
+                      <div className="text-[10px] text-slate-300 truncate">{item.label}</div>
+                      <div className="text-[10px] font-mono text-slate-400 uppercase">{item.hex}</div>
+                    </div>
+                  </div>
+                ))}
+              </div>
+            </div>
+          )}
+
+          {/* Render Telemetry Footer */}
+          <div className="mt-4 pt-3 border-t border-slate-800/80 flex flex-wrap gap-4 text-xs text-slate-400 font-mono">
+            <span>
+              Resolution: <strong className="text-slate-200">{DEFAULT_WIDTH}×{DEFAULT_HEIGHT}</strong>
+            </span>
+            <span>
+              Samples: <strong className="text-slate-200">{samples} spp</strong>
+            </span>
+            <span>
+              Render Time:{' '}
+              <strong className="text-amber-300">
+                {elapsedMs !== null ? `${elapsedMs} ms` : 'Rendering…'}
+              </strong>
+            </span>
+            <span>
+              Frames Rendered: <strong className="text-slate-200">{renderCount}</strong>
+            </span>
+          </div>
+        </div>
+      </div>
+    </section>
+  );
+}
