+import initSmallpt from './smallpt.js';
+
+let wasmPromise = null;
+
+function getWasm() {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt();
+  }
+  return wasmPromise;
+}
+
+self.addEventListener('message', async (event) => {
+  const {
+    width = 320,
+    height = 240,
+    samples = 16,
+    randomize = false,
+    seed = Date.now() >>> 0,
+    requestId = 0,
+  } = event.data || {};
+
+  try {
+    const wasm = await getWasm();
+
+    if (randomize) {
+      wasm._randomize_sphere_colors(seed >>> 0);
+    } else if (event.data?.resetDefault) {
+      wasm._reset_default_colors();
+    }
+
+    const byteLength = width * height * 4;
+    const paletteLength = 18;
+    const ptr = wasm._malloc(byteLength);
+    const palettePtr = wasm._malloc(paletteLength);
+
+    try {
+      const startTime = performance.now();
+      wasm._render_frame(ptr, width, height, samples);
+      wasm._get_sphere_palette(palettePtr);
+      const elapsedMs = Math.round(performance.now() - startTime);
+
+      // Re-read wasm.HEAPU8.buffer after Wasm execution in case memory grew
+      const heapBuffer = wasm.HEAPU8.buffer;
+      const pixels = new Uint8ClampedArray(heapBuffer, ptr, byteLength).slice();
+      const paletteBytes = new Uint8Array(heapBuffer, palettePtr, paletteLength).slice();
+
+      const palette = [];
+      const labels = ['Left Wall', 'Right Wall', 'Back Wall', 'Floor', 'Mirror Sphere', 'Glass Sphere'];
+      for (let i = 0; i < 6; i++) {
+        const r = paletteBytes[i * 3 + 0];
+        const g = paletteBytes[i * 3 + 1];
+        const b = paletteBytes[i * 3 + 2];
+        palette.push({
+          label: labels[i],
+          hex: `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`,
+          rgb: `rgb(${r}, ${g}, ${b})`,
+        });
+      }
+
+      self.postMessage(
+        {
+          type: 'rendered',
+          requestId,
+          pixels,
+          width,
+          height,
+          samples,
+          elapsedMs,
+          palette,
+          randomized: Boolean(randomize),
+          seed,
+        },
+        [pixels.buffer],
+      );
+    } finally {
+      wasm._free(palettePtr);
+      wasm._free(ptr);
+    }
+  } catch (err) {
+    self.postMessage({
+      type: 'error',
+      requestId,
+      message: err instanceof Error ? err.message : String(err),
+    });
+  }
