--- /dev/null
+++ b/src/components/SmallptPathTracer.tsx
@@ -0,0 +1,353 @@
+import React, { useEffect, useRef, useState, useCallback } from 'react';
+
+interface SmallptWasmExports {
+  memory: WebAssembly.Memory;
+  _initialize?: () => void;
+  get_pixels: () => number;
+  get_sphere_count: () => number;
+  get_sphere_color: (index: number, channel: number) => number;
+  set_sphere_color: (index: number, r: number, g: number, b: number) => void;
+  reset_sphere_colors: () => void;
+  randomize_sphere_colors: (seed: number) => void;
+  reset_accum: () => void;
+  get_sample_count: () => number;
+  render_pass: (w: number, h: number, samps: number, seed: number) => number;
+  render: (w: number, h: number, samps: number, seed: number) => number;
+}
+
+interface SphereColorInfo {
+  index: number;
+  name: string;
+  material: string;
+  rgb: [number, number, number];
+}
+
+const SPHERE_METADATA: { index: number; name: string; material: string }[] = [
+  { index: 0, name: 'Left Wall', material: 'DIFF' },
+  { index: 1, name: 'Right Wall', material: 'DIFF' },
+  { index: 2, name: 'Back Wall', material: 'DIFF' },
+  { index: 4, name: 'Floor', material: 'DIFF' },
+  { index: 6, name: 'Mirror Sphere', material: 'SPEC' },
+  { index: 7, name: 'Glass Sphere', material: 'REFR' },
+];
+
+const WIDTH = 256;
+const HEIGHT = 192;
+const TARGET_PASSES = 4; // 4 passes * 4 subpixels = 16 spp
+
+function toCssHex(r: number, g: number, b: number): string {
+  const clamp = (x: number) => Math.max(0, Math.min(1, x));
+  const toByte = (x: number) => Math.round(Math.pow(clamp(x), 1 / 2.2) * 255);
+  return (
+    '#' +
+    [toByte(r), toByte(g), toByte(b)]
+      .map((v) => v.toString(16).padStart(2, '0'))
+      .join('')
+  );
+}
+
+export default function SmallptPathTracer() {
+  const canvasRef = useRef<HTMLCanvasElement | null>(null);
+  const wasmRef = useRef<SmallptWasmExports | null>(null);
+  const rafRef = useRef<number | null>(null);
+  const seedRef = useRef<number>(1);
+
+  const [status, setStatus] = useState<'loading' | 'rendering' | 'ready' | 'error'>('loading');
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [samplesPerPixel, setSamplesPerPixel] = useState<number>(0);
+  const [renderTimeMs, setRenderTimeMs] = useState<number>(0);
+  const [renderRunCount, setRenderRunCount] = useState<number>(0);
+  const [sphereColors, setSphereColors] = useState<SphereColorInfo[]>([]);
+
+  const readSphereColorsFromWasm = useCallback((exports: SmallptWasmExports) => {
+    const list: SphereColorInfo[] = SPHERE_METADATA.map((meta) => ({
+      ...meta,
+      rgb: [
+        exports.get_sphere_color(meta.index, 0),
+        exports.get_sphere_color(meta.index, 1),
+        exports.get_sphere_color(meta.index, 2),
+      ],
+    }));
+    setSphereColors(list);
+  }, []);
+
+  const drawWasmBufferToCanvas = useCallback((exports: SmallptWasmExports, ptr: number) => {
+    const canvas = canvasRef.current;
+    if (!canvas) return;
+    const ctx = canvas.getContext('2d');
+    if (!ctx) return;
+
+    const byteLength = WIDTH * HEIGHT * 4;
+    const wasmBytes = new Uint8ClampedArray(exports.memory.buffer, ptr, byteLength);
+    const copy = new Uint8ClampedArray(byteLength);
+    copy.set(wasmBytes);
+    const imageData = new ImageData(copy, WIDTH, HEIGHT);
+    ctx.putImageData(imageData, 0, 0);
+  }, []);
+
+  const cancelProgressiveLoop = useCallback(() => {
+    if (rafRef.current !== null) {
+      cancelAnimationFrame(rafRef.current);
+      rafRef.current = null;
+    }
+  }, []);
+
+  const runRenderWithCurrentScene = useCallback(
+    (exports: SmallptWasmExports) => {
+      cancelProgressiveLoop();
+      setStatus('rendering');
+
+      const startTime = performance.now();
+      const baseSeed = seedRef.current++;
+
+      // Synchronous first pass so the canvas immediately displays the new render
+      const ptr = exports.render(WIDTH, HEIGHT, 1, baseSeed * 97 + 1);
+      drawWasmBufferToCanvas(exports, ptr);
+
+      let completedPasses = 1;
+      let totalElapsed = performance.now() - startTime;
+      setSamplesPerPixel(exports.get_sample_count());
+      setRenderTimeMs(Math.round(totalElapsed));
+      setRenderRunCount((c) => c + 1);
+
+      const step = () => {
+        if (completedPasses >= TARGET_PASSES) {
+          setStatus('ready');
+          rafRef.current = null;
+          return;
+        }
+        const passStart = performance.now();
+        const nextPtr = exports.render_pass(
+          WIDTH,
+          HEIGHT,
+          1,
+          baseSeed * 97 + completedPasses * 31 + 7
+        );
+        drawWasmBufferToCanvas(exports, nextPtr);
+        completedPasses += 1;
+        totalElapsed += performance.now() - passStart;
+        setSamplesPerPixel(exports.get_sample_count());
+        setRenderTimeMs(Math.round(totalElapsed));
+
+        if (completedPasses < TARGET_PASSES) {
+          rafRef.current = requestAnimationFrame(step);
+        } else {
+          setStatus('ready');
+          rafRef.current = null;
+        }
+      };
+
+      rafRef.current = requestAnimationFrame(step);
+    },
+    [cancelProgressiveLoop, drawWasmBufferToCanvas]
+  );
+
+  useEffect(() => {
+    let mounted = true;
+
+    async function initWasm() {
+      try {
+        const baseUrl = import.meta.env.BASE_URL || '/';
+        const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+        const candidateUrls = [
+          `${normalizedBase}smallpt.wasm`,
+          '/devtools-times/smallpt.wasm',
+          '/smallpt.wasm',
+        ];
+
+        let response: Response | null = null;
+        for (const url of candidateUrls) {
+          try {
+            const res = await fetch(url);
+            if (res.ok) {
+              response = res;
+              break;
+            }
+          } catch {
+            // try next candidate
+          }
+        }
+
+        if (!response) {
+          throw new Error('Failed to fetch smallpt.wasm');
+        }
+
+        let instance: WebAssembly.Instance;
+        if ('instantiateStreaming' in WebAssembly) {
+          try {
+            const cloned = response.clone();
+            const result = await WebAssembly.instantiateStreaming(cloned, {});
+            instance = result.instance;
+          } catch {
+            const bytes = await response.arrayBuffer();
+            const result = await WebAssembly.instantiate(bytes, {});
+            instance = result.instance;
+          }
+        } else {
+          const bytes = await response.arrayBuffer();
+          const result = await WebAssembly.instantiate(bytes, {});
+          instance = result.instance;
+        }
+
+        if (!mounted) return;
+
+        const exports = instance.exports as unknown as SmallptWasmExports;
+        if (typeof exports._initialize === 'function') {
+          exports._initialize();
+        }
+
+        wasmRef.current = exports;
+        readSphereColorsFromWasm(exports);
+        runRenderWithCurrentScene(exports);
+      } catch (err) {
+        if (!mounted) return;
+        setStatus('error');
+        setErrorMessage(err instanceof Error ? err.message : String(err));
+      }
+    }
+
+    initWasm();
+
+    return () => {
+      mounted = false;
+      cancelProgressiveLoop();
+    };
+  }, [cancelProgressiveLoop, readSphereColorsFromWasm, runRenderWithCurrentScene]);
+
+  const handleRandomizeColors = useCallback(() => {
+    const exports = wasmRef.current;
+    if (!exports) return;
+
+    const randomSeed =
+      ((Date.now() & 0xffff) ^ Math.floor(Math.random() * 0x7fffffff)) >>> 0 || 1;
+    exports.randomize_sphere_colors(randomSeed);
+    readSphereColorsFromWasm(exports);
+    runRenderWithCurrentScene(exports);
+  }, [readSphereColorsFromWasm, runRenderWithCurrentScene]);
+
+  const handleResetColors = useCallback(() => {
+    const exports = wasmRef.current;
+    if (!exports) return;
+
+    exports.reset_sphere_colors();
+    readSphereColorsFromWasm(exports);
+    runRenderWithCurrentScene(exports);
+  }, [readSphereColorsFromWasm, runRenderWithCurrentScene]);
+
+  return (
+    <section
+      id="smallpt-wasm-section"
+      data-testid="smallpt-wasm-section"
+      className="my-6 bg-gray-900 text-white rounded-lg shadow-lg border border-gray-800 overflow-hidden"
+    >
+      <div className="p-5 md:p-6 border-b border-gray-800 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
+        <div>
+          <div className="flex items-center gap-2">
+            <span className="inline-block px-2 py-0.5 text-xs font-semibold uppercase tracking-wider bg-amber-500 text-gray-950 rounded">
+              WebAssembly Path Tracer
+            </span>
+            <span
+              data-testid="smallpt-status"
+              className="text-xs font-mono text-gray-400"
+            >
+              {status === 'loading' && 'Loading smallpt.wasm...'}
+              {status === 'rendering' && `Rendering in WASM (${samplesPerPixel} spp)...`}
+              {status === 'ready' && `Complete (${samplesPerPixel} spp in ${renderTimeMs} ms)`}
+              {status === 'error' && `Error: ${errorMessage}`}
+            </span>
+          </div>
+          <h2 className="text-xl md:text-2xl font-bold mt-1">
+            smallpt: Global Illumination in C++ Compiled to WebAssembly
+          </h2>
+          <p className="text-xs md:text-sm text-gray-400 mt-0.5">
+            Kevin Beason&apos;s Monte Carlo path tracer (<code className="text-amber-300">smallpt.cpp</code> → <code className="text-amber-300">smallpt.wasm</code>) running client-side in your browser.
+          </p>
+        </div>
+
+        <div className="flex flex-wrap items-center gap-3">
+          <button
+            id="randomize-sphere-colors-btn"
+            data-testid="randomize-sphere-colors-btn"
+            type="button"
+            onClick={handleRandomizeColors}
+            disabled={status === 'loading'}
+            className="bg-amber-500 hover:bg-amber-400 disabled:opacity-50 text-gray-950 font-bold text-sm px-4 py-2.5 rounded shadow transition cursor-pointer"
+          >
+            Run Again with Randomized Sphere Colors
+          </button>
+          <button
+            id="reset-sphere-colors-btn"
+            data-testid="reset-sphere-colors-btn"
+            type="button"
+            onClick={handleResetColors}
+            disabled={status === 'loading'}
+            className="bg-gray-800 hover:bg-gray-700 disabled:opacity-50 text-gray-200 font-medium text-xs px-3 py-2.5 rounded border border-gray-700 transition cursor-pointer"
+          >
+            Reset Cornell Box Colors
+          </button>
+        </div>
+      </div>
+
+      <div className="p-5 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-center">
+        <div className="lg:col-span-7 flex flex-col items-center">
+          <div className="relative bg-black rounded border border-gray-700 overflow-hidden shadow-inner">
+            <canvas
+              id="smallpt-canvas"
+              data-testid="smallpt-canvas"
+               data-render-count={renderRunCount}
+              ref={canvasRef}
+              width={WIDTH}
+              height={HEIGHT}
+              className="w-full max-w-[512px] h-auto block"
+              style={{ imageRendering: 'auto', aspectRatio: `${WIDTH} / ${HEIGHT}` }}
+            />
+          </div>
+          <div className="mt-2 flex items-center justify-between w-full max-w-[512px] text-xs text-gray-400 font-mono">
+            <span>Resolution: {WIDTH}×{HEIGHT}</span>
+            <span>Samples/pixel: {samplesPerPixel}</span>
+            <span>Render #{renderRunCount} ({renderTimeMs} ms)</span>
+          </div>
+        </div>
+
+        <div className="lg:col-span-5 space-y-4">
+          <div>
+            <h3 className="text-sm font-semibold uppercase tracking-wider text-gray-300 mb-2">
+              Active Scene Sphere Colors
+            </h3>
+            <div className="grid grid-cols-2 gap-2.5">
+              {sphereColors.map((sphere) => {
+                const hex = toCssHex(sphere.rgb[0], sphere.rgb[1], sphere.rgb[2]);
+                return (
+                  <div
+                    key={sphere.index}
+                    className="flex items-center gap-2.5 bg-gray-800/80 border border-gray-700/80 rounded px-3 py-2"
+                  >
+                    <span
+                      className="w-5 h-5 rounded-full border border-white/20 shrink-0"
+                      style={{ backgroundColor: hex }}
+                    />
+                    <div className="min-w-0">
+                      <div className="text-xs font-semibold text-gray-100 truncate">
+                        {sphere.name}
+                      </div>
+                      <div className="text-[11px] font-mono text-gray-400">
+                        {hex.toUpperCase()} · {sphere.material}
+                      </div>
+                    </div>
+                  </div>
+                );
+              })}
+            </div>
+          </div>
+
+          <div className="bg-gray-800/50 border border-gray-800 rounded p-3 text-xs text-gray-300 space-y-1">
+            <div className="font-semibold text-amber-400">Path Tracer Features</div>
+            <p className="text-gray-400 leading-relaxed">
+              Renders the 9-sphere Cornell Box scene using Monte Carlo ray tracing with diffuse, ideal specular (mirror), and dielectric refractive (glass, Fresnel + Snell&apos;s Law) spheres, 2×2 tent-filtered subpixels, Russian roulette termination, and explicit light sampling.
+            </p>
+          </div>
+        </div>
+      </div>
+    </section>
+  );
+}
