new file mode 100644
index 0000000..b4c6637
--- /dev/null
+++ b/src/wasm/smallpt.cpp
@@ -0,0 +1,266 @@
+// smallpt, a Path Tracer by Kevin Beason, 2008 (http://www.kevinbeason.com/smallpt/)
+// Compiled to WebAssembly (WASM) for client-side execution in the browser.
+
+#include <math.h>
+#include <stdlib.h>
+#include <stdio.h>
+
+struct Vec {        // Usage: time ./smallpt 5000 && xv image.ppm
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(Vec&b){return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
+
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+
+enum Refl_t { DIFF, SPEC, REFR };  // material types, used in radiance()
+
+struct Sphere {
+  double rad;       // radius
+  Vec p, e, c;      // position, emission, color
+  Refl_t refl;      // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_):
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p-r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps=1e-4, b=op.dot(r.d), det=b*b-op.dot(op)+rad*rad;
+    if (det<0) return 0; else det=sqrt(det);
+    return (t=b-det)>eps ? t : ((t=b+det)>eps ? t : 0);
+  }
+};
+
+Sphere spheres[] = {//Scene: radius, position, emission, color, material
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+
+inline double clamp(double x){ return x<0 ? 0 : x>1 ? 1 : x; }
+inline int toInt(double x){ return int(pow(clamp(x),1/2.2)*255+.5); }
+inline bool intersect(const Ray &r, double &t, int &id){
+  double n=sizeof(spheres)/sizeof(Sphere), d, inf=t=1e20;
+  for(int i=int(n);i--;) if((d=spheres[i].intersect(r))&&d<t){t=d;id=i;}
+  return t<inf;
+}
+
+Vec radiance(const Ray &r, int depth, unsigned short *Xi, int E=1){
+  double t;                               // distance to intersection
+  int id=0;                               // id of intersected object
+  if (!intersect(r, t, id)) return Vec(); // if miss, return black
+  const Sphere &obj = spheres[id];        // the hit object
+  Vec x=r.o+r.d*t, n=(x-obj.p).norm(), nl=n.dot(r.d)<0?n:n*-1, f=obj.c;
+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5 || !p) {
+    if (erand48(Xi)<p && depth<32) f=f*(1/p);
+    else return obj.e*E; // R.R.
+  }
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
+    double r1=2*M_PI*erand48(Xi), r2=erand48(Xi), r2s=sqrt(r2);
+    Vec w=nl, u=((fabs(w.x)>.1?Vec(0,1):Vec(1))%w).norm(), v=w%u;
+    Vec d = (u*cos(r1)*r2s + v*sin(r1)*r2s + w*sqrt(1-r2)).norm();
+
+    // Explicit ceiling light sampling (Next Event Estimation on spheres[8])
+    Vec e;
+    double lr1 = 2*M_PI*erand48(Xi), lr2 = 17.9 * sqrt(erand48(Xi));
+    double ly = 681.33 - sqrt(600.0*600.0 - lr2*lr2);
+    Vec lp(50.0 + lr2*cos(lr1), ly, 81.6 + lr2*sin(lr1));
+    Vec ld = lp - x;
+    double dist2 = ld.dot(ld);
+    ld.norm();
+    double cos_a = nl.dot(ld), cos_l = ld.y;
+    if (cos_a > 0 && cos_l > 0) {
+      double st; int sid = 0;
+      if (intersect(Ray(x, ld), st, sid) && sid == 8) {
+        double omega = (M_PI * 17.9 * 17.9) * cos_l / dist2;
+        e = e + f.mult(spheres[8].e * (cos_a * omega * M_1_PI));
+      }
+    }
+    return obj.e*E + e + f.mult(radiance(Ray(x,d),depth,Xi,0));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x,r.d-n*2*n.dot(r.d)),depth,Xi,1));
+  Ray reflRay(x, r.d-n*2*n.dot(r.d));     // Ideal dielectric REFRACTION
+  bool into = n.dot(nl)>0;                // Ray from outside going in?
+  double nc=1, nt=1.5, nnt=into?nc/nt:nt/nc, ddn=r.d.dot(nl), cos2t;
+  if ((cos2t=1-nnt*nnt*(1-ddn*ddn))<0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay,depth,Xi,1));
+  Vec tdir = (r.d*nnt - n*((into?1:-1)*(ddn*nnt+sqrt(cos2t)))).norm();
+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi,1)*RP:radiance(Ray(x,tdir),depth,Xi,1)*TP) :
+    radiance(reflRay,depth,Xi,1)*Re+radiance(Ray(x,tdir),depth,Xi,1)*Tr);
+}
+
+static const int MAX_PIXELS = 1024 * 768;
+static unsigned char pixels[MAX_PIXELS * 4];
+static double accum[MAX_PIXELS * 3];
+static int accum_passes = 0;
+static int last_w = 0;
+static int last_h = 0;
+
+static Vec hsvToRgb(double h, double s, double v) {
+  double c = v * s;
+  double hp = fmod(h * 6.0, 6.0);
+  double x = c * (1.0 - fabs(fmod(hp, 2.0) - 1.0));
+  double m = v - c;
+  double r = 0, g = 0, b = 0;
+  if (hp < 1.0)      { r = c; g = x; b = 0; }
+  else if (hp < 2.0) { r = x; g = c; b = 0; }
+  else if (hp < 3.0) { r = 0; g = c; b = x; }
+  else if (hp < 4.0) { r = 0; g = x; b = c; }
+  else if (hp < 5.0) { r = x; g = 0; b = c; }
+  else               { r = c; g = 0; b = x; }
+  return Vec(r + m, g + m, b + m);
+}
+
+extern "C" {
+
+  __attribute__((export_name("get_pixels")))
+  unsigned char* get_pixels() {
+    return pixels;
+  }
+
+  __attribute__((export_name("get_sphere_count")))
+  int get_sphere_count() {
+    return int(sizeof(spheres) / sizeof(Sphere));
+  }
+
+  __attribute__((export_name("get_sphere_color")))
+  double get_sphere_color(int index, int channel) {
+    if (index < 0 || index >= get_sphere_count()) return 0.0;
+    if (channel == 0) return spheres[index].c.x;
+    if (channel == 1) return spheres[index].c.y;
+    return spheres[index].c.z;
+  }
+
+  __attribute__((export_name("reset_accum")))
+  void reset_accum() {
+    int n = (last_w > 0 && last_h > 0) ? (last_w * last_h * 3) : (MAX_PIXELS * 3);
+    if (n > MAX_PIXELS * 3) n = MAX_PIXELS * 3;
+    for (int i = 0; i < n; i++) accum[i] = 0.0;
+    accum_passes = 0;
+  }
+
+  __attribute__((export_name("get_sample_count")))
+  int get_sample_count() {
+    return accum_passes * 4;
+  }
+
+  __attribute__((export_name("set_sphere_color")))
+  void set_sphere_color(int index, double r, double g, double b) {
+    if (index < 0 || index >= get_sphere_count()) return;
+    spheres[index].c = Vec(clamp(r), clamp(g), clamp(b));
+    reset_accum();
+  }
+
+  __attribute__((export_name("reset_sphere_colors")))
+  void reset_sphere_colors() {
+    spheres[0].c = Vec(.75, .25, .25);      // Left wall
+    spheres[1].c = Vec(.25, .25, .75);      // Right wall
+    spheres[2].c = Vec(.75, .75, .75);      // Back wall
+    spheres[3].c = Vec(0, 0, 0);            // Front wall
+    spheres[4].c = Vec(.75, .75, .75);      // Bottom floor
+    spheres[5].c = Vec(.75, .75, .75);      // Top ceiling
+    spheres[6].c = Vec(1, 1, 1) * .999;     // Mirror sphere
+    spheres[7].c = Vec(1, 1, 1) * .999;     // Glass sphere
+    spheres[8].c = Vec(0, 0, 0);            // Light
+    reset_accum();
+  }
+
+  __attribute__((export_name("randomize_sphere_colors")))
+  void randomize_sphere_colors(unsigned int seed) {
+    unsigned short Xi[3] = {
+      (unsigned short)((seed & 0xFFFF) ^ 0x330E),
+      (unsigned short)(((seed >> 16) & 0xFFFF) ^ 0xABCD),
+      (unsigned short)((seed * 2654435761u) & 0xFFFF)
+    };
+    double h0 = erand48(Xi);
+    double h1 = fmod(h0 + 0.28 + 0.44 * erand48(Xi), 1.0);
+    double h2 = erand48(Xi);
+    double h4 = erand48(Xi);
+    double h6 = erand48(Xi);
+    double h7 = fmod(h6 + 0.3 + 0.4 * erand48(Xi), 1.0);
+
+    // Left & Right walls: rich saturated hues
+    spheres[0].c = hsvToRgb(h0, 0.65 + 0.25 * erand48(Xi), 0.75 + 0.15 * erand48(Xi));
+    spheres[1].c = hsvToRgb(h1, 0.65 + 0.25 * erand48(Xi), 0.75 + 0.15 * erand48(Xi));
+    // Back wall & Floor: soft complementary tints
+    spheres[2].c = hsvToRgb(h2, 0.25 + 0.30 * erand48(Xi), 0.75 + 0.15 * erand48(Xi));
+    spheres[4].c = hsvToRgb(h4, 0.20 + 0.25 * erand48(Xi), 0.75 + 0.15 * erand48(Xi));
+    // Mirror & Glass spheres: vivid specular/refractive tints
+    spheres[6].c = hsvToRgb(h6, 0.45 + 0.45 * erand48(Xi), 0.98);
+    spheres[7].c = hsvToRgb(h7, 0.45 + 0.45 * erand48(Xi), 0.98);
+    reset_accum();
+  }
+
+  __attribute__((export_name("render_pass")))
+  unsigned char* render_pass(int w, int h, int samps, unsigned int seed) {
+    if (w <= 0 || h <= 0 || w * h > MAX_PIXELS) return pixels;
