+
+    for (int y=0; y<h; y++){
+      unsigned short Xi[3]={
+        (unsigned short)(y + pass_seed),
+        (unsigned short)(y * y + pass_seed * 131 + 17),
+        (unsigned short)(y * y * y + pass_seed * 997 + 53)
+      };
+      for (unsigned short x=0; x<w; x++) {
+        int i=(h-y-1)*w+x;
+        Vec c(0,0,0);
+        for (int sy=0; sy<2; sy++) {
