+  <script>
+    document.addEventListener("DOMContentLoaded", () => {
+      const roastSelect = document.getElementById("roast-picker");
+      if (!roastSelect) return;
+
+      // Check if browser supports customizable select (appearance: base-select)
+      if (!CSS.supports("appearance", "base-select")) {
+        // Degrades gracefully to a native OS <select> reading plain option text
+        return;
+      }
+
+      // Add Left/Right arrow key navigation that follows the 3-column horizontal grid geometry
+      roastSelect.addEventListener("keydown", (event) => {
+        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
+
+        const options = Array.from(roastSelect.querySelectorAll("option"));
+        const activeOption = document.activeElement?.closest("option") ||
+          roastSelect.querySelector("option:checked") ||
+          options[0];
+        if (!activeOption) return;
+
+        const currentRect = activeOption.getBoundingClientRect();
+        const isRight = event.key === "ArrowRight";
+
+        let nearestOption = null;
+        let nearestDistance = Infinity;
+
+        for (const option of options) {
+          if (option === activeOption) continue;
+          const rect = option.getBoundingClientRect();
+          const dx = rect.left - currentRect.left;
+
+          if ((isRight && dx > 0) || (!isRight && dx < 0)) {
+            const distance = Math.hypot(dx, rect.top - currentRect.top);
+            if (distance < nearestDistance) {
+              nearestDistance = distance;
+              nearestOption = option;
+            }
+          }
+        }
+
+        if (nearestOption) {
+          event.preventDefault();
+          nearestOption.focus();
+        }
+      });
+    });
+  </script>
