+    (function () {
+      const toggleBtn = document.getElementById('theme-toggle');
+      const iconEl = toggleBtn.querySelector('.theme-icon');
+      const labelEl = toggleBtn.querySelector('.theme-label');
+      const root = document.documentElement;
+      const body = document.body;
+      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function getSavedTheme() {
+        try {
+          return localStorage.getItem('theme');
+        } catch (e) {
+          return null;
+        }
+      }
+
+      function setSavedTheme(theme) {
+        try {
+          localStorage.setItem('theme', theme);
+        } catch (e) {
+          // Ignore storage errors
+        }
+      }
+
+      function getEffectiveTheme() {
+        const saved = getSavedTheme();
+        if (saved === 'dark' || saved === 'light') {
+          return saved;
+        }
+        return mediaQuery.matches ? 'dark' : 'light';
+      }
+
+      function applyTheme(theme) {
+        const isDark = theme === 'dark';
+        root.setAttribute('data-theme', theme);
+        body.setAttribute('data-theme', theme);
+        root.classList.toggle('dark-mode', isDark);
+        root.classList.toggle('light-mode', !isDark);
+        body.classList.toggle('dark-mode', isDark);
+        body.classList.toggle('light-mode', !isDark);
+
+        toggleBtn.setAttribute('aria-pressed', String(isDark));
+        toggleBtn.setAttribute(
+          'aria-label',
+          isDark ? 'Switch to light mode' : 'Switch to dark mode'
+        );
+        iconEl.textContent = isDark ? '☀️' : '🌙';
+        labelEl.textContent = isDark ? 'Light Mode' : 'Dark Mode';
+      }
+
+      applyTheme(getEffectiveTheme());
+
+      toggleBtn.addEventListener('click', function () {
+        const currentTheme = root.getAttribute('data-theme') || getEffectiveTheme();
+        const nextTheme = currentTheme === 'dark' ? 'light' : 'dark';
+        setSavedTheme(nextTheme);
+        applyTheme(nextTheme);
+      });
+
+      mediaQuery.addEventListener('change', function (e) {
+        const saved = getSavedTheme();
+        if (saved !== 'dark' && saved !== 'light') {
+          applyTheme(e.matches ? 'dark' : 'light');
+        }
+      });
+    })();
+  </script>
