+  <script>
+    (function () {
+      const meta = document.querySelector('meta[name="color-scheme"]');
+      const themeSelect = document.getElementById('theme-select');
+      const systemOption = document.getElementById('theme-option-system');
+      const darkMediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function updateSystemOptionLabel() {
+        if (!systemOption) return;
+        const currentSystem = darkMediaQuery.matches ? 'dark' : 'light';
+        systemOption.textContent = `System Default (Currently ${currentSystem})`;
+      }
+
+      function applyStoredTheme(storedValue) {
+        const isExplicit = storedValue === 'light' || storedValue === 'dark';
+        if (meta) {
+          meta.content = isExplicit ? storedValue : 'light dark';
+        }
+        if (themeSelect) {
+          themeSelect.value = isExplicit ? storedValue : 'system';
+        }
+      }
+
+      let initialStored = null;
+      try {
+        initialStored = localStorage.getItem('color-scheme');
+      } catch {}
+
+      applyStoredTheme(initialStored);
+      updateSystemOptionLabel();
+
+      darkMediaQuery.addEventListener('change', updateSystemOptionLabel);
+
+      if (themeSelect) {
+        themeSelect.addEventListener('change', (e) => {
+          const val = e.target.value;
+          if (val === 'light' || val === 'dark') {
+            if (meta) meta.content = val;
+            try {
+              localStorage.setItem('color-scheme', val);
+            } catch {}
+          } else {
+            if (meta) meta.content = 'light dark';
+            try {
+              localStorage.removeItem('color-scheme');
+            } catch {}
+          }
+        });
+      }
+
+      window.addEventListener('storage', (e) => {
+        if (e.key === 'color-scheme' || e.key === null) {
+          applyStoredTheme(e.newValue);
+        }
+      });
+    })();
+  </script>
