+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Fetch Priority Demo</title>
+</head>
+<body>
+  <button type="button" id="load-btn">Load Data</button>
+  <pre id="output" aria-live="polite"></pre>
+
+  <script type="module">
+    const button = document.getElementById('load-btn');
+    const output = document.getElementById('output');
+
+    button.addEventListener('click', async () => {
+      // Trigger both requests concurrently:
+      // 1. Mission-critical data uses default high fetch priority
+      const dataPromise = fetch('/api/data');
+
+      // 2. Non-critical analytics is explicitly deprioritized to avoid network contention
+      fetch('/api/analytics', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ click: 1 }),
+        priority: 'low'
+      }).catch(() => {});
+
+      try {
+        const response = await dataPromise;
+        output.textContent = await response.text();
+      } catch (error) {
+        output.textContent = 'Failed to load data.';
+      }
+    });
+  </script>
+</body>
+</html>

