+  <script>
+    /**
+     * Accurately determines visibility state history using the Performance API
+     * (VisibilityStateEntry).
+     */
+    function getVisibilityInfo() {
+      const entries = performance.getEntriesByType('visibility-state');
+
+      if (entries.length > 0) {
+        const firstEntry = entries[0];
+        const initiallyBackgrounded = firstEntry.name === 'hidden';
+
+        let timeBackgrounded = null;
+        for (const entry of entries) {
+          if (entry.name === 'hidden') {
+            timeBackgrounded = entry.startTime;
+            break;
+          }
+        }
+
+        return {
+          initiallyBackgrounded,
+          backgrounded: initiallyBackgrounded,
+          timeBackgrounded,
+          timestamp: timeBackgrounded !== null ? timeBackgrounded : firstEntry.startTime,
+          note: 'Measured via VisibilityStateEntry performance timeline entries; older fallback checks using document.visibilityState are unreliable for async scripts if the user foregrounds the tab before the script executes.'
+        };
+      }
+
+      return getFallbackVisibilityInfo();
+    }
+
+    /**
+     * Fallback implementation using document.visibilityState.
+     * Note: This approach is prone to race conditions and unreliable if the script loads asynchronously,
+     * because a background tab could be foregrounded before the script executes.
+     */
+    function getFallbackVisibilityInfo() {
+      let initiallyBackgrounded = document.visibilityState === 'hidden';
+      let timeBackgrounded = initiallyBackgrounded ? 0 : null;
+      const fallbackNote =
+        'Fallback check using document.visibilityState is unreliable and inaccurate for async scripts: if the page opened in a background tab and was foregrounded before this script executed, document.visibilityState synchronously reads as "visible", missing the initial hidden state, and performance.now() lacks internal browser timeline precision.';
+
+      document.addEventListener('visibilitychange', () => {
+        if (document.visibilityState === 'hidden' && timeBackgrounded === null) {
+          timeBackgrounded = performance.now();
+        }
+      });
+
+      return {
+        get initiallyBackgrounded() {
+          return initiallyBackgrounded;
+        },
+        get backgrounded() {
+          return initiallyBackgrounded;
+        },
+        get timeBackgrounded() {
+          return timeBackgrounded;
+        },
+        get timestamp() {
+          return timeBackgrounded !== null ? timeBackgrounded : performance.now();
+        },
+        note: fallbackNote
+      };
+    }
+
+    const visibilityStatus =
+      'VisibilityStateEntry' in window
+        ? getVisibilityInfo()
+        : getFallbackVisibilityInfo();
+
+    console.log({
+      initiallyBackgrounded: visibilityStatus.initiallyBackgrounded,
+      backgrounded: visibilityStatus.backgrounded,
+      timeBackgrounded: visibilityStatus.timeBackgrounded,
+      timestamp: visibilityStatus.timestamp,
+      note: visibilityStatus.note
