+        const computedEnds = [];
+        for (let i = 0; i < WOTS_TOTAL_CHAINS; i++) {
+          let node = sigObj.chains[i];
+          for (let step = digits[i]; step < WOTS_W - 1; step++) {
+            node = await wotsChainStep(node, pubObj.pubSeed, i, step);
