+      if (algName === 'RSA-PSS-2048') {
+        const keyPair = await window.crypto.subtle.generateKey(
+          {
+            name: 'RSA-PSS',
+            modulusLength: 2048,
+            publicExponent: new Uint8Array([1, 0, 1]),
+            hash: 'SHA-256'
+          },
+          true,
+          ['sign', 'verify']
+        );
+        const spki = new Uint8Array(await window.crypto.subtle.exportKey('spki', keyPair.publicKey));
+        const pkcs8 = new Uint8Array(await window.crypto.subtle.exportKey('pkcs8', keyPair.privateKey));
+        return {
+          publicKeyPem: formatPem(bytesToBase64(spki), 'PUBLIC KEY'),
+          privateKeyPem: formatPem(bytesToBase64(pkcs8), 'PRIVATE KEY'),
+          cryptoKeyPair: keyPair
+        };
+      }
