+        sigBuffer = await window.crypto.subtle.sign(
+          { name: 'ECDSA', hash: { name: 'SHA-256' } },
+          privKey,
+          messageBytes
+        );
+      } else if (algName === 'RSA-PSS-2048') {
+        sigBuffer = await window.crypto.subtle.sign(
+          { name: 'RSA-PSS', saltLength: 32 },
+          privKey,
+          messageBytes
+        );
+      } else if (algName === 'Ed25519') {
+        sigBuffer = await window.crypto.subtle.sign(
+          { name: 'Ed25519' },
+          privKey,
+          messageBytes
+        );
+      }
+      return bytesToBase64(new Uint8Array(sigBuffer));
+    }
