+        if (algName === 'ECDSA-P256') {
+          const pubKey = await window.crypto.subtle.importKey(
+            'spki',
+            spkiBytes.buffer,
+            { name: 'ECDSA', namedCurve: 'P-256' },
+            true,
+            ['verify']
+          );
+          return await window.crypto.subtle.verify(
+            { name: 'ECDSA', hash: { name: 'SHA-256' } },
+            pubKey,
+            sigBytes.buffer,
+            messageBytes
+          );
+        }
+
+        if (algName === 'RSA-PSS-2048') {
+          const pubKey = await window.crypto.subtle.importKey(
+            'spki',
+            spkiBytes.buffer,
+            { name: 'RSA-PSS', hash: 'SHA-256' },
+            true,
+            ['verify']
+          );
+          return await window.crypto.subtle.verify(
+            { name: 'RSA-PSS', saltLength: 32 },
+            pubKey,
+            sigBytes.buffer,
+            messageBytes
+          );
+        }
+
+        if (algName === 'Ed25519') {
+          try {
+            const pubKey = await window.crypto.subtle.importKey(
+              'spki',
+              spkiBytes.buffer,
+              { name: 'Ed25519' },
+              true,
+              ['verify']
+            );
+            return await window.crypto.subtle.verify(
+              { name: 'Ed25519' },
+              pubKey,
+              sigBytes.buffer,
+              messageBytes
+            );
+          } catch (_) {
+            const pubKey = await window.crypto.subtle.importKey(
+              'spki',
+              spkiBytes.buffer,
+              { name: 'ECDSA', namedCurve: 'P-256' },
+              true,
+              ['verify']
+            );
+            return await window.crypto.subtle.verify(
+              { name: 'ECDSA', hash: { name: 'SHA-256' } },
+              pubKey,
+              sigBytes.buffer,
+              messageBytes
+            );
+          }
+        }
+        return false;
+      } catch (e) {
+        return false;
+      }
+    }
