+    /*************************************************************************
+     * UNIFIED KEY PAIR REGISTRY & SIGN/VERIFY DISPATCHER
+     *************************************************************************/
+    const state = {
+      activeAlgorithm: 'ML-DSA-65',
+      keysByAlgorithm: {},
+      trustedPublicKeyRegistry: {}, // fingerprint -> { keyId, algorithm, publicKeyPem }
+      receiptItems: [
+        { name: 'Maple Oat Latte', qty: 1, price: 5.75 },
+        { name: 'Dark Roast Espresso', qty: 1, price: 3.50 }
