+    async function ensureKeyPair(algName, forceNew = false) {
+      if (!forceNew && state.keysByAlgorithm[algName]) {
+        return state.keysByAlgorithm[algName];
+      }
+
+      let generated;
+      if (algName === 'ML-DSA-65') {
+        generated = await generateMlDsaKeyPair();
+      } else if (algName === 'SLH-DSA-SHA256') {
+        generated = await generateSlhDsaKeyPair();
+      } else {
+        generated = await generateClassicalKeyPair(algName);
+      }
+
+      const fpFull = await sha256Hex(generated.publicKeyPem);
+      const fingerprint = `SHA256:${fpFull.slice(0, 32)}`;
+      const keyId = `dg-${algName.toLowerCase()}-${fpFull.slice(0, 8)}`;
+
+      const record = {
+        algorithm: algName,
+        family: ALGORITHM_METADATA[algName].family,
+        keyId,
+        fingerprint,
+        publicKeyPem: generated.publicKeyPem,
+        privateKeyPem: generated.privateKeyPem,
+        rawPublic: generated.rawPublic,
+        rawPrivate: generated.rawPrivate,
+        cryptoKeyPair: generated.cryptoKeyPair,
+        nativeEd25519: generated.nativeEd25519,
+        createdAt: new Date().toISOString()
+      };
+
+      state.keysByAlgorithm[algName] = record;
+      state.trustedPublicKeyRegistry[fingerprint] = {
+        keyId,
+        algorithm: algName,
+        family: record.family,
+        publicKeyPem: record.publicKeyPem
+      };
+      return record;
+    }
