+      const payloadBytes = textEncoder.encode(canonicalPayload);
+      const payloadHash = await sha256Hex(payloadBytes);
+
+      let signature;
+      if (algName === 'ML-DSA-65') {
+        signature = await signMlDsa(keyRecord.rawPrivate, payloadBytes);
+      } else if (algName === 'SLH-DSA-SHA256') {
+        signature = await signSlhDsa(keyRecord.rawPrivate, payloadBytes);
+      } else {
+        signature = await signClassical(algName, keyRecord, payloadBytes);
+      }
