+      const envelope = {
+        documentType,
+        version: '1.0',
+        merchant: 'The Daily Grind Coffee Co.',
+        payload,
+        security: {
+          algorithm: algName,
+          keyFamily: keyRecord.family,
+          keyId: keyRecord.keyId,
+          publicKeyFingerprint: keyRecord.fingerprint,
+          payloadCanonicalSha256: payloadHash,
+          signature,
+          publicKey: keyRecord.publicKeyPem,
+          signedAt: new Date().toISOString()
