+    async function verifyEnvelopeCryptographically(envelope, overridePublicKeyPem = '') {
+      const checks = [];
+      if (!envelope || typeof envelope !== 'object' || !envelope.payload || !envelope.security) {
+        return {
+          valid: false,
+          summary: 'Malformed envelope: Missing required payload or security signature block.',
+          checks: [
+            {
+              title: 'Envelope Structure & Schema',
+              passed: false,
+              detail: 'Expected JSON object with "payload" and "security" properties.'
+            }
+          ]
+        };
+      }
+
+      const { documentType, payload, security } = envelope;
+      const isKnownDocType = documentType === 'COFFEE_ORDER_RECEIPT' || documentType === 'GIFT_VOUCHER';
+      checks.push({
+        title: '1. Document Schema & Type Validation',
+        passed: isKnownDocType && Boolean(security.algorithm) && Boolean(security.signature),
+        detail: `Type: ${documentType || 'UNKNOWN'} | Algorithm: ${security.algorithm || 'NONE'} | Key Family: ${security.keyFamily || 'Unknown'}`
+      });
+
+      // Check 2: Canonical Payload SHA-256 Digest (Integrity)
+      const canonicalPayload = canonicalizeJson(payload);
+      const payloadBytes = textEncoder.encode(canonicalPayload);
+      const recomputedHash = await sha256Hex(payloadBytes);
+      const hashMatches = recomputedHash === security.payloadCanonicalSha256;
+
+      checks.push({
+        title: '2. Canonical Payload SHA-256 Digest (Data Integrity)',
+        passed: hashMatches,
+        detail: hashMatches
+          ? `Digest verified: ${recomputedHash.slice(0, 36)}...`
+          : `MISMATCH! Recomputed ${recomputedHash.slice(0, 24)}... != Signed ${String(security.payloadCanonicalSha256).slice(0, 24)}...`
+      });
+
+      // Check 3: Public Key & Fingerprint Verification
+      const publicKeyToUse = (overridePublicKeyPem && overridePublicKeyPem.trim())
+        ? overridePublicKeyPem.trim()
+        : security.publicKey;
+      const computedFp = publicKeyToUse
+        ? `SHA256:${(await sha256Hex(publicKeyToUse)).slice(0, 32)}`
+        : 'MISSING';
+      const fpMatches = Boolean(publicKeyToUse) && (
+        overridePublicKeyPem.trim()
+          ? true
+          : computedFp === security.publicKeyFingerprint
+      );
+      const isRegisteredMerchantKey = Boolean(state.trustedPublicKeyRegistry[computedFp]);
+
+      checks.push({
+        title: '3. Public Key Fingerprint & Merchant Trust',
+        passed: fpMatches,
+        detail: fpMatches
+          ? `${computedFp} (${isRegisteredMerchantKey ? 'Trusted Daily Grind Session Key' : 'External/Custom Public Key'})`
+          : `Public key fingerprint mismatch: computed ${computedFp} vs ${security.publicKeyFingerprint}`
+      });
