+      // Check 4: Asymmetric Cryptographic Signature Verification (Authenticity)
+      let signatureValid = false;
+      const alg = security.algorithm;
+      if (publicKeyToUse && security.signature) {
+        if (alg === 'ML-DSA-65') {
+          signatureValid = await verifyMlDsa(publicKeyToUse, security.signature, payloadBytes);
+        } else if (alg === 'SLH-DSA-SHA256') {
+          signatureValid = await verifySlhDsa(publicKeyToUse, security.signature, payloadBytes);
+        } else if (alg === 'ECDSA-P256' || alg === 'RSA-PSS-2048' || alg === 'Ed25519') {
+          signatureValid = await verifyClassical(alg, publicKeyToUse, security.signature, payloadBytes);
+        }
+      }
+
+      checks.push({
+        title: `4. Asymmetric Signature Verification (${alg || 'Unknown'})`,
+        passed: signatureValid,
+        detail: signatureValid
+          ? `Cryptographic signature mathematically verified against canonical payload using ${alg} (${ALGORITHM_METADATA[alg]?.family || 'Asymmetric'} Public Key).`
+          : `INVALID SIGNATURE! Payload bytes or signature do not verify under the ${alg} public key.`
+      });
+
+      const allPassed = checks.every(c => c.passed);
+      return {
+        valid: allPassed,
+        summary: allPassed
+          ? `Verified authentic ${documentType === 'GIFT_VOUCHER' ? 'Gift Voucher' : 'Coffee Order Receipt'} signed with ${alg} (${ALGORITHM_METADATA[alg]?.family || 'Asymmetric'}).`
+          : 'Verification failed! Document payload was tampered with or the cryptographic signature is invalid.',
+        checks
+      };
+    }
