+import React, { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStoryItem {
+  id: string;
+  slug?: string;
+  data: {
+    title: string;
+    date: Date | string;
+    category?: string;
+    summary?: string;
+  };
+}
+
+interface TopStoriesCarouselProps {
+  stories: TopStoryItem[];
+}
+
+type Direction = 'next' | 'prev' | null;
+
+export default function TopStoriesCarousel({ stories }: TopStoriesCarouselProps) {
+  const [currentIndex, setCurrentIndex] = useState(0);
+  const [direction, setDirection] = useState<Direction>(null);
+  const [stepCount, setStepCount] = useState(0);
+
+  if (!stories || stories.length === 0) {
+    return null;
+  }
+
+  const handlePrevious = () => {
+    setDirection('prev');
+    setStepCount((prev) => prev + 1);
+    setCurrentIndex((prevIndex) => (prevIndex - 1 + stories.length) % stories.length);
+  };
+
+  const handleNext = () => {
+    setDirection('next');
+    setStepCount((prev) => prev + 1);
+    setCurrentIndex((prevIndex) => (prevIndex + 1) % stories.length);
+  };
+
+  const currentStory = stories[currentIndex];
+  const storyDate =
+    currentStory.data.date instanceof Date
+      ? currentStory.data.date
+      : new Date(currentStory.data.date);
+
+  const animationClass =
+    direction === 'next'
+      ? 'animate-slide-in-right'
+      : direction === 'prev'
+      ? 'animate-slide-in-left'
+      : '';
+
+  return (
+    <section
+      aria-label="Top Stories"
+      aria-roledescription="carousel"
+      className="flex items-center justify-between gap-4"
+    >
+      <button
+        type="button"
+        onClick={handlePrevious}
+        aria-label="Previous story"
+        className="flex items-center gap-1 px-3 py-1.5 text-xs font-semibold text-gray-700 bg-gray-100 hover:bg-amber-400 hover:text-gray-900 rounded transition-colors cursor-pointer shrink-0"
+      >
+        <ChevronLeftIcon className="w-4 h-4" />
+        <span>Previous</span>
+      </button>
+
+      <div className="flex-1 overflow-hidden px-2" aria-live="polite">
+        <div
+          key={`${currentStory.id}-${stepCount}`}
+          data-direction={direction ?? 'none'}
+          className={`flex flex-col sm:flex-row sm:items-baseline sm:justify-between gap-1 sm:gap-4 ${animationClass}`}
+        >
+          <div className="flex items-baseline gap-3 min-w-0">
+            <span className="text-xs font-bold uppercase tracking-wider text-amber-800 shrink-0">
+              Top Story {currentIndex + 1} of {stories.length}
+            </span>
+            <a
+              href={`${import.meta.env.BASE_URL}articles/${currentStory.id}`}
+              className="truncate"
+            >
+              <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer truncate">
+                {currentStory.data.title}
+              </h3>
+            </a>
+          </div>
+          <span className="text-xs text-gray-500 shrink-0">
+            {storyDate.toLocaleDateString()}
+          </span>
+        </div>
+      </div>
+
+      <button
+        type="button"
+        onClick={handleNext}
+        aria-label="Next story"
+        className="flex items-center gap-1 px-3 py-1.5 text-xs font-semibold text-gray-700 bg-gray-100 hover:bg-amber-400 hover:text-gray-900 rounded transition-colors cursor-pointer shrink-0"
+      >
+        <span>Next</span>
+        <ChevronRightIcon className="w-4 h-4" />
+      </button>
+    </section>
+  );
+}
