+  <script>
+    (() => {
+      const draggable = document.querySelector('[data-draggable]');
+      const handle = draggable?.querySelector('[data-drag-handle]');
+      const liveRegion = document.getElementById('drag-live-region');
+      const repositionToggle = document.getElementById('reposition-menu-toggle');
+      const repositionMenu = document.getElementById('reposition-menu');
+      const helpToggle = document.getElementById('drag-help-toggle');
+      const helpPanel = document.getElementById('drag-help-panel');
+
+      if (draggable && handle) {
+        // Progressive enhancement: reveal drag handle and movement utilities once JS initializes
+        handle.hidden = false;
+        if (repositionToggle) repositionToggle.hidden = false;
+        if (helpToggle) helpToggle.hidden = false;
+
+        let offsetX = 0;
+        let offsetY = 0;
+        let startLeft = 0;
+        let startTop = 0;
+        let hasCustomPosition = false;
+        let announceTimer = 0;
+        const KEYBOARD_STEP = 15;
+        const EDGE_PADDING = 12;
+
+        function announceMove(description) {
+          if (!liveRegion) return;
+          window.clearTimeout(announceTimer);
+          liveRegion.textContent = `Quick Order Cart panel ${description}`;
+          announceTimer = window.setTimeout(() => {
+            liveRegion.textContent = '';
+          }, 1000);
+        }
+
+        function moveTo(left, top) {
+          const maxLeft = Math.max(0, window.innerWidth - draggable.offsetWidth);
+          const maxTop = Math.max(0, window.innerHeight - draggable.offsetHeight);
+
+          draggable.style.margin = '0';
+          draggable.style.right = 'auto';
+          draggable.style.bottom = 'auto';
+          draggable.style.left = `${Math.max(0, Math.min(left, maxLeft))}px`;
+          draggable.style.top = `${Math.max(0, Math.min(top, maxTop))}px`;
+          hasCustomPosition = true;
+        }
+
+        function reclampPosition() {
+          if (!hasCustomPosition) return;
+          const rect = draggable.getBoundingClientRect();
+          moveTo(rect.left, rect.top);
+        }
+
+        handle.addEventListener('pointerdown', (event) => {
+          const control = event.target.closest('button, input, select, textarea, a');
+          if (event.button !== 0 || (control && control !== handle)) return;
+
+          const rect = draggable.getBoundingClientRect();
+          startLeft = rect.left;
+          startTop = rect.top;
+          offsetX = event.clientX - rect.left;
+          offsetY = event.clientY - rect.top;
+          handle.setPointerCapture(event.pointerId);
+        });
+
+        handle.addEventListener('pointermove', (event) => {
+          if (!handle.hasPointerCapture(event.pointerId)) return;
+          handle.classList.add('dragging');
+          moveTo(event.clientX - offsetX, event.clientY - offsetY);
+        });
+
+        handle.addEventListener('lostpointercapture', () => {
+          const wasDragging = handle.classList.contains('dragging');
+          handle.classList.remove('dragging');
+          if (wasDragging) {
+            const rect = draggable.getBoundingClientRect();
+            const dx = rect.left - startLeft;
+            const dy = rect.top - startTop;
+            if (Math.abs(dx) > Math.abs(dy)) {
+              announceMove(dx < 0 ? 'moved left' : 'moved right');
+            } else if (Math.abs(dy) > 0) {
+              announceMove(dy < 0 ? 'moved up' : 'moved down');
+            } else {
+              announceMove('moved');
+            }
+          }
+        });
+
+        handle.addEventListener('keydown', (event) => {
+          const rect = draggable.getBoundingClientRect();
+          switch (event.key) {
+            case 'ArrowLeft':
+              event.preventDefault();
+              moveTo(rect.left - KEYBOARD_STEP, rect.top);
+              announceMove('moved left');
+              break;
+            case 'ArrowRight':
+              event.preventDefault();
+              moveTo(rect.left + KEYBOARD_STEP, rect.top);
+              announceMove('moved right');
+              break;
+            case 'ArrowUp':
+              event.preventDefault();
+              moveTo(rect.left, rect.top - KEYBOARD_STEP);
+              announceMove('moved up');
+              break;
+            case 'ArrowDown':
+              event.preventDefault();
+              moveTo(rect.left, rect.top + KEYBOARD_STEP);
+              announceMove('moved down');
+              break;
+          }
+        });
+
+        window.addEventListener('resize', reclampPosition);
+        if ('ResizeObserver' in window) {
+          new ResizeObserver(reclampPosition).observe(draggable);
+        }
+
+        if (repositionToggle && repositionMenu) {
+          repositionToggle.addEventListener('click', () => {
+            const nextOpen = repositionMenu.hidden;
+            repositionMenu.hidden = !nextOpen;
+            repositionToggle.setAttribute('aria-expanded', String(nextOpen));
+          });
+
+          repositionMenu.addEventListener('click', (event) => {
+            const btn = event.target.closest('[data-move-action]');
+            if (!btn) return;
+            const action = btn.getAttribute('data-move-action');
+            const rect = draggable.getBoundingClientRect();
+            const maxLeft = Math.max(0, window.innerWidth - draggable.offsetWidth);
+            const maxTop = Math.max(0, window.innerHeight - draggable.offsetHeight);
+
+            switch (action) {
+              case 'dock-left':
+                moveTo(EDGE_PADDING, rect.top);
+                announceMove('docked left');
+                break;
+              case 'move-left':
+                moveTo(rect.left - KEYBOARD_STEP * 3, rect.top);
+                announceMove('moved left');
+                break;
+              case 'dock-top':
+                moveTo(rect.left, EDGE_PADDING);
+                announceMove('docked top');
+                break;
+              case 'move-up':
+                moveTo(rect.left, rect.top - KEYBOARD_STEP * 3);
+                announceMove('moved up');
+                break;
+              case 'dock-right':
+                moveTo(maxLeft - EDGE_PADDING, rect.top);
+                announceMove('docked right');
+                break;
+              case 'move-right':
+                moveTo(rect.left + KEYBOARD_STEP * 3, rect.top);
+                announceMove('moved right');
+                break;
+              case 'dock-bottom':
+                moveTo(rect.left, maxTop - EDGE_PADDING);
+                announceMove('docked bottom');
+                break;
+              case 'move-down':
+                moveTo(rect.left, rect.top + KEYBOARD_STEP * 3);
+                announceMove('moved down');
+                break;
+            }
+          });
+        }
+
+        if (helpToggle && helpPanel) {
+          helpToggle.addEventListener('click', () => {
+            const nextOpen = helpPanel.hidden;
+            helpPanel.hidden = !nextOpen;
+            helpToggle.setAttribute('aria-expanded', String(nextOpen));
+          });
+        }
+      }
+
+      // Interactive Quick Order Cart controls
+      const itemRows = Array.from(document.querySelectorAll('.cart-item'));
+      const sizeSelect = document.getElementById('cup-size-select');
+      const milkSelect = document.getElementById('milk-select');
+      const subtotalEl = document.getElementById('cart-subtotal');
+      const totalEl = document.getElementById('cart-total');
+      const countBadge = document.getElementById('cart-count-badge');
+      const checkoutBtn = document.getElementById('quick-checkout-btn');
+      const statusMsg = document.getElementById('order-status-msg');
+
+      function updateCartTotals() {
+        const sizeUpcharge = parseFloat(sizeSelect?.value || '0') || 0;
+        let totalQty = 0;
+        let subtotal = 0;
+
+        for (const row of itemRows) {
+          const basePrice = parseFloat(row.getAttribute('data-base-price') || '0') || 0;
+          const qtyEl = row.querySelector('[data-item-qty]');
+          const qty = parseInt(qtyEl?.textContent || '0', 10) || 0;
+          totalQty += qty;
+          subtotal += qty * (basePrice + sizeUpcharge);
+        }
+
+        if (countBadge) countBadge.textContent = String(totalQty);
+        const formatted = `$${subtotal.toFixed(2)}`;
+        if (subtotalEl) subtotalEl.textContent = formatted;
+        if (totalEl) totalEl.textContent = formatted;
+      }
+
+      document.getElementById('cart-items-list')?.addEventListener('click', (event) => {
+        const btn = event.target.closest('[data-qty-delta]');
+        if (!btn) return;
+        const delta = parseInt(btn.getAttribute('data-qty-delta') || '0', 10);
+        const row = btn.closest('.cart-item');
+        const qtyEl = row?.querySelector('[data-item-qty]');
+        if (!qtyEl) return;
+        const current = parseInt(qtyEl.textContent || '0', 10) || 0;
+        qtyEl.textContent = String(Math.max(0, current + delta));
+        if (statusMsg) statusMsg.textContent = '';
