+          qtyEl.textContent = String(current + 1);
+          if (statusMsg) statusMsg.textContent = 'Added to Quick Order Cart!';
+          updateCartTotals();
+        });
+      });
+
+      sizeSelect?.addEventListener('change', updateCartTotals);
+      milkSelect?.addEventListener('change', () => {
+        if (statusMsg) statusMsg.textContent = '';
+      });
+
+      checkoutBtn?.addEventListener('click', () => {
+        const count = parseInt(countBadge?.textContent || '0', 10) || 0;
