+
+    function switchToView(viewId, options = { moveFocus: true }) {
+      const activeView = document.getElementById(viewId);
+      if (!activeView) return;
+
+      // Hide all views while keeping their DOM and rendering state cached in memory
+      document.querySelectorAll('.spa-view').forEach(view => {
