+---
+import ArticleTeaser from './ArticleTeaser.astro';
+import TopStoryTeaserGrid from './TopStoryTeaserGrid.astro';
+import SimpleTeaserGrid from './SimpleTeaserGrid.astro';
+import Ad from './AdSlotBanner';
+import { getCollection } from 'astro:content';
+import type { RenderResult } from 'astro:content';
+
+export interface Props {
+  initialView?: 'top-news' | 'world' | 'politics' | 'multimedia' | 'reports';
+}
+
+const { initialView = 'top-news' } = Astro.props;
+const baseUrl = import.meta.env.BASE_URL;
+
+const articles = await getCollection('articles');
+articles.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
+
+const reports = await getCollection('reports');
+const multimedia = await getCollection('multimedia');
+
+// Slicing articles for different sections
+const topArticle = articles[0];
+const topStories = articles.slice(1, 4);
+const topNewsArticles = articles.slice(4, 8);      // 4 articles for the Top News grid
+const worldNewsArticles = articles.slice(8, 11);   // 3 articles for the World grid
+const politicsArticles = articles.slice(11, 15);   // 4 articles for the Politics grid
+
+// Add a fake What's new in DevTools post in there, demonstrating a CORS issue for the image
+politicsArticles[2] = {
+  id: 'public-transit-overhaul',
+  data: {
+    title: "What's new in DevTools",
+    summary:
+      'Learn about what is new in Chrome DevTools 144: from request conditions to performance debugging, we got you covered.',
+    author: 'Chrome DevTools Team',
+    date: new Date('2025-09-16T00:00:00.000Z'),
+    category: 'Web Development',
+    image:
+      'https://cinemai-1026410574114.us-central1.run.app/cinemai/_next/image?url=%2Fcinemai%2F_next%2Fstatic%2Fmedia%2Fthumbnail-wndt-139-141.45ba64a6.jpg&w=3840&q=75',
+    image_caption: '',
+    readingTime: 3,
+  },
+  body: '',
+  collection: 'articles',
+  slug: 'public-transit-overhaul',
+  render: async () => '' as unknown as RenderResult,
+};
+
+const isViewActive = (viewId: string) => initialView === viewId;
+---
+
+<div id="spa-views-root" class="relative" data-initial-view={initialView} data-base-url={baseUrl}>
+  <!-- View 1: Top News -->
+  <section
+    id="top-news"
+    data-view-id="top-news"
+     data-view-title="The DevTools Times - Top News"
+    class={`spa-view ${isViewActive('top-news') ? '' : 'inactive'}`}
+    tabindex="-1"
+    aria-label="Top News"
+    aria-hidden={isViewActive('top-news') ? 'false' : 'true'}
+    inert={isViewActive('top-news') ? undefined : 'inert'}
+  >
+    <!-- Top Stories Bar -->
+    <div class="bg-white border-b border-gray-300">
+      <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
+        <div class="grid grid-cols-1 md:grid-cols-3 gap-6">
+          {topStories.map((article) => (
+            <div class="border-l border-gray-300 pl-4 first:border-l-0 first:pl-0">
+              <a href={`${baseUrl}articles/${article.id}`}>
+                <h3 class="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">
+                  {article.data.title}
+                </h3>
+              </a>
+              <span class="text-xs text-gray-500">{article.data.date.toLocaleDateString()}</span>
+            </div>
+          ))}
+        </div>
+      </div>
+    </div>
+
+    <!-- Main Featured Story -->
+    <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-6 mt-6">
+      <ArticleTeaser article={topArticle} large={true} />
+    </div>
+
+    <div class="divide-y divide-gray-200 max-w-6xl mx-auto">
+      <section class="p-4 md:p-6 text-center">
+        <Ad client:visible />
+      </section>
+
+      <TopStoryTeaserGrid title="Top News" articles={topNewsArticles} />
+    </div>
+  </section>
+
+  <!-- View 2: World -->
+  <section
+    id="world"
+    data-view-id="world"
+    data-view-title="The DevTools Times - World"
+    class={`spa-view ${isViewActive('world') ? '' : 'inactive'}`}
+    tabindex="-1"
+    aria-label="World"
+    aria-hidden={isViewActive('world') ? 'false' : 'true'}
+    inert={isViewActive('world') ? undefined : 'inert'}
+  >
+    <div class="divide-y divide-gray-200 max-w-6xl mx-auto">
+      <SimpleTeaserGrid title="World" articles={worldNewsArticles} />
+
+      <section class="p-4 md:p-6 text-center">
+        <Ad client:visible />
+      </section>
+    </div>
+  </section>
+
+  <!-- View 3: Politics -->
+  <section
+    id="politics"
+    data-view-id="politics"
+    data-view-title="The DevTools Times - Politics"
+    class={`spa-view ${isViewActive('politics') ? '' : 'inactive'}`}
+    tabindex="-1"
+    aria-label="Politics"
+    aria-hidden={isViewActive('politics') ? 'false' : 'true'}
+    inert={isViewActive('politics') ? undefined : 'inert'}
+  >
+    <div class="divide-y divide-gray-200 max-w-6xl mx-auto">
+      <TopStoryTeaserGrid title="Politics" articles={politicsArticles} />
+
+      <section class="p-4 md:p-6 text-center">
+        <Ad client:visible />
+      </section>
+    </div>
+  </section>
+
+  <!-- View 4: Multimedia -->
+  <section
+    id="multimedia"
+    data-view-id="multimedia"
+    data-view-title="The DevTools Times - Multimedia"
+    class={`spa-view ${isViewActive('multimedia') ? '' : 'inactive'}`}
+    tabindex="-1"
+    aria-label="Multimedia"
+    aria-hidden={isViewActive('multimedia') ? 'false' : 'true'}
+    inert={isViewActive('multimedia') ? undefined : 'inert'}
+  >
+    <div class="max-w-4xl mx-auto px-4 py-8 md:py-12">
+      <h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-4 pb-2 border-b-2 border-gray-900">
+        Multimedia
+      </h1>
+      <p class="text-gray-700 mb-6">Watch our latest multimedia content.</p>
+      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
+        {multimedia.map((item) => (
+          <article class="border border-gray-200 rounded-lg p-5 shadow-xs hover:shadow-md transition-shadow bg-white flex flex-col justify-between">
+            <div>
+              <div class="flex items-center space-x-3 mb-3">
+                <div class="w-10 h-10 rounded bg-blue-100 flex items-center justify-center flex-shrink-0">
+                  <span class="text-blue-800 font-semibold">{item.data.title.charAt(0)}</span>
+                </div>
+                <div>
+                  <span class="text-xs font-semibold uppercase tracking-wider text-blue-800">
+                    {item.data.category}
+                  </span>
+                  <p class="text-xs text-gray-500">{item.data.publishDate}</p>
+                </div>
+              </div>
+              <h2 class="text-xl font-brand text-gray-900 mb-2">
+                <a href={`${baseUrl}multimedia/${item.id}`} class="hover:text-amber-700 hover:underline">
+                  {item.data.title}
+                </a>
+              </h2>
+              <p class="text-sm text-gray-600">{item.data.description}</p>
+            </div>
+          </article>
+        ))}
+      </div>
+    </div>
+  </section>
+
+  <!-- View 5: Reports -->
+  <section
+    id="reports"
+    data-view-id="reports"
+    data-view-title="The DevTools Times - Reports"
+    class={`spa-view ${isViewActive('reports') ? '' : 'inactive'}`}
+    tabindex="-1"
+    aria-label="Reports"
+    aria-hidden={isViewActive('reports') ? 'false' : 'true'}
+    inert={isViewActive('reports') ? undefined : 'inert'}
+  >
+    <div class="max-w-4xl mx-auto px-4 py-8 md:py-12">
+      <h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-4 pb-2 border-b-2 border-gray-900">
+        Reports
+      </h1>
+      <p class="text-gray-700 mb-6">Read our latest reports.</p>
+      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
+        {reports.map((report) => (
+          <article class="border border-gray-200 rounded-lg p-5 shadow-xs hover:shadow-md transition-shadow bg-white flex flex-col justify-between">
+            <div>
+              <div class="flex items-center space-x-3 mb-3">
+                <div class="w-10 h-10 rounded bg-yellow-100 flex items-center justify-center flex-shrink-0">
+                  <span class="text-yellow-800 font-semibold">{report.data.title.charAt(0)}</span>
+                </div>
+                <div>
+                  <span class="text-xs font-semibold uppercase tracking-wider text-amber-800">
+                    {report.data.category}
+                  </span>
+                  <p class="text-xs text-gray-500">{report.data.publishDate}</p>
+                </div>
+              </div>
+              <h2 class="text-xl font-brand text-gray-900 mb-2">
+                <a href={`${baseUrl}reports/${report.id}`} class="hover:text-amber-700 hover:underline">
+                  {report.data.title}
+                </a>
+              </h2>
+              <p class="text-sm text-gray-600">{report.data.description}</p>
+            </div>
+          </article>
+        ))}
+      </div>
+    </div>
+  </section>
+</div>
+
+<script>
+  const CORE_VIEWS = new Set(['top-news', 'world', 'politics', 'multimedia', 'reports']);
+  const MAX_DYNAMIC_CACHED_VIEWS = 5;
+  const dynamicViewLru: string[] = [];
+
+  function touchDynamicView(viewId: string) {
+    if (CORE_VIEWS.has(viewId)) return;
+    const existingIndex = dynamicViewLru.indexOf(viewId);
+    if (existingIndex !== -1) {
+      dynamicViewLru.splice(existingIndex, 1);
+    }
+    dynamicViewLru.push(viewId);
+
+    while (dynamicViewLru.length > MAX_DYNAMIC_CACHED_VIEWS) {
+      const oldestViewId = dynamicViewLru.shift();
+      if (oldestViewId) {
+        const oldView = document.getElementById(oldestViewId);
+        if (oldView && oldView.classList.contains('inactive')) {
+          oldView.remove();
+        }
+      }
+    }
+  }
+
+  function getViewUrl(viewId: string, baseUrl: string): string {
+    const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+    switch (viewId) {
+      case 'top-news':
+        return normalizedBase;
+      case 'world':
+        return `${normalizedBase}?view=world`;
+      case 'politics':
+        return `${normalizedBase}?view=politics`;
+      case 'multimedia':
+        return `${normalizedBase}multimedia`;
+      case 'reports':
+        return `${normalizedBase}reports`;
+      default:
+        return `${normalizedBase}?view=${encodeURIComponent(viewId)}`;
+    }
+  }
+
+  function resolveViewIdFromLocation(loc: Location): string | null {
+    const params = new URLSearchParams(loc.search);
+    const queryView = params.get('view');
+    if (queryView && CORE_VIEWS.has(queryView)) {
+      return queryView;
+    }
+
+    const hashView = loc.hash.replace(/^#/, '');
+    if (hashView && CORE_VIEWS.has(hashView)) {
+      return hashView;
+    }
+
+    const path = loc.pathname.replace(/\/+$/, '');
+    if (path.endsWith('/multimedia')) return 'multimedia';
+    if (path.endsWith('/reports')) return 'reports';
+    if (path.endsWith('/category/politics')) return 'politics';
+
+    const root = document.getElementById('spa-views-root');
+    if (root) {
+      const baseUrl = (root.dataset.baseUrl || '/').replace(/\/+$/, '');
+      if (path === baseUrl || path === '') {
+        return 'top-news';
+      }
+    }
+
+    return null;
+  }
+
+  function switchToView(
+    viewId: string,
+    options: { updateHistory?: boolean; focusView?: boolean; targetUrl?: string } = {}
+  ): boolean {
+    const { updateHistory = true, focusView = true, targetUrl } = options;
+    const activeView = document.getElementById(viewId);
+    if (!activeView) return false;
+
+    // Hide all views while preserving their DOM & rendering state
+    document.querySelectorAll<HTMLElement>('.spa-view').forEach((view) => {
+      view.classList.add('inactive');
+      view.setAttribute('aria-hidden', 'true');
+      view.setAttribute('inert', 'inert');
+    });
+
+    // Show the target view
+    activeView.classList.remove('inactive');
+    activeView.setAttribute('aria-hidden', 'false');
+    activeView.removeAttribute('inert');
+
+    touchDynamicView(viewId);
+
+    if (activeView.dataset.viewTitle) {
+      document.title = activeView.dataset.viewTitle;
+    }
+
+    if (focusView) {
+      // MANDATORY: Move focus to the new view to ensure a logical tab-order
+      activeView.focus();
+    }
+
+    const root = document.getElementById('spa-views-root');
+    const baseUrl = root?.dataset.baseUrl || '/';
+
+    if (updateHistory) {
+      const nextUrl = targetUrl || getViewUrl(viewId, baseUrl);
+      if (window.location.pathname + window.location.search !== nextUrl) {
+        window.history.pushState({ viewId }, '', nextUrl);
+      }
+    }
+
+    window.dispatchEvent(
+      new CustomEvent('spa:viewchange', {
+        detail: { viewId },
+      })
+    );
+
+    return true;
+  }
