+  // Expose switchToView globally for components and scripts
+  (window as any).switchToView = switchToView;
+
+  // Handle CustomEvent triggers from React components
+  window.addEventListener('spa:navigate', ((event: CustomEvent<{ viewId: string; url?: string }>) => {
+    if (event.detail?.viewId) {
+      switchToView(event.detail.viewId, {
+        updateHistory: true,
+        focusView: true,
+        targetUrl: event.detail.url,
+      });
+    }
+  }) as EventListener);
+
+  // Intercept clicks on any [data-spa-view] link across the page
+  document.addEventListener('click', (event) => {
+    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
+      return;
+    }
+    const target = event.target as Element | null;
+    const link = target?.closest<HTMLAnchorElement>('a[data-spa-view]');
+    if (!link) return;
+
+    const viewId = link.dataset.spaView;
+    if (!viewId) return;
+
+    const viewEl = document.getElementById(viewId);
+    if (viewEl) {
+      event.preventDefault();
+      switchToView(viewId, {
+        updateHistory: true,
+        focusView: true,
+        targetUrl: link.getAttribute('href') || undefined,
+      });
+    }
+  });
