+            trackerItem.setAttribute('aria-current', 'step');
+            trackerItem.classList.remove('step-done');
+            if (labelSpan) labelSpan.textContent = meta.shortLabel;
+          } else {
+            trackerItem.removeAttribute('aria-current');
+            trackerItem.classList.remove('step-done');
+            if (labelSpan) labelSpan.textContent = meta.shortLabel;
+          }
+        });
+
+        hideErrorSummary();
+
+        if (focusHeading) {
+          const heading = steps[targetIndex].querySelector('.step-heading');
+          if (heading) {
+            heading.focus();
+          }
+        }
+      };
+
+      document.getElementById('next-to-step-2')?.addEventListener('click', () => {
+        if (validateStep(0)) showStep(1);
+      });
+
+      document.getElementById('back-to-step-1')?.addEventListener('click', () => {
+        showStep(0);
+      });
+
+      document.getElementById('next-to-step-3')?.addEventListener('click', () => {
+        if (validateStep(1)) showStep(2);
+      });
+
+      document.getElementById('back-to-step-2')?.addEventListener('click', () => {
+        showStep(1);
+      });
+
+      // 9. IME-Safe Enter Key Handling in Multi-Step Inputs
+      form.addEventListener('keydown', (e) => {
+        if (e.key !== 'Enter' || e.isComposing || e.keyCode === 229) return;
+        const target = e.target;
+        if (!target || target.tagName === 'TEXTAREA' || target.tagName === 'BUTTON') return;
+
+        if (currentStepIndex < steps.length - 1) {
+          e.preventDefault();
+          if (validateStep(currentStepIndex)) {
+            showStep(currentStepIndex + 1);
+          }
+        }
+      });
+
+      // 10. Secure Form Submission Handler
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
