+        const memberEmail = String(formData.get('email') || '').trim();
+
+        // Safe DOM sink updates using textContent (preventing XSS)
+        const confirmationBox = document.getElementById('rewards-confirmation');
+        const confirmationSummary = document.getElementById('confirmation-summary');
