+          trackerItem.removeAttribute('aria-current');
+          trackerItem.classList.add('step-done');
+          const labelSpan = trackerItem.querySelector('.step-label');
+          if (labelSpan) labelSpan.textContent = `${meta.shortLabel} (completed)`;
+        });
+
+        form.hidden = true;
+        form.setAttribute('inert', '');
+
+        if (confirmationBox) {
+          confirmationBox.hidden = false;
+          confirmationBox.focus();
+        }
+
+        document.title = 'Welcome to Rewards | The Daily Grind';
+      });
+    })();
