+        card.classList.remove('hovercard--below');
+        const rect = wrapper.getBoundingClientRect();
+        // If there is not enough room above the button, flip the hovercard below
+        if (rect.top < 360 && window.innerHeight - rect.bottom > 340) {
+          card.classList.add('hovercard--below');
+        }
+      }
+
+      wrappers.forEach((wrapper) => {
+        const trigger = wrapper.querySelector('.hovercard-trigger');
+        const card = wrapper.querySelector('.hovercard');
+        let closeTimer = null;
+
+        function openCard() {
+          if (closeTimer) {
+            clearTimeout(closeTimer);
+            closeTimer = null;
+          }
+          closeAllExcept(wrapper);
+          adjustPlacement(wrapper, card);
+          card.classList.add('is-open');
+          card.setAttribute('aria-hidden', 'false');
+          trigger.setAttribute('aria-expanded', 'true');
+        }
+
+        function scheduleClose() {
+          if (closeTimer) clearTimeout(closeTimer);
+          closeTimer = setTimeout(() => {
+            card.classList.remove('is-open');
+            card.setAttribute('aria-hidden', 'true');
+            trigger.setAttribute('aria-expanded', 'false');
+          }, 120);
+        }
