+      }
+
+      function saveSnapshot() {
+        orderSnapshot = deepCopy(activeOrder);
+        snapshotStatusEl.textContent = `Snapshot saved (${orderSnapshot.length} ${orderSnapshot.length === 1 ? 'item' : 'items'})`;
+      }
+
+      function restoreSnapshot() {
+        if (orderSnapshot === null) {
+          return;
+        }
+        activeOrder = deepCopy(orderSnapshot);
+        snapshotStatusEl.textContent = `Snapshot restored (${activeOrder.length} ${activeOrder.length === 1 ? 'item' : 'items'})`;
+        renderOrder();
+      }
+
+      function clearOrder() {
+        activeOrder = [];
+        renderOrder();
+      }
+
+      // Wire up event listeners
+      categoryFilterEl.addEventListener('change', applyControlsChange);
+      sortSelectEl.addEventListener('change', applyControlsChange);
+      reverseOrderEl.addEventListener('change', applyControlsChange);
+      groupByCategoryEl.addEventListener('change', applyControlsChange);
+
+      saveSnapshotBtn.addEventListener('click', saveSnapshot);
+      restoreSnapshotBtn.addEventListener('click', restoreSnapshot);
+      clearOrderBtn.addEventListener('click', clearOrder);
+
+      window.addEventListener('popstate', () => {
+        readStateFromUrl();
+        const state = getFilterStateFromControls();
+        const processed = getProcessedItems(state);
+        renderMenu(state, processed);
+        dispatchFilterChange(state, processed);
+      });
+
+      // Expose state helpers for programmatic access if needed
+      window.dailyGrindOrder = {
+        getActiveOrder: () => activeOrder,
+        getSnapshot: () => orderSnapshot,
+        saveSnapshot,
+        restoreSnapshot,
+        clearOrder
+      };
+
+      // Initial load
+      readStateFromUrl();
+      applyControlsChange();
+      renderOrder();
+    })();
+  </script>
