+    const managedSessions = new Set();
+
+    const questionInput = document.getElementById('barista-question');
+    const askBaristaBtn = document.getElementById('ask-the-barista');
+    const baristaAnswer = document.getElementById('barista-answer');
+    const progressEl = document.getElementById('download-progress');
+
+    const feedbackInput = document.getElementById('feedback-input');
+    const sentimentBtn = document.getElementById('sentiment-btn');
+    const sentimentOutput = document.getElementById('sentiment-output');
+
+    const cloneBtn = document.getElementById('clone-btn');
+    const cleanupBtn = document.getElementById('cleanup-btn');
+    const contextUsageEl = document.getElementById('context-usage');
+    const sessionStatusEl = document.getElementById('session-status');
+    const branchOutput = document.getElementById('branch-output');
+
+    function updateContextMetrics(session = activeSession) {
+      if (session && typeof session.inputUsage === 'number' && typeof session.inputQuota === 'number') {
+        contextUsageEl.textContent = `Context Usage: ${session.inputUsage} / ${session.inputQuota} tokens`;
+      } else {
+        contextUsageEl.textContent = 'Context Usage: 0 / 0 tokens';
+      }
+      sessionStatusEl.textContent = `Active Sessions: ${managedSessions.size}`;
+    }
+
+    function cleanupUnneededSessions(keepSession = activeSession) {
+      for (const session of Array.from(managedSessions)) {
+        if (session !== keepSession) {
+          try {
+            session.destroy();
+          } catch (err) {
+            console.warn('Error destroying session:', err);
+          }
+          managedSessions.delete(session);
+        }
+      }
+      updateContextMetrics(keepSession);
+    }
+
+    async function ensureModelAvailable() {
+      if (typeof LanguageModel === 'undefined') {
+        throw new Error('Built-in AI LanguageModel API is not supported in this browser.');
+      }
+
+      const availability = await LanguageModel.availability();
+      if (availability === 'unavailable') {
+        throw new Error('Built-in AI model is currently unavailable on this device.');
+      }
+      return availability;
+    }
+
+    async function createBaristaSession(systemPrompt = BARISTA_SYSTEM_PROMPT) {
+      await ensureModelAvailable();
+
+      const session = await LanguageModel.create({
+        initialPrompts: [
+          {
+            role: 'system',
+            content: systemPrompt
+          }
+        ],
+        monitor(m) {
+          m.addEventListener('downloadprogress', (e) => {
+            const percent = Math.round((e.loaded || 0) * 100);
+            progressEl.textContent = `Model download progress: ${percent}%`;
+          });
+        }
+      });
+
+      managedSessions.add(session);
+      updateContextMetrics(session);
+      return session;
+    }
+
+    askBaristaBtn.addEventListener('click', async () => {
+      const question = questionInput.value.trim() || 'Tell me about the Maple Oat Latte and Cold Brew.';
+      baristaAnswer.textContent = '';
+      progressEl.textContent = '';
+
+      try {
+        await ensureModelAvailable();
+
+        if (!activeSession) {
+          activeSession = await createBaristaSession();
+        }
+
+        const stream = activeSession.promptStreaming(question);
+        for await (const chunk of stream) {
+          baristaAnswer.textContent += chunk;
+        }
+
+        updateContextMetrics(activeSession);
+      } catch (error) {
+        baristaAnswer.textContent = `Error: ${error.message}`;
+      }
+    });
+
+    sentimentBtn.addEventListener('click', async () => {
+      const feedbackText = feedbackInput.value.trim();
+      if (!feedbackText) {
+        sentimentOutput.textContent = JSON.stringify({ error: 'Please provide feedback text.' }, null, 2);
+        return;
+      }
+
+      sentimentOutput.textContent = 'Analyzing feedback...';
+      let analyzerSession = null;
+
+      try {
+        await ensureModelAvailable();
+
+        analyzerSession = await LanguageModel.create({
+          initialPrompts: [
+            {
+              role: 'system',
+              content: 'You are a customer feedback sentiment analyzer for a coffee shop. Respond strictly with JSON containing a numeric sentiment score (from 1 to 10) and a feedback category string.'
+            }
+          ],
+          monitor(m) {
+            m.addEventListener('downloadprogress', (e) => {
+              const percent = Math.round((e.loaded || 0) * 100);
+              progressEl.textContent = `Model download progress: ${percent}%`;
+            });
+          }
+        });
+        managedSessions.add(analyzerSession);
+
+        const schema = {
+          type: 'object',
+          properties: {
+            score: { type: 'number' },
+            category: { type: 'string' }
+          },
+          required: ['score', 'category'],
+          additionalProperties: false
+        };
+
+        const rawJson = await analyzerSession.prompt(
+          `Analyze the following customer feedback: "${feedbackText}"`,
+          { responseConstraint: schema }
+        );
+
+        const parsed = JSON.parse(rawJson);
+        sentimentOutput.textContent = JSON.stringify(parsed, null, 2);
+      } catch (error) {
+        sentimentOutput.textContent = JSON.stringify({ error: error.message }, null, 2);
+      } finally {
+        if (analyzerSession) {
+          analyzerSession.destroy();
+          managedSessions.delete(analyzerSession);
+          updateContextMetrics(activeSession);
+        }
+      }
+    });
+
+    cloneBtn.addEventListener('click', async () => {
+      try {
+        await ensureModelAvailable();
+
+        if (!activeSession) {
+          activeSession = await createBaristaSession();
+        }
+
+        const previousSession = activeSession;
+        const clonedSession = await previousSession.clone();
+        managedSessions.add(clonedSession);
+        activeSession = clonedSession;
+
+        // Clean up unneeded previous sessions to free resources
+        cleanupUnneededSessions(activeSession);
+
+        branchOutput.textContent =
+          `Cloned active session successfully. Context usage: ${activeSession.inputUsage ?? 0} / ${activeSession.inputQuota ?? 0} tokens.`;
+        updateContextMetrics(activeSession);
+      } catch (error) {
+        branchOutput.textContent = `Error cloning session: ${error.message}`;
+      }
+    });
+
+    cleanupBtn.addEventListener('click', () => {
+      cleanupUnneededSessions(null);
+      activeSession = null;
+      branchOutput.textContent = 'All sessions destroyed and resources cleaned up.';
+    });
+
+    window.addEventListener('beforeunload', () => {
+      cleanupUnneededSessions(null);
+      activeSession = null;
+    });
+  </script>
 </body>

 </html>

