+import React, { useState, useEffect, useRef, useId } from 'react';
+import {
+  type LnaPermissionName,
+  type DiagnosticsEndpointPayload,
+  observeNetworkPermission,
+  fetchLocalDeviceStatus,
+  fetchLoopbackDaemon,
+  openDiagnosticsWebSocket,
+} from '../utils/localNetworkAccess';
+
+type ConnectionState = 'idle' | 'connecting' | 'connected' | 'error';
+
+interface EndpointPanelState {
+  url: string;
+  wsUrl: string;
+  permissionState: PermissionState;
+  connectionState: ConnectionState;
+  payload: DiagnosticsEndpointPayload | null;
+  errorMessage: string | null;
+  wsConnected: boolean;
+  wsMessages: string[];
+}
+
+interface DiagnosticsConnectionWidgetProps {
+  mode?: 'header' | 'inline';
+}
+
+export default function DiagnosticsConnectionWidget({
+  mode = 'inline',
+}: DiagnosticsConnectionWidgetProps) {
+  const dialogId = useId();
+  const titleId = useId();
+  const lanInputId = useId();
+  const cliInputId = useId();
+  const dialogRef = useRef<HTMLDialogElement | null>(null);
