+
+  const [lanState, setLanState] = useState<EndpointPanelState>({
+    url: 'http://192.168.1.100:8080/api/status',
+    wsUrl: 'ws://192.168.1.100:8080/stream',
+    permissionState: 'prompt',
+    connectionState: 'idle',
+    payload: null,
+    errorMessage: null,
+    wsConnected: false,
+    wsMessages: [],
+  });
+
+  const [cliState, setCliState] = useState<EndpointPanelState>({
+    url: 'http://127.0.0.1:45678/health',
+    wsUrl: 'ws://127.0.0.1:45678/stream',
+    permissionState: 'prompt',
+    connectionState: 'idle',
+    payload: null,
+    errorMessage: null,
+    wsConnected: false,
+    wsMessages: [],
+  });
+
+  const connectToLanDevice = async (targetUrl?: string) => {
+    const endpointUrl = (targetUrl ?? lanState.url).trim();
+    setLanState((prev) => ({
+      ...prev,
+      connectionState: 'connecting',
+      errorMessage: null,
+    }));
+
+    try {
+      const payload = await fetchLocalDeviceStatus(endpointUrl);
+      setLanState((prev) => ({
+        ...prev,
+        connectionState: 'connected',
+        payload,
+        errorMessage: null,
+      }));
+    } catch (err) {
+      const message =
+        err instanceof Error
+          ? err.message
+          : 'Unable to reach hardware test device on local network.';
+      setLanState((prev) => ({
+        ...prev,
+        connectionState: 'error',
+        errorMessage: `${message} Verify the hardware device at ${endpointUrl} is powered on, connected to the same Wi-Fi LAN, sends CORS header Access-Control-Allow-Origin, and that "Local network" permission is allowed.`,
+      }));
+    }
+  };
+
+  const connectToLoopbackCli = async (targetUrl?: string) => {
+    const endpointUrl = (targetUrl ?? cliState.url).trim();
+    setCliState((prev) => ({
+      ...prev,
+      connectionState: 'connecting',
+      errorMessage: null,
+    }));
+
+    try {
+      const payload = await fetchLoopbackDaemon(endpointUrl);
+      setCliState((prev) => ({
+        ...prev,
+        connectionState: 'connected',
+        payload,
+        errorMessage: null,
+      }));
+    } catch (err) {
+      const message =
+        err instanceof Error
+          ? err.message
+          : 'Unable to reach local companion CLI on loopback interface.';
+      setCliState((prev) => ({
+        ...prev,
+        connectionState: 'error',
+        errorMessage: `${message} Verify the companion CLI daemon at ${endpointUrl} is running on this machine, sends CORS header Access-Control-Allow-Origin, and that "Loopback network" permission is allowed.`,
+      }));
+    }
+  };
+
+  const toggleWebSocketStream = (target: LnaPermissionName) => {
+    const isLan = target === 'local-network';
+    const currentRef = isLan ? lanWsRef : cliWsRef;
+    const wsUrl = isLan ? lanState.wsUrl : cliState.wsUrl;
+
+    if (currentRef.current) {
+      currentRef.current.close();
+      currentRef.current = null;
+      if (isLan) {
+        setLanState((prev) => ({ ...prev, wsConnected: false }));
+      } else {
+        setCliState((prev) => ({ ...prev, wsConnected: false }));
+      }
+      return;
+    }
+
+    try {
+      const socket = openDiagnosticsWebSocket(wsUrl, ['v1.telemetry']);
+      currentRef.current = socket;
+
+      socket.addEventListener('open', () => {
