@@ -0,0 +1,180 @@
+export type LnaPermissionName = 'local-network' | 'loopback-network';
+export type LnaAddressSpace = 'local' | 'loopback';
+
+export interface DiagnosticsEndpointPayload {
+  status: string;
+  device?: string;
+  version?: string;
+  uptimeSeconds?: number;
+  latencyMs?: number;
+  addressSpace: LnaAddressSpace;
+  endpoint: string;
+  timestamp: string;
+  metrics?: Record<string, string | number | boolean>;
+}
+
+/**
+ * Cross-browser permission check for the granular LNA permissions ('local-network' | 'loopback-network').
+ * Never queries the legacy combined 'local-network-access' permission name, which crashes older Chrome versions.
+ */
+export async function queryLnaPermissionSafe(
+  permissionName: LnaPermissionName
+): Promise<PermissionState> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    return 'prompt';
+  }
+  try {
+    const status = await navigator.permissions.query({
+      name: permissionName as PermissionName,
+    });
+    return status.state;
+  } catch {
+    // Unrecognized permission name in browsers without LNA support; proceed on explicit user gesture.
+    return 'prompt';
+  }
+}
+
+/**
+ * Queries the granular Local Network Access permission for the target address space
+ * and subscribes to permission state changes so UI stays synchronized with browser Site settings.
+ */
+export async function observeNetworkPermission(
+  permissionName: LnaPermissionName,
+  onChange: (state: PermissionState) => void
+): Promise<{ state: PermissionState; cleanup: () => void }> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    onChange('prompt');
+    return { state: 'prompt', cleanup: () => {} };
+  }
+
+  try {
+    const status = await navigator.permissions.query({
+      name: permissionName as PermissionName,
+    });
+    const handleChange = () => {
+      onChange(status.state);
+    };
+    status.addEventListener('change', handleChange);
+    onChange(status.state);
+    return {
+      state: status.state,
+      cleanup: () => status.removeEventListener('change', handleChange),
+    };
+  } catch {
+    onChange('prompt');
+    return { state: 'prompt', cleanup: () => {} };
+  }
+}
+
+/**
