+  signal?: AbortSignal
+): Promise<DiagnosticsEndpointPayload> {
+  const startedAt = performance.now();
+  const requestInit = {
+    method: 'GET',
+    mode: 'cors' as RequestMode,
+    // MANDATORY: Declare 'loopback' when targeting 127.0.0.1, [::1], or localhost
+    targetAddressSpace: 'loopback',
+    signal,
+  } as RequestInit;
+
+  const request = new Request(daemonUrl, requestInit);
+  const response = await fetch(request, requestInit);
+
+  if (!response.ok) {
+    throw new Error(`Companion CLI responded with HTTP ${response.status}`);
+  }
+
+  const data = await response.json();
+  const latencyMs = Math.round(performance.now() - startedAt);
