+
+      // Keyboard navigation on the carousel track and within cards
+      carousel.addEventListener('keydown', (e) => {
+        if (e.key === 'ArrowRight') {
+          e.preventDefault();
+          scrollToCard(getActiveIndex() + 1);
+        } else if (e.key === 'ArrowLeft') {
+          e.preventDefault();
+          scrollToCard(getActiveIndex() - 1);
+        } else if (e.key === 'Home') {
+          e.preventDefault();
+          scrollToCard(0);
+        } else if (e.key === 'End') {
+          e.preventDefault();
+          scrollToCard(cards.length - 1);
+        }
+      });
+
+      // Pointer drag-to-swipe support for mouse / touch
+      let isPointerDown = false;
+      let hasDragged = false;
+      let startX = 0;
+      let startScrollLeft = 0;
+
+      carousel.addEventListener('pointerdown', (e) => {
+        if (e.target.closest('button, a')) return;
+        isPointerDown = true;
+        hasDragged = false;
+        startX = e.clientX;
+        startScrollLeft = carousel.scrollLeft;
+        carousel.classList.add('is-dragging');
+        if (carousel.setPointerCapture) {
+          try { carousel.setPointerCapture(e.pointerId); } catch (_) {}
+        }
+      });
+
+      carousel.addEventListener('pointermove', (e) => {
+        if (!isPointerDown) return;
+        const deltaX = e.clientX - startX;
+        if (Math.abs(deltaX) > 5) {
+          hasDragged = true;
+        }
+        carousel.scrollLeft = startScrollLeft - deltaX;
+      });
+
+      function endPointerDrag() {
+        if (!isPointerDown) return;
+        isPointerDown = false;
+        carousel.classList.remove('is-dragging');
+        if (hasDragged) {
+          scrollToCard(getActiveIndex());
+        }
+      }
+
+      carousel.addEventListener('pointerup', endPointerDrag);
+      carousel.addEventListener('pointercancel', endPointerDrag);
+      carousel.addEventListener('pointerleave', endPointerDrag);
+
+      updateCarouselControls();
+
+      // Expanding Detail View right out of the triggering "View Details" button
+      const panel = document.getElementById('drink-detail-panel');
+      const backdrop = document.getElementById('detail-backdrop');
+      const closeBtn = document.getElementById('detail-close-btn');
+      const dismissBtn = document.getElementById('detail-dismiss-btn');
+      const detailTitle = document.getElementById('detail-title');
+      const detailPrice = document.getElementById('detail-price');
+      const detailDesc = document.getElementById('detail-desc');
+      const detailImg = document.getElementById('detail-img');
+      const detailRoast = document.getElementById('detail-roast');
+      const detailCaffeine = document.getElementById('detail-caffeine');
+      const detailNotes = document.getElementById('detail-notes');
+      const detailOrderLink = document.getElementById('detail-order-link');
+      const sizeButtons = Array.from(panel.querySelectorAll('.size-option-btn'));
+
+      let activeTriggerBtn = null;
+      let currentAnim = null;
+
+      sizeButtons.forEach((btn) => {
+        btn.addEventListener('click', () => {
+          sizeButtons.forEach((b) => b.setAttribute('aria-pressed', b === btn ? 'true' : 'false'));
+        });
+      });
+
+      function computeTriggerTransform(triggerEl) {
+        const panelRect = panel.getBoundingClientRect();
+        const btnRect = triggerEl.getBoundingClientRect();
+
+        const panelCenterX = window.innerWidth / 2;
+        const panelCenterY = window.innerHeight / 2;
+        const btnCenterX = btnRect.left + btnRect.width / 2;
+        const btnCenterY = btnRect.top + btnRect.height / 2;
+
+        const deltaX = btnCenterX - panelCenterX;
+        const deltaY = btnCenterY - panelCenterY;
+        const scaleX = Math.max(0.08, btnRect.width / Math.max(panelRect.width, 320));
+        const scaleY = Math.max(0.08, btnRect.height / Math.max(panelRect.height, 320));
+
+        return { deltaX, deltaY, scaleX, scaleY };
+      }
+
+      function openDetailFromButton(triggerBtn) {
+        const drinkId = triggerBtn.getAttribute('data-drink-id');
+        const data = DRINK_DATA[drinkId];
+        if (!data) return;
+
+        if (activeTriggerBtn && activeTriggerBtn !== triggerBtn) {
+          activeTriggerBtn.setAttribute('aria-expanded', 'false');
+        }
+        activeTriggerBtn = triggerBtn;
+        activeTriggerBtn.setAttribute('aria-expanded', 'true');
+
+        detailTitle.textContent = data.title;
+        detailPrice.textContent = data.price;
+        detailDesc.textContent = data.description;
+        detailImg.src = data.img;
+        detailImg.alt = data.alt;
+        detailRoast.textContent = data.roast;
+        detailCaffeine.textContent = data.caffeine;
+        detailNotes.textContent = data.notes;
+        detailOrderLink.setAttribute('href', data.href);
+
+        panel.setAttribute('aria-hidden', 'false');
+        backdrop.setAttribute('aria-hidden', 'false');
+        panel.classList.add('is-open');
+        backdrop.classList.add('is-open');
+
+        const { deltaX, deltaY, scaleX, scaleY } = computeTriggerTransform(triggerBtn);
+
+        if (currentAnim) {
+          currentAnim.cancel();
+        }
+
+        if (typeof panel.animate === 'function') {
+          currentAnim = panel.animate(
+            [
+              {
+                transform: `translate(calc(-50% + ${deltaX}px), calc(-50% + ${deltaY}px)) scale(${scaleX}, ${scaleY})`,
+                opacity: 0.25,
+                borderRadius: '28px'
+              },
+              {
+                transform: 'translate(-50%, -50%) scale(1, 1)',
+                opacity: 1,
+                borderRadius: '16px'
+              }
+            ],
+            {
+              duration: 380,
+              easing: 'cubic-bezier(0.22, 1, 0.36, 1)',
+              fill: 'forwards'
+            }
+          );
+        }
+
+        closeBtn.focus();
+      }
+
+      function closeDetailToButton() {
+        if (!panel.classList.contains('is-open')) return;
+
+        const triggerBtn = activeTriggerBtn;
+        if (triggerBtn) {
+          triggerBtn.setAttribute('aria-expanded', 'false');
+        }
+
+        backdrop.classList.remove('is-open');
+        backdrop.setAttribute('aria-hidden', 'true');
+
+        if (triggerBtn && typeof panel.animate === 'function') {
+          const { deltaX, deltaY, scaleX, scaleY } = computeTriggerTransform(triggerBtn);
+          if (currentAnim) {
+            currentAnim.cancel();
+          }
+          currentAnim = panel.animate(
+            [
+              {
+                transform: 'translate(-50%, -50%) scale(1, 1)',
+                opacity: 1,
+                borderRadius: '16px'
+              },
+              {
+                transform: `translate(calc(-50% + ${deltaX}px), calc(-50% + ${deltaY}px)) scale(${scaleX}, ${scaleY})`,
+                opacity: 0,
+                borderRadius: '28px'
+              }
+            ],
+            {
+              duration: 280,
+              easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
+              fill: 'forwards'
+            }
+          );
+          currentAnim.onfinish = () => {
+            panel.classList.remove('is-open');
+            panel.setAttribute('aria-hidden', 'true');
+            if (currentAnim) {
+              currentAnim.cancel();
+              currentAnim = null;
+            }
+          };
+        } else {
+          panel.classList.remove('is-open');
+          panel.setAttribute('aria-hidden', 'true');
+        }
+
+        if (triggerBtn) {
+          triggerBtn.focus();
+        }
+      }
+
+      document.querySelectorAll('.view-details-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          openDetailFromButton(btn);
+        });
+      });
+
+      closeBtn.addEventListener('click', closeDetailToButton);
+      dismissBtn.addEventListener('click', closeDetailToButton);
+      backdrop.addEventListener('click', closeDetailToButton);
+
+      // Focus trap and Escape key handling inside open detail dialog
+      document.addEventListener('keydown', (e) => {
+        if (!panel.classList.contains('is-open')) return;
+        if (e.key === 'Escape') {
+          e.preventDefault();
+          closeDetailToButton();
+          return;
+        }
+        if (e.key === 'Tab') {
+          const focusable = Array.from(
+            panel.querySelectorAll('button:not(:disabled), [href], [tabindex]:not([tabindex="-1"])')
+          );
+          if (focusable.length === 0) return;
+          const first = focusable[0];
+          const last = focusable[focusable.length - 1];
+          if (e.shiftKey && document.activeElement === first) {
+            e.preventDefault();
+            last.focus();
+          } else if (!e.shiftKey && document.activeElement === last) {
+            e.preventDefault();
+            first.focus();
+          }
+        }
+      });
+    })();
+  </script>
 </body>

 </html>

