+const INITIAL_STORE = {
+  rpId: RP_ID,
+  user: {
+    id: DEFAULT_USER_ID,
+    passkeyUserId: DEFAULT_USER_ID,
+    name: 'alex.rivera@dailygrind.coffee',
+    displayName: 'Alex Rivera',
+    tier: 'Gold Bean Member',
+  },
+  credentials: [
+    {
+      // Base64URL('dg-cred-icloud-001') -> length 24 (24 % 4 === 0)
+      id: 'ZGctY3JlZC1pY2xvdWQtMDAx',
+      passkeyUserId: DEFAULT_USER_ID,
+      credentialPublicKey: 'pQECAyYgASFYIJV8c2FtcGxlLXB1YmxpYy1rZXktaWNsb3VkLTAwMSYg',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      providerIcon: aaguids['fbfc3007-154e-4ecc-8c0b-6e020557d7bd'].icon_light,
+      name: 'iCloud Keychain',
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1789401600000,
+      lastUsedAt: 1795276800000,
+      counter: 14,
+    },
+    {
+      // Base64URL('dg-cred-google-002') -> length 24 (24 % 4 === 0)
+      id: 'ZGctY3JlZC1nb29nbGUtMDAy',
+      passkeyUserId: DEFAULT_USER_ID,
+      credentialPublicKey: 'pQECAyYgASFYIJV8c2FtcGxlLXB1YmxpYy1rZXktZ29vZ2xlLTAwMiYg',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      providerIcon: aaguids['ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4'].icon_light,
+      name: 'Personal Pixel 9 Pro',
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1791129600000,
+      lastUsedAt: 1794844800000,
+      counter: 6,
+    },
+    {
+      // Base64URL('dg-cred-1password-003') -> length 28 (28 % 4 === 0)
+      id: 'ZGctY3JlZC0xcGFzc3dvcmQtMDAz',
+      passkeyUserId: DEFAULT_USER_ID,
+      credentialPublicKey: 'pQECAyYgASFYIJV8c2FtcGxlLXB1YmxpYy1rZXktMXBhc3N3b3JkLTAz',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+      providerIcon: aaguids['bada5566-a7aa-401f-bd96-45619a55120d'].icon_light,
+      name: '1Password Vault',
+      transports: ['internal'],
+      registeredAt: 1792857600000,
+      lastUsedAt: 1793721600000,
+      counter: 3,
+    },
+  ],
+};
+
+function loadStore() {
+  try {
+    const raw = window.localStorage.getItem(STORAGE_KEY);
+    if (raw) {
+      const parsed = JSON.parse(raw);
+      if (parsed && Array.isArray(parsed.credentials) && parsed.user) {
+        return parsed;
+      }
+    }
+  } catch {
+    // Ignore storage access errors and use in-memory clone
+  }
+  return structuredClone(INITIAL_STORE);
+}
+
+function saveStore(store) {
+  try {
+    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(store));
+  } catch {
+    // Ignore storage quota errors
+  }
+}
+
+function jsonResponse(data, status = 200) {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json' },
+  });
+}
+
+function isStaticFallbackNeeded(response) {
+  const contentType = response.headers.get('content-type') || '';
+  return (response.status === 404 || response.status === 405 || response.status === 501) &&
+    !contentType.includes('application/json');
+}
+
+function generateRandomBase64Url(byteLength = 32) {
+  const bytes = new Uint8Array(byteLength);
+  crypto.getRandomValues(bytes);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i += 1) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
+}
+
+export async function listFetch() {
+  try {
+    const response = await fetch('/api/credentials', {
+      method: 'GET',
+      headers: { Accept: 'application/json' },
+    });
+    if (!isStaticFallbackNeeded(response)) {
+      return response;
+    }
+  } catch {
+    // Fall back to local store when offline/unmounted
+  }
+
+  const store = loadStore();
+  saveStore(store);
+  return jsonResponse({
+    rpId: store.rpId || RP_ID,
+    userId: store.user.passkeyUserId,
+    user: store.user,
+    credentials: store.credentials,
+  });
+}
+
+export async function renameCredentialFetch(credentialId, { name }) {
+  const store = loadStore();
+  const target = store.credentials.find((c) => c.id === credentialId);
+  if (target && typeof name === 'string' && name.trim()) {
+    target.name = name.trim();
+    saveStore(store);
+  }
+
+  try {
+    const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+      method: 'PUT',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ name }),
+    });
+    if (!isStaticFallbackNeeded(response)) {
+      return response;
+    }
+  } catch {
+    // Fall back to local store
+  }
+
+  if (!target) {
+    return jsonResponse({ error: 'Credential not found.' }, 404);
+  }
+  return jsonResponse(target, 200);
+}
+
+export async function deleteFetch(credentialId) {
+  const store = loadStore();
+  const index = store.credentials.findIndex((c) => c.id === credentialId);
+  const existed = index !== -1;
+  if (existed) {
+    store.credentials.splice(index, 1);
+    saveStore(store);
+  }
+
+  try {
+    const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+      method: 'DELETE',
+      headers: { Accept: 'application/json' },
+    });
+    if (!isStaticFallbackNeeded(response)) {
+      return response;
+    }
+  } catch {
+    // Fall back to local store
+  }
+
+  if (!existed) {
+    return jsonResponse({ error: 'Credential not found.' }, 404);
+  }
+  return jsonResponse({ success: true }, 200);
+}
+
+export async function updateUserFetch({ name, displayName }) {
+  const store = loadStore();
+  if (typeof name === 'string' && name.trim()) {
+    store.user.name = name.trim();
+  }
+  if (typeof displayName === 'string' && displayName.trim()) {
+    store.user.displayName = displayName.trim();
+  }
+  saveStore(store);
+
+  try {
+    const response = await fetch('/api/user', {
+      method: 'PUT',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({
+        name: store.user.name,
+        displayName: store.user.displayName,
+      }),
+    });
+    if (!isStaticFallbackNeeded(response)) {
+      return response;
+    }
+  } catch {
+    // Fall back to local store
+  }
+
+  return jsonResponse({
+    ...store.user,
+    rpId: store.rpId || RP_ID,
+    userId: store.user.passkeyUserId,
+  });
+}
+
+export async function optionsFetch({ promotion = false } = {}) {
+  try {
+    const response = await fetch('/api/register/options', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ promotion }),
+    });
+    if (!isStaticFallbackNeeded(response)) {
+      return response.json();
+    }
+  } catch {
+    // Fall back to local options generator
+  }
+
+  const store = loadStore();
+  // Management flow omits authenticatorAttachment so external security keys and platform authenticators are both allowed
+  const authenticatorSelection = {
+    residentKey: 'required',
+    requireResidentKey: true,
+    userVerification: 'preferred',
+    ...(promotion && { authenticatorAttachment: 'platform' }),
+  };
+
+  return {
+    challenge: generateRandomBase64Url(32),
+    rp: {
+      id: store.rpId || RP_ID,
+      name: 'The Daily Grind',
+    },
+    user: {
+      id: store.user.passkeyUserId,
+      name: store.user.name,
+      displayName: store.user.displayName,
+    },
+    pubKeyCredParams: [
+      { type: 'public-key', alg: -7 },
+      { type: 'public-key', alg: -257 },
+    ],
+    excludeCredentials: store.credentials.map((cred) => ({
+      type: 'public-key',
+      id: cred.id,
+      transports: cred.transports,
+    })),
+    authenticatorSelection,
+  };
+}
+
+export async function registerVerifyFetch(encodedResponse) {
+  const response = await fetch('/api/register/verify', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+    body: JSON.stringify(encodedResponse),
+  });
+
+  if (!isStaticFallbackNeeded(response)) {
+    return response;
+  }
+
+  const store = loadStore();
+  const aaguid = encodedResponse.aaguid || 'adce0002-35bc-c60a-648b-0b25f1f05503';
+  const isZeroAaguid = aaguid === '00000000-0000-0000-0000-000000000000';
+  const provider = isZeroAaguid ? undefined : aaguids[aaguid];
+  const now = Date.now();
+
+  const newCredential = {
+    id: encodedResponse.id || generateRandomBase64Url(18),
+    passkeyUserId: store.user.passkeyUserId,
+    credentialPublicKey: generateRandomBase64Url(32),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid,
+    name: isZeroAaguid ? 'Unknown passkey provider' : provider?.name || 'Unknown passkey provider',
+    providerIcon: isZeroAaguid ? undefined : provider?.icon_light,
+    transports: encodedResponse.response?.transports || ['internal', 'hybrid'],
+    registeredAt: now,
+    lastUsedAt: now,
+    counter: 0,
+  };
+
+  store.credentials.push(newCredential);
+  saveStore(store);
+  return jsonResponse(newCredential, 200);
+}
