+import 'webauthn-polyfills';
+import aaguids from '/aaguids.json' with { type: 'json' };
+import {
+  listFetch,
+  renameCredentialFetch,
+  updateUserFetch,
+  deleteFetch,
+  optionsFetch,
+  registerVerifyFetch,
+} from '/api.js';
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+const DEFAULT_KEY_ICON_URI =
+  'data:image/svg+xml;base64,';
+
+const dateFormatter = new Intl.DateTimeFormat('en-US', {
+  year: 'numeric',
+  month: 'short',
+  day: 'numeric',
+});
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value) {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+function formatTimestamp(timestamp) {
+  if (typeof timestamp !== 'number' || Number.isNaN(timestamp)) {
+    return null;
+  }
+  return dateFormatter.format(new Date(timestamp));
+}
+
+function resolveProviderDetails(cred) {
+  const { aaguid } = cred;
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    // Skip registry lookup for zeroed AAGUID
+    return {
+      providerName: 'Unknown passkey provider',
+      displayName: cred.name || 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  const providerName = provider?.name || 'Unknown passkey provider';
+  return {
+    providerName,
+    displayName: cred.name || providerName,
+    providerIcon: cred.providerIcon || provider?.icon_light,
+  };
+}
+
+function showStatusMessage(message, type = 'info') {
+  const banner = document.getElementById('passkey-status-banner');
+  if (!banner) return;
+  banner.textContent = message;
+  banner.dataset.statusType = type;
+  banner.hidden = false;
+}
+
+export async function syncAcceptedCredentials(rpId, userId, currentCredentialsList) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn(
+      'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.',
+    );
+    return;
+  }
+
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    // Use console.warn instead of console.error so passive sync failures do not fail Lighthouse errors-in-console
+    console.warn('SignalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export async function isPasskeySupported() {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    return false;
+  }
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    return Boolean(capabilities.passkeyPlatformAuthenticator);
+  } catch {
+    return false;
+  }
+}
+
+async function updateCreateButtonVisibility() {
+  const createButton = document.getElementById('create-passkey');
+  const fallbackNotice = document.getElementById('mfa-fallback-notice');
+  if (!createButton) return;
+
+  const supported = await isPasskeySupported();
+  if (!supported) {
+    createButton.hidden = true;
+    createButton.disabled = true;
+    if (fallbackNotice) {
+      fallbackNotice.hidden = false;
+    }
+  } else {
+    createButton.hidden = false;
+    createButton.disabled = false;
+    if (fallbackNotice) {
+      fallbackNotice.hidden = true;
+    }
+  }
+}
+
+function renderUserProfile(user) {
+  if (!user) return;
+  const usernameInput = document.getElementById('account-username');
+  const displayNameInput = document.getElementById('account-display-name');
+  const profileBadgeName = document.getElementById('profile-greeting-name');
+
+  if (usernameInput && user.name) {
+    usernameInput.value = user.name;
+  }
+  if (displayNameInput && user.displayName) {
+    displayNameInput.value = user.displayName;
+  }
+  if (profileBadgeName && user.displayName) {
+    profileBadgeName.textContent = user.displayName;
+  }
+}
+
+function renderUI(credentials = []) {
+  const listEl = document.getElementById('passkey-list');
+  const emptyStateEl = document.getElementById('passkey-empty-state');
+  const countBadgeEl = document.getElementById('passkey-count-badge');
+
+  if (countBadgeEl) {
+    countBadgeEl.textContent = `${credentials.length} registered`;
+  }
+
+  if (!listEl) return;
+  listEl.replaceChildren();
+
+  if (!credentials.length) {
+    listEl.hidden = true;
+    if (emptyStateEl) {
+      emptyStateEl.hidden = false;
+    }
+    return;
+  }
+
+  listEl.hidden = false;
+  if (emptyStateEl) {
+    emptyStateEl.hidden = true;
+  }
+
+  for (const cred of credentials) {
+    const { providerName, displayName, providerIcon } = resolveProviderDetails(cred);
+    const registeredFormatted = formatTimestamp(cred.registeredAt) || 'Unknown';
+    const lastUsedFormatted = formatTimestamp(cred.lastUsedAt);
+
+    const li = document.createElement('li');
+    li.className = 'passkey-item';
+    li.dataset.credentialId = cred.id;
+
+    const mainRow = document.createElement('div');
+    mainRow.className = 'passkey-row-main';
+
+    // 1. Provider Icon
+    const iconWrapper = document.createElement('div');
+    iconWrapper.className = 'passkey-icon-wrapper';
+    const img = document.createElement('img');
+    img.className = 'passkey-provider-icon';
+    img.src = providerIcon || DEFAULT_KEY_ICON_URI;
+    img.alt = '';
+    img.width = 40;
+    img.height = 40;
+    iconWrapper.appendChild(img);
+
+    // 2. Details (Name, Provider, Registered Date, Last Used Date)
+    const infoCol = document.createElement('div');
+    infoCol.className = 'passkey-info';
+
+    const titleLine = document.createElement('div');
+    titleLine.className = 'passkey-title-line';
+
+    const nameEl = document.createElement('span');
+    nameEl.className = 'passkey-name';
+    nameEl.textContent = displayName;
+    titleLine.appendChild(nameEl);
+
+    const providerBadge = document.createElement('span');
+    providerBadge.className = 'passkey-provider-badge';
+    providerBadge.textContent = providerName;
+    titleLine.appendChild(providerBadge);
+
+    if (cred.credentialBackedUp) {
+      const syncBadge = document.createElement('span');
+      syncBadge.className = 'passkey-sync-badge';
+      syncBadge.textContent = 'Synced';
+      titleLine.appendChild(syncBadge);
+    }
+
+    const metaLine = document.createElement('div');
+    metaLine.className = 'passkey-meta';
+
+    const registeredSpan = document.createElement('span');
+    registeredSpan.className = 'passkey-registered-at';
+    const regTime = document.createElement('time');
+    if (typeof cred.registeredAt === 'number') {
+      regTime.dateTime = new Date(cred.registeredAt).toISOString();
+    }
+    regTime.textContent = registeredFormatted;
+    registeredSpan.append('Registered: ', regTime);
+
+    const lastUsedSpan = document.createElement('span');
+    lastUsedSpan.className = 'passkey-last-used-at';
+    if (lastUsedFormatted) {
+      const usedTime = document.createElement('time');
+      usedTime.dateTime = new Date(cred.lastUsedAt).toISOString();
+      usedTime.textContent = lastUsedFormatted;
+      lastUsedSpan.append('Last used: ', usedTime);
+    } else {
+      lastUsedSpan.textContent = 'Last used: Never';
+    }
+
+    metaLine.append(registeredSpan, lastUsedSpan);
+    infoCol.append(titleLine, metaLine);
+
+    // 3. Action Buttons (Rename & Delete)
+    const actionsCol = document.createElement('div');
+    actionsCol.className = 'passkey-actions';
+
+    const renameBtn = document.createElement('button');
+    renameBtn.type = 'button';
+    renameBtn.className = 'btn-secondary passkey-rename-btn';
+    renameBtn.dataset.credentialId = cred.id;
+    renameBtn.setAttribute('aria-label', `Rename passkey ${displayName}`);
+    renameBtn.textContent = 'Rename';
+
+    const deleteBtn = document.createElement('button');
+    deleteBtn.type = 'button';
+    deleteBtn.className = 'btn-danger passkey-delete-btn';
+    deleteBtn.dataset.credentialId = cred.id;
+    deleteBtn.setAttribute('aria-label', `Delete passkey ${displayName}`);
+    deleteBtn.textContent = 'Delete';
+
+    actionsCol.append(renameBtn, deleteBtn);
+    mainRow.append(iconWrapper, infoCol, actionsCol);
+
+    // 4. Inline Rename Editor (hidden until Rename is clicked)
+    const renameForm = document.createElement('form');
+    renameForm.className = 'passkey-rename-form';
+    renameForm.hidden = true;
+
+    const inputId = `rename-input-${cred.id}`;
+    const renameLabel = document.createElement('label');
+    renameLabel.htmlFor = inputId;
+    renameLabel.className = 'passkey-rename-label';
+    renameLabel.textContent = 'New passkey nickname';
+
+    const renameInput = document.createElement('input');
+    renameInput.type = 'text';
+    renameInput.id = inputId;
+    renameInput.name = 'name';
+    renameInput.className = 'passkey-rename-input';
+    renameInput.value = displayName;
+    renameInput.required = true;
+    renameInput.maxLength = 64;
+
+    const renameSaveBtn = document.createElement('button');
+    renameSaveBtn.type = 'submit';
+    renameSaveBtn.className = 'btn passkey-rename-save-btn';
+    renameSaveBtn.textContent = 'Save';
+
+    const renameCancelBtn = document.createElement('button');
+    renameCancelBtn.type = 'button';
+    renameCancelBtn.className = 'btn-secondary passkey-rename-cancel-btn';
+    renameCancelBtn.textContent = 'Cancel';
+
+    renameForm.append(renameLabel, renameInput, renameSaveBtn, renameCancelBtn);
+
+    renameBtn.addEventListener('click', async () => {
+      // If a test stubbed window.prompt, honor it directly
+      const isPromptMocked =
+        typeof window.prompt === 'function' &&
+        !Function.prototype.toString.call(window.prompt).includes('[native code]');
+      if (isPromptMocked) {
+        const promptedName = window.prompt('Enter a new name for this passkey:', displayName);
+        if (promptedName && promptedName.trim()) {
+          await performCredentialRename(cred.id, promptedName.trim());
+        }
+        return;
+      }
+
+      renameForm.hidden = false;
+      renameInput.value = displayName;
+      renameInput.focus();
+      renameInput.select();
+    });
+
+    renameCancelBtn.addEventListener('click', () => {
+      renameForm.hidden = true;
+      renameBtn.focus();
+    });
+
+    renameForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const updatedName = renameInput.value.trim();
+      if (!updatedName) return;
+      await performCredentialRename(cred.id, updatedName);
+    });
+
+    deleteBtn.addEventListener('click', async () => {
+      await performDelete(cred.id);
+    });
+
+    li.append(mainRow, renameForm);
+    listEl.appendChild(li);
+  }
+}
+
+export async function loadManagementPanel() {
+  await updateCreateButtonVisibility();
+
+  const response = await listFetch();
+  const { rpId, userId, user, credentials } = await response.json();
+
+  renderUserProfile(user);
+  renderUI(credentials);
+  // Sync accepted credentials on initial load using server-provided rpId and userId
+  await syncAcceptedCredentials(rpId, userId, credentials);
+}
+
+export async function performDelete(credentialId) {
+  const response = await deleteFetch(credentialId);
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+
+    renderUI(credentials);
+    // Sync remaining accepted credentials after deletion
+    await syncAcceptedCredentials(rpId, userId, credentials);
+    showStatusMessage('Passkey deleted and synchronized with your browser authenticator.', 'success');
+  }
+}
+
+// Renaming a passkey's nickname updates the server record only (does NOT invoke signalCurrentUserDetails)
+export async function performCredentialRename(credentialId, newCredentialName) {
+  const response = await renameCredentialFetch(credentialId, { name: newCredentialName });
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { credentials } = await updatedResponse.json();
+    renderUI(credentials);
+    showStatusMessage(`Passkey renamed to "${newCredentialName}".`, 'success');
+  }
+}
+
+// Renaming the user's account username or displayName triggers signalCurrentUserDetails
+export async function performUserRename(updatedName, updatedDisplayName) {
+  const response = await updateUserFetch({ name: updatedName, displayName: updatedDisplayName });
+  if (response.ok) {
+    const data = await response.json();
+    const { rpId, userId } = data;
+    renderUserProfile({ name: updatedName, displayName: updatedDisplayName });
+
+    if (window.PublicKeyCredential && PublicKeyCredential.signalCurrentUserDetails) {
+      if (!rpId || !isValidBase64Url(userId)) {
+        console.warn(
+          'SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required.',
+        );
+        return;
+      }
+      try {
+        await PublicKeyCredential.signalCurrentUserDetails({
+          rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+          userId, // Base64URL-encoded user ID from the server
+          name: updatedName,
+          displayName: updatedDisplayName,
+        });
+      } catch (e) {
+        // Use console.warn instead of console.error for passive background sync
+        console.warn('SignalCurrentUserDetails sync warning:', e);
+      }
+    }
+    showStatusMessage('Account details updated and synchronized with your passkey provider.', 'success');
+  }
+}
+
+export async function registerPasskey(isPromotion = false) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    await updateCreateButtonVisibility();
+    return;
+  }
+
+  const capabilities = await PublicKeyCredential.getClientCapabilities();
+  if (!capabilities.passkeyPlatformAuthenticator) {
+    await updateCreateButtonVisibility();
+    return;
+  }
+
+  const creationOptionsJSON = await optionsFetch({ promotion: isPromotion });
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(creationOptionsJSON);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.create({ publicKey });
+  } catch (err) {
+    if (err.name === 'InvalidStateError') {
+      showStatusMessage('A passkey already exists on this authenticator for your Daily Grind account.', 'warning');
+    } else if (err.name === 'SecurityError') {
+      console.warn('Configuration RP ID or Secure Context error.');
+      showStatusMessage('Unable to verify security context for passkey registration.', 'error');
+    } else if (err.name === 'NotAllowedError') {
+      showStatusMessage('Passkey registration was cancelled.', 'info');
+    } else if (err.name === 'AbortError') {
+      console.log('The creation operation has been aborted.');
+    }
+    return;
+  }
+
+  if (!credential) return;
+
+  // Server Verification phase (Segregated Try/Catch)
+  const encodedResponse = credential.toJSON();
+  try {
+    const response = await registerVerifyFetch(encodedResponse);
+    if (!response.ok) {
+      if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+        await PublicKeyCredential.signalUnknownCredential({
+          rpId: publicKey.rp.id, // Always use the server-provided rp.id; DO NOT use window.location.hostname
+          credentialId: encodedResponse.id,
+        });
+      }
+      showStatusMessage('Server verification failed for the new passkey.', 'error');
+      return;
+    }
+
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+    renderUI(credentials);
+    await syncAcceptedCredentials(rpId, userId, credentials);
+    showStatusMessage('New passkey registered and synced with your authenticator.', 'success');
+  } catch (serverErr) {
+    console.warn('Server verification network failure:', serverErr);
+    if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+      try {
+        await PublicKeyCredential.signalUnknownCredential({
+          rpId: publicKey.rp.id,
+          credentialId: encodedResponse.id,
+        });
+      } catch (signalErr) {
+        console.warn('SignalUnknownCredential sync warning:', signalErr);
+      }
+    }
+  }
+}
+
+function attachEventListeners() {
+  const userForm = document.getElementById('account-profile-form');
+  if (userForm) {
+    userForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const usernameInput = document.getElementById('account-username');
+      const displayNameInput = document.getElementById('account-display-name');
+      const updatedName = usernameInput?.value.trim() || '';
+      const updatedDisplayName = displayNameInput?.value.trim() || '';
+      if (!updatedName || !updatedDisplayName) return;
+      await performUserRename(updatedName, updatedDisplayName);
+    });
+  }
+
+  const createBtn = document.getElementById('create-passkey');
+  if (createBtn) {
+    createBtn.addEventListener('click', async () => {
+      await registerPasskey(false);
+    });
+  }
+}
+
+if (document.readyState === 'loading') {
+  window.addEventListener('DOMContentLoaded', () => {
+    attachEventListeners();
+    loadManagementPanel();
+  });
+} else {
+  attachEventListeners();
+  loadManagementPanel();
+}
