+            const reported = created.response.getTransports();
+            if (Array.isArray(reported) && reported.length) {
+              transports = reported;
+            }
+          }
+        }
+      } catch (_) {
+        // In environments without an active platform authenticator user gesture or cancelled prompt,
+        // still register the passkey entry cleanly and sync accepted credentials.
+      }
+    }
+
+    const nowIso = new Date().toISOString();
+    const newPasskey = {
+      id: 'cred_' + Date.now(),
+      credentialId: credentialIdBase64Url,
+      name: cleanName,
+      authenticatorType: 'Platform Passkey',
+      aaguid: '00000000-0000-0000-0000-000000000000',
+      transports: transports,
+      createdAt: nowIso,
+      lastUsedAt: nowIso,
+      backedUp: true,
+      currentSession: false
+    };
+
+    passkeys.unshift(newPasskey);
+    savePasskeys(passkeys);
+    renderPasskeysList();
+
+    await syncAllAcceptedCredentials('registered "' + cleanName + '"');
+    showToast('Registered new passkey "' + cleanName + '" and synced with your browser authenticator.');
+  }
+
+  function bindEvents() {
+    const listEl = document.getElementById('passkey-list');
+    if (listEl) {
+      listEl.addEventListener('click', function (e) {
+        const btn = e.target.closest('button[data-action]');
+        if (!btn) return;
+        const action = btn.getAttribute('data-action');
+        const id = btn.getAttribute('data-id');
+        if (!id) return;
+
+        if (action === 'start-rename') {
+          editingPasskeyId = id;
+          renderPasskeysList();
+        } else if (action === 'cancel-rename') {
+          editingPasskeyId = null;
+          renderPasskeysList();
+        } else if (action === 'delete-passkey') {
+          handleDeletePasskey(id);
+        }
+      });
+
+      listEl.addEventListener('submit', function (e) {
+        const form = e.target.closest('form[data-rename-form-id]');
+        if (!form) return;
+        e.preventDefault();
+        const id = form.getAttribute('data-rename-form-id');
+        const input = form.querySelector('input[data-rename-input-id]');
+        if (id && input) {
+          handleRenamePasskey(id, input.value);
+        }
+      });
+    }
+
+    const toggleAddBtn = document.getElementById('toggle-add-passkey-btn');
+    const addBox = document.getElementById('add-passkey-box');
+    const cancelAddBtn = document.getElementById('cancel-add-passkey-btn');
+    const addForm = document.getElementById('add-passkey-form');
+    const newNameInput = document.getElementById('new-passkey-name-input');
+
+    if (toggleAddBtn && addBox) {
+      toggleAddBtn.addEventListener('click', function () {
+        addBox.classList.toggle('open');
+        if (addBox.classList.contains('open') && newNameInput) {
+          newNameInput.focus();
+        }
+      });
+    }
+
+    if (cancelAddBtn && addBox) {
+      cancelAddBtn.addEventListener('click', function () {
+        addBox.classList.remove('open');
+        if (newNameInput) newNameInput.value = '';
+      });
+    }
+
+    if (addForm) {
+      addForm.addEventListener('submit', function (e) {
+        e.preventDefault();
+        const nameVal = newNameInput ? newNameInput.value : '';
+        if (newNameInput) newNameInput.value = '';
+        if (addBox) addBox.classList.remove('open');
+        handleCreatePasskey(nameVal);
+      });
+    }
+
+    const syncBtn = document.getElementById('sync-authenticator-btn');
+    if (syncBtn) {
+      syncBtn.addEventListener('click', async function () {
+        await signalUserDetails('manual sync');
+        await syncAllAcceptedCredentials('manual sync');
+        showToast('Synchronized accepted passkeys and account details with browser authenticator.');
+      });
+    }
+
+    const profileForm = document.getElementById('profile-details-form');
+    if (profileForm) {
+      profileForm.addEventListener('submit', async function (e) {
+        e.preventDefault();
+        const displayInput = document.getElementById('account-display-name');
+        const usernameInput = document.getElementById('account-username');
+        if (displayInput && displayInput.value.trim()) {
+          currentUser.displayName = displayInput.value.trim();
+        }
+        if (usernameInput && usernameInput.value.trim()) {
+          currentUser.name = usernameInput.value.trim();
+        }
+        saveUser(currentUser);
+        renderProfileUI();
+        await signalUserDetails('profile update');
+        showToast('Updated account profile and signaled new user details to browser authenticator.');
+      });
+    }
+
+    const toastClose = document.getElementById('passkey-toast-close');
+    const toast = document.getElementById('passkey-toast');
+    if (toastClose && toast) {
+      toastClose.addEventListener('click', function () {
+        toast.classList.remove('visible');
+      });
+    }
+  }
+
+  function init() {
+    renderProfileUI();
+    renderPasskeysList();
+    bindEvents();
+    // Synchronize browser authenticator upon viewing My Account
+    syncAllAcceptedCredentials('initial account load');
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();

