+import React, { useState, useEffect, useCallback } from 'react';
+import 'webauthn-polyfills';
+import aaguidsData from '../utils/aaguids.json';
+
+interface AaguidInfo {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids: Record<string, AaguidInfo> = aaguidsData;
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export interface PasskeyCredentialItem {
+  id: string;
+  passkeyUserId: string;
+  credentialPublicKey: string;
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+export interface UserProfile {
+  id: string;
+  passkeyUserId: string;
+  name: string;
+  displayName: string;
+  subscriptionTier?: string;
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+function getAaguidMetadata(cred: PasskeyCredentialItem): {
+  displayName: string;
+  providerName: string;
+  providerIcon?: string;
+} {
+  if (!cred.aaguid || cred.aaguid === ZERO_AAGUID) {
+    return {
+      displayName: cred.name || 'Unknown passkey provider',
+      providerName: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[cred.aaguid];
+  const providerName = provider?.name || 'Unknown passkey provider';
+  return {
+    displayName: cred.name || providerName,
+    providerName,
+    providerIcon: cred.providerIcon || provider?.icon_light,
+  };
+}
+
+function formatEpochDate(timestamp?: number): string {
+  if (!timestamp) return 'Never used';
+  try {
+    return new Date(timestamp).toLocaleDateString('en-US', {
+      year: 'numeric',
+      month: 'short',
+      day: 'numeric',
+    });
+  } catch {
+    return 'Unknown date';
+  }
+}
+
+export default function PasskeyManagement() {
+  const baseUrl = import.meta.env.BASE_URL || '/';
+
+  const [credentials, setCredentials] = useState<PasskeyCredentialItem[]>([]);
+  const [rpId, setRpId] = useState<string>('');
+  const [userId, setUserId] = useState<string>('');
+  const [userName, setUserName] = useState<string>('alex.morgan@devtoolstimes.dev');
+  const [userDisplayName, setUserDisplayName] = useState<string>('Alex Morgan');
+  const [subscriptionTier, setSubscriptionTier] = useState<string>('Digital All-Access Subscriber');
+
+  const [loading, setLoading] = useState<boolean>(true);
+  const [passkeySupported, setPasskeySupported] = useState<boolean>(true);
+  const [creatingPasskey, setCreatingPasskey] = useState<boolean>(false);
+
+  // Rename state for individual passkey credentials
+  const [editingCredentialId, setEditingCredentialId] = useState<string | null>(null);
+  const [editingCredentialName, setEditingCredentialName] = useState<string>('');
+  const [savingCredentialId, setSavingCredentialId] = useState<string | null>(null);
+  const [deletingCredentialId, setDeletingCredentialId] = useState<string | null>(null);
+
+  // User profile form state
+  const [savingProfile, setSavingProfile] = useState<boolean>(false);
+
+  // Feedback banners
+  const [statusMessage, setStatusMessage] = useState<{
+    type: 'success' | 'error' | 'info';
+    text: string;
+  } | null>(null);
+
+  const syncAcceptedCredentials = useCallback(
+    async (serverRpId: string, serverUserId: string, currentCredentialsList: PasskeyCredentialItem[]) => {
+      if (
+        typeof window === 'undefined' ||
+        !window.PublicKeyCredential ||
+        !PublicKeyCredential.signalAllAcceptedCredentials
+      ) {
+        return;
+      }
+
+      const credentialIds = currentCredentialsList.map((c) => c.id);
+      if (
+        !serverRpId ||
+        !isValidBase64Url(serverUserId) ||
+        !credentialIds.every(isValidBase64Url)
+      ) {
+        console.warn(
+          'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.'
+        );
+        return;
+      }
+
+      try {
+        await PublicKeyCredential.signalAllAcceptedCredentials({
+          rpId: serverRpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+          userId: serverUserId, // Base64URL-encoded user ID from the server
+          allAcceptedCredentialIds: credentialIds,
+        });
+      } catch (e) {
+        // Use console.warn instead of console.error so passive sync failures do not trigger console error checks
+        console.warn('SignalAllAcceptedCredentials sync warning:', e);
+      }
+    },
+    []
+  );
+
+  const fetchCredentialsList = useCallback(async () => {
+    const response = await fetch(`${baseUrl}api/credentials`);
+    if (!response.ok) {
+      throw new Error('Failed to load registered passkeys.');
+    }
+    return response.json();
+  }, [baseUrl]);
+
+  useEffect(() => {
+    let mounted = true;
+
+    async function checkPasskeyCapabilities() {
+      if (
+        typeof window === 'undefined' ||
+        !window.PublicKeyCredential ||
+        !PublicKeyCredential.getClientCapabilities
+      ) {
+        if (mounted) setPasskeySupported(false);
+        return;
+      }
+      try {
+        const capabilities = await PublicKeyCredential.getClientCapabilities();
+        const isSupported = Boolean(
+          capabilities.passkeyPlatformAuthenticator &&
+            (capabilities.conditionalGet === undefined || capabilities.conditionalGet)
+        );
+        if (mounted) setPasskeySupported(isSupported);
+      } catch {
+        if (mounted) setPasskeySupported(false);
+      }
+    }
+
+    async function loadManagementPanel() {
+      setLoading(true);
+      try {
+        const data = await fetchCredentialsList();
+        if (!mounted) return;
+
+        setRpId(data.rpId);
+        setUserId(data.userId);
+        setCredentials(data.credentials || []);
+        if (data.user) {
+          setUserName(data.user.name || '');
+          setUserDisplayName(data.user.displayName || '');
+          if (data.user.subscriptionTier) {
+            setSubscriptionTier(data.user.subscriptionTier);
+          }
+        }
+
+        // Sync accepted credentials on initial page load using server-provided rpId and userId
+        await syncAcceptedCredentials(data.rpId, data.userId, data.credentials || []);
+      } catch {
+        if (mounted) {
+          setStatusMessage({
+            type: 'error',
+            text: 'Unable to load your registered passkeys. Please refresh the page.',
+          });
+        }
+      } finally {
+        if (mounted) setLoading(false);
+      }
+    }
+
+    checkPasskeyCapabilities();
+    loadManagementPanel();
+
+    return () => {
+      mounted = false;
+    };
+  }, [fetchCredentialsList, syncAcceptedCredentials]);
+
+  // Renaming the user's account username or displayName triggers signalCurrentUserDetails
+  const handleUserProfileUpdate = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setStatusMessage(null);
+    setSavingProfile(true);
+
+    try {
+      const response = await fetch(`${baseUrl}api/user`, {
+        method: 'PUT',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          name: userName,
+          displayName: userDisplayName,
+        }),
+      });
+
+      if (!response.ok) {
+        const errData = await response.json().catch(() => ({}));
+        setStatusMessage({
+          type: 'error',
+          text: errData.error || 'Could not update reader profile details.',
+        });
+        return;
+      }
+
+      const updatedData = await response.json();
+      const serverRpId = updatedData.rpId || rpId;
+      const serverUserId = updatedData.userId || userId;
+      const updatedName = updatedData.name || userName;
+      const updatedDisplayName = updatedData.displayName || userDisplayName;
+
+      setRpId(serverRpId);
+      setUserId(serverUserId);
+      setUserName(updatedName);
+      setUserDisplayName(updatedDisplayName);
+
+      if (
+        typeof window !== 'undefined' &&
+        window.PublicKeyCredential &&
+        PublicKeyCredential.signalCurrentUserDetails
+      ) {
+        if (!serverRpId || !isValidBase64Url(serverUserId)) {
+          console.warn(
+            'SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required.'
+          );
+        } else {
+          try {
+            await PublicKeyCredential.signalCurrentUserDetails({
+              rpId: serverRpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+              userId: serverUserId, // Base64URL-encoded user ID from the server
+              name: updatedName,
+              displayName: updatedDisplayName,
+            });
+          } catch (syncErr) {
+            console.warn('SignalCurrentUserDetails sync warning:', syncErr);
+          }
+        }
+      }
+
+      setStatusMessage({
+        type: 'success',
+        text: 'Reader profile updated and synchronized with your passkey authenticator.',
+      });
+    } catch {
+      setStatusMessage({
+        type: 'error',
+        text: 'A network error occurred while updating your profile.',
+      });
+    } finally {
+      setSavingProfile(false);
+    }
+  };
+
+  // Start inline rename for a credential
+  const startCredentialRename = (cred: PasskeyCredentialItem) => {
+    const meta = getAaguidMetadata(cred);
+    setEditingCredentialId(cred.id);
+    setEditingCredentialName(meta.displayName);
+    setStatusMessage(null);
+  };
+
+  const cancelCredentialRename = () => {
+    setEditingCredentialId(null);
+    setEditingCredentialName('');
+  };
+
+  // Renaming an individual passkey's nickname updates the server record only (does NOT invoke signalCurrentUserDetails)
+  const performCredentialRename = async (credentialId: string, newCredentialName: string) => {
+    const trimmed = newCredentialName.trim();
+    if (!trimmed) {
+      setStatusMessage({
+        type: 'error',
+        text: 'Passkey display name cannot be empty.',
+      });
+      return;
+    }
+
+    setSavingCredentialId(credentialId);
+    setStatusMessage(null);
+
+    try {
+      const response = await fetch(
+        `${baseUrl}api/credential/${encodeURIComponent(credentialId)}`,
+        {
+          method: 'PUT',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ name: trimmed }),
+        }
+      );
+
+      if (response.ok) {
+        const updatedData = await fetchCredentialsList();
+        setCredentials(updatedData.credentials || []);
+        setEditingCredentialId(null);
+        setEditingCredentialName('');
+        setStatusMessage({
+          type: 'success',
+          text: `Updated passkey display name to "${trimmed}".`,
+        });
+      } else {
+        const errData = await response.json().catch(() => ({}));
+        setStatusMessage({
+          type: 'error',
+          text: errData.error || 'Could not rename passkey.',
+        });
+      }
+    } catch {
+      setStatusMessage({
+        type: 'error',
+        text: 'A network error occurred while renaming the passkey.',
+      });
+    } finally {
+      setSavingCredentialId(null);
+    }
+  };
+
+  // Deleting a passkey removes it from the server and calls signalAllAcceptedCredentials
+  const performDelete = async (credentialId: string, label: string) => {
+    setDeletingCredentialId(credentialId);
+    setStatusMessage(null);
+
+    try {
+      const response = await fetch(
+        `${baseUrl}api/credential/${encodeURIComponent(credentialId)}`,
+        {
+          method: 'DELETE',
+        }
+      );
+
+      if (response.ok) {
+        const updatedData = await fetchCredentialsList();
+        const nextCredentials = updatedData.credentials || [];
+        const serverRpId = updatedData.rpId || rpId;
+        const serverUserId = updatedData.userId || userId;
+
+        setRpId(serverRpId);
+        setUserId(serverUserId);
+        setCredentials(nextCredentials);
+
+        // Immediately synchronize remaining accepted credential IDs with browser authenticator
+        await syncAcceptedCredentials(serverRpId, serverUserId, nextCredentials);
+
+        setStatusMessage({
+          type: 'success',
+          text: `Removed passkey "${label}" and synchronized your authenticator.`,
+        });
+      } else {
+        const errData = await response.json().catch(() => ({}));
+        setStatusMessage({
+          type: 'error',
+          text: errData.error || 'Failed to remove passkey.',
+        });
+      }
+    } catch {
+      setStatusMessage({
+        type: 'error',
+        text: 'A network error occurred while removing the passkey.',
+      });
+    } finally {
+      setDeletingCredentialId(null);
+    }
+  };
+
+  // Create a new passkey (management flow: omits authenticatorAttachment so security keys are also allowed)
+  const handleCreatePasskey = async () => {
+    setStatusMessage(null);
+
+    if (
+      typeof window === 'undefined' ||
+      !window.PublicKeyCredential ||
+      !PublicKeyCredential.getClientCapabilities
+    ) {
+      setPasskeySupported(false);
+      return;
+    }
+
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    if (!capabilities.passkeyPlatformAuthenticator || !capabilities.conditionalGet) {
+      setPasskeySupported(false);
+      return;
+    }
+
+    setCreatingPasskey(true);
+
+    try {
+      const optionsResponse = await fetch(`${baseUrl}api/passkeys/register-options`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ promotion: false }),
+      });
+
+      if (!optionsResponse.ok) {
+        setStatusMessage({
+          type: 'error',
+          text: 'Could not initialize passkey creation options.',
+        });
+        return;
+      }
+
+      const creationOptionsJSON = await optionsResponse.json();
+      const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(creationOptionsJSON);
+
+      let credential: PublicKeyCredential | null = null;
+      try {
+        credential = (await navigator.credentials.create({
+          publicKey,
+        })) as PublicKeyCredential | null;
+      } catch (err: any) {
+        if (err?.name === 'InvalidStateError') {
+          setStatusMessage({
+            type: 'info',
+            text: 'A passkey from this authenticator is already registered for your account.',
+          });
+        } else if (err?.name === 'SecurityError') {
+          setStatusMessage({
+            type: 'error',
+            text: 'Configuration RP ID or Secure Context error prevented passkey creation.',
+          });
+        } else if (err?.name === 'NotAllowedError') {
+          setStatusMessage({
+            type: 'info',
+            text: 'Passkey registration was cancelled.',
+          });
+        } else if (err?.name === 'AbortError') {
+          setStatusMessage({
+            type: 'info',
+            text: 'Passkey registration operation was aborted.',
+          });
+        }
+        return; // Safe exit: do not signal unknown credential for user cancels
+      }
+
+      if (!credential) return;
+
+      // Server Verification phase (Segregated Try/Catch for signalUnknownCredential)
+      const encodedResponse = credential.toJSON();
+      const serverOptionRpId = creationOptionsJSON?.rp?.id || publicKey.rp.id || rpId;
+
+      try {
+        const verifyResponse = await fetch(`${baseUrl}api/passkeys/register-verify`, {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify(encodedResponse),
+        });
+
+        if (!verifyResponse.ok) {
+          if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+            try {
+              await PublicKeyCredential.signalUnknownCredential({
+                rpId: serverOptionRpId,
+                credentialId: encodedResponse.id,
+              });
+            } catch (sigErr) {
+              console.warn('SignalUnknownCredential sync warning:', sigErr);
+            }
+          }
+          const errData = await verifyResponse.json().catch(() => ({}));
+          setStatusMessage({
+            type: 'error',
+            text: errData.error || 'Server verification failed for the new passkey.',
+          });
+          return;
+        }
+
+        const updatedData = await fetchCredentialsList();
+        const nextCredentials = updatedData.credentials || [];
+        const nextRpId = updatedData.rpId || serverOptionRpId;
+        const nextUserId = updatedData.userId || userId;
+
+        setRpId(nextRpId);
+        setUserId(nextUserId);
+        setCredentials(nextCredentials);
+
+        await syncAcceptedCredentials(nextRpId, nextUserId, nextCredentials);
+
+        setStatusMessage({
+          type: 'success',
+          text: 'New passkey registered and synchronized with your authenticator.',
+        });
+      } catch (serverErr) {
+        console.warn('Server verification network failure:', serverErr);
+        if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+          try {
+            await PublicKeyCredential.signalUnknownCredential({
+              rpId: serverOptionRpId,
+              credentialId: encodedResponse.id,
+            });
+          } catch (sigErr) {
+            console.warn('SignalUnknownCredential sync warning:', sigErr);
+          }
+        }
+        setStatusMessage({
+          type: 'error',
+          text: 'Network error during passkey verification.',
+        });
+      }
+    } finally {
+      setCreatingPasskey(false);
+    }
+  };
+
+  return (
+    <div className="max-w-4xl mx-auto py-8 px-4 sm:px-6 lg:px-8 space-y-8">
