+import type { APIRoute } from 'astro';
+import {
+  RP_ID,
+  getUser,
+  findCredentialById,
+  saveCredential,
+  deleteCredentialById,
+  findCredentialsByUserId,
+} from '../../../utils/passkeyStore';
+
+export const PUT: APIRoute = async ({ params, request }) => {
+  const id = params.id;
+  const user = getUser();
+
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const cred = findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const body = await request.json();
+  const name = typeof body?.name === 'string' ? body.name.trim() : '';
+  if (!name) {
+    return new Response(JSON.stringify({ error: 'A valid passkey name is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const updated = saveCredential({
+    ...cred,
+    name,
+  });
+
+  return new Response(JSON.stringify(updated), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
+
+export const DELETE: APIRoute = async ({ params }) => {
+  const id = params.id;
+  const user = getUser();
+
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const cred = findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  deleteCredentialById(id);
+  const credentials = findCredentialsByUserId(user.passkeyUserId);
+
+  return new Response(
+    JSON.stringify({
+      success: true,
+      rpId: RP_ID,
+      userId: user.passkeyUserId,
+      credentials,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
