+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import {
+  RP_ID,
+  RP_NAME,
+  getUser,
+  findCredentialsByUserId,
+  setCurrentChallenge,
+} from '../../../utils/passkeyStore';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  let isPromotionFlow = false;
+  try {
+    const body = await request.json();
+    isPromotionFlow = Boolean(body?.promotion);
+  } catch {
+    isPromotionFlow = false;
+  }
+
+  const user = getUser();
+  const userExistingCredentials = findCredentialsByUserId(user.passkeyUserId);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: RP_ID,
+    userID: new Uint8Array(Buffer.from(user.passkeyUserId, 'base64url')),
+    userName: user.name,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: userExistingCredentials.map((cred) => ({
+      id: cred.id,
+      transports: cred.transports as any,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow && { authenticatorAttachment: 'platform' }),
+    },
+    supportedAlgorithmIDs: [-7, -257],
+  });
+
+  // Ensure user.id in the JSON options matches our unpadded Base64URL passkeyUserId
+  const creationOptionsJSON = {
+    ...options,
+    rp: {
+      id: RP_ID,
+      name: RP_NAME,
+    },
+    user: {
+      id: user.passkeyUserId,
+      name: user.name,
+      displayName: user.displayName,
+    },
+    excludeCredentials: userExistingCredentials.map((cred) => ({
+      type: 'public-key',
+      id: cred.id,
+      transports: cred.transports,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow && { authenticatorAttachment: 'platform' }),
+    },
+  };
+
+  setCurrentChallenge(options.challenge);
+  if (session) {
+    await session.set('passkeyChallenge', options.challenge);
+  }
+
+  return new Response(JSON.stringify(creationOptionsJSON), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
