@@ -0,0 +1,126 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import aaguidsData from '../../../utils/aaguids.json';
+import {
+  RP_ID,
+  ZERO_AAGUID,
+  getUser,
+  getCurrentChallenge,
+  setCurrentChallenge,
+  saveCredential,
+  type StoredPasskeyCredential,
+  type AaguidEntry,
+} from '../../../utils/passkeyStore';
+
+const aaguids: Record<string, AaguidEntry> = aaguidsData;
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = getUser();
+  const body = await request.json();
+
+  const expectedChallenge =
+    (session ? await session.get('passkeyChallenge') : null) || getCurrentChallenge();
+
+  if (!expectedChallenge) {
+    return new Response(
+      JSON.stringify({ error: 'Registration challenge expired or missing.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const originHeader = request.headers.get('origin') || `http://${RP_ID}:11224`;
+
+  try {
+    const verification = await verifyRegistrationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin: originHeader,
+      expectedRPID: RP_ID,
+      requireUserVerification: false,
+    });
+
+    if (!verification.verified || !verification.registrationInfo) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey registration verification failed.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const { registrationInfo } = verification;
+    // Verify User Present (UP) flag
+    if (!registrationInfo.userVerified && registrationInfo.credentialDeviceType === undefined) {
+      return new Response(
+        JSON.stringify({ error: 'User presence could not be verified.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const aaguid = registrationInfo.aaguid || ZERO_AAGUID;
+    let name = 'Unknown passkey provider';
+    let providerIcon: string | undefined = undefined;
+
+    if (aaguid === ZERO_AAGUID) {
+      name = 'Passkey on this device';
+      providerIcon = undefined;
+    } else {
+      const provider = aaguids[aaguid];
+      name = provider?.name || 'Unknown passkey provider';
+      providerIcon = provider?.icon_light;
+    }
+
+    const now = Date.now();
+    const newCredential: StoredPasskeyCredential = {
+      id: registrationInfo.credential.id,
+      passkeyUserId: user.passkeyUserId,
+      credentialPublicKey: Buffer.from(registrationInfo.credential.publicKey).toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: registrationInfo.credentialDeviceType,
+      credentialBackedUp: registrationInfo.credentialBackedUp,
+      aaguid,
+      providerIcon,
+      name,
+      transports: registrationInfo.credential.transports || ['internal'],
+      registeredAt: now,
+      lastUsedAt: now,
+      counter: registrationInfo.credential.counter,
+    };
+
+    saveCredential(newCredential);
+    setCurrentChallenge(null);
+    if (session) {
+      await session.set('passkeyChallenge', null);
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        rpId: RP_ID,
+        userId: user.passkeyUserId,
+        credential: newCredential,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({
+        error: err?.message || 'Failed to verify passkey registration.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
