+import type { APIRoute } from 'astro';
+import { RP_ID, getUser, updateUser } from '../../utils/passkeyStore';
+
+export const GET: APIRoute = async () => {
+  const user = getUser();
+  return new Response(
+    JSON.stringify({
+      ...user,
+      rpId: RP_ID,
+      userId: user.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = async ({ request }) => {
+  const body = await request.json();
+  const name = typeof body?.name === 'string' ? body.name.trim() : undefined;
+  const displayName = typeof body?.displayName === 'string' ? body.displayName.trim() : undefined;
+
+  if (!name && !displayName) {
+    return new Response(
+      JSON.stringify({ error: 'Please provide a username or display name.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const updatedUser = updateUser({ name, displayName });
+
+  return new Response(
+    JSON.stringify({
+      ...updatedUser,
+      rpId: RP_ID,
+      userId: updatedUser.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
