@@ -0,0 +1,191 @@
+import aaguidsData from './aaguids.json';
+
+export interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids: Record<string, AaguidEntry> = aaguidsData;
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string; // Authenticator Attestation GUID
+  providerIcon?: string; // Provider icon derived from the AAGUID registry
+  name: string; // Provider name derived from AAGUID registry or custom user nickname
+  transports: string[]; // Array of transport names (e.g. 'internal', 'hybrid')
+  lastUsedAt?: number; // Optional epoch timestamp of last sign-in
+  registeredAt: number; // Registration epoch timestamp
+  counter: number; // Authenticator sign-in signature counter
+}
+
+export interface UserAccount {
+  id: string;
+  passkeyUserId: string; // Unpadded Base64URL string
+  name: string; // Username / email
+  displayName: string; // Reader display name
+  subscriptionTier: string;
+}
+
+// Predefined server RP ID and Name
+export const RP_ID = 'localhost';
+export const RP_NAME = 'The DevTools Times';
+
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+export function resolveAaguidProvider(aaguid?: string): {
+  name: string;
+  providerIcon?: string;
+  providerName: string;
+} {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return {
+      name: 'Unknown passkey provider',
+      providerName: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  return {
+    name: provider?.name || 'Unknown passkey provider',
+    providerName: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light,
+  };
+}
+
+// Default signed-in reader profile with valid unpadded Base64URL passkeyUserId
+const DEFAULT_PASSKEY_USER_ID = Buffer.from('reader-alex-morgan-01').toString('base64url');
+
+let currentUser: UserAccount = {
+  id: 'user-reader-01',
+  passkeyUserId: DEFAULT_PASSKEY_USER_ID,
+  name: 'alex.morgan@devtoolstimes.dev',
+  displayName: 'Alex Morgan',
+  subscriptionTier: 'Digital All-Access Subscriber',
+};
+
+// Initial seeded credentials with genuine unpadded Base64URL IDs
+const initialCredentials: StoredPasskeyCredential[] = [
+  {
+    id: Buffer.from('cred-gpm-pixel-pro-01').toString('base64url'),
+    passkeyUserId: DEFAULT_PASSKEY_USER_ID,
+    credentialPublicKey: Buffer.from('mock-pub-key-gpm-01').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+    providerIcon: aaguids['ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4']?.icon_light,
+    name: 'Google Password Manager',
+    transports: ['internal', 'hybrid'],
+    registeredAt: 1726394400000,
+    lastUsedAt: 1732176000000,
+    counter: 14,
+  },
+  {
+    id: Buffer.from('cred-icloud-macbook-02').toString('base64url'),
+    passkeyUserId: DEFAULT_PASSKEY_USER_ID,
+    credentialPublicKey: Buffer.from('mock-pub-key-icloud-02').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+    providerIcon: aaguids['fbfc3007-154e-4ecc-8c0b-6e020557d7bd']?.icon_light,
+    name: 'iCloud Keychain',
+    transports: ['internal'],
+    registeredAt: 1723802400000,
+    lastUsedAt: 1731916800000,
+    counter: 8,
+  },
+  {
+    id: Buffer.from('cred-1password-vault-03').toString('base64url'),
+    passkeyUserId: DEFAULT_PASSKEY_USER_ID,
+    credentialPublicKey: Buffer.from('mock-pub-key-1password-03').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+    providerIcon: aaguids['bada5566-a7aa-401f-bd96-45619a55120d']?.icon_light,
+    name: '1Password Work Vault',
+    transports: ['internal', 'hybrid'],
+    registeredAt: 1719828000000,
+    lastUsedAt: 1729504800000,
+    counter: 3,
+  },
+];
+
+let credentialsStore: StoredPasskeyCredential[] = [...initialCredentials];
+let currentChallenge: string | null = null;
+
+export function getUser(): UserAccount {
+  return { ...currentUser };
+}
+
+export function updateUser(updates: { name?: string; displayName?: string }): UserAccount {
+  if (typeof updates.name === 'string' && updates.name.trim()) {
+    currentUser.name = updates.name.trim();
+  }
+  if (typeof updates.displayName === 'string' && updates.displayName.trim()) {
+    currentUser.displayName = updates.displayName.trim();
+  }
+  return { ...currentUser };
+}
+
+export function findCredentialsByUserId(passkeyUserId: string): StoredPasskeyCredential[] {
+  return credentialsStore
+    .filter((cred) => cred.passkeyUserId === passkeyUserId)
+    .map((cred) => {
+      if (cred.aaguid === ZERO_AAGUID) {
+        return {
+          ...cred,
+          providerIcon: undefined,
+        };
+      }
+      const resolved = resolveAaguidProvider(cred.aaguid);
+      return {
+        ...cred,
+        providerIcon: cred.providerIcon || resolved.providerIcon,
+      };
+    });
+}
+
+export function findCredentialById(id: string): StoredPasskeyCredential | undefined {
+  return credentialsStore.find((cred) => cred.id === id);
+}
+
+export function saveCredential(credential: StoredPasskeyCredential): StoredPasskeyCredential {
+  const index = credentialsStore.findIndex((cred) => cred.id === credential.id);
+  if (index >= 0) {
+    credentialsStore[index] = { ...credential };
+    return credentialsStore[index];
+  }
+  credentialsStore.unshift({ ...credential });
+  return credential;
+}
+
+export function deleteCredentialById(id: string): boolean {
+  const initialLength = credentialsStore.length;
+  credentialsStore = credentialsStore.filter((cred) => cred.id !== id);
+  return credentialsStore.length < initialLength;
+}
+
+export function setCurrentChallenge(challenge: string | null): void {
+  currentChallenge = challenge;
+}
+
+export function getCurrentChallenge(): string | null {
+  return currentChallenge;
+}

