+
+function toBase64Url(str: string): string {
+  try {
+    const bytes = new TextEncoder().encode(str);
+    let binary = '';
+    for (let i = 0; i < bytes.byteLength; i++) {
+      binary += String.fromCharCode(bytes[i]);
+    }
+    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+  } catch {
+    return 'dXNlci1kZXZ0b29scy1yZWFkZXItMDE';
+  }
+}
+
+function bufferToBase64Url(buffer: ArrayBuffer): string {
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function base64UrlToUint8Array(base64Url: string): Uint8Array<ArrayBuffer> {
+  const padding = '='.repeat((4 - (base64Url.length % 4)) % 4);
+  const base64 = (base64Url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  try {
+    const rawData = atob(base64);
+    const buffer = new ArrayBuffer(rawData.length);
+    const outputArray = new Uint8Array(buffer);
+    for (let i = 0; i < rawData.length; ++i) {
+      outputArray[i] = rawData.charCodeAt(i);
+    }
+    return outputArray;
+  } catch {
+    const encoded = new TextEncoder().encode(base64Url);
+    const buffer = new ArrayBuffer(encoded.length);
+    const outputArray = new Uint8Array(buffer);
+    outputArray.set(encoded);
+    return outputArray;
+  }
+}
+
+function getRpId(): string {
+  if (typeof window !== 'undefined' && window.location?.hostname) {
+    return window.location.hostname;
+  }
+  return 'localhost';
+}
+
+export default function PasskeyManagement() {
+  const [user, setUser] = useState<PasskeyUser>(DEFAULT_USER);
+  const [passkeys, setPasskeys] = useState<PasskeyCredential[]>(DEFAULT_PASSKEYS);
+  const [loading, setLoading] = useState<boolean>(true);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editNameValue, setEditNameValue] = useState<string>('');
+  const [editDisplayNameValue, setEditDisplayNameValue] = useState<string>('');
+  const [accountDisplayName, setAccountDisplayName] = useState<string>(DEFAULT_USER.displayName);
+  const [accountUserName, setAccountUserName] = useState<string>(DEFAULT_USER.name);
+  const [isEditingAccount, setIsEditingAccount] = useState<boolean>(false);
+  const [newKeyName, setNewKeyName] = useState<string>('');
+  const [isAddingKey, setIsAddingKey] = useState<boolean>(false);
+  const [feedback, setFeedback] = useState<{
+    type: 'success' | 'info' | 'warning' | 'error';
+    message: string;
+  } | null>(null);
+  const [signalLogs, setSignalLogs] = useState<SignalEventLog[]>([]);
+  const [signalSupport, setSignalSupport] = useState<{
+    allAccepted: boolean;
+    unknownCredential: boolean;
+    currentUserDetails: boolean;
+  }>({
+    allAccepted: false,
+    unknownCredential: false,
+    currentUserDetails: false,
+  });
+
+  const appendSignalLog = useCallback(
+    (
+      method: SignalEventLog['method'],
+      status: SignalEventLog['status'],
+      payload: Record<string, unknown>,
+      message: string
+    ) => {
+      setSignalLogs((prev) => [
+        {
+          id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
+          timestamp: new Date().toLocaleTimeString(),
+          method,
+          status,
+          payload,
+          message,
+        },
+        ...prev.slice(0, 9),
+      ]);
+    },
+    []
+  );
+
+  // Sync accepted credentials list with browser authenticator
+  const syncAllAcceptedCredentials = useCallback(
+    async (currentUser: PasskeyUser, acceptedKeys: PasskeyCredential[]) => {
+      const rpId = getRpId();
+      const allAcceptedCredentialIds = acceptedKeys.map((k) => k.id);
+      const payload = {
+        rpId,
+        userId: currentUser.id,
+        allAcceptedCredentialIds,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        'PublicKeyCredential' in window &&
+        typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalAllAcceptedCredentials(payload);
+          appendSignalLog(
+            'signalAllAcceptedCredentials',
+            'synced',
+            payload,
+            `Synchronized ${allAcceptedCredentialIds.length} accepted passkey(s) with browser authenticator.`
+          );
+          return true;
+        } catch (err: any) {
+          appendSignalLog(
+            'signalAllAcceptedCredentials',
+            'error',
+            payload,
+            err?.message || 'Failed to signal accepted credentials to authenticator.'
+          );
+          return false;
+        }
+      } else {
+        appendSignalLog(
+          'signalAllAcceptedCredentials',
+          'unsupported',
+          payload,
+          'PublicKeyCredential.signalAllAcceptedCredentials is not supported in this browser; state saved on server.'
+        );
+        return false;
+      }
+    },
+    [appendSignalLog]
+  );
+
+  // Signal an unknown/deleted credential to browser authenticator
+  const syncUnknownCredential = useCallback(
+    async (credentialId: string) => {
+      const rpId = getRpId();
+      const payload = {
+        rpId,
+        credentialId,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        'PublicKeyCredential' in window &&
+        typeof PublicKeyCredential.signalUnknownCredential === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalUnknownCredential(payload);
+          appendSignalLog(
+            'signalUnknownCredential',
+            'synced',
+            payload,
+            `Signaled removed credential (${credentialId.slice(0, 12)}…) to browser authenticator.`
+          );
+          return true;
+        } catch (err: any) {
+          appendSignalLog(
+            'signalUnknownCredential',
+            'error',
+            payload,
+            err?.message || 'Failed to signal unknown credential to authenticator.'
+          );
+          return false;
+        }
+      } else {
+        appendSignalLog(
+          'signalUnknownCredential',
+          'unsupported',
+          payload,
+          'PublicKeyCredential.signalUnknownCredential is not supported in this browser.'
+        );
+        return false;
+      }
+    },
+    [appendSignalLog]
+  );
+
+  // Signal updated user details / display name to browser authenticator
+  const syncCurrentUserDetails = useCallback(
+    async (userId: string, name: string, displayName: string) => {
+      const rpId = getRpId();
+      const payload = {
+        rpId,
+        userId,
+        name,
+        displayName,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        'PublicKeyCredential' in window &&
+        typeof PublicKeyCredential.signalCurrentUserDetails === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalCurrentUserDetails(payload);
+          appendSignalLog(
+            'signalCurrentUserDetails',
+            'synced',
+            payload,
+            `Signaled updated display name "${displayName}" (${name}) to browser authenticator.`
+          );
+          return true;
+        } catch (err: any) {
+          appendSignalLog(
+            'signalCurrentUserDetails',
+            'error',
+            payload,
+            err?.message || 'Failed to signal user details to authenticator.'
+          );
+          return false;
+        }
+      } else {
+        appendSignalLog(
+          'signalCurrentUserDetails',
+          'unsupported',
+          payload,
+          `PublicKeyCredential.signalCurrentUserDetails is not available; updated "${displayName}" locally.`
