+        }
+      } catch {
+        // Fallback to default state
+      } finally {
+        setLoading(false);
+      }
+    };
+
+    fetchPasskeys();
+  }, [syncAllAcceptedCredentials]);
+
+  const handleStartEditPasskey = (pk: PasskeyCredential) => {
+    setEditingId(pk.id);
