+
+      if (res.ok) {
+        const data = await res.json();
+        setUser(data.user);
+        setAccountDisplayName(data.user.displayName);
+        setPasskeys(data.passkeys);
+      } else {
+        setUser(updatedUser);
+        setAccountDisplayName(trimmedDisplayName);
