+        prev.map((item) =>
+          item.id === pk.id
+            ? { ...item, name: trimmedName, displayName: trimmedDisplayName }
+            : item
+        )
+      );
+    }
+
+    // Signal updated display name to the browser authenticator via WebAuthn Signal API
+    const synced = await syncCurrentUserDetails(
+      user.id,
+      pk.userName || user.name,
