+    });
+  };
+
+  const handleUpdateAccountDetails = async (e: React.FormEvent) => {
+    e.preventDefault();
+    const trimmedDisplay = accountDisplayName.trim();
+    const trimmedUser = accountUserName.trim() || user.name;
+    if (!trimmedDisplay) {
+      setFeedback({ type: 'error', message: 'Reader display name cannot be empty.' });
+      return;
+    }
+
+    try {
+      const res = await fetch(`${import.meta.env.BASE_URL}api/passkeys.json`, {
+        method: 'PUT',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
