+        );
+      }
+    } catch {
+      setUser((prev) => ({ ...prev, name: trimmedUser, displayName: trimmedDisplay }));
+      setPasskeys((prev) =>
+        prev.map((pk) => ({
+          ...pk,
+          userName: trimmedUser,
+          displayName: trimmedDisplay,
+        }))
