@@ -0,0 +1,300 @@
+import type { APIRoute } from 'astro';
+
+export interface PasskeyCredential {
+  id: string;
+  name: string;
+  userName: string;
+  displayName: string;
+  createdAt: string;
+  lastUsedAt: string;
+  transports?: string[];
+  deviceType?: string;
+  backedUp?: boolean;
+}
+
+export interface PasskeyUser {
+  id: string; // Base64URL-encoded user handle
+  name: string; // Username / email
+  displayName: string;
+}
+
+const DEFAULT_USER: PasskeyUser = {
+  id: 'dXNlci1kZXZ0b29scy1yZWFkZXItMDE',
+  name: 'alex.rivera@devtoolstimes.dev',
+  displayName: 'Alex Rivera',
+};
+
+const DEFAULT_PASSKEYS: PasskeyCredential[] = [
+  {
+    id: 'Y3JlZC1tYWNib29rLXByby10b3VjaGlkLTAx',
+    name: 'MacBook Pro (Touch ID)',
+    userName: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    createdAt: '2026-08-14T10:24:00.000Z',
+    lastUsedAt: '2026-11-22T08:15:00.000Z',
+    transports: ['internal', 'hybrid'],
+    deviceType: 'multiDevice',
+    backedUp: true,
+  },
+  {
+    id: 'Y3JlZC1waXhlbC05LXByby1iaW9tZXRyaWMtMDI',
+    name: 'Pixel 9 Pro (Google Password Manager)',
+    userName: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    createdAt: '2026-09-03T16:40:00.000Z',
+    lastUsedAt: '2026-11-19T21:05:00.000Z',
+    transports: ['internal', 'hybrid'],
+    deviceType: 'multiDevice',
+    backedUp: true,
+  },
+  {
+    id: 'Y3JlZC15dWJpa2V5LTUtbmZjLWhhcmR3YXJlLTAz',
+    name: 'YubiKey 5C NFC',
+    userName: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera (Hardware Key)',
+    createdAt: '2026-06-20T09:00:00.000Z',
+    lastUsedAt: '2026-10-11T14:32:00.000Z',
+    transports: ['usb', 'nfc'],
+    deviceType: 'singleDevice',
+    backedUp: false,
+  },
+];
+
+async function getSessionState(session: App.Locals['session'] | undefined) {
+  let user: PasskeyUser | undefined = await session?.get('passkeyUser');
+  if (!user) {
+    user = { ...DEFAULT_USER };
+    await session?.set('passkeyUser', user);
+  }
+
+  let passkeys: PasskeyCredential[] | undefined = await session?.get('passkeys');
+  if (!passkeys) {
+    passkeys = DEFAULT_PASSKEYS.map((k) => ({ ...k }));
+    await session?.set('passkeys', passkeys);
+  }
+
+  return { user, passkeys };
+}
+
+export const GET: APIRoute = async ({ session }) => {
+  const { user, passkeys } = await getSessionState(session);
+
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.id),
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const { user, passkeys } = await getSessionState(session);
+  const body = await request.json().catch(() => ({}));
+  const action = body.action || 'create';
+
+  if (action === 'reset') {
+    const resetUser = { ...DEFAULT_USER };
+    const resetPasskeys = DEFAULT_PASSKEYS.map((k) => ({ ...k }));
+    await session?.set('passkeyUser', resetUser);
+    await session?.set('passkeys', resetPasskeys);
+    return new Response(
+      JSON.stringify({
+        user: resetUser,
+        passkeys: resetPasskeys,
+        allAcceptedCredentialIds: resetPasskeys.map((pk) => pk.id),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  if (action === 'update_DisplayName' || action === 'update_user' || action === 'update') {
+    const newDisplayName = typeof body.displayName === 'string' ? body.displayName.trim() : '';
+    const newUserName = typeof body.userName === 'string' && body.userName.trim() ? body.userName.trim() : user.name;
+    const credentialId = body.credentialId || body.id;
+
+    if (!newDisplayName) {
+      return new Response(JSON.stringify({ error: 'Display name is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const updatedUser: PasskeyUser = {
+      ...user,
+      name: newUserName,
+      displayName: newDisplayName,
+    };
+
+    const updatedPasskeys = passkeys.map((pk) => {
+      if (!credentialId || pk.id === credentialId) {
+        return {
+          ...pk,
+          name: typeof body.name === 'string' && body.name.trim() ? body.name.trim() : newDisplayName,
+          displayName: newDisplayName,
+          userName: newUserName,
+        };
+      }
+      return pk;
+    });
+
+    await session?.set('passkeyUser', updatedUser);
+    await session?.set('passkeys', updatedPasskeys);
+
+    return new Response(
+      JSON.stringify({
+        user: updatedUser,
+        passkeys: updatedPasskeys,
+        allAcceptedCredentialIds: updatedPasskeys.map((pk) => pk.id),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  if (action === 'delete' || action === 'remove') {
+    const credentialId = body.credentialId || body.id;
+    if (!credentialId) {
+      return new Response(JSON.stringify({ error: 'Credential ID is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const updatedPasskeys = passkeys.filter((pk) => pk.id !== credentialId);
+    await session?.set('passkeys', updatedPasskeys);
+
+    return new Response(
+      JSON.stringify({
+        deletedCredentialId: credentialId,
+        user,
+        passkeys: updatedPasskeys,
+        allAcceptedCredentialIds: updatedPasskeys.map((pk) => pk.id),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  // Default: add/register a new passkey
+  const now = new Date().toISOString();
+  const newPasskey: PasskeyCredential = {
+    id:
+      typeof body.id === 'string' && body.id.trim()
+        ? body.id.trim()
+        : `Y3JlZC1uZXctcGFzc2tleS0${Date.now().toString(36)}`,
+    name:
+      typeof body.name === 'string' && body.name.trim()
+        ? body.name.trim()
+        : typeof body.displayName === 'string' && body.displayName.trim()
+        ? body.displayName.trim()
+        : 'Chrome Profile Passkey',
+    userName: user.name,
+    displayName:
+      typeof body.displayName === 'string' && body.displayName.trim()
+        ? body.displayName.trim()
+        : user.displayName,
+    createdAt: now,
+    lastUsedAt: now,
+    transports: Array.isArray(body.transports) ? body.transports : ['internal', 'hybrid'],
+    deviceType: 'multiDevice',
+    backedUp: true,
+  };
+
+  const updatedPasskeys = [newPasskey, ...passkeys];
+  await session?.set('passkeys', updatedPasskeys);
+
+  return new Response(
+    JSON.stringify({
+      passkey: newPasskey,
+      user,
+      passkeys: updatedPasskeys,
+      allAcceptedCredentialIds: updatedPasskeys.map((pk) => pk.id),
+    }),
+    { status: 201, headers: { 'Content-Type': 'application/json' } }
+  );
+};
+
+export const PUT: APIRoute = async (context) => {
+  const { session, request } = context;
+  const { user, passkeys } = await getSessionState(session);
+  const body = await request.json().catch(() => ({}));
+
+  const credentialId = body.credentialId || body.id;
+  const newDisplayName =
+    typeof body.displayName === 'string' && body.displayName.trim()
+      ? body.displayName.trim()
+      : typeof body.name === 'string' && body.name.trim()
+      ? body.name.trim()
+      : '';
+
+  if (!newDisplayName) {
+    return new Response(JSON.stringify({ error: 'Display name is required' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const newUserName =
+    typeof body.userName === 'string' && body.userName.trim() ? body.userName.trim() : user.name;
+
+  const updatedUser: PasskeyUser = {
+    ...user,
+    name: newUserName,
+    displayName: newDisplayName,
+  };
+
+  const updatedPasskeys = passkeys.map((pk) => {
+    if (!credentialId || pk.id === credentialId) {
+      return {
+        ...pk,
+        name: typeof body.name === 'string' && body.name.trim() ? body.name.trim() : newDisplayName,
+        displayName: newDisplayName,
+        userName: newUserName,
+      };
+    }
+    return pk;
+  });
+
+  await session?.set('passkeyUser', updatedUser);
+  await session?.set('passkeys', updatedPasskeys);
+
+  return new Response(
+    JSON.stringify({
+      user: updatedUser,
+      passkeys: updatedPasskeys,
+      allAcceptedCredentialIds: updatedPasskeys.map((pk) => pk.id),
+    }),
+    { status: 200, headers: { 'Content-Type': 'application/json' } }
+  );
+};
+
+export const PATCH: APIRoute = PUT;
+
+export const DELETE: APIRoute = async ({ request, url, session }) => {
+  const { user, passkeys } = await getSessionState(session);
+  const body = await request.json().catch(() => ({}));
+  const credentialId = body.credentialId || body.id || url.searchParams.get('id');
+
+  if (!credentialId) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const updatedPasskeys = passkeys.filter((pk) => pk.id !== credentialId);
+  await session?.set('passkeys', updatedPasskeys);
+
+  return new Response(
+    JSON.stringify({
+      deletedCredentialId: credentialId,
+      user,
+      passkeys: updatedPasskeys,
+      allAcceptedCredentialIds: updatedPasskeys.map((pk) => pk.id),
+    }),
+    { status: 200, headers: { 'Content-Type': 'application/json' } }
+  );
+};
