+  }
+  const binary = String.fromCharCode(...bytes);
+  const encoded = btoa(`${prefix}-${binary}`)
+    .replace(/=/g, '')
+    .replace(/\+/g, '-')
+    .replace(/\//g, '_');
+  return encoded.length % 4 === 1 ? `${encoded}A` : encoded;
