+  const meta = resolveAaguidMetadata(aaguid, 'Device Passkey');
+  const now = Date.now();
+  const newCred = {
+    id: encodedResponse?.id || generateChallengeBase64Url('cred'),
+    passkeyUserId: store.user.passkeyUserId,
+    credentialPublicKey: encodedResponse?.response?.attestationObject || 'cHVibGljLWtleS1uZXc',
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid,
+    providerIcon: meta.providerIcon,
+    name: meta.name,
+    transports: encodedResponse?.response?.transports || ['internal', 'hybrid'],
+    registeredAt: now,
+    lastUsedAt: now,
+    counter: 0,
+  };
+
+  store.credentials = [
+    ...store.credentials.filter((c) => c.id !== newCred.id),
+    newCred,
+  ];
+  saveStore(store);
+
+  return jsonResponse({
+    verified: true,
+    rpId: store.rpId,
+    userId: store.user.passkeyUserId,
+    credential: newCred,
+  });
+}
+
+// 7. Passkey Management: List Credentials
+export async function listFetch() {
+  const response = await fetch('/api/credentials');
+  if (localStorage.getItem(STORAGE_KEY)) {
+    const store = loadStore();
+    return jsonResponse({
+      rpId: store.rpId || RP_ID,
+      userId: store.user.passkeyUserId,
+      user: store.user,
+      credentials: store.credentials,
+    });
+  }
+  return response;
+}
+
+// 8. Passkey Management: Rename Credential Nickname
+export async function renameCredentialFetch(credentialId, { name }) {
+  const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+    method: 'PUT',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ name }),
+  });
+
+  if (!(await isUnhandledStaticServerResponse(response))) {
+    return response;
+  }
+
+  const store = loadStore();
+  const cred = store.credentials.find((c) => c.id === credentialId);
+  if (!cred || cred.passkeyUserId !== store.user.passkeyUserId) {
+    return jsonResponse({ error: 'Credential not found.' }, 404);
+  }
+  cred.name = name;
+  saveStore(store);
+  return jsonResponse(cred);
+}
+
+// 9. Passkey Management: Delete Credential
+export async function deleteFetch(credentialId) {
+  const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+    method: 'DELETE',
+  });
+
+  if (!(await isUnhandledStaticServerResponse(response))) {
+    return response;
+  }
+
+  const store = loadStore();
+  const cred = store.credentials.find((c) => c.id === credentialId);
+  if (!cred || cred.passkeyUserId !== store.user.passkeyUserId) {
+    return jsonResponse({ error: 'Credential not found.' }, 404);
+  }
+  store.credentials = store.credentials.filter((c) => c.id !== credentialId);
+  saveStore(store);
+  return jsonResponse({
+    success: true,
+    rpId: store.rpId,
+    userId: store.user.passkeyUserId,
+    credentials: store.credentials,
+  });
+}
+
+// 10. Profile Update (Username & Display Name)
+export async function updateUserFetch({ name, displayName }) {
+  const response = await fetch('/api/user', {
+    method: 'PUT',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ name, displayName }),
+  });
+
+  if (!(await isUnhandledStaticServerResponse(response))) {
+    return response;
+  }
+
+  const store = loadStore();
+  store.user = {
+    ...store.user,
+    name: name ?? store.user.name,
+    displayName: displayName ?? store.user.displayName,
+  };
+  saveStore(store);
+
+  return jsonResponse({
+    ...store.user,
+    rpId: store.rpId || RP_ID,
+    userId: store.user.passkeyUserId,
+  });
+}
+
+// 11. Step-Up Reauthentication Options (Strictly Constrained to Signed-In User's Passkeys)
+export async function reauthOptionsFetch() {
+  const store = loadStore();
+  try {
+    const response = await fetch('/api/reauth/options');
+    if (response.ok) {
+      const data = await response.json();
+      if (localStorage.getItem(STORAGE_KEY)) {
+        return {
+          ...data,
+          rpId: store.rpId || data.rpId || RP_ID,
+          allowCredentials: store.credentials.map((cred) => ({
+            type: 'public-key',
+            id: cred.id,
+            transports: cred.transports || ['internal', 'hybrid'],
+          })),
+        };
+      }
+      return data;
+    }
+  } catch {
+    // Fall back to local options
+  }
+
+  return {
+    challenge: generateChallengeBase64Url('reauth'),
+    rpId: store.rpId || RP_ID,
+    userVerification: 'preferred',
+    allowCredentials: store.credentials.map((cred) => ({
+      type: 'public-key',
+      id: cred.id,
+      transports: cred.transports || ['internal', 'hybrid'],
+    })),
+  };
+}
+
+// 12. Step-Up Reauthentication Verification (Strict Account Ownership Check)
+export async function reauthVerifyFetch(encodedCredential) {
+  const response = await fetch('/api/reauth/verify', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify(encodedCredential),
+  });
+
+  if (!(await isUnhandledStaticServerResponse(response))) {
+    return response;
+  }
+
+  const store = loadStore();
+  const storedCredential = store.credentials.find((c) => c.id === encodedCredential?.id);
+  if (!storedCredential) {
+    return jsonResponse({ error: 'Credential not found.' }, 404);
+  }
+  if (storedCredential.passkeyUserId !== store.user.passkeyUserId) {
+    return jsonResponse({ error: 'Credential does not belong to the active user.' }, 403);
+  }
+
+  storedCredential.lastUsedAt = Date.now();
+  storedCredential.counter = (storedCredential.counter || 0) + 1;
+  saveStore(store);
+
+  return jsonResponse({
+    reauthenticated: true,
+    verifiedAt: storedCredential.lastUsedAt,
+    rpId: store.rpId,
+    userId: store.user.passkeyUserId,
+    credentialId: storedCredential.id,
+  });
+}
