+import React, { useEffect, useRef, useState } from 'react';
+import 'webauthn-polyfills';
+import aaguidsData from '../data/aaguids.json';
+
+const rawBaseUrl = import.meta.env.BASE_URL || '/';
+const baseUrl = rawBaseUrl.endsWith('/') ? rawBaseUrl : `${rawBaseUrl}/`;
+
+interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids: Record<string, AaguidEntry> = aaguidsData;
+
+export interface PasskeyItem {
+  id: string;
+  passkeyUserId: string;
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+function getProviderDisplayFromAaguid(cred: PasskeyItem): {
+  name: string;
+  icon?: string;
+} {
+  if (!cred.aaguid || cred.aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      name: cred.name || 'Unknown passkey provider',
+      icon: undefined,
+    };
+  }
+  const provider = aaguids[cred.aaguid];
+  return {
+    name: cred.name || provider?.name || 'Unknown passkey provider',
+    icon: cred.providerIcon || provider?.icon_light,
+  };
+}
+
+export default function AccountSettings() {
+  const [credentials, setCredentials] = useState<PasskeyItem[]>([]);
+  const [rpId, setRpId] = useState<string>('');
+  const [userId, setUserId] = useState<string>('');
+  const [username, setUsername] = useState<string>('');
+  const [displayName, setDisplayName] = useState<string>('');
+  const [loading, setLoading] = useState<boolean>(true);
+  const [passkeySupported, setPasskeySupported] = useState<boolean>(true);
+  const [statusMessage, setStatusMessage] = useState<string | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  // Rename dialog state
+  const renameDialogRef = useRef<HTMLDialogElement | null>(null);
+  const [renamingCred, setRenamingCred] = useState<PasskeyItem | null>(null);
+  const [newCredentialName, setNewCredentialName] = useState<string>('');
+
+  // Step-up reauthentication state
+  const reauthAbortControllerRef = useRef<AbortController>(new AbortController());
+  const [reauthenticatedAt, setReauthenticatedAt] = useState<number | null>(null);
+  const [newPassword, setNewPassword] = useState<string>('');
