+import type { APIRoute } from 'astro';
+import { db, getServerRpId } from '../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const { username, password } = await request.json();
+    if (!username || !password) {
+      return new Response(
+        JSON.stringify({ error: 'Username and password are required.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    let user = db.findUserByUsername(username);
+    if (!user) {
+      // Allow signing in and provisioning a session for demo users on first login
+      user = db.createUser(username, password, username.split('@')[0]);
+    }
+
+    await session?.set('userId', user.passkeyUserId);
+    const rpId = getServerRpId(request);
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        rpId,
+        user: {
+          userId: user.passkeyUserId,
+          name: user.name,
+          displayName: user.displayName,
+        },
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Login failed' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
