@@ -0,0 +1,37 @@
+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getServerRpId } from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const rpId = getServerRpId(request);
+    const options = await generateAuthenticationOptions({
+      rpID: rpId,
+      // Request discoverable credentials with an empty allowCredentials array
+      allowCredentials: [],
+      userVerification: 'preferred',
+    });
+
+    // Explicitly include rpId and allowCredentials in returned request options
+    const responseOptions = {
+      ...options,
+      rpId,
+      allowCredentials: [],
+      userVerification: 'preferred' as const,
+    };
+
+    // Persist expected challenge and userVerification level in session
+    await session?.set('authenticationChallenge', options.challenge);
+    await session?.set('expectedUserVerification', 'preferred');
+
+    return new Response(JSON.stringify(responseOptions), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate authentication options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
