+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { db, getExpectedOrigins, getServerRpId } from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const credentialId = body?.id;
+    const rpId = getServerRpId(request);
+
+    if (!credentialId) {
+      return new Response(
+        JSON.stringify({ error: 'Missing credential ID' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const storedCredential = db.findCredentialById(credentialId);
+    // Clean Server Error 404: If the credential ID is not found in the database, return HTTP 404
+    // so the client can trigger PublicKeyCredential.signalUnknownCredential()
+    if (!storedCredential) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey credential not found', rpId }),
+        { status: 404, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const expectedChallenge = await session?.get('authenticationChallenge');
+    const expectedUserVerification = (await session?.get('expectedUserVerification')) || 'preferred';
+
+    if (!expectedChallenge) {
+      return new Response(
+        JSON.stringify({ error: 'Authentication challenge expired or missing' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const expectedOrigin = getExpectedOrigins(request, rpId);
+    const verification = await verifyAuthenticationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin,
+      expectedRPID: rpId,
+      credential: {
+        id: storedCredential.id,
+        publicKey: Buffer.from(storedCredential.credentialPublicKey, 'base64url'),
+        counter: storedCredential.counter,
+        transports: storedCredential.transports as AuthenticatorTransport[],
+      },
+      // Allow UV-less authenticators when session expectedUserVerification requested "preferred"
+      requireUserVerification: expectedUserVerification === 'required',
+    });
+
+    if (!verification.verified) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey assertion verification failed' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    storedCredential.counter = verification.authenticationInfo.newCounter;
+    storedCredential.lastUsedAt = Date.now();
+    db.saveCredential(storedCredential);
+
+    const user = db.findUserById(storedCredential.passkeyUserId) || db.getDefaultUser();
+    await session?.set('userId', user.passkeyUserId);
+    await session?.set('authenticationChallenge', undefined);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        rpId,
+        user: {
+          userId: user.passkeyUserId,
+          name: user.name,
+          displayName: user.displayName,
+        },
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Passkey sign-in verification failed' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
