+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { db, getServerRpId } from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const sessionUserId = await session?.get('userId');
+    const user = (sessionUserId ? db.findUserById(sessionUserId) : undefined) || db.getDefaultUser();
+    const userPasskeys = db.findCredentialsByUserId(user.passkeyUserId);
+    const rpId = getServerRpId(request);
+
+    const options = await generateAuthenticationOptions({
+      rpID: rpId,
+      // Constrain allowCredentials strictly to the signed-in user's registered credentials
+      allowCredentials: userPasskeys.map((cred) => ({
+        id: cred.id,
+        transports: cred.transports as AuthenticatorTransport[],
+      })),
+      userVerification: 'preferred',
+    });
+
+    const responseOptions = {
+      ...options,
+      rpId,
+      allowCredentials: userPasskeys.map((cred) => ({
+        type: 'public-key' as const,
+        id: cred.id,
+        transports: cred.transports,
+      })),
+      userVerification: 'preferred' as const,
+    };
+
+    await session?.set('reauthChallenge', options.challenge);
+    await session?.set('expectedReauthUserVerification', 'preferred');
+
+    return new Response(JSON.stringify(responseOptions), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate reauthentication options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/pages/api/passkeys/reauth/verify.ts b/src/pages/api/passkeys/reauth/verify.ts
new file mode 100644
index 0000000..0b4f6a0
