@@ -0,0 +1,92 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { db, getExpectedOrigins, getServerRpId } from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const credentialId = body?.id;
+    const rpId = getServerRpId(request);
+
+    const sessionUserId = await session?.get('userId');
+    const activeUser = (sessionUserId ? db.findUserById(sessionUserId) : undefined) || db.getDefaultUser();
+
+    if (!credentialId) {
+      return new Response(
+        JSON.stringify({ error: 'Missing credential ID' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const storedCredential = db.findCredentialById(credentialId);
+    if (!storedCredential) {
+      return new Response(
+        JSON.stringify({ error: 'Credential not found', rpId }),
+        { status: 404, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    // Verify Account Ownership: strictly ensure the credential belongs to the active signed-in user
+    if (storedCredential.passkeyUserId !== activeUser.passkeyUserId) {
+      return new Response(
+        JSON.stringify({ error: 'Credential does not belong to the active user account.' }),
+        { status: 403, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const expectedChallenge = await session?.get('reauthChallenge');
+    const expectedUserVerification =
+      (await session?.get('expectedReauthUserVerification')) || 'preferred';
+
+    if (!expectedChallenge) {
+      return new Response(
+        JSON.stringify({ error: 'Reauthentication challenge expired or missing.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const expectedOrigin = getExpectedOrigins(request, rpId);
+    const verification = await verifyAuthenticationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin,
+      expectedRPID: rpId,
+      credential: {
+        id: storedCredential.id,
+        publicKey: Buffer.from(storedCredential.credentialPublicKey, 'base64url'),
+        counter: storedCredential.counter,
+        transports: storedCredential.transports as AuthenticatorTransport[],
+      },
+      requireUserVerification: expectedUserVerification === 'required',
+    });
+
+    if (!verification.verified) {
+      return new Response(
+        JSON.stringify({ error: 'Reauthentication assertion failed.' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    storedCredential.counter = verification.authenticationInfo.newCounter;
+    storedCredential.lastUsedAt = Date.now();
+    db.saveCredential(storedCredential);
+
+    const reauthenticatedAt = Date.now();
+    await session?.set('reauthenticatedAt', reauthenticatedAt);
+    await session?.set('reauthChallenge', undefined);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        reauthenticatedAt,
+        rpId,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Reauthentication verification failed' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
