@@ -0,0 +1,66 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { db, getServerRpId, RP_NAME } from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const isPromotionFlow = Boolean(body.promotion || body.conditional);
+    const isConditional = Boolean(body.conditional);
+
+    const sessionUserId = await session?.get('userId');
+    let user = sessionUserId ? db.findUserById(sessionUserId) : undefined;
+
+    if (!user && body.username) {
+      user = db.findUserByUsername(body.username) || db.createUser(body.username, '', body.displayName);
+    }
+    if (!user) {
+      user = db.getDefaultUser();
+    }
+
+    const rpId = getServerRpId(request);
+    const userExistingCredentials = db.findCredentialsByUserId(user.passkeyUserId);
+
+    const options = await generateRegistrationOptions({
+      rpName: RP_NAME,
+      rpID: rpId,
+      userID: Buffer.from(user.passkeyUserId, 'base64url'),
+      userName: user.name,
+      userDisplayName: user.displayName,
+      attestationType: 'none',
+      excludeCredentials: userExistingCredentials.map((cred) => ({
+        id: cred.id,
+        transports: cred.transports as AuthenticatorTransport[],
+      })),
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'preferred',
+        ...(isPromotionFlow ? { authenticatorAttachment: 'platform' } : {}),
+      },
+      supportedAlgorithmIDs: [-7, -257],
+    });
+
+    // Ensure rp.id and user.id are explicitly set to the predefined RP ID and Base64URL user ID
+    options.rp = {
+      id: rpId,
+      name: RP_NAME,
+    };
+    options.user.id = user.passkeyUserId;
+
+    await session?.set('registrationChallenge', options.challenge);
+    await session?.set('expectedUserVerification', 'preferred');
+    await session?.set('isConditionalRegistration', isConditional);
+    await session?.set('pendingUserId', user.passkeyUserId);
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate registration options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/pages/api/passkeys/register/verify.ts b/src/pages/api/passkeys/register/verify.ts
new file mode 100644
index 0000000..2212204
--- /dev/null
+++ b/src/pages/api/passkeys/register/verify.ts
@@ -0,0 +1,96 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import {
+  db,
+  getExpectedOrigins,
+  getServerRpId,
+  resolveAaguidMetadata,
+  type StoredPasskeyCredential,
+} from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const expectedChallenge = await session?.get('registrationChallenge');
+    const isConditional = Boolean(
+      (await session?.get('isConditionalRegistration')) || body?.conditional
+    );
+    const pendingUserId =
+      (await session?.get('pendingUserId')) ||
+      (await session?.get('userId')) ||
+      db.getDefaultUser().passkeyUserId;
+
+    if (!expectedChallenge) {
+      return new Response(
+        JSON.stringify({ error: 'Registration session challenge expired or missing.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const rpId = getServerRpId(request);
+    const expectedOrigin = getExpectedOrigins(request, rpId);
+
+    const verification = await verifyRegistrationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin,
+      expectedRPID: rpId,
+      // Creation options specified userVerification: "preferred", so relax UV requirement
+      requireUserVerification: false,
+      // Relax User Presence (UP) requirement ONLY when verifying conditional-create credentials
+      requireUserPresence: !isConditional,
+    });
+
+    if (!verification.verified || !verification.registrationInfo) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey registration verification failed.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const {
+      credential,
+      credentialDeviceType,
+      credentialBackedUp,
+      aaguid,
+    } = verification.registrationInfo;
+
+    const aaguidMeta = resolveAaguidMetadata(aaguid);
+    const publicKeyBase64Url = Buffer.from(credential.publicKey).toString('base64url');
+
+    const storedCredential: StoredPasskeyCredential = {
+      id: credential.id,
+      passkeyUserId: pendingUserId,
+      credentialPublicKey: publicKeyBase64Url,
+      credentialType: 'public-key',
+      credentialDeviceType,
+      credentialBackedUp,
+      aaguid,
+      providerIcon: aaguidMeta.providerIcon,
+      name: aaguidMeta.name,
+      transports: credential.transports || ['internal', 'hybrid'],
+      registeredAt: Date.now(),
+      lastUsedAt: Date.now(),
+      counter: credential.counter,
+    };
+
+    db.saveCredential(storedCredential);
+    await session?.set('userId', pendingUserId);
+    await session?.set('registrationChallenge', undefined);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        credential: storedCredential,
+        rpId,
+        userId: pendingUserId,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Verification failed' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
