diff --git a/src/utils/passkey-store.ts b/src/utils/passkey-store.ts
new file mode 100644
index 0000000..98c872c
--- /dev/null
+++ b/src/utils/passkey-store.ts
@@ -0,0 +1,260 @@
+import crypto from 'node:crypto';
+import aaguidsData from '../data/aaguids.json';
+
+export interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids: Record<string, AaguidEntry> = aaguidsData;
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice'; // Helps distinguish device-bound vs cloud-synced passkeys
+  credentialBackedUp: boolean; // Boolean backup state reported by the authenticator
+  aaguid: string; // Authenticator Attestation GUID
+  providerIcon?: string; // Provider icon derived from the AAGUID registry
+  name: string; // Provider name derived from AAGUID registry or user nickname
+  transports: string[]; // Array of transport names (e.g. 'internal', 'hybrid')
+  lastUsedAt?: number; // Optional epoch timestamp of last sign-in
+  registeredAt: number; // Registration epoch timestamp
+  counter: number; // Authenticator sign-in signature counter used to prevent replay attacks
+}
+
+export interface UserAccount {
+  id: string; // Internal ID
+  passkeyUserId: string; // Valid unpadded Base64URL string
+  name: string; // Username
+  displayName: string; // Display name
+  passwordHash: string;
+}
+
+// Predefined server RP ID and Name
+export const RP_NAME = 'The DevTools Times';
+export const DEFAULT_RP_ID = 'localhost';
+
+export function getServerRpId(request?: Request): string {
+  if (process.env.RP_ID) {
+    return process.env.RP_ID;
+  }
+  if (request) {
+    try {
+      const url = new URL(request.url);
+      if (url.hostname) {
+        return url.hostname;
+      }
+    } catch {
+      // Fallback to default RP ID
+    }
+  }
+  return DEFAULT_RP_ID;
+}
+
+export function getExpectedOrigins(request?: Request, rpId: string = DEFAULT_RP_ID): string[] {
+  const origins = new Set<string>([
+    `http://${rpId}:11224`,
+    `http://${rpId}:4321`,
+    `http://${rpId}`,
+    `https://${rpId}`,
+    'http://localhost:11224',
+    'http://localhost:4321',
+    'https://astro-news-pytrpecapa-uc.a.run.app',
+  ]);
+  if (request) {
+    try {
+      const url = new URL(request.url);
+      if (url.origin) {
+        origins.add(url.origin);
+      }
+    } catch {
+      // ignore
+    }
+  }
+  return Array.from(origins);
+}
+
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+export function generateBase64UrlId(byteLength = 32): string {
+  return crypto.randomBytes(byteLength).toString('base64url');
+}
+
+export function resolveAaguidMetadata(aaguid: string): {
+  name: string;
+  providerIcon?: string;
+} {
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      name: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  return {
+    name: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light,
+  };
+}
+
+// Global in-memory store across Astro SSR module evaluations
+const globalStore = globalThis as unknown as {
+  __devtoolsTimesUsers?: Map<string, UserAccount>;
+  __devtoolsTimesCredentials?: Map<string, StoredPasskeyCredential>;
+};
+
+if (!globalStore.__devtoolsTimesUsers) {
+  const usersMap = new Map<string, UserAccount>();
+  const defaultUserId = Buffer.from('devtools-times-reader-01').toString('base64url');
+  usersMap.set(defaultUserId, {
+    id: defaultUserId,
+    passkeyUserId: defaultUserId,
+    name: 'reader@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    passwordHash: 'devtools123',
+  });
+  globalStore.__devtoolsTimesUsers = usersMap;
+}
+
+if (!globalStore.__devtoolsTimesCredentials) {
+  const credsMap = new Map<string, StoredPasskeyCredential>();
+  const defaultUserId = Buffer.from('devtools-times-reader-01').toString('base64url');
+  const seedCredId1 = Buffer.from('seed-credential-gpm-0001').toString('base64url');
+  const seedCredId2 = Buffer.from('seed-credential-icloud-02').toString('base64url');
+  const gpmMeta = resolveAaguidMetadata('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+  const icloudMeta = resolveAaguidMetadata('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+
+  credsMap.set(seedCredId1, {
+    id: seedCredId1,
+    passkeyUserId: defaultUserId,
+    credentialPublicKey: Buffer.from('mock-public-key-bytes-0001').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+    providerIcon: gpmMeta.providerIcon,
+    name: gpmMeta.name,
+    transports: ['internal', 'hybrid'],
+    registeredAt: Date.now() - 1000 * 60 * 60 * 24 * 14,
+    lastUsedAt: Date.now() - 1000 * 60 * 60 * 3,
+    counter: 4,
+  });
+
+  credsMap.set(seedCredId2, {
+    id: seedCredId2,
+    passkeyUserId: defaultUserId,
+    credentialPublicKey: Buffer.from('mock-public-key-bytes-0002').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+    providerIcon: icloudMeta.providerIcon,
+    name: icloudMeta.name,
+    transports: ['internal'],
+    registeredAt: Date.now() - 1000 * 60 * 60 * 24 * 30,
+    lastUsedAt: Date.now() - 1000 * 60 * 60 * 24 * 5,
+    counter: 2,
+  });
+
+  globalStore.__devtoolsTimesCredentials = credsMap;
+}
+
+const users = globalStore.__devtoolsTimesUsers;
+const credentials = globalStore.__devtoolsTimesCredentials;
+
+export const db = {
+  getDefaultUser(): UserAccount {
+    const defaultUserId = Buffer.from('devtools-times-reader-01').toString('base64url');
+    let user = users.get(defaultUserId);
+    if (!user) {
+      user = {
+        id: defaultUserId,
+        passkeyUserId: defaultUserId,
+        name: 'reader@devtoolstimes.dev',
+        displayName: 'Alex Rivera',
+        passwordHash: 'devtools123',
+      };
+      users.set(defaultUserId, user);
+    }
+    return user;
+  },
+
+  findUserById(userId: string): UserAccount | undefined {
+    return users.get(userId);
+  },
+
+  findUserByUsername(username: string): UserAccount | undefined {
+    const normalized = username.trim().toLowerCase();
+    for (const user of users.values()) {
+      if (user.name.toLowerCase() === normalized) {
+        return user;
+      }
+    }
+    return undefined;
+  },
+
+  createUser(username: string, passwordHash: string, displayName?: string): UserAccount {
+    const existing = this.findUserByUsername(username);
+    if (existing) {
+      return existing;
+    }
+    const passkeyUserId = generateBase64UrlId(24);
+    const user: UserAccount = {
+      id: passkeyUserId,
+      passkeyUserId,
+      name: username.trim(),
+      displayName: (displayName || username).trim(),
+      passwordHash,
+    };
+    users.set(passkeyUserId, user);
+    return user;
+  },
+
+  updateUser(userId: string, updates: { name?: string; displayName?: string; passwordHash?: string }): UserAccount {
+    const user = users.get(userId) || this.getDefaultUser();
+    if (typeof updates.name === 'string' && updates.name.trim()) {
+      user.name = updates.name.trim();
+    }
