@@ -0,0 +1,47 @@
+import React, { useEffect, useState } from 'react';
+import { getExplicitSignedInSession, type AuthSession } from '../utils/passkeys';
+import { PasskeySymbolIcon } from './PasskeyIcons';
+
+export default function HeaderAccountStatus() {
+  const [session, setSession] = useState<AuthSession | null>(null);
+  const baseUrl = (import.meta as any).env?.BASE_URL || '/';
+
+  useEffect(() => {
+    const sync = () => {
+      setSession(getExplicitSignedInSession());
+    };
+    sync();
+    window.addEventListener('dtt-auth-changed', sync);
+    return () => window.removeEventListener('dtt-auth-changed', sync);
+  }, []);
+
+  return (
+    <div className="flex items-center space-x-2 sm:space-x-3">
+      <a
+        href={`${baseUrl}account`}
+        data-skip-tracking="true"
+        className="inline-flex items-center space-x-1.5 bg-amber-100 hover:bg-amber-200 text-gray-900 text-xs font-semibold py-2 px-3 rounded whitespace-nowrap transition"
+        title="Manage Passkeys & Account Settings"
+      >
+        <PasskeySymbolIcon className="w-4 h-4 text-gray-900" />
+        <span>
+          {session ? `@${session.user.username} · Passkeys` : 'Account & Passkeys'}
+        </span>
+      </a>
+      <a
+        href={`${baseUrl}signup`}
+        data-skip-tracking="true"
+        className="bg-gray-800 text-white text-xs font-semibold py-2 px-3 rounded whitespace-nowrap hover:bg-gray-700"
+      >
+        Sign up
+      </a>
+      <a
+        href={`${baseUrl}signin`}
+        data-skip-tracking="true"
+        className="bg-gray-500 text-white text-xs font-semibold py-2 px-3 rounded whitespace-nowrap hover:bg-gray-400"
+      >
+        Sign in
+      </a>
+    </div>
+  );
+}
