diff --git a/src/components/ReauthModal.tsx b/src/components/ReauthModal.tsx
new file mode 100644
index 0000000..c8444c2
--- /dev/null
+++ b/src/components/ReauthModal.tsx
@@ -0,0 +1,248 @@
+import React, { useState } from 'react';
+import {
+  authenticateWithPasskey,
+  getPasskeys,
+  getSession,
+  saveSession,
+  type AuthSession,
+  type PasskeyCredential,
+} from '../utils/passkeys';
+import { PasskeySymbolIcon, ProviderBadgeIcon } from './PasskeyIcons';
+
+interface ReauthModalProps {
+  isOpen: boolean;
+  actionTitle: string;
+  actionDescription?: string;
+  username: string;
+  onSuccess: (session: AuthSession) => void;
+  onClose: () => void;
+}
+
+export default function ReauthModal({
+  isOpen,
+  actionTitle,
+  actionDescription,
+  username,
+  onSuccess,
+  onClose,
+}: ReauthModalProps) {
+  const [selectedCredentialId, setSelectedCredentialId] = useState<string>('');
+  const [usePasswordFallback, setUsePasswordFallback] = useState(false);
+  const [password, setPassword] = useState('');
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  if (!isOpen) return null;
+
+  const userPasskeys: PasskeyCredential[] = getPasskeys(username);
+  const session = getSession();
+
+  const handlePasskeyReauth = async (credentialIdFilter?: string) => {
+    setError(null);
+    setLoading(true);
+    try {
+      const result = await authenticateWithPasskey({
+        username,
+        credentialIdFilter: credentialIdFilter || selectedCredentialId || undefined,
+        isReauth: true,
+        mediation: 'optional',
+      });
+      onSuccess(result.session);
+    } catch (err: any) {
+      setError(err?.message || 'Passkey verification failed. Please try again.');
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  const handlePasswordReauth = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    if (!password || password.length < 4) {
+      setError('Please enter your account password to verify your identity.');
+      return;
+    }
+    setLoading(true);
+    try {
+      const updatedSession: AuthSession = {
+        ...session,
+        lastReauthenticatedAt: new Date().toISOString(),
+        reauthMethod: 'password',
+      };
+      saveSession(updatedSession);
+      onSuccess(updatedSession);
+    } finally {
+      setLoading(false);
+      setPassword('');
+    }
+  };
+
+  return (
+    <div
+      className="fixed inset-0 bg-black/50 backdrop-blur-xs z-[99999] flex items-center justify-center p-4"
+      role="dialog"
+      aria-modal="true"
+      aria-labelledby="reauth-modal-title"
+      onClick={onClose}
+    >
+      <div
+        className="bg-white border border-gray-200 rounded-xl shadow-2xl max-w-md w-full overflow-hidden"
+        onClick={(e) => e.stopPropagation()}
+      >
+        {/* Top Header */}
+        <div className="bg-gray-900 text-white px-6 py-4 flex items-center justify-between">
+          <div className="flex items-center space-x-2.5">
+            <div className="p-1.5 rounded-lg bg-amber-400/20 text-amber-300">
+              <PasskeySymbolIcon className="w-5 h-5" />
+            </div>
+            <div>
+              <h3 id="reauth-modal-title" className="text-base font-bold">
+                Verify Your Identity
+              </h3>
+              <p className="text-xs text-gray-300">Step-up reauthentication required</p>
+            </div>
+          </div>
+          <button
+            type="button"
+            onClick={onClose}
+            className="text-gray-400 hover:text-white p-1 rounded-md transition-colors"
+            aria-label="Close verification modal"
+          >
+            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </div>
+
+        <div className="p-6 space-y-5">
+          {/* Action explanation */}
+          <div className="bg-amber-50 border border-amber-200 rounded-lg p-3.5 text-sm text-gray-800">
+            <p className="font-semibold text-gray-900">Protected Action: {actionTitle}</p>
+            <p className="text-xs text-gray-600 mt-1">
+              {actionDescription ||
+                `For your security, please confirm it's really you (${username}) using a registered passkey before continuing.`}
+            </p>
+          </div>
+
+          {error && (
+            <div className="p-3 text-xs font-medium text-red-700 bg-red-50 border border-red-200 rounded-lg" role="alert">
+              {error}
+            </div>
+          )}
+
+          {!usePasswordFallback ? (
+            <div className="space-y-4">
+              {userPasskeys.length > 0 && (
+                <div>
+                  <label className="block text-xs font-semibold uppercase tracking-wider text-gray-500 mb-2">
+                    Select Passkey to Verify ({userPasskeys.length} registered)
+                  </label>
+                  <div className="space-y-2 max-h-44 overflow-y-auto pr-1">
+                    {userPasskeys.map((pk) => {
+                      const isSelected = selectedCredentialId === pk.id;
+                      return (
+                        <button
+                          key={pk.id}
+                          type="button"
+                          onClick={() => setSelectedCredentialId(isSelected ? '' : pk.id)}
+                          className={`w-full text-left p-2.5 rounded-lg border transition flex items-center justify-between ${
+                            isSelected
+                              ? 'border-gray-900 bg-gray-50 ring-1 ring-gray-900'
+                              : 'border-gray-200 hover:border-gray-300'
+                          }`}
+                        >
+                          <div className="flex items-center space-x-2.5 min-w-0">
+                            <div className="w-8 h-8 rounded-md bg-gray-100 text-gray-800 flex items-center justify-center flex-shrink-0">
+                              <ProviderBadgeIcon icon={pk.providerIcon} className="w-4 h-4" />
+                            </div>
+                            <div className="truncate">
+                              <p className="text-sm font-semibold text-gray-900 truncate">{pk.name}</p>
+                              <p className="text-xs text-gray-500 truncate">
+                                {pk.providerName} · {pk.backupState ? 'Synced' : 'Device-bound'}
+                              </p>
+                            </div>
+                          </div>
+                          <span className="text-xs font-medium text-gray-600 ml-2 flex-shrink-0">
+                            {isSelected ? 'Selected' : 'Use'}
+                          </span>
+                        </button>
+                      );
+                    })}
+                  </div>
+                </div>
+              )}
+
+              <button
+                type="button"
+                disabled={loading}
+                onClick={() => handlePasskeyReauth()}
+                className="w-full py-2.5 px-4 rounded-lg shadow-xs text-sm font-semibold text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 flex items-center justify-center space-x-2 transition disabled:opacity-60 cursor-pointer"
+              >
+                <PasskeySymbolIcon className="w-5 h-5 text-amber-400" />
+                <span>
+                  {loading
+                    ? 'Waiting for authenticator...'
+                    : selectedCredentialId
+                    ? 'Verify with Selected Passkey'
+                    : 'Verify with Passkey'}
+                </span>
+              </button>
+
+              {session.user.hasPassword && !session.user.passwordlessOnly && (
+                <div className="text-center pt-1">
+                  <button
+                    type="button"
+                    onClick={() => {
+                      setError(null);
+                      setUsePasswordFallback(true);
+                    }}
+                    className="text-xs text-gray-600 hover:text-gray-900 underline cursor-pointer"
+                  >
+                    Having trouble with your passkey? Verify with password instead
+                  </button>
+                </div>
+              )}
+            </div>
+          ) : (
+            <form onSubmit={handlePasswordReauth} className="space-y-4">
+              <div>
+                <label htmlFor="reauth-password" className="block text-xs font-semibold text-gray-700 mb-1">
+                  Confirm Account Password for @{username}
+                </label>
+                <input
+                  id="reauth-password"
+                  type="password"
+                  autoComplete="current-password"
+                  value={password}
+                  onChange={(e) => setPassword(e.target.value)}
+                  placeholder="Enter your password"
+                  required
+                  className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
+                />
+              </div>
+              <div className="flex items-center space-x-2">
+                <button
+                  type="button"
+                  onClick={() => {
+                    setError(null);
+                    setUsePasswordFallback(false);
+                  }}
+                  className="w-1/2 py-2 px-3 border border-gray-300 rounded-md text-xs font-semibold text-gray-700 hover:bg-gray-50"
+                >
+                  Back to Passkey
+                </button>
+                <button
+                  type="submit"
+                  disabled={loading}
+                  className="w-1/2 py-2 px-3 rounded-md text-xs font-semibold text-white bg-gray-900 hover:bg-gray-800"
+                >
+                  {loading ? 'Verifying...' : 'Confirm Password'}
+                </button>
+              </div>
+            </form>
+          )}
+        </div>
+      </div>
+    </div>
+  );
+}
