index 0000000..da7ffc0
--- /dev/null
+++ b/src/pages/api/passkeys.json.ts
@@ -0,0 +1,208 @@
+import type { APIRoute } from 'astro';
+import {
+  DEFAULT_DEMO_PASSKEYS,
+  DEFAULT_DEMO_USER,
+  generateRandomChallenge,
+  type PasskeyCredential,
+  type UserAccount,
+} from '../../utils/passkeys';
+
+// In-memory store on the server for WebAuthn challenges, users, and credentials
+const serverStore: {
+  users: UserAccount[];
+  passkeys: PasskeyCredential[];
+  challenges: Map<string, { challenge: string; createdAt: number }>;
+} = {
+  users: [{ ...DEFAULT_DEMO_USER }],
+  passkeys: DEFAULT_DEMO_PASSKEYS.map((p) => ({ ...p })),
+  challenges: new Map(),
+};
+
+export const GET: APIRoute = async ({ url, session }) => {
+  const username = url.searchParams.get('username');
+  const sessionPasskeys = (await session?.get('passkeys')) as PasskeyCredential[] | undefined;
+  const passkeys = sessionPasskeys || serverStore.passkeys;
+  const filtered = username
+    ? passkeys.filter((p) => p.username.toLowerCase() === username.toLowerCase())
+    : passkeys;
+
+  return new Response(
+    JSON.stringify({
+      users: serverStore.users,
+      passkeys: filtered,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const { action } = body;
+
+    if (action === 'register-options') {
+      const challenge = generateRandomChallenge(32);
+      const username = body.username || DEFAULT_DEMO_USER.username;
+      serverStore.challenges.set(username, { challenge, createdAt: Date.now() });
+      await session?.set('currentChallenge', challenge);
+
+      const userPasskeys = serverStore.passkeys.filter(
+        (p) => p.username.toLowerCase() === username.toLowerCase()
+      );
+
+      return new Response(
+        JSON.stringify({
+          challenge,
+          rp: { name: 'The DevTools Times' },
+          user: {
+            id: body.userId || DEFAULT_DEMO_USER.id,
+            name: username,
+            displayName: body.displayName || username,
+          },
+          excludeCredentials: userPasskeys.map((p) => ({
+            id: p.id,
+            type: 'public-key',
+            transports: p.transports,
+          })),
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'register-verify') {
+      const { passkey, user } = body as {
+        passkey: PasskeyCredential;
+        user?: UserAccount;
+      };
+      if (!passkey || !passkey.id) {
+        return new Response(JSON.stringify({ error: 'Missing passkey data' }), {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+
+      if (user) {
+        const existingIdx = serverStore.users.findIndex(
+          (u) => u.username.toLowerCase() === user.username.toLowerCase()
+        );
+        if (existingIdx >= 0) {
+          serverStore.users[existingIdx] = user;
+        } else {
+          serverStore.users.push(user);
+        }
+      }
+
+      serverStore.passkeys = [
+        passkey,
+        ...serverStore.passkeys.filter((p) => p.id !== passkey.id),
+      ];
+      await session?.set('passkeys', serverStore.passkeys);
+
+      return new Response(
+        JSON.stringify({
+          verified: true,
+          passkey,
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'auth-options' || action === 'reauth-options') {
+      const challenge = generateRandomChallenge(32);
+      const username = body.username;
+      if (username) {
+        serverStore.challenges.set(username, { challenge, createdAt: Date.now() });
+      }
+      await session?.set('currentChallenge', challenge);
+
+      const allowCredentials = username
+        ? serverStore.passkeys
+            .filter((p) => p.username.toLowerCase() === username.toLowerCase())
+            .map((p) => ({
+              id: p.id,
+              type: 'public-key',
+              transports: p.transports,
+            }))
+        : [];
+
+      return new Response(
+        JSON.stringify({
+          challenge,
+          allowCredentials,
+          userVerification: action === 'reauth-options' ? 'required' : 'preferred',
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'auth-verify' || action === 'reauth-verify') {
+      const { credentialId } = body;
+      const pk = serverStore.passkeys.find((p) => p.id === credentialId);
+      if (pk) {
+        pk.lastUsedAt = new Date().toISOString();
+        pk.signCount += 1;
+      }
+      await session?.set('lastReauthenticatedAt', new Date().toISOString());
+
+      return new Response(
+        JSON.stringify({
+          verified: true,
+          reauthenticatedAt: new Date().toISOString(),
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'rename') {
+      const { credentialId, name } = body;
+      const pk = serverStore.passkeys.find((p) => p.id === credentialId);
+      if (pk && name) {
+        pk.name = name;
+      }
+      await session?.set('passkeys', serverStore.passkeys);
+      return new Response(JSON.stringify({ ok: true, passkeys: serverStore.passkeys }), {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    if (action === 'delete') {
+      const { credentialId } = body;
+      serverStore.passkeys = serverStore.passkeys.filter((p) => p.id !== credentialId);
+      await session?.set('passkeys', serverStore.passkeys);
+      return new Response(JSON.stringify({ ok: true, passkeys: serverStore.passkeys }), {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    if (action === 'update-profile' || action === 'update-security') {
+      const { user } = body as { user: UserAccount };
+      if (user) {
+        const idx = serverStore.users.findIndex((u) => u.id === user.id);
+        if (idx >= 0) {
+          serverStore.users[idx] = user;
+        } else {
+          serverStore.users.push(user);
+        }
+      }
+      return new Response(JSON.stringify({ ok: true, user }), {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    return new Response(JSON.stringify({ error: 'Unknown action' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Internal Server Error' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
