+// WebAuthn & Passkeys client/shared utilities for The DevTools Times
+
+export interface PasskeyCredential {
+  id: string; // base64url credential ID
+  userId: string; // base64url user handle
+  username: string;
+  name: string; // friendly nickname
+  aaguid: string;
+  providerName: string;
+  providerIcon: 'apple' | 'google' | 'windows' | '1password' | 'bitwarden' | 'yubikey' | 'chrome' | 'key';
+  transports: AuthenticatorTransport[];
+  backupEligible: boolean;
+  backupState: boolean;
+  userVerified: boolean;
+  algorithm: 'ES256' | 'RS256' | 'EdDSA';
+  publicKey: string;
+  signCount: number;
+  createdAt: string;
+  lastUsedAt: string | null;
+  deviceInfo: string;
+}
+
+export interface UserAccount {
+  id: string; // base64url user handle
+  username: string;
+  displayName: string;
+  email: string;
+  role: string;
+  hasPassword: boolean;
+  passwordlessOnly: boolean;
+  requireReauthForSensitive: boolean;
+  apiKey: string;
+  createdAt: string;
+}
+
+export interface AuthSession {
+  user: UserAccount;
+  authMethod: 'passkey' | 'password';
+  passkeyIdUsed?: string;
+  signedInAt: string;
+  lastReauthenticatedAt: string | null;
+  reauthMethod?: 'passkey' | 'password';
+}
+
+export interface WebAuthnLogEntry {
+  id: string;
+  timestamp: string;
+  operation:
+    | 'credentials.create'
+    | 'credentials.get (explicit)'
+    | 'credentials.get (conditional)'
+    | 'credentials.get (reauth)'
+    | 'signalUnknownCredential'
+    | 'signalAllAcceptedCredentials'
+    | 'signalCurrentUserDetails';
+  status: 'success' | 'cancelled' | 'error' | 'simulated' | 'unsupported';
+  details: string;
+  metadata?: Record<string, any>;
+}
+
+// Known Authenticator AAGUID lookup table
+export const KNOWN_AAGUIDS: Record<
+  string,
+  { name: string; icon: PasskeyCredential['providerIcon'] }
+> = {
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', icon: 'apple' },
+  '00000000-0000-0000-0000-000000000000': { name: 'Platform / Virtual Authenticator', icon: 'chrome' },
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', icon: 'google' },
+  'adce0002-35bc-c60a-648b-0b25f1f05503': { name: 'Chrome on macOS', icon: 'chrome' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', icon: 'windows' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello', icon: 'windows' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', icon: '1password' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', icon: 'bitwarden' },
+  '2fc0579f-8113-47ea-b116-bb5a8db9202a': { name: 'YubiKey 5 Series', icon: 'yubikey' },
+  'ee882879-721c-4913-9775-3dfcce97072a': { name: 'YubiKey Bio Series', icon: 'yubikey' },
+};
+
+// Base64URL encoding and decoding helpers
+export function bufferToBase64url(buffer: ArrayBuffer | Uint8Array): string {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function base64urlToBuffer(base64url: string): ArrayBuffer {
+  const padding = '='.repeat((4 - (base64url.length % 4)) % 4);
+  const base64 = (base64url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = atob(base64);
+  const outputArray = new Uint8Array(rawData.length);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray.buffer;
+}
+
+export function stringToBase64url(str: string): string {
+  const encoder = new TextEncoder();
+  return bufferToBase64url(encoder.encode(str));
+}
+
+export function generateRandomChallenge(byteLength = 32): string {
+  const bytes = new Uint8Array(byteLength);
+  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
+    crypto.getRandomValues(bytes);
+  } else {
+    for (let i = 0; i < byteLength; i++) {
+      bytes[i] = Math.floor(Math.random() * 256);
+    }
+  }
+  return bufferToBase64url(bytes);
+}
+
+// Parse WebAuthn binary authenticatorData structure
+export interface ParsedAuthenticatorData {
+  userPresent: boolean;
+  userVerified: boolean;
+  backupEligible: boolean;
+  backupState: boolean;
+  attestedCredentialDataIncluded: boolean;
+  extensionDataIncluded: boolean;
+  signCount: number;
+  aaguid: string;
+}
+
+export function parseAuthenticatorData(authDataBuffer: ArrayBuffer): ParsedAuthenticatorData {
+  const bytes = new Uint8Array(authDataBuffer);
+  if (bytes.byteLength < 37) {
+    return {
+      userPresent: true,
+      userVerified: true,
+      backupEligible: true,
+      backupState: true,
+      attestedCredentialDataIncluded: false,
+      extensionDataIncluded: false,
+      signCount: 0,
+      aaguid: '00000000-0000-0000-0000-000000000000',
+    };
+  }
+
+  const flags = bytes[32];
+  const userPresent = Boolean(flags & 0x01); // Bit 0: UP
+  const userVerified = Boolean(flags & 0x04); // Bit 2: UV
+  const backupEligible = Boolean(flags & 0x08); // Bit 3: BE
+  const backupState = Boolean(flags & 0x10); // Bit 4: BS
+  const attestedCredentialDataIncluded = Boolean(flags & 0x40); // Bit 6: AT
+  const extensionDataIncluded = Boolean(flags & 0x80); // Bit 7: ED
+
+  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
+  const signCount = view.getUint32(33, false);
+
+  let aaguid = '00000000-0000-0000-0000-000000000000';
+  if (attestedCredentialDataIncluded && bytes.byteLength >= 53) {
+    const aaguidBytes = bytes.slice(37, 53);
+    const hex = Array.from(aaguidBytes)
+      .map((b) => b.toString(16).padStart(2, '0'))
+      .join('');
+    aaguid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
+  }
+
+  return {
+    userPresent,
+    userVerified,
+    backupEligible,
+    backupState,
+    attestedCredentialDataIncluded,
+    extensionDataIncluded,
+    signCount,
+    aaguid,
+  };
+}
+
+export function detectDeviceAndProvider(aaguid?: string): {
+  defaultName: string;
+  providerName: string;
+  providerIcon: PasskeyCredential['providerIcon'];
+  deviceInfo: string;
+} {
+  const known = aaguid && KNOWN_AAGUIDS[aaguid.toLowerCase()];
+  const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
+
+  let os = 'Desktop';
+  let defaultIcon: PasskeyCredential['providerIcon'] = 'key';
+  let defaultProvider = 'Passkey Authenticator';
+
+  if (/Mac|iPhone|iPad|iPod/i.test(ua)) {
+    os = /iPhone|iPad|iPod/i.test(ua) ? 'iPhone / iOS' : 'MacBook / macOS';
+    defaultIcon = 'apple';
+    defaultProvider = 'iCloud Keychain';
+  } else if (/Android/i.test(ua)) {
+    os = 'Android Device';
+    defaultIcon = 'google';
+    defaultProvider = 'Google Password Manager';
+  } else if (/Win/i.test(ua)) {
+    os = 'Windows PC';
+    defaultIcon = 'windows';
+    defaultProvider = 'Windows Hello';
+  } else if (/Linux/i.test(ua)) {
+    os = 'Linux Workstation';
+    defaultIcon = 'chrome';
+    defaultProvider = 'Chrome Passkey Authenticator';
+  }
+
+  const browser = /Edg/i.test(ua)
+    ? 'Edge'
+    : /Chrome/i.test(ua)
+    ? 'Chrome'
+    : /Safari/i.test(ua)
+    ? 'Safari'
+    : /Firefox/i.test(ua)
+    ? 'Firefox'
+    : 'Browser';
+
+  const providerName = known ? known.name : defaultProvider;
+  const providerIcon = known ? known.icon : defaultIcon;
+  const defaultName = known && known.name !== 'Platform / Virtual Authenticator'
+    ? `${known.name} (${os})`
+    : `${os} · ${browser}`;
+
+  return {
+    defaultName,
+    providerName,
+    providerIcon,
+    deviceInfo: `${os} · ${browser}`,
+  };
+}
