+export async function invokeSignalUnknownCredential(credentialId: string): Promise<void> {
+  const rpId = getRpId();
+  const pkcAny = typeof PublicKeyCredential !== 'undefined' ? (PublicKeyCredential as any) : null;
+  if (pkcAny && typeof pkcAny.signalUnknownCredential === 'function') {
+    try {
+      await pkcAny.signalUnknownCredential({
+        rpId,
+        credentialId,
+      });
+      appendWebAuthnLog({
+        operation: 'signalUnknownCredential',
+        status: 'success',
+        details: `Signaled unknown/deleted credential ${credentialId.slice(0, 14)}... to authenticator`,
+        metadata: { rpId, credentialId },
+      });
+      return;
+    } catch (err: any) {
+      appendWebAuthnLog({
+        operation: 'signalUnknownCredential',
+        status: 'error',
+        details: err?.message || 'Failed to signal unknown credential',
+        metadata: { rpId, credentialId },
+      });
+      return;
+    }
+  }
+  appendWebAuthnLog({
+    operation: 'signalUnknownCredential',
+    status: 'unsupported',
+    details: `Recorded unknown credential signal for ${credentialId.slice(0, 14)}... (Signal API not active in browser)`,
+    metadata: { rpId, credentialId },
+  });
