+// ============================================================================
+// 1. PASSKEY REGISTRATION (navigator.credentials.create)
+// ============================================================================
+export interface RegisterPasskeyOptions {
+  username: string;
+  displayName?: string;
+  email?: string;
+  passkeyName?: string;
+  authenticatorAttachment?: AuthenticatorAttachment;
+  allowSimulatedFallback?: boolean;
+}
+
+export interface RegisterPasskeyResult {
+  passkey: PasskeyCredential;
+  user: UserAccount;
+  session: AuthSession;
+  simulated: boolean;
+}
+
+export async function registerPasskey(
+  options: RegisterPasskeyOptions
+): Promise<RegisterPasskeyResult> {
+  const cleanUsername = options.username.trim() || DEFAULT_DEMO_USER.username;
+  const cleanDisplayName = options.displayName?.trim() || cleanUsername;
+  const cleanEmail =
+    options.email?.trim() ||
+    (cleanUsername.includes('@') ? cleanUsername : `${cleanUsername}@devtoolstimes.dev`);
+
+  const users = getUsers();
+  let user = users.find((u) => u.username.toLowerCase() === cleanUsername.toLowerCase());
+  if (!user) {
+    user = {
+      id: stringToBase64url(`user_${cleanUsername}_${Date.now()}`),
+      username: cleanUsername,
+      displayName: cleanDisplayName,
+      email: cleanEmail,
+      role: 'Subscriber · Digital Access',
+      hasPassword: false,
+      passwordlessOnly: true,
+      requireReauthForSensitive: true,
+      apiKey: `dtt_live_${generateRandomChallenge(12).toLowerCase()}`,
+      createdAt: new Date().toISOString(),
+    };
+    users.push(user);
+    saveUsers(users);
+  } else if (options.displayName || options.email) {
+    user.displayName = cleanDisplayName;
+    user.email = cleanEmail;
+    saveUsers(users);
+  }
+
+  const existingPasskeys = getPasskeys(user.username);
+
+  // Request registration challenge & options from server API
+  const serverOpts = await callPasskeyApi({
+    action: 'register-options',
+    username: user.username,
+    displayName: user.displayName,
+    userId: user.id,
+  });
+
+  const challengeStr = serverOpts?.challenge || generateRandomChallenge(32);
+  const rpId = getRpId();
+
+  // Build excludeCredentials from already registered passkeys for this user
+  const excludeCredentials: PublicKeyCredentialDescriptor[] = [];
+  for (const cred of existingPasskeys) {
+    try {
+      excludeCredentials.push({
+        id: base64urlToBuffer(cred.id),
+        type: 'public-key',
+        transports: cred.transports,
+      });
+    } catch {
+      // Ignore non-base64url legacy IDs
+    }
+  }
+
+  const authenticatorSelection: AuthenticatorSelectionCriteria = {
+    residentKey: 'required',
+    requireResidentKey: true,
+    userVerification: 'preferred',
+  };
+  if (options.authenticatorAttachment) {
+    authenticatorSelection.authenticatorAttachment = options.authenticatorAttachment;
+  }
+
+  const publicKeyOptions: PublicKeyCredentialCreationOptions = {
+    challenge: base64urlToBuffer(challengeStr),
+    rp: {
+      name: 'The DevTools Times',
+      id: rpId,
+    },
+    user: {
+      id: base64urlToBuffer(user.id),
+      name: user.username,
+      displayName: user.displayName,
+    },
+    pubKeyCredParams: [
+      { alg: -7, type: 'public-key' }, // ES256
+      { alg: -257, type: 'public-key' }, // RS256
+      { alg: -8, type: 'public-key' }, // EdDSA
+    ],
+    timeout: 60000,
+    attestation: 'none',
+    excludeCredentials,
+    authenticatorSelection,
+  };
+
+  let createdCred: PublicKeyCredential | null = null;
+  let simulated = false;
+
+  if (typeof window !== 'undefined' && window.PublicKeyCredential && navigator.credentials?.create) {
+    try {
+      createdCred = (await navigator.credentials.create({
+        publicKey: publicKeyOptions,
+      })) as PublicKeyCredential | null;
+    } catch (err: any) {
+      if (err?.name === 'InvalidStateError') {
+        appendWebAuthnLog({
+          operation: 'credentials.create',
+          status: 'error',
+          details: 'InvalidStateError: A passkey for this account already exists on this authenticator.',
+          metadata: { username: user.username, rpId },
+        });
+        throw new Error(
+          'A passkey for this account is already registered on this device or password manager.'
+        );
+      }
+
+      const allowFallback =
+        options.allowSimulatedFallback ?? getSimulationFallbackEnabled();
+
+      if (!allowFallback) {
+        appendWebAuthnLog({
+          operation: 'credentials.create',
+          status: err?.name === 'NotAllowedError' ? 'cancelled' : 'error',
+          details: `${err?.name || 'Error'}: ${err?.message || 'Passkey creation was cancelled or failed.'}`,
+          metadata: { username: user.username, rpId },
+        });
+        if (err?.name === 'NotAllowedError') {
+          throw new Error('Passkey registration was cancelled or timed out. Please try again.');
+        }
+        throw new Error(err?.message || 'Unable to create a passkey on this device.');
+      }
+      simulated = true;
+    }
+  } else {
+    simulated = true;
+  }
+
+  let newPasskey: PasskeyCredential;
+
+  if (createdCred && !simulated) {
+    const response = createdCred.response as AuthenticatorAttestationResponse;
+    const authData = parseAuthenticatorData(response.getAuthenticatorData());
+    const transports =
+      (typeof response.getTransports === 'function'
+        ? (response.getTransports() as AuthenticatorTransport[])
+        : ['internal', 'hybrid']) || ['internal'];
+
+    const detected = detectDeviceAndProvider(authData.aaguid);
+    const pubKeyBuffer =
+      typeof response.getPublicKey === 'function' ? response.getPublicKey() : null;
+    const algCode =
+      typeof response.getPublicKeyAlgorithm === 'function'
+        ? response.getPublicKeyAlgorithm()
+        : -7;
+
+    newPasskey = {
+      id: createdCred.id || bufferToBase64url(createdCred.rawId),
+      userId: user.id,
+      username: user.username,
+      name: options.passkeyName?.trim() || detected.defaultName,
+      aaguid: authData.aaguid,
+      providerName: detected.providerName,
+      providerIcon: detected.providerIcon,
+      transports: transports.length > 0 ? transports : ['internal'],
+      backupEligible: authData.backupEligible,
+      backupState: authData.backupState,
+      userVerified: authData.userVerified,
+      algorithm: algCode === -257 ? 'RS256' : algCode === -8 ? 'EdDSA' : 'ES256',
+      publicKey: pubKeyBuffer ? bufferToBase64url(pubKeyBuffer) : generateRandomChallenge(48),
+      signCount: authData.signCount,
+      createdAt: new Date().toISOString(),
+      lastUsedAt: new Date().toISOString(),
+      deviceInfo: detected.deviceInfo,
+    };
+
+    appendWebAuthnLog({
+      operation: 'credentials.create',
+      status: 'success',
+      details: `Registered passkey "${newPasskey.name}" (${newPasskey.id.slice(0, 14)}...)`,
+      metadata: {
+        rpId,
+        aaguid: newPasskey.aaguid,
+        backupEligible: newPasskey.backupEligible,
+        backupState: newPasskey.backupState,
+        transports: newPasskey.transports,
+      },
+    });
+  } else {
+    // Simulated WebAuthn credential creation (when running in environment without virtual/hardware authenticator)
+    const isSecurityKey = options.authenticatorAttachment === 'cross-platform';
+    const simulatedAaguid = isSecurityKey
+      ? '2fc0579f-8113-47ea-b116-bb5a8db9202a'
+      : 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd';
+    const detected = detectDeviceAndProvider(simulatedAaguid);
+
+    newPasskey = {
+      id: generateRandomChallenge(24),
+      userId: user.id,
+      username: user.username,
+      name:
+        options.passkeyName?.trim() ||
+        (isSecurityKey ? 'Hardware Security Key (USB/NFC)' : detected.defaultName),
+      aaguid: simulatedAaguid,
+      providerName: isSecurityKey ? 'YubiKey 5 Series' : detected.providerName,
+      providerIcon: isSecurityKey ? 'yubikey' : detected.providerIcon,
+      transports: isSecurityKey ? ['usb', 'nfc'] : ['internal', 'hybrid'],
+      backupEligible: !isSecurityKey,
+      backupState: !isSecurityKey,
+      userVerified: true,
+      algorithm: 'ES256',
+      publicKey: generateRandomChallenge(48),
+      signCount: 0,
+      createdAt: new Date().toISOString(),
+      lastUsedAt: new Date().toISOString(),
+      deviceInfo: isSecurityKey ? 'Hardware Security Key · USB/NFC' : detected.deviceInfo,
+    };
+
+    appendWebAuthnLog({
+      operation: 'credentials.create',
+      status: 'simulated',
+      details: `Registered passkey "${newPasskey.name}" (${newPasskey.id.slice(0, 14)}...)`,
+      metadata: {
+        rpId,
+        aaguid: newPasskey.aaguid,
+        backupState: newPasskey.backupState,
+        transports: newPasskey.transports,
+      },
+    });
+  }
+
+  // Persist passkey locally & on server
+  const allPasskeys = getPasskeys();
+  const updatedPasskeys = [newPasskey, ...allPasskeys];
+  savePasskeys(updatedPasskeys);
+
+  await callPasskeyApi({
+    action: 'register-verify',
+    passkey: newPasskey,
+    user,
+  });
+
+  // Notify authenticator of all accepted credentials for this user
+  const userPasskeyIds = updatedPasskeys
+    .filter((p) => p.username.toLowerCase() === user!.username.toLowerCase())
+    .map((p) => p.id);
+  await invokeSignalAllAcceptedCredentials(user.id, userPasskeyIds);
+
+  const session: AuthSession = {
+    user,
+    authMethod: 'passkey',
+    passkeyIdUsed: newPasskey.id,
+    signedInAt: new Date().toISOString(),
+    lastReauthenticatedAt: new Date().toISOString(),
+    reauthMethod: 'passkey',
+  };
+  saveSession(session);
+
+  return {
+    passkey: newPasskey,
+    user,
+    session,
+    simulated,
+  };
+}
+
+// ============================================================================
+// 2. PASSKEY AUTHENTICATION & REAUTHENTICATION (navigator.credentials.get)
+// ============================================================================
+export interface AuthenticatePasskeyOptions {
+  username?: string;
+  credentialIdFilter?: string; // Used when testing/verifying a specific passkey
+  mediation?: CredentialMediationRequirement;
+  isReauth?: boolean;
+  signal?: AbortSignal;
+  allowSimulatedFallback?: boolean;
+}
+
+export interface AuthenticatePasskeyResult {
+  passkey: PasskeyCredential;
+  user: UserAccount;
+  session: AuthSession;
+  simulated: boolean;
+}
+
+export async function authenticateWithPasskey(
+  options: AuthenticatePasskeyOptions = {}
+): Promise<AuthenticatePasskeyResult> {
+  const isConditional = options.mediation === 'conditional';
+  const isReauth = Boolean(options.isReauth);
+  const rpId = getRpId();
+
+  const serverOpts = await callPasskeyApi({
+    action: isReauth ? 'reauth-options' : 'auth-options',
+    username: options.username,
+  });
+
+  const challengeStr = serverOpts?.challenge || generateRandomChallenge(32);
+
+  // Determine allowCredentials:
+  // - For conditional UI or discoverable sign-in without a username: empty allowCredentials []
+  // - For reauthentication or specific username/credential: scope allowCredentials to matching credentials
+  const allowCredentials: PublicKeyCredentialDescriptor[] = [];
+  const candidatePasskeys = options.credentialIdFilter
+    ? getPasskeys().filter((p) => p.id === options.credentialIdFilter)
+    : options.username
+    ? getPasskeys(options.username)
+    : [];
+
+  if (!isConditional && (isReauth || options.username || options.credentialIdFilter)) {
+    for (const cred of candidatePasskeys) {
+      try {
+        allowCredentials.push({
+          id: base64urlToBuffer(cred.id),
+          type: 'public-key',
+          transports: cred.transports,
+        });
+      } catch {
+        // Ignore non-base64url IDs
+      }
+    }
+  }
+
+  const publicKeyRequestOptions: PublicKeyCredentialRequestOptions = {
+    challenge: base64urlToBuffer(challengeStr),
+    rpId,
+    timeout: 60000,
+    userVerification: isReauth ? 'required' : 'preferred',
+    allowCredentials,
+  };
+
+  let assertion: PublicKeyCredential | null = null;
+  let simulated = false;
+
+  if (typeof window !== 'undefined' && window.PublicKeyCredential && navigator.credentials?.get) {
+    try {
+      const credentialGetOptions: CredentialRequestOptions = {
+        publicKey: publicKeyRequestOptions,
+        mediation: options.mediation || 'optional',
+      };
+      if (options.signal) {
+        credentialGetOptions.signal = options.signal;
+      }
+      assertion = (await navigator.credentials.get(
+        credentialGetOptions
+      )) as PublicKeyCredential | null;
+    } catch (err: any) {
+      if (err?.name === 'AbortError' || isConditional) {
+        throw err;
+      }
+
+      const allowFallback =
+        options.allowSimulatedFallback ?? getSimulationFallbackEnabled();
+
+      if (!allowFallback) {
+        appendWebAuthnLog({
+          operation: isReauth ? 'credentials.get (reauth)' : 'credentials.get (explicit)',
+          status: err?.name === 'NotAllowedError' ? 'cancelled' : 'error',
+          details: `${err?.name || 'Error'}: ${err?.message || 'Passkey verification cancelled.'}`,
+          metadata: { rpId, isReauth, username: options.username },
+        });
+        if (err?.name === 'NotAllowedError') {
+          throw new Error('Passkey verification was cancelled or timed out.');
+        }
+        throw new Error(err?.message || 'Passkey verification failed.');
+      }
+      simulated = true;
+    }
+  } else {
+    if (isConditional) {
+      throw new Error('Conditional mediation not supported');
+    }
+    simulated = true;
+  }
+
+  const allPasskeys = getPasskeys();
+  const allUsers = getUsers();
+  let matchedPasskey: PasskeyCredential | undefined;
+
+  if (assertion && !simulated) {
+    const credId = assertion.id || bufferToBase64url(assertion.rawId);
+    const assertionResp = assertion.response as AuthenticatorAssertionResponse;
+    const authData = parseAuthenticatorData(assertionResp.authenticatorData);
+    const userHandleStr = assertionResp.userHandle
+      ? bufferToBase64url(assertionResp.userHandle)
+      : undefined;
+
+    matchedPasskey = allPasskeys.find((p) => p.id === credId);
+
+    if (!matchedPasskey && userHandleStr) {
+      matchedPasskey = allPasskeys.find((p) => p.userId === userHandleStr);
+    }
+
+    // If a real authenticator returned a valid credential not yet in local storage, register it in state
+    if (!matchedPasskey) {
+      const targetUser =
+        (options.username &&
+          allUsers.find((u) => u.username.toLowerCase() === options.username!.toLowerCase())) ||
+        (userHandleStr && allUsers.find((u) => u.id === userHandleStr)) ||
+        allUsers[0] ||
+        DEFAULT_DEMO_USER;
+
+      const detected = detectDeviceAndProvider();
+      matchedPasskey = {
+        id: credId,
+        userId: userHandleStr || targetUser.id,
+        username: targetUser.username,
+        name: detected.defaultName,
+        aaguid: authData.aaguid,
+        providerName: detected.providerName,
+        providerIcon: detected.providerIcon,
+        transports: ['internal', 'hybrid'],
+        backupEligible: authData.backupEligible,
+        backupState: authData.backupState,
+        userVerified: authData.userVerified,
+        algorithm: 'ES256',
+        publicKey: generateRandomChallenge(48),
+        signCount: authData.signCount,
+        createdAt: new Date().toISOString(),
+        lastUsedAt: new Date().toISOString(),
+        deviceInfo: detected.deviceInfo,
+      };
+      allPasskeys.unshift(matchedPasskey);
+    } else {
+      matchedPasskey.lastUsedAt = new Date().toISOString();
+      matchedPasskey.signCount = Math.max(
+        matchedPasskey.signCount + 1,
+        authData.signCount
+      );
+      matchedPasskey.backupEligible = authData.backupEligible;
+      matchedPasskey.backupState = authData.backupState;
+    }
+
+    appendWebAuthnLog({
+      operation: isReauth
+        ? 'credentials.get (reauth)'
+        : isConditional
+        ? 'credentials.get (conditional)'
+        : 'credentials.get (explicit)',
+      status: 'success',
+      details: `Authenticated as ${matchedPasskey.username} using "${matchedPasskey.name}"`,
+      metadata: {
+        rpId,
+        credentialId: matchedPasskey.id,
+        signCount: matchedPasskey.signCount,
+        userVerified: authData.userVerified,
+      },
+    });
+  } else {
+    // Simulated assertion fallback
+    matchedPasskey =
+      (options.credentialIdFilter &&
+        allPasskeys.find((p) => p.id === options.credentialIdFilter)) ||
+      (options.username &&
+        allPasskeys.find(
+          (p) => p.username.toLowerCase() === options.username!.toLowerCase()
+        )) ||
+      allPasskeys[0];
+
+    if (!matchedPasskey) {
+      throw new Error(
+        options.username
+          ? `No passkeys found for "${options.username}". Please sign up or create a passkey first.`
+          : 'No registered passkeys found. Please create a passkey first.'
+      );
+    }
+
+    matchedPasskey.lastUsedAt = new Date().toISOString();
+    matchedPasskey.signCount += 1;
+
+    appendWebAuthnLog({
+      operation: isReauth
+        ? 'credentials.get (reauth)'
+        : 'credentials.get (explicit)',
+      status: 'simulated',
+      details: `Verified "${matchedPasskey.name}" for ${matchedPasskey.username}`,
+      metadata: {
+        rpId,
+        credentialId: matchedPasskey.id,
+        signCount: matchedPasskey.signCount,
+      },
+    });
+  }
+
+  savePasskeys(allPasskeys);
+
+  const user =
+    allUsers.find(
+      (u) =>
+        u.id === matchedPasskey!.userId ||
+        u.username.toLowerCase() === matchedPasskey!.username.toLowerCase()
+    ) || DEFAULT_DEMO_USER;
+
+  const existingSession = getSession();
+  const session: AuthSession = {
+    user,
+    authMethod: 'passkey',
+    passkeyIdUsed: matchedPasskey.id,
+    signedInAt: isReauth ? existingSession.signedInAt : new Date().toISOString(),
+    lastReauthenticatedAt: new Date().toISOString(),
+    reauthMethod: 'passkey',
+  };
+  saveSession(session);
+
+  await callPasskeyApi({
+    action: isReauth ? 'reauth-verify' : 'auth-verify',
+    credentialId: matchedPasskey.id,
+    username: user.username,
+  });
+
+  return {
+    passkey: matchedPasskey,
+    user,
+    session,
+    simulated,
+  };
+}
+
+// ============================================================================
+// 3. PASSKEY MANAGEMENT (Rename, Delete, Profile & Security Updates)
+// ============================================================================
+export async function renamePasskeyCredential(
+  credentialId: string,
+  newName: string
+): Promise<PasskeyCredential[]> {
+  const cleanName = newName.trim();
+  if (!cleanName) {
+    throw new Error('Passkey name cannot be empty.');
+  }
+  const all = getPasskeys();
+  const target = all.find((p) => p.id === credentialId);
+  if (!target) {
+    throw new Error('Passkey not found.');
+  }
+  target.name = cleanName;
+  savePasskeys(all);
+
+  await callPasskeyApi({
+    action: 'rename',
+    credentialId,
+    name: cleanName,
+  });
+
+  return all;
+}
+
+export async function deletePasskeyCredential(
+  credentialId: string
+): Promise<PasskeyCredential[]> {
+  const all = getPasskeys();
+  const target = all.find((p) => p.id === credentialId);
+  if (!target) {
+    throw new Error('Passkey not found.');
+  }
+
+  const remainingForUser = all.filter(
+    (p) =>
+      p.username.toLowerCase() === target.username.toLowerCase() &&
+      p.id !== credentialId
+  );
+
+  const users = getUsers();
+  const user = users.find(
+    (u) => u.username.toLowerCase() === target.username.toLowerCase()
+  );
+
+  if (user && user.passwordlessOnly && remainingForUser.length === 0) {
+    throw new Error(
+      'Cannot delete your only passkey while Passwordless-Only mode is enabled. Add another passkey or enable password fallback first.'
+    );
+  }
+
+  const updated = all.filter((p) => p.id !== credentialId);
+  savePasskeys(updated);
+
+  await callPasskeyApi({
+    action: 'delete',
+    credentialId,
+  });
+
+  // Notify browser/authenticator via WebAuthn Signal APIs
+  await invokeSignalUnknownCredential(credentialId);
+  if (user) {
+    await invokeSignalAllAcceptedCredentials(
+      user.id,
+      remainingForUser.map((p) => p.id)
+    );
+  }
+
+  return updated;
+}
+
+export async function updateUserAccountProfile(updates: {
+  username?: string;
+  displayName?: string;
+  email?: string;
+}): Promise<UserAccount> {
+  const session = getSession();
+  const users = getUsers();
+  const idx = users.findIndex((u) => u.id === session.user.id);
+  const current = idx >= 0 ? users[idx] : session.user;
+  const oldUsername = current.username;
+
+  const updatedUser: UserAccount = {
+    ...current,
+    username: updates.username?.trim() || current.username,
+    displayName: updates.displayName?.trim() || current.displayName,
+    email: updates.email?.trim() || current.email,
+  };
+
+  if (idx >= 0) {
+    users[idx] = updatedUser;
+  } else {
+    users.push(updatedUser);
+  }
+  saveUsers(users);
+
+  // Update username references on user's passkeys if username changed
+  if (oldUsername.toLowerCase() !== updatedUser.username.toLowerCase()) {
+    const passkeys = getPasskeys();
+    for (const pk of passkeys) {
+      if (pk.userId === updatedUser.id || pk.username.toLowerCase() === oldUsername.toLowerCase()) {
+        pk.username = updatedUser.username;
+      }
+    }
+    savePasskeys(passkeys);
+  }
+
+  saveSession({
+    ...session,
+    user: updatedUser,
+  });
+
+  await callPasskeyApi({
+    action: 'update-profile',
+    user: updatedUser,
+  });
+
+  // Signal updated user details to authenticator / password manager
+  await invokeSignalCurrentUserDetails(
+    updatedUser.id,
+    updatedUser.username,
+    updatedUser.displayName
+  );
+
+  return updatedUser;
+}
+
+export async function updateUserSecuritySettings(updates: {
+  passwordlessOnly?: boolean;
+  requireReauthForSensitive?: boolean;
+  hasPassword?: boolean;
+  regenerateApiKey?: boolean;
+}): Promise<UserAccount> {
+  const session = getSession();
+  const users = getUsers();
+  const idx = users.findIndex((u) => u.id === session.user.id);
+  const current = idx >= 0 ? users[idx] : session.user;
+
+  const userPasskeys = getPasskeys(current.username);
+  if (updates.passwordlessOnly && userPasskeys.length === 0) {
+    throw new Error('Register at least one passkey before enabling Passwordless-Only sign-in.');
+  }
+
+  const updatedUser: UserAccount = {
+    ...current,
+    passwordlessOnly:
+      updates.passwordlessOnly !== undefined
+        ? updates.passwordlessOnly
+        : current.passwordlessOnly,
+    requireReauthForSensitive:
+      updates.requireReauthForSensitive !== undefined
+        ? updates.requireReauthForSensitive
+        : current.requireReauthForSensitive,
+    hasPassword:
+      updates.hasPassword !== undefined ? updates.hasPassword : current.hasPassword,
+    apiKey: updates.regenerateApiKey
+      ? `dtt_live_${generateRandomChallenge(12).toLowerCase()}`
+      : current.apiKey,
+  };
+
+  if (idx >= 0) {
+    users[idx] = updatedUser;
+  } else {
+    users.push(updatedUser);
+  }
+  saveUsers(users);
+
+  saveSession({
+    ...session,
+    user: updatedUser,
+  });
+
+  await callPasskeyApi({
+    action: 'update-security',
+    user: updatedUser,
+  });
+
+  return updatedUser;
+}

