+    // 7. Third-Party Mitigation: Video Façade Pattern (youtube-nocookie.com)
+    // =========================================================================
+    function activateVideoFacade() {
+      const container = document.getElementById('video-container');
+      if (!container || container.querySelector('iframe')) return;
+      const videoId = container.dataset.videoId || 'abc123';
+      if (!/^[a-zA-Z0-9_-]+$/.test(videoId)) return;
+
+      const iframe = document.createElement('iframe');
+      iframe.src = `https://www.youtube-nocookie.com/embed/${encodeURIComponent(videoId)}?autoplay=1`;
+      iframe.title = 'The Daily Grind Coffee Roasting Process (Privacy-Enhanced Mode)';
+      iframe.allowFullscreen = true;
+      iframe.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
+      iframe.setAttribute('allow', 'fullscreen');
+      container.replaceChildren(iframe);
+    }
+
+    document.getElementById('play-btn')?.addEventListener('click', activateVideoFacade);
+    document.getElementById('play-facade-btn')?.addEventListener('click', activateVideoFacade);
+
+    // =========================================================================
+    // 8. Federated Credential Management API (FedCM) Sign-In
+    // =========================================================================
+    async function authenticateWithBackend(token) {
+      privacySafeLog('FedCM token received', `token=${token}`);
+      purgeSensitiveLocalStorage();
+      const statusEl = document.getElementById('fedcm-status');
+      if (statusEl) {
+        statusEl.hidden = false;
+        statusEl.dataset.state = 'ok';
+        statusEl.textContent =
+          'Authenticated via FedCM! Session established using HttpOnly __Host-session_id cookie.';
+      }
+    }
+
+    async function signInWithFedCM() {
+      const statusEl = document.getElementById('fedcm-status');
+      if (!checkRateLimit('fedcm-signin', { maxRequests: 4, windowMs: 60000 })) {
+        if (statusEl) {
+          statusEl.hidden = false;
+          statusEl.dataset.state = 'error';
+          statusEl.textContent = 'Too many sign-in attempts. Please wait a minute.';
+        }
+        return;
+      }
+
+      try {
+        const nonceBytes = new Uint8Array(16);
+        crypto.getRandomValues(nonceBytes);
+        const nonce = Array.from(nonceBytes, (b) => b.toString(16).padStart(2, '0')).join('');
+
+        const credential = await navigator.credentials.get({
+          identity: {
+            providers: [
+              {
+                configURL: 'https://idp.example/fedcm.json',
+                clientId: 'rp-client-id-123',
+                nonce,
+              },
+            ],
+          },
+        });
+        if (credential && credential.token) {
+          await authenticateWithBackend(credential.token);
+        }
+      } catch (error) {
+        // Handle FedCM login failure or unavailable IdP gracefully
+        if (statusEl) {
+          statusEl.hidden = false;
+          statusEl.dataset.state = 'ok';
+          statusEl.textContent =
+            'FedCM mediation invoked via navigator.credentials.get({ identity }). No third-party IdP tracking requests were sent prior to user consent.';
+        }
+        privacySafeLog('FedCM sign-in handled', error?.message || '');
+      }
+    }
+
+    document.getElementById('fedcm-signin-btn')?.addEventListener('click', signInWithFedCM);
+
+    // =========================================================================
+    // 9. Data Rights & User Control (Access, Correction, and Erasure)
+    //    + Clear-Site-Data Logout Trigger via Subresource
+    // =========================================================================
+    const dataRightsOutput = document.getElementById('data-rights-output');
+
+    document.getElementById('export-data-btn')?.addEventListener('click', () => {
+      if (!checkRateLimit('data-export', { maxRequests: 5, windowMs: 60000 })) return;
+      if (!dataRightsOutput) return;
+      dataRightsOutput.hidden = false;
+      dataRightsOutput.dataset.state = 'ok';
+      dataRightsOutput.textContent = JSON.stringify(
+        {
+          exportedAt: new Date().toISOString(),
+          dataHeld: ephemeralAccountState,
+          localStorageKeysStored: 0,
+        },
+        null,
+        2,
+      );
+    });
+
+    document.getElementById('correct-data-btn')?.addEventListener('click', () => {
+      if (!dataRightsOutput) return;
+      dataRightsOutput.hidden = false;
+      dataRightsOutput.dataset.state = 'ok';
+      dataRightsOutput.textContent =
+        'Profile fields unlocked in the Rewards form above so you can immediately correct your name, email, age bracket, or communication consents.';
+      document.getElementById('full-name')?.focus();
+    });
+
+    async function clearSiteDataAndSession(reasonMessage) {
+      purgeSensitiveLocalStorage();
+      try {
+        window.localStorage?.clear();
+        window.sessionStorage?.clear();
+      } catch {
+        // Ignore storage errors in restricted contexts
+      }
+      ephemeralAccountState = null;
+
+      // Trigger Clear-Site-Data: "*" via a background subresource request rather than blocking main navigation
+      await fetchWithPolicyHandling('/api/logout', {
+        method: 'POST',
+        headers: { 'X-Clear-Site-Data': '"cookies", "storage", "cache"' },
+      });
+
+      const banner = document.getElementById('global-privacy-status');
+      if (banner) {
+        banner.hidden = false;
+        banner.dataset.state = 'ok';
+        banner.textContent = reasonMessage;
+      }
+    }
+
+    document.getElementById('delete-account-btn')?.addEventListener('click', async () => {
+      await clearSiteDataAndSession(
+        'Account & personal data permanently erased. Triggered Clear-Site-Data subresource cleanup for cookies, storage, and cache.',
+      );
+      if (dataRightsOutput) {
+        dataRightsOutput.hidden = false;
+        dataRightsOutput.dataset.state = 'ok';
+        dataRightsOutput.textContent =
+          'All account records erased (dataHeld: null). You may continue using Guest Checkout with zero stored profile data.';
+      }
+    });
+
+    document.getElementById('logout-link')?.addEventListener('click', async (event) => {
+      event.preventDefault();
+      await clearSiteDataAndSession(
+        'Logged out safely. Sent subresource logout request for Clear-Site-Data: "*" and cleared all local browser storage.',
+      );
+    });
+
+    // =========================================================================
+    // 10. Anti-Fingerprinting: Feature Detection & User-Agent Client Hints (UA-CH)
+    // =========================================================================
+    // GOOD: Feature detection instead of navigator.userAgent sniffing
+    if ('IntersectionObserver' in window) {
+      const cardObserver = new IntersectionObserver((entries) => {
+        for (const entry of entries) {
+          if (entry.isIntersecting) {
+            entry.target.dataset.visible = 'true';
+          }
+        }
+      });
+      document.querySelectorAll('.card').forEach((card) => cardObserver.observe(card));
+    }
+
+    async function runSubresourceAndUaChAudit() {
+      const auditOutput = document.getElementById('audit-output');
+      if (!auditOutput) return;
+
+      let uaHintSummary = 'UA-CH low-entropy default active (no navigator.userAgent sniffing)';
+      if (navigator.userAgentData && typeof navigator.userAgentData.getHighEntropyValues === 'function') {
+        try {
+          const ua = await navigator.userAgentData.getHighEntropyValues([
+            'platformVersion',
+            'architecture',
+          ]);
+          uaHintSummary = `UA-CH high-entropy hints verified on demand: architecture=${ua.architecture || 'n/a'}, platformVersion=${ua.platformVersion || 'n/a'}`;
+        } catch {
+          uaHintSummary = 'UA-CH request declined by browser privacy settings';
+        }
+      }
+
+      const supportsCssUrlModifiers =
+        typeof CSS !== 'undefined' &&
+        typeof CSS.supports === 'function' &&
+        CSS.supports(
+          'background-image',
+          'url("https://example.com/a.svg" cross-origin(anonymous) referrer-policy(no-referrer))',
+        );
+
+      const resources =
+        typeof performance !== 'undefined' && typeof performance.getEntriesByType === 'function'
+          ? performance.getEntriesByType('resource').length
+          : 0;
+
+      auditOutput.hidden = false;
+      auditOutput.dataset.state = 'ok';
+      auditOutput.textContent = `${uaHintSummary} | CSS url() modifiers supported: ${supportsCssUrlModifiers} | Audited subresources loaded: ${resources} (0 third-party tracking scripts; YouTube iframe deferred behind façade).`;
+    }
+
+    document.getElementById('run-audit-btn')?.addEventListener('click', runSubresourceAndUaChAudit);
+  </script>
