@@ -0,0 +1,214 @@
+/**
+ * Privacy-by-Design & Web Security Server Middleware Helpers for The Daily Grind
+ * Implements:
+ * - Privacy-preserving headers (Referrer-Policy, Permissions-Policy, Clear-Site-Data)
+ * - Hardened cookies (__Host- session cookies and Partitioned CHIPS cookies)
+ * - Nonce-based Content-Security-Policy with 'strict-dynamic' and Trusted Types
+ * - Connection-Allowlist (RFC 9651 Inner List) for outbound network restriction
+ * - Fetch Metadata (Sec-Fetch-*) resource isolation and rate limiting
+ * - Build-time Subresource Integrity (SHA-384) digest helper
+ */
+
+const ALLOWLIST_DESTS = new Set([
+  'document',
+  'iframe',
+  'worker',
+  'sharedworker',
+  'serviceworker',
+]);
+
+/**
+ * Normalize a config URL or URLPattern string for Connection-Allowlist:
+ * - Rewrites ws:// and wss:// to http:// and https://
+ * - Strips a bare trailing slash on origin-only URLs so all subpaths are permitted
+ */
+export function normalizeAllowlistPattern(rawPattern) {
+  const trimmed = String(rawPattern)
+    .trim()
+    .replace(/^ws(s?):\/\//i, 'http$1://');
+  if (!/^https?:\/\//i.test(trimmed)) {
+    throw new Error(
+      `Pattern must include an http:// or https:// scheme: ${rawPattern}`,
+    );
+  }
+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(
+      `Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`,
+    );
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(
+      `Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`,
+    );
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+/**
+ * Build an RFC 9651 Inner List value for Connection-Allowlist or Connection-Allowlist-Report-Only.
+ */
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = [],
+  reportTo,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+/**
+ * Generate a cryptographic per-request CSP nonce.
+ */
+export function generateCspNonce() {
+  const bytes = new Uint8Array(16);
+  crypto.getRandomValues(bytes);
+  return btoa(String.fromCharCode(...bytes));
+}
+
+/**
+ * Compute a sha384- Subresource Integrity string from known-good local bytes at build time.
+ */
+export async function computeIntegrityMetadata(bytes) {
+  const rawBytes =
+    typeof bytes === 'string' ? new TextEncoder().encode(bytes) : bytes;
+  const digestBuffer = await crypto.subtle.digest('SHA-384', rawBytes);
+  const binary = Array.from(new Uint8Array(digestBuffer), (b) =>
+    String.fromCharCode(b),
+  ).join('');
+  return `sha384-${btoa(binary)}`;
+}
+
+/**
+ * Build hardened Set-Cookie header values (__Host- session cookie & Partitioned CHIPS cookie).
+ */
+export function buildPrivacyCookies({ sessionId, themePref = 'light' } = {}) {
+  const cookies = [];
+  if (sessionId) {
+    cookies.push(
+      `__Host-session_id=${encodeURIComponent(sessionId)}; SameSite=Lax; HttpOnly; Secure; Path=/`,
+    );
+  }
+  if (themePref) {
+    cookies.push(
+      `theme_pref=${encodeURIComponent(themePref)}; SameSite=None; Secure; Path=/; Partitioned; HttpOnly`,
+    );
+  }
+  return cookies;
+}
+
+/**
+ * Apply privacy-preserving and preventative security headers to a server response.
+ */
+export function setPrivacyAndSecurityHeaders(res, options = {}) {
+  const {
+    nonce = generateCspNonce(),
+    secFetchDest = 'document',
+    allowlistPatterns = [
+      'https://images.unsplash.com/*',
+      'https://img.youtube.com/*',
+      'https://www.youtube-nocookie.com/*',
+      'https://idp.example/*',
+    ],
+    reportEndpointUrl = 'https://reports.dailygrind.example/main',
+    connReportEndpointUrl = 'https://reports.dailygrind.example/connections',
+  } = options;
+
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function'
+      ? res.setHeader(name, value)
+      : res.headers.set(name, value);
+
+  // Privacy-Preserving Headers
+  setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  setHeader(
+    'Permissions-Policy',
+    'geolocation=(), camera=(), microphone=(), accelerometer=()',
+  );
+
+  // Core & Companion Security Headers
+  setHeader(
+    'Strict-Transport-Security',
+    'max-age=31536000; includeSubDomains; preload',
+  );
+  setHeader('X-Content-Type-Options', 'nosniff');
+  setHeader('X-Frame-Options', 'DENY');
+  setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+  setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+
+  // Violation Reporting Endpoints
+  setHeader(
+    'Reporting-Endpoints',
+    `default="${reportEndpointUrl}", main-endpoint="${reportEndpointUrl}", conn-reports="${connReportEndpointUrl}"`,
+  );
+
+  // Enforced CSP with Nonce, 'strict-dynamic', and Trusted Types
+  const csp = [
+    `script-src 'nonce-${nonce}' 'strict-dynamic' 'report-sample'`,
+    "style-src 'self' 'unsafe-inline'",
+    "img-src 'self' https://images.unsplash.com https://img.youtube.com data:",
+    'frame-src https://www.youtube-nocookie.com',
+    "connect-src 'self' https://idp.example",
+    "form-action 'self'",
+    "worker-src 'self'",
+    "object-src 'none'",
+    "base-uri 'none'",
+    "frame-ancestors 'none'",
+    "require-trusted-types-for 'script'",
+    'trusted-types app-html escape-html sanitize-html dompurify default',
+    'report-to main-endpoint',
+  ].join('; ');
+  setHeader('Content-Security-Policy', csp);
+
+  // Connection-Allowlist for document and worker destinations
+  if (
+    !secFetchDest ||
+    ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())
+  ) {
+    setHeader(
+      'Connection-Allowlist',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: allowlistPatterns,
+        reportTo: 'conn-reports',
+      }),
+    );
+  }
+
+  return { nonce, csp };
+}
+
+/**
+ * Send Clear-Site-Data on logout subresource endpoint to wipe cookies, storage, and cache.
+ */
+export function setLogoutClearSiteDataHeaders(res) {
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function'
+      ? res.setHeader(name, value)
+      : res.headers.set(name, value);
+
+  setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+  setHeader(
+    'Set-Cookie',
+    '__Host-session_id=; Max-Age=0; SameSite=Lax; HttpOnly; Secure; Path=/',
+  );
+  setHeader('Cache-Control', 'no-store, max-age=0');
+}

