+/**
+ * The Daily Grind — Privacy by Design Client-Side Architecture
+ * Implements:
+ * 1. Data Minimization & Purpose Limitation
+ * 2. Ephemeral Storage with TTL Auto-Expiration (PrivacyStorage)
+ * 3. PII Masking, SHA-256 Hashing & Input Sanitization
+ * 4. URL Tracking Parameter & Sensitive Query Stripping
+ * 5. Global Privacy Control (GPC) & Do Not Track (DNT) Detection
+ * 6. Live Third-Party Resource & DOM Security Auditor + MutationObserver Guard
+ * 7. Data Subject Rights (Export / Portability, Purge Expired, Complete Erasure)
+ * 8. Secure Logout with Full Client-Side Storage & Cookie Wipe
+ */
+(function () {
+  'use strict';
+
+  if (window.__DG_PRIVACY_INITIALIZED__) return;
+  window.__DG_PRIVACY_INITIALIZED__ = true;
+
+  const ALLOWED_THIRD_PARTY_HOSTS = new Set(['images.unsplash.com']);
+  const TRACKING_PARAMS = [
+    'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
+    'fbclid', 'gclid', 'msclkid', 'twclid', 'mc_cid', 'mc_eid', '_ga', '_gl',
+    'ref', 'affiliate_id', 'session_token', 'auth_token', 'email', 'phone'
+  ];
+
+  const STORAGE_KEYS = {
+    CONSENT: 'dg_privacy_consent_v1',
+    ORDER: 'dg_ephemeral_order_v1',
+    REWARDS: 'dg_minimized_rewards_v1',
+    AUDIT_LOG: 'dg_privacy_audit_log_v1'
+  };
+
+  const DEFAULT_TTL_MS = {
+    ORDER: 30 * 60 * 1000,      // 30 minutes for active coffee order pickup
+    REWARDS: 24 * 60 * 60 * 1000, // 24 hours local cache for minimized membership hash
+    CONSENT: 30 * 24 * 60 * 60 * 1000 // 30 days for explicit opt-in settings
+  };
+
+  /**
+   * Sanitizes user text input to prevent XSS and strip control characters.
+   */
+  function sanitizeInput(value, maxLength = 64) {
+    if (typeof value !== 'string') return '';
+    return value
+      .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
+      .replace(/[<>'"&`]/g, '')
+      .trim()
+      .slice(0, maxLength);
+  }
+
+  /**
+   * Masks an email address so raw PII is never stored or displayed in cleartext.
+   * Example: "alice.smith@example.com" -> "a***h@example.com"
