--- /dev/null
+++ b/src/pages/api/logout.ts
@@ -0,0 +1,25 @@
+import type { APIRoute } from 'astro';
+
+const clearSessionAndSiteData: APIRoute = async ({ session }) => {
+  if (session) {
+    session.destroy();
+  }
+
+  return new Response(
+    JSON.stringify({
+      cleared: true,
+      message: 'Session terminated and browser site data cleared.',
+    }),
+    {
+      status: 200,
+      headers: {
+        'Content-Type': 'application/json',
+        'Clear-Site-Data': '"cookies", "storage", "cache"',
+        'Cache-Control': 'no-store, max-age=0',
+      },
+    },
+  );
+};
+
+export const POST = clearSessionAndSiteData;
+export const GET = clearSessionAndSiteData;
