diff --git a/src/components/PrivacyConsent.tsx b/src/components/PrivacyConsent.tsx
new file mode 100644
index 0000000..a7a6767
--- /dev/null
+++ b/src/components/PrivacyConsent.tsx
@@ -0,0 +1,256 @@
+import React, { useEffect, useState } from 'react';
+import {
+  getStoredPrivacyPreferences,
+  hasBrowserPrivacySignal,
+  OPEN_PRIVACY_MODAL_EVENT,
+  PRIVACY_CHANGED_EVENT,
+  savePrivacyPreferences,
+  syncThirdPartyScripts,
+} from '../utils/privacy';
+
+interface Props {
+  baseUrl?: string;
+}
+
+export default function PrivacyConsent({ baseUrl = '/devtools-times/' }: Props) {
+  const [showBanner, setShowBanner] = useState(false);
+  const [showModal, setShowModal] = useState(false);
+  const [analyticsEnabled, setAnalyticsEnabled] = useState(false);
+  const [advertisingEnabled, setAdvertisingEnabled] = useState(false);
+  const [gpcOrDntActive, setGpcOrDntActive] = useState(false);
+
+  useEffect(() => {
+    const signalActive = hasBrowserPrivacySignal();
+    setGpcOrDntActive(signalActive);
+
+    const stored = getStoredPrivacyPreferences();
+    if (!stored) {
+      setAnalyticsEnabled(false);
+      setAdvertisingEnabled(false);
+      setShowBanner(true);
+    } else {
+      setAnalyticsEnabled(stored.analytics);
+      setAdvertisingEnabled(stored.advertising);
+      setShowBanner(false);
+    }
+
+    syncThirdPartyScripts(stored ?? undefined);
+
+    const handleOpenModal = () => {
+      const current = getStoredPrivacyPreferences();
+      setAnalyticsEnabled(current?.analytics ?? false);
+      setAdvertisingEnabled(current?.advertising ?? false);
+      setShowModal(true);
+    };
+
+    const handleConsentChanged = () => {
+      const current = getStoredPrivacyPreferences();
+      if (current) {
+        setAnalyticsEnabled(current.analytics);
+        setAdvertisingEnabled(current.advertising);
+      }
+    };
+
+    window.addEventListener(OPEN_PRIVACY_MODAL_EVENT, handleOpenModal);
+    window.addEventListener(PRIVACY_CHANGED_EVENT, handleConsentChanged);
+
+    return () => {
+      window.removeEventListener(OPEN_PRIVACY_MODAL_EVENT, handleOpenModal);
+      window.removeEventListener(PRIVACY_CHANGED_EVENT, handleConsentChanged);
+    };
+  }, []);
+
+  const handleEssentialOnly = () => {
+    savePrivacyPreferences({ analytics: false, advertising: false });
+    setAnalyticsEnabled(false);
+    setAdvertisingEnabled(false);
+    setShowBanner(false);
+    setShowModal(false);
+  };
+
+  const handleSaveCustom = (e: React.FormEvent) => {
+    e.preventDefault();
+    savePrivacyPreferences({
+      analytics: analyticsEnabled,
+      advertising: advertisingEnabled,
+    });
+    setShowBanner(false);
+    setShowModal(false);
+  };
+
+  const handleAcceptAll = () => {
+    savePrivacyPreferences({ analytics: true, advertising: true });
+    setAnalyticsEnabled(!gpcOrDntActive);
+    setAdvertisingEnabled(!gpcOrDntActive);
+    setShowBanner(false);
+    setShowModal(false);
+  };
+
+  const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+
+  return (
+    <>
+      {showBanner && !showModal && (
+        <aside
+          role="region"
+          aria-label="Privacy and data preferences"
+          data-skip-tracking="true"
+          className="fixed bottom-0 inset-x-0 z-50 bg-white border-t-2 border-gray-900 shadow-lg p-4 md:p-6"
+        >
+          <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
+            <div className="text-sm text-gray-700 space-y-1 max-w-3xl">
+              <p className="font-bold text-gray-900">
+                Privacy by Default &amp; Data Minimization
+              </p>
+              <p>
+                We collect only what is strictly necessary to deliver The DevTools Times. Non-essential third-party analytics and advertising scripts are{' '}
+                <strong>disabled by default</strong> and never run unless you explicitly opt in. Read our{' '}
+                <a
+                  href={`${normalizedBase}legal/privacy`}
+                  className="underline font-medium text-gray-900 hover:text-amber-700"
+                >
+                  Privacy Policy
+                </a>{' '}
+                for full details.
+              </p>
+              {gpcOrDntActive && (
+                <p className="text-xs text-green-800 bg-green-50 border border-green-200 rounded px-2 py-1 inline-block">
