index 0000000..2c7dcd4
--- /dev/null
+++ b/src/utils/privacy.ts
@@ -0,0 +1,159 @@
+export interface PrivacyPreferences {
+  essential: true;
+  analytics: boolean;
+  advertising: boolean;
+  updatedAt: string;
+}
+
+export const PRIVACY_STORAGE_KEY = 'dtt_privacy_consent';
+export const PRIVACY_CHANGED_EVENT = 'dtt:privacy-consent-updated';
+export const OPEN_PRIVACY_MODAL_EVENT = 'dtt:open-privacy-preferences';
+
+export const DEFAULT_PRIVACY_PREFERENCES: PrivacyPreferences = {
+  essential: true,
+  analytics: false,
+  advertising: false,
+  updatedAt: '',
+};
+
+/**
+ * Checks whether the user's browser sends Global Privacy Control (GPC)
+ * or Do Not Track (DNT) signals.
+ */
+export function hasBrowserPrivacySignal(): boolean {
+  if (typeof window === 'undefined' || typeof navigator === 'undefined') {
+    return false;
+  }
+  const nav = navigator as Navigator & {
+    globalPrivacyControl?: boolean;
+    msDoNotTrack?: string;
+  };
+  const win = window as Window & { doNotTrack?: string };
+
+  return (
+    nav.globalPrivacyControl === true ||
+    nav.doNotTrack === '1' ||
+    nav.doNotTrack === 'yes' ||
+    nav.msDoNotTrack === '1' ||
+    win.doNotTrack === '1'
+  );
+}
+
+/**
+ * Reads saved privacy preferences from localStorage.
+ * Returns null if the user has not yet made an explicit choice.
+ * Always enforces opt-out when GPC/DNT is active.
+ */
+export function getStoredPrivacyPreferences(): PrivacyPreferences | null {
+  if (typeof window === 'undefined') {
+    return null;
+  }
+
+  try {
+    const raw = window.localStorage.getItem(PRIVACY_STORAGE_KEY);
+    if (!raw) {
+      return null;
+    }
+    const parsed = JSON.parse(raw) as Partial<PrivacyPreferences>;
+    const signalActive = hasBrowserPrivacySignal();
+
+    return {
+      essential: true,
+      analytics: signalActive ? false : Boolean(parsed.analytics),
+      advertising: signalActive ? false : Boolean(parsed.advertising),
+      updatedAt: typeof parsed.updatedAt === 'string' ? parsed.updatedAt : '',
+    };
+  } catch {
+    return null;
+  }
+}
+
+/**
+ * Returns the effective privacy preferences (defaults to all non-essential disabled).
+ */
+export function getEffectivePrivacyPreferences(): PrivacyPreferences {
+  return getStoredPrivacyPreferences() ?? DEFAULT_PRIVACY_PREFERENCES;
+}
+
+/**
+ * Saves the user's explicit privacy preferences and notifies listeners.
+ */
+export function savePrivacyPreferences(
+  prefs: Pick<PrivacyPreferences, 'analytics' | 'advertising'>
+): PrivacyPreferences {
+  const signalActive = hasBrowserPrivacySignal();
+  const normalized: PrivacyPreferences = {
+    essential: true,
+    analytics: signalActive ? false : Boolean(prefs.analytics),
+    advertising: signalActive ? false : Boolean(prefs.advertising),
+    updatedAt: new Date().toISOString(),
+  };
+
+  if (typeof window !== 'undefined') {
+    try {
+      window.localStorage.setItem(PRIVACY_STORAGE_KEY, JSON.stringify(normalized));
+    } catch {
+      // Ignore storage errors in private browsing modes
+    }
+    syncThirdPartyScripts(normalized);
+    window.dispatchEvent(
+      new CustomEvent<PrivacyPreferences>(PRIVACY_CHANGED_EVENT, {
+        detail: normalized,
+      })
+    );
+  }
+
+  return normalized;
+}
+
+/**
+ * Dynamically activates or removes third-party scripts based on explicit user consent.
+ * Scripts are never loaded on authentication pages (/signin, /signup) or without opt-in.
+ */
+export function syncThirdPartyScripts(prefs?: PrivacyPreferences): void {
+  if (typeof window === 'undefined' || typeof document === 'undefined') {
+    return;
+  }
+
+  const effective = prefs ?? getEffectivePrivacyPreferences();
+  const pathname = window.location.pathname;
+  const isSensitiveAuthPage =
+    pathname.endsWith('/signin') ||
+    pathname.endsWith('/signin/') ||
+    pathname.endsWith('/signup') ||
+    pathname.endsWith('/signup/');
+
+  const categories: Array<'analytics' | 'advertising'> = ['analytics', 'advertising'];
+
+  for (const category of categories) {
+    const allowed = !isSensitiveAuthPage && !hasBrowserPrivacySignal() && effective[category];
+    const activeScriptId = `dtt-active-script-${category}`;
+    const existingActive = document.getElementById(activeScriptId);
+
+    if (allowed) {
+      if (!existingActive) {
+        const placeholder = document.querySelector<HTMLScriptElement>(
+          `script[type="text/plain"][data-consent="${category}"][data-src]`
+        );
+        const src = placeholder?.getAttribute('data-src');
+        if (src) {
+          const script = document.createElement('script');
+          script.id = activeScriptId;
+          script.src = src;
+          script.defer = true;
+          script.crossOrigin = 'anonymous';
+          script.referrerPolicy = 'no-referrer';
+          script.setAttribute('data-loaded-by-consent', category);
+          document.head.appendChild(script);
+        }
+      }
+    } else {
+      if (existingActive) {
+        existingActive.remove();
+      }
+      if (category === 'advertising') {
+        window.adNetwork = [];
+      }
+    }
+  }
+}

