+      var milestones = document.querySelectorAll('#primary-milestones .milestone');
+
+      function updateMilestones(val, mode) {
+        var thresholds = [25, 50, 75, 100];
+        milestones.forEach(function (el, idx) {
+          el.classList.remove('completed', 'current');
+          if (mode === 'indeterminate') {
+            if (idx === 2) el.classList.add('current');
+            return;
+          }
+          if (val >= thresholds[idx]) {
+            if (idx === thresholds.length - 1 || val >= thresholds[idx + 1]) {
+              el.classList.add('completed');
+            } else {
+              el.classList.add('current');
+            }
+          }
+        });
+      }
+
+      function renderProgress() {
+        if (currentMode === 'indeterminate') {
