+          badge.classList.add('indeterminate-badge');
+          status.textContent = 'Syncing order preparation with barista queue and verifying reward balance...';
+
+          btnInd.classList.add('active');
+          btnDet.classList.remove('active');
+        } else {
+          bar.classList.remove('indeterminate');
+          bar.classList.add('determinate');
+          bar.setAttribute('data-state', 'determinate');
+          bar.setAttribute('aria-valuenow', String(currentProgress));
+          bar.removeAttribute('aria-busy');
+          bar.setAttribute('aria-valuetext', currentProgress + '% complete - ' + currentProgress + ' of 100 reward beans earned');
+
+          progressEl.classList.remove('indeterminate');
+          progressEl.classList.add('determinate');
+          progressEl.setAttribute('value', String(currentProgress));
+          progressEl.value = currentProgress;
+          progressEl.textContent = currentProgress + '%';
+
+          fill.classList.remove('indeterminate');
+          fill.classList.add('determinate');
+          fill.style.width = currentProgress + '%';
+
+          badge.textContent = currentProgress + '% Complete (' + currentProgress + ' / 100 Beans)';
+          badge.classList.remove('indeterminate-badge');
+
+          if (currentProgress >= 100) {
+            status.textContent = 'Reward complete! Your free handcrafted artisanal drink and order are ready for pickup.';
+          } else {
+            status.textContent = 'Earn ' + (100 - currentProgress) + ' more Bean Points to unlock a complimentary seasonal beverage.';
+          }
+
+          btnDet.textContent = 'Determinate (' + currentProgress + '%)';
+          btnDet.classList.add('active');
+          btnInd.classList.remove('active');
+        }
+        updateMilestones(currentProgress, currentMode);
