+        emailInput.addEventListener('blur', () => {
+          if (emailInput.value.trim().length > 0 && !emailInput.checkValidity()) {
+            emailInput.setAttribute('aria-invalid', 'true');
+            showStatus(getValidationMessage(emailInput), 'error');
+          }
+        });
+      }
+
+      if (form && emailInput) {
+        form.addEventListener('submit', async (event) => {
+          event.preventDefault();
+          emailInput.setCustomValidity('');
+
+          if (!emailInput.checkValidity()) {
+            emailInput.setAttribute('aria-invalid', 'true');
+            showStatus(getValidationMessage(emailInput), 'error');
+            emailInput.focus();
+            return;
+          }
+
+          emailInput.removeAttribute('aria-invalid');
+          if (submitBtn) submitBtn.disabled = true;
+
+          const endpoint = form.getAttribute('action') || '/api/newsletter';
+          const result = await fetchWithPolicyHandling(endpoint, {
+            method: 'POST',
+            headers: {
+              'Content-Type': 'application/json',
+              Accept: 'application/json',
+            },
+            body: JSON.stringify({ email: emailInput.value.trim() }),
+            statusElement: statusEl,
+          });
+
+          if (submitBtn) submitBtn.disabled = false;
+          if (result.ok) {
+            form.reset();
+          }
+        });
+      }
+    })();
+  </script>
+
