+
+function getPort() {
+  const portFlagIndex = process.argv.findIndex(
+    (arg) => arg === '--port' || arg === '-p'
+  );
+  if (portFlagIndex !== -1 && process.argv[portFlagIndex + 1]) {
+    const parsed = Number(process.argv[portFlagIndex + 1]);
+    if (!Number.isNaN(parsed) && parsed > 0) {
+      return parsed;
+    }
+  }
+  return Number(process.env.PORT) || 11222;
+}
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_POLICY);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+}
+
+function sendJson(res, statusCode, payload) {
+  setSecurityHeaders(res);
+  res.writeHead(statusCode, {
+    'Content-Type': 'application/json; charset=utf-8'
+  });
+  res.end(JSON.stringify(payload));
+}
+
+function parseEmailFromBody(rawBody, contentType) {
+  const trimmed = (rawBody || '').trim();
+  if (!trimmed) return '';
+
+  if (contentType.includes('application/json')) {
+    try {
+      const parsed = JSON.parse(trimmed);
+      if (typeof parsed === 'string') return parsed.trim();
+      if (parsed && typeof parsed.email === 'string') return parsed.email.trim();
+    } catch {
+      return '';
+    }
+  }
+
+  if (contentType.includes('application/x-www-form-urlencoded')) {
+    const params = new URLSearchParams(trimmed);
+    return (params.get('email') || '').trim();
+  }
+
+  try {
+    const parsed = JSON.parse(trimmed);
+    if (parsed && typeof parsed.email === 'string') return parsed.email.trim();
+  } catch {
+    const params = new URLSearchParams(trimmed);
+    if (params.has('email')) return (params.get('email') || '').trim();
+  }
+
+  return trimmed;
+}
+
+function isValidEmail(email) {
+  return typeof email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+}
+
+const NEWSLETTER_PATHS = new Set([
+  '/newsletter',
+  '/api/newsletter',
+  '/subscribe',
+  '/api/subscribe'
+]);
+
+const server = http.createServer((req, res) => {
+  setSecurityHeaders(res);
+
+  const reqUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = reqUrl.pathname;
+
+  if (req.method === 'POST' && (NEWSLETTER_PATHS.has(pathname) || pathname === '/')) {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString();
+      if (body.length > 1e6) {
+        req.destroy();
+      }
+    });
+
+    req.on('end', () => {
+      const contentType = (req.headers['content-type'] || '').toLowerCase();
+      const email = parseEmailFromBody(body, contentType);
+
+      if (!isValidEmail(email)) {
+        sendJson(res, 400, {
+          ok: false,
+          error: 'Please provide a valid email address.'
+        });
+        return;
+      }
+
+      subscribers.push({
+        email,
+        subscribedAt: new Date().toISOString()
+      });
+
+      sendJson(res, 200, {
+        ok: true,
+        email,
+        message: 'Thank you for subscribing to The Daily Grind newsletter!'
+      });
+    });
+    return;
+  }
+
+  if (req.method === 'GET' && NEWSLETTER_PATHS.has(pathname)) {
+    sendJson(res, 200, {
+      ok: true,
+      subscribers
+    });
+    return;
+  }
+
+  if (req.method === 'GET' && pathname === '/favicon.ico') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    sendJson(res, 405, {
+      ok: false,
+      error: 'Method not allowed.'
+    });
+    return;
+  }
+
+  const relativePath = pathname === '/' ? '/index.html' : pathname;
+  const safePath = path.normalize(relativePath).replace(/^(\.\.[/\\])+/, '');
+  const filePath = path.join(PUBLIC_DIR, safePath);
+
+  if (!filePath.startsWith(PUBLIC_DIR)) {
+    sendJson(res, 403, { ok: false, error: 'Forbidden' });
+    return;
+  }
+
+  fs.readFile(filePath, (err, content) => {
+    if (err) {
+      if (err.code === 'ENOENT') {
+        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+        res.end('Not Found');
+        return;
+      }
+      res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Internal Server Error');
+      return;
+    }
+
+    const ext = path.extname(filePath).toLowerCase();
+    const mimeType = MIME_TYPES[ext] || 'application/octet-stream';
+    res.writeHead(200, { 'Content-Type': mimeType });
+    if (req.method === 'HEAD') {
+      res.end();
+    } else {
+      res.end(content);
+    }
+  });
+});
+
+if (require.main === module) {
+  const port = getPort();
+  server.listen(port, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${port}`);
+  });
+}
+
+module.exports = { server, CSP_POLICY };

