@@ -0,0 +1,55 @@
+import type { APIRoute } from 'astro';
+import { extractHostDomain, formatOriginBoundSms, generateSixDigitOtp } from '../../utils/smsOtp';
+
+// Fallback in-memory OTP store keyed by normalized phone number
+export const otpStore = new Map<string, { code: string; expiresAt: number }>();
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const contentType = request.headers.get('content-type') || '';
+    let phone = '';
+    let domain = '';
+
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      phone = (body.phone || '').toString().trim();
+      domain = (body.domain || '').toString().trim();
+    } else {
+      const formData = await request.formData();
+      phone = (formData.get('phone') || '').toString().trim();
+      domain = (formData.get('domain') || '').toString().trim();
+    }
+
+    if (!phone) {
+      return new Response(
+        JSON.stringify({ error: 'Please enter a valid phone number.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const code = generateSixDigitOtp();
+    const hostDomain = extractHostDomain(domain || request.headers.get('host') || url.hostname);
+    const smsMessage = formatOriginBoundSms(hostDomain, code);
+    const expiresAt = Date.now() + 10 * 60 * 1000;
+
+    otpStore.set(phone, { code, expiresAt });
+
+    if (session) {
+      await session.set('pendingOtp', { phone, code, expiresAt });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        message: `Verification code sent to ${phone}.`,
+        smsMessage,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({ error: 'Failed to send verification code. Please try again.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
