+/**
+ * Extracts only the host domain from a hostname, origin, or URL string.
+ * Strips URL schemes (https://, http://), ports (:8080), paths (/verify), and whitespace.
+ */
+export function extractHostDomain(input: string): string {
+  const trimmed = (input || '').trim();
+  if (!trimmed) {
+    return 'example.com';
+  }
+
+  try {
+    if (trimmed.includes('://')) {
+      const parsed = new URL(trimmed);
+      return parsed.hostname;
+    }
+    const parsed = new URL(`https://${trimmed}`);
+    return parsed.hostname;
+  } catch {
+    return trimmed
+      .replace(/^https?:\/\//i, '')
+      .split('/')[0]
+      .split(':')[0]
+      .replace(/\s+/g, '');
+  }
+}
+
+/**
+ * Formats an origin-bound SMS OTP message for WebOTP API and autocomplete="one-time-code".
+ *
+ * Formatting rules enforced:
+ * 1. Starts with human-readable text containing the verification code.
+ * 2. Places `@<domain> #<otp>` (or `@<topDomain> #<otp> @<iframeDomain>`) on the very last line.
+ * 3. Uses only the host domain (no scheme, port, or path).
+ * 4. Separates tokens with a single space and includes no trailing lines or whitespace.
+ */
+export function formatOriginBoundSms(
+  domainInput: string,
+  otpCode: string,
+  iframeDomainInput?: string
+): string {
+  const hostDomain = extractHostDomain(domainInput);
+  const cleanCode = otpCode.trim().replace(/\s+/g, '');
+  const bindingLine = iframeDomainInput
+    ? `@${hostDomain} #${cleanCode} @${extractHostDomain(iframeDomainInput)}`
+    : `@${hostDomain} #${cleanCode}`;
+
+  return `Your verification code is ${cleanCode}.\n\n${bindingLine}`;
+}
+
+/**
+ * Generates a cryptographically random 6-digit numeric OTP string (preserving leading zeros).
+ */
+export function generateSixDigitOtp(): string {
+  const array = new Uint32Array(1);
+  crypto.getRandomValues(array);
+  const code = array[0] % 1000000;
+  return code.toString().padStart(6, '0');
+}

