+import type { APIRoute } from 'astro';
+
+const PHONE_REGEX = /^\+?[0-9\s\-().]{7,20}$/;
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const body = await request.json();
+    const phone = typeof body.phone === 'string' ? body.phone.trim() : '';
+    const digitsOnly = phone.replace(/\D/g, '');
+
+    if (!phone || !PHONE_REGEX.test(phone) || digitsOnly.length < 7 || digitsOnly.length > 15) {
+      return new Response(
+        JSON.stringify({
+          error: 'Invalid phone number. Please enter a valid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const code = '123456';
+    const host = url.hostname || 'localhost';
+    // WebOTP standard origin-bound one-time code SMS format
+    const smsMessage = `Your DevTools Times verification code is ${code}.\n\n@${host} #${code}`;
+
+    if (session) {
+      await session.set('otpVerification', {
+        phone: digitsOnly,
+        code,
+        verified: false,
+        expiresAt: Date.now() + 10 * 60 * 1000,
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        message: `Verification code sent via SMS to ${phone}.`,
+        smsMessage,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({ error: 'Failed to send verification SMS.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
