+  try {
+    const body = await request.json();
+    const phone = typeof body.phone === 'string' ? body.phone.trim() : '';
+    const otp = typeof body.otp === 'string' ? body.otp.trim() : '';
+    const digitsOnly = phone.replace(/\D/g, '');
+
+    if (!phone || digitsOnly.length < 7 || digitsOnly.length > 15) {
+      return new Response(
+        JSON.stringify({ error: 'Please provide a valid phone number.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (!OTP_REGEX.test(otp)) {
+      return new Response(
+        JSON.stringify({ error: 'Invalid passcode. Please enter the 6-digit code sent via SMS.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (session) {
+      const stored = await session.get('otpVerification');
+      if (stored && stored.expiresAt && Date.now() > stored.expiresAt) {
+        return new Response(
+          JSON.stringify({ error: 'Verification code has expired. Please request a new code.' }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+
+      await session.set('otpVerification', {
+        phone: digitsOnly,
+        code: otp,
+        verified: true,
+        verifiedAt: Date.now(),
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        verified: true,
+        message: 'Phone number verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({ error: 'Failed to verify one-time passcode.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

