+        const balanced = duration.round({
+          largestUnit: 'second',
+          smallestUnit: 'nanosecond'
+        });
+        const parts = [];
+        if (balanced.seconds) parts.push(`${balanced.seconds} s`);
+        if (balanced.milliseconds) parts.push(`${balanced.milliseconds} ms`);
+        if (balanced.microseconds) parts.push(`${balanced.microseconds} µs`);
