+      rem %= 1000000n;
+      const us = rem / 1000n;
+      const ns = rem % 1000n;
+      const parts = [];
+      if (s > 0n) parts.push(`${s} s`);
+      if (ms > 0n) parts.push(`${ms} ms`);
+      if (us > 0n) parts.push(`${us} µs`);
