+      }
+
+      connectedCallback() {
+        this.#syncAttributes();
+      }
+
+      attributeChangedCallback() {
+        if (this.isConnected) {
+          this.#syncAttributes();
+        }
+      }
+
+      #syncAttributes() {
+        const badgeEl = this.shadowRoot.querySelector('[part="badge"]');
+        const badgeSlot = this.shadowRoot.querySelector('slot[name="badge"]');
+        const priceEl = this.shadowRoot.querySelector('[part="price"]');
