+        const mediaEl = this.shadowRoot.querySelector('[part="media"]');
+
+        const badge = this.getAttribute('badge');
+        if (badgeSlot && badgeSlot.assignedNodes().length === 0 && badge) {
+          badgeSlot.textContent = badge;
+        }
+        if (badgeEl) {
+          badgeEl.hidden = !badge && (!badgeSlot || badgeSlot.assignedNodes().length === 0);
+        }
+
+        const price = this.getAttribute('price');
+        if (priceSlot && priceSlot.assignedNodes().length === 0 && price) {
+          priceSlot.textContent = price;
+        }
+        if (priceEl) {
+          priceEl.hidden = !price && (!priceSlot || priceSlot.assignedNodes().length === 0);
+        }
+
+        const href = this.getAttribute('href');
+        if (linkEl && href) {
+          linkEl.setAttribute('href', href);
+        }
+
+        const image = this.getAttribute('image');
+        const imageAlt = this.getAttribute('image-alt') || this.querySelector('[slot="title"]')?.textContent || 'Coffee drink';
