+        }
+        if (mediaEl && !image && !badge && this.shadowRoot.querySelector('slot[name="media"]')?.assignedNodes().length === 0) {
+          mediaEl.hidden = true;
+        }
+      }
+    }
+
+    if (!customElements.get('drink-card')) {
+      customElements.define('drink-card', DrinkCard);
