+            activeSwipe = null;
+            setCardOpenState(card, wasOpen, dir);
+          }
+        });
+
+        card.addEventListener('pointerdown', (e) => {
+          if (e.button !== undefined && e.button !== 0) return;
+          startSwipe(card, e.clientX, e.clientY, e.target);
+        });
+
+        card.addEventListener('mousedown', (e) => {
+          if (e.button !== 0) return;
+          startSwipe(card, e.clientX, e.clientY, e.target);
+        });
+
+        card.addEventListener('click', (e) => {
+          if (suppressNextClick && !e.target.closest('.card-actions')) {
+            e.preventDefault();
+            e.stopPropagation();
+            suppressNextClick = false;
+          }
+        }, true);
+
+        const statusEl = card.querySelector('.drink-status');
+        const drinkName = card.dataset.drinkName || 'Drink';
+
+        card.querySelectorAll('.action-btn').forEach((btn) => {
+          btn.addEventListener('click', (e) => {
+            e.stopPropagation();
