+            btn.classList.toggle('is-active');
+
+            if (action === 'add-to-order') {
+              statusEl.textContent = `Added ${drinkName} to order`;
+            } else if (action === 'customize') {
+              statusEl.textContent = `Customizing ${drinkName}`;
+            } else if (action === 'favorite') {
