+    (function () {
+      const STORAGE_KEY = 'dailyGrindDarkRoastPreference';
+      const toggleInput = document.getElementById('preference-toggle');
+      const preferenceCard = document.getElementById('preference-card');
+      const stateBadge = document.getElementById('preference-state-badge');
+      const statusText = document.getElementById('preference-status-text');
+      const boldCards = document.querySelectorAll('[data-bold-roast="true"]');
+
+      function applyPreference(isOn) {
+        toggleInput.checked = isOn;
+        toggleInput.setAttribute('aria-checked', String(isOn));
+        preferenceCard.setAttribute('data-state', isOn ? 'on' : 'off');
+        stateBadge.textContent = isOn ? 'ON' : 'OFF';
+        statusText.textContent = isOn
+          ? 'Current preference: On (Dark Roast Theme & Bold Picks Active)'
+          : 'Current preference: Off (Standard Café Theme)';
+
+        document.body.classList.toggle('dark-mode', isOn);
+        boldCards.forEach(function (card) {
+          card.classList.toggle('preferred-highlight', isOn);
+        });
+
+        try {
+          localStorage.setItem(STORAGE_KEY, isOn ? 'on' : 'off');
+        } catch (e) {
+          // Ignore storage errors in restricted environments
+        }
+      }
+
+      let initialIsOn = false;
+      try {
+        initialIsOn = localStorage.getItem(STORAGE_KEY) === 'on';
+      } catch (e) {
+        initialIsOn = false;
+      }
+
+      applyPreference(initialIsOn);
+
+      toggleInput.addEventListener('change', function (event) {
+        applyPreference(Boolean(event.target.checked));
+      });
