+  <script>
+    (function () {
+      const tabsShell = document.getElementById('menu-tabs-shell');
+      const tabList = document.getElementById('menu-tab-list');
+      const tabs = Array.from(tabList.querySelectorAll('[role="tab"]'));
+      const panels = Array.from(document.querySelectorAll('#coffee-menu [role="tabpanel"]'));
+      const prevBtn = document.getElementById('tab-scroll-prev');
+      const nextBtn = document.getElementById('tab-scroll-next');
+
+      function updateScrollAffordances() {
+        const maxScrollLeft = tabList.scrollWidth - tabList.clientWidth;
+        const isOverflowing = maxScrollLeft > 4;
+        const canScrollLeft = tabList.scrollLeft > 4;
+        const canScrollRight = tabList.scrollLeft < maxScrollLeft - 4;
+
+        tabsShell.classList.toggle('is-overflowing', isOverflowing);
+        tabsShell.classList.toggle('can-scroll-left', canScrollLeft);
+        tabsShell.classList.toggle('can-scroll-right', canScrollRight);
+
+        prevBtn.disabled = !canScrollLeft;
+        nextBtn.disabled = !canScrollRight;
+      }
+
+      function scrollTabIntoView(tab) {
+        if (!tab) return;
+        const tabRect = tab.getBoundingClientRect();
+        const listRect = tabList.getBoundingClientRect();
+        const targetScrollLeft =
+          tabList.scrollLeft +
+          (tabRect.left - listRect.left) -
+          (listRect.width / 2 - tabRect.width / 2);
+
+        tabList.scrollTo({
+          left: Math.max(0, targetScrollLeft),
+          behavior: 'smooth'
+        });
+      }
+
+      function activateTab(selectedTab, { focus = false } = {}) {
+        tabs.forEach((tab) => {
+          const isSelected = tab === selectedTab;
+          tab.setAttribute('aria-selected', String(isSelected));
+          tab.tabIndex = isSelected ? 0 : -1;
+        });
+
+        panels.forEach((panel) => {
+          const isMatch = panel.id === selectedTab.getAttribute('aria-controls');
+          panel.hidden = !isMatch;
+        });
+
+        if (focus) {
+          selectedTab.focus({ preventScroll: true });
+        }
+
+        scrollTabIntoView(selectedTab);
+      }
+
+      tabs.forEach((tab, index) => {
+        tab.addEventListener('click', () => {
+          activateTab(tab);
+        });
+
+        tab.addEventListener('keydown', (event) => {
+          let targetIndex = null;
+
+          if (event.key === 'ArrowRight') {
+            targetIndex = (index + 1) % tabs.length;
+          } else if (event.key === 'ArrowLeft') {
+            targetIndex = (index - 1 + tabs.length) % tabs.length;
+          } else if (event.key === 'Home') {
+            targetIndex = 0;
+          } else if (event.key === 'End') {
+            targetIndex = tabs.length - 1;
+          }
+
+          if (targetIndex !== null) {
+            event.preventDefault();
+            activateTab(tabs[targetIndex], { focus: true });
+          }
+        });
+      });
