+          behavior: 'smooth'
+        });
+      });
+
+      tabList.addEventListener('scroll', updateScrollAffordances, { passive: true });
+      window.addEventListener('resize', updateScrollAffordances);
+
+      updateScrollAffordances();
+    })();
