+
+      function setStatus(message, state = 'idle') {
+        statusEl.textContent = message;
+        statusEl.dataset.state = state;
+      }
+
+      function applyLanguageAttribute(bcp47Code) {
+        if (translatableRoot) {
+          translatableRoot.setAttribute('lang', bcp47Code);
+        }
+        translatableContainers.forEach((container) => {
+          container.setAttribute('lang', bcp47Code);
+        });
+      }
+
+      function restoreOriginalLanguage() {
+        for (const [node, originalText] of originalTexts.entries()) {
+          node.textContent = originalText;
+        }
+        applyLanguageAttribute(SOURCE_LANGUAGE);
+        progressEl.hidden = true;
+        setStatus('Showing original English content.', 'ready');
+      }
+
+      // Check feature support on the global scope (never window.ai.translator)
