+  };
+
+  const handleSwapLanguages = () => {
+    if (isTranslating) return;
+    const prevSource = sourceLanguage;
+    const prevTarget = targetLanguage;
+    setSourceLanguage(prevTarget);
+    setTargetLanguage(prevSource);
+  };
+
+  const handleDetectLanguage = async () => {
+    setErrorMessage(null);
+    setDetectedInfo(null);
+
+    if (!isLanguageDetectorSupported()) {
+      setErrorMessage('Client-side language detection is currently unsupported in this browser.');
+      return;
+    }
+
+    const containers = getContainers();
+    const sampleText = containers
+      .map((c) => c.textContent || '')
+      .join(' ')
+      .replace(/\s+/g, ' ')
+      .trim()
+      .slice(0, 600);
+
+    if (sampleText.length < 20) {
+      setErrorMessage('Not enough text content to accurately detect language.');
+      return;
+    }
+
+    setIsDetecting(true);
+    setDownloadProgress(null);
+
+    try {
+      const detected = await detectTextLanguage(sampleText, (pct) => {
+        setDownloadProgress(pct);
+      });
+      if (detected) {
+        const confidencePct = Math.round(detected.confidence * 100);
+        const matchingOption = SUPPORTED_LANGUAGES.find(
+          (l) => l.code === detected.detectedLanguage
+        );
+        if (matchingOption) {
+          setSourceLanguage(matchingOption.code);
+          if (matchingOption.code === targetLanguage) {
+            const fallbackTarget = matchingOption.code === 'en' ? 'es' : 'en';
+            setTargetLanguage(fallbackTarget);
+          }
+        }
+        setDetectedInfo(
+          `Detected ${getLanguageName(detected.detectedLanguage)} (${confidencePct}% confidence)`
+        );
+      } else {
+        setErrorMessage('Could not confidently detect source language.');
+      }
+    } catch (err: any) {
+      setErrorMessage(
+        err?.message || 'Client-side language detection is unavailable in this browser.'
+      );
+    } finally {
+      setIsDetecting(false);
+      setDownloadProgress(null);
+    }
+  };
+
+  const handleTranslate = async () => {
+    setErrorMessage(null);
+
+    if (!isTranslatorSupported()) {
+      setErrorMessage('Client-side translation is currently unsupported in this browser.');
+      return;
+    }
+
+    if (sourceLanguage === targetLanguage) {
+      handleRestoreOriginal();
+      return;
+    }
+
+    const containers = getContainers();
+    if (containers.length === 0) {
+      setErrorMessage('No translatable article or teaser content found on this page.');
+      return;
+    }
+
+    setIsTranslating(true);
+    setDownloadProgress(null);
+
+    try {
+      const translator = await getOrCreateTranslator(
+        sourceLanguage,
+        targetLanguage,
+        (pct) => {
+          setDownloadProgress(pct);
+        }
+      );
+
+      for (const container of containers) {
+        await translateContainerElement(
+          container,
+          translator,
+          targetLanguage,
+          sourceLanguage
+        );
+      }
+
+      setTranslatedTo(targetLanguage);
+      setAvailability('available');
+      setStatusMessage(null);
+
+      if (scope === 'page' && typeof window !== 'undefined') {
+        window.dispatchEvent(
+          new CustomEvent('devtools-times:translated', {
+            detail: { sourceLanguage, targetLanguage },
+          })
+        );
+      }
+    } catch (err: any) {
+      setErrorMessage(
+        err?.message || 'Unable to translate content on this device.'
+      );
+    } finally {
+      setIsTranslating(false);
+      setDownloadProgress(null);
+    }
+  };
+
+  const handleRestoreOriginal = () => {
+    const containers = getContainers();
+    for (const container of containers) {
+      restoreContainerElement(container, sourceLanguage);
+    }
+    setTranslatedTo(null);
+    setErrorMessage(null);
+
+    if (scope === 'page' && typeof window !== 'undefined') {
+      window.dispatchEvent(new CustomEvent('devtools-times:restored'));
+    }
+  };
+
+  const isTranslateDisabled =
+    apiSupported === false ||
+    availability === 'unavailable' ||
+    isTranslating ||
+    sourceLanguage === targetLanguage;
+
+  if (compact && !isExpanded) {
+    return (
+      <div className="inline-flex items-center gap-2">
+        <button
+          type="button"
+          onClick={() => setIsExpanded(true)}
+          className="inline-flex items-center gap-1.5 text-xs font-semibold text-gray-700 hover:text-amber-700 bg-gray-100 hover:bg-amber-50 border border-gray-300 rounded px-2.5 py-1.5 transition-colors cursor-pointer"
+          aria-expanded={isExpanded}
+          title="Open on-device article & teaser translator"
+        >
+          <LanguageIcon className="w-4 h-4 text-amber-700" />
+          <span>
+            {translatedTo
+              ? `Translated (${translatedTo.toUpperCase()})`
+              : 'Translate'}
+          </span>
+        </button>
+        {translatedTo && (
+          <button
+            type="button"
+            onClick={handleRestoreOriginal}
+            className="text-xs text-amber-800 hover:underline font-medium cursor-pointer"
+          >
+            Original
+          </button>
+        )}
+      </div>
+    );
+  }
+
+  return (
+    <section
+      aria-label={
+        scope === 'page'
+          ? 'On-device page & teaser translation controls'
+          : 'On-device article translation controls'
+      }
+      className={`bg-amber-50/60 border border-amber-200 rounded-lg ${
+        compact ? 'p-3 my-2' : 'p-4 my-4'
+      } text-gray-800 shadow-xs`}
+    >
+      <div className="flex flex-wrap items-center justify-between gap-3">
+        {/* Title & On-Device Badge */}
+        <div className="flex items-center gap-2">
+          <LanguageIcon className="w-5 h-5 text-amber-800 shrink-0" />
+          <div>
+            <div className="flex items-center gap-2 flex-wrap">
+              <span className="text-sm font-bold text-gray-900">
+                {scope === 'page'
+                  ? 'Translate Articles & Teasers'
+                  : 'Translate This Article'}
+              </span>
+              <span className="inline-flex items-center gap-1 text-[11px] font-medium bg-amber-100 text-amber-900 px-2 py-0.5 rounded-full">
+                <SparklesIcon className="w-3 h-3" />
+                On-Device AI
+              </span>
+              {availability === 'available' && apiSupported && (
+                <span className="text-[11px] font-medium bg-green-100 text-green-800 px-2 py-0.5 rounded-full">
+                  Model Ready
+                </span>
+              )}
+              {(availability === 'downloadable' ||
+                availability === 'downloading') &&
+                apiSupported && (
+                  <span className="text-[11px] font-medium bg-blue-100 text-blue-800 px-2 py-0.5 rounded-full">
+                    {availability === 'downloading'
+                      ? 'Downloading Model…'
+                      : 'Downloadable on Click'}
+                  </span>
+                )}
+              {(apiSupported === false || availability === 'unavailable') && (
+                <span className="text-[11px] font-medium bg-gray-200 text-gray-700 px-2 py-0.5 rounded-full">
+                  Unavailable
+                </span>
+              )}
+            </div>
+          </div>
+        </div>
+
+        {/* Controls Row */}
+        <div className="flex flex-wrap items-center gap-2">
+          {/* Source Language */}
+          <div className="flex items-center gap-1.5">
+            <label
+              htmlFor={sourceSelectId}
+              className="text-xs font-medium text-gray-600"
+            >
+              From
+            </label>
+            <select
+              id={sourceSelectId}
+              value={sourceLanguage}
+              onChange={(e) => setSourceLanguage(e.target.value)}
+              disabled={apiSupported === false || isTranslating}
+              className="text-xs bg-white border border-gray-300 rounded px-2 py-1.5 text-gray-800 focus:outline-none focus:ring-2 focus:ring-amber-400 disabled:opacity-50"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={`src-${lang.code}`} value={lang.code}>
+                  {lang.name}
+                </option>
+              ))}
+            </select>
+          </div>
+
+          {/* Swap Button */}
+          <button
+            type="button"
+            onClick={handleSwapLanguages}
+            disabled={apiSupported === false || isTranslating}
+            title="Swap source and target languages"
+            aria-label="Swap source and target languages"
+            className="p-1.5 text-gray-600 hover:text-amber-800 bg-white border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50 cursor-pointer"
+          >
+            <ArrowPathIcon className="w-3.5 h-3.5" />
+          </button>
+
+          {/* Target Language */}
+          <div className="flex items-center gap-1.5">
+            <label
+              htmlFor={targetSelectId}
+              className="text-xs font-medium text-gray-600"
+            >
+              To
+            </label>
+            <select
+              id={targetSelectId}
+              value={targetLanguage}
+              onChange={(e) => setTargetLanguage(e.target.value)}
+              disabled={apiSupported === false || isTranslating}
+              className="text-xs bg-white border border-gray-300 rounded px-2 py-1.5 text-gray-800 focus:outline-none focus:ring-2 focus:ring-amber-400 disabled:opacity-50"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={`tgt-${lang.code}`} value={lang.code}>
+                  {lang.name}
+                </option>
+              ))}
+            </select>
+          </div>
+
+          {/* Optional Language Detector Button (User Gesture) */}
+          <button
+            type="button"
+            onClick={handleDetectLanguage}
+            disabled={!detectorSupported || isDetecting || isTranslating}
+            title={
+              detectorSupported
+                ? 'Detect source language using on-device LanguageDetector API'
+                : 'Client-side language detection is unsupported in this browser'
+            }
+            className="text-xs font-medium px-2.5 py-1.5 rounded border border-gray-300 bg-white text-gray-700 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
+          >
+            {isDetecting ? 'Detecting…' : 'Detect Language'}
+          </button>
+
+          {/* Translate Action Button (User Gesture) */}
+          <button
+            type="button"
+            onClick={handleTranslate}
+            disabled={isTranslateDisabled}
+            className="text-xs font-semibold px-3 py-1.5 rounded bg-gray-900 text-white hover:bg-amber-700 transition-colors disabled:bg-gray-300 disabled:text-gray-500 disabled:cursor-not-allowed cursor-pointer"
+          >
+            {isTranslating
+              ? downloadProgress !== null && downloadProgress < 100
+                ? `Downloading (${downloadProgress}%)…`
+                : 'Translating…'
+              : scope === 'page'
+              ? 'Translate All'
+              : 'Translate Article'}
+          </button>
+
+          {/* Restore Original Button */}
+          {translatedTo && (
+            <button
+              type="button"
+              onClick={handleRestoreOriginal}
+              disabled={isTranslating}
+              className="text-xs font-semibold px-2.5 py-1.5 rounded border border-amber-700 text-amber-900 hover:bg-amber-100 transition-colors cursor-pointer"
+            >
+              Show Original
+            </button>
+          )}
+
+          {compact && (
+            <button
+              type="button"
+              onClick={() => setIsExpanded(false)}
+              className="text-xs text-gray-500 hover:text-gray-800 px-1.5 py-1 cursor-pointer"
+              aria-label="Collapse translator panel"
+            >
+              Close
+            </button>
+          )}
+        </div>
+      </div>
+
+      {/* Download Progress Bar */}
+      {(isTranslating || isDetecting) && downloadProgress !== null && (
+        <div className="mt-3" role="status" aria-live="polite">
+          <div className="flex justify-between text-xs text-gray-700 mb-1">
+            <span>Downloading on-device language model…</span>
+            <span className="font-semibold">{downloadProgress}%</span>
+          </div>
+          <div className="w-full bg-gray-200 rounded-full h-1.5 overflow-hidden">
+            <div
+              className="bg-amber-600 h-1.5 rounded-full transition-all duration-200"
+              style={{ width: `${Math.min(100, Math.max(0, downloadProgress))}%` }}
+            />
+          </div>
+        </div>
+      )}
+
+      {/* Status, Detection, or Fallback Feedback */}
+      {(statusMessage || detectedInfo || errorMessage || translatedTo) && (
+        <div
+          className="mt-2 flex flex-wrap items-center justify-between gap-2 text-xs"
+          role="status"
+          aria-live="polite"
+        >
+          <div className="flex flex-wrap items-center gap-3">
+            {translatedTo && !errorMessage && (
+              <span className="text-green-800 font-medium">
+                Translated into {getLanguageName(translatedTo)} (lang=&quot;{translatedTo}&quot;)
+              </span>
+            )}
+            {detectedInfo && (
+              <span className="text-amber-900 font-medium">{detectedInfo}</span>
+            )}
+            {statusMessage && !errorMessage && (
+              <span className="text-gray-600">{statusMessage}</span>
+            )}
+            {errorMessage && (
+              <span className="text-red-700 font-medium">{errorMessage}</span>
+            )}
+          </div>
+        </div>
+      )}
+    </section>
+  );
+}
