diff --git a/src/components/TeaserTranslator.tsx b/src/components/TeaserTranslator.tsx
new file mode 100644
index 0000000..6f639a6
--- /dev/null
+++ b/src/components/TeaserTranslator.tsx
@@ -0,0 +1,212 @@
+import React, { useState, useEffect, useRef, useId } from 'react';
+import {
+  SUPPORTED_LANGUAGES,
+  getLanguageName,
+  isTranslatorSupported,
+  checkTranslatorAvailability,
+  getOrCreateTranslator,
+  translateContainerElement,
+  restoreContainerElement,
+} from '../utils/translator';
+import type { AvailabilityStatus } from '../../global';
+import { LanguageIcon } from '@heroicons/react/24/outline';
+
+interface TeaserTranslatorProps {
+  defaultSourceLanguage?: string;
+  defaultTargetLanguage?: string;
+}
+
+export default function TeaserTranslator({
+  defaultSourceLanguage = 'en',
+  defaultTargetLanguage = 'es',
+}: TeaserTranslatorProps) {
+  const rootRef = useRef<HTMLDivElement>(null);
+  const selectId = useId();
+
+  const [apiSupported, setApiSupported] = useState<boolean | null>(null);
+  const [sourceLanguage] = useState<string>(defaultSourceLanguage);
+  const [targetLanguage, setTargetLanguage] = useState<string>(defaultTargetLanguage);
+  const [availability, setAvailability] = useState<AvailabilityStatus>('available');
+  const [isTranslating, setIsTranslating] = useState<boolean>(false);
+  const [downloadProgress, setDownloadProgress] = useState<number | null>(null);
+  const [translatedLang, setTranslatedLang] = useState<string | null>(null);
+  const [errorMsg, setErrorMsg] = useState<string | null>(null);
+
+  useEffect(() => {
+    const supported = isTranslatorSupported();
+    setApiSupported(supported);
+    if (!supported) {
+      setAvailability('unavailable');
+    }
+
+    const onGlobalTranslated = (e: Event) => {
+      const detail = (e as CustomEvent).detail;
+      if (detail?.targetLanguage) {
+        setTargetLanguage(detail.targetLanguage);
+        setTranslatedLang(detail.targetLanguage);
+      }
+    };
+
+    const onGlobalRestored = () => {
+      setTranslatedLang(null);
+    };
+
+    window.addEventListener('devtools-times:translated', onGlobalTranslated);
+    window.addEventListener('devtools-times:restored', onGlobalRestored);
+    return () => {
+      window.removeEventListener('devtools-times:translated', onGlobalTranslated);
+      window.removeEventListener('devtools-times:restored', onGlobalRestored);
+    };
+  }, []);
+
+  useEffect(() => {
+    if (!apiSupported) return;
+    let cancelled = false;
+    checkTranslatorAvailability({ sourceLanguage, targetLanguage }).then((status) => {
+      if (!cancelled) {
+        setAvailability(status);
+      }
+    });
+    return () => {
+      cancelled = true;
+    };
+  }, [apiSupported, sourceLanguage, targetLanguage]);
+
+  const findTeaserContainer = (): HTMLElement | null => {
+    if (!rootRef.current) return null;
+    return rootRef.current.closest<HTMLElement>('[data-translatable-scope]');
+  };
+
+  const handleTranslateClick = async (e: React.MouseEvent) => {
+    e.preventDefault();
+    e.stopPropagation();
+    setErrorMsg(null);
+
+    if (!isTranslatorSupported()) {
+      setErrorMsg('Unsupported in this browser');
+      return;
+    }
+
+    const container = findTeaserContainer();
+    if (!container) return;
+
+    if (translatedLang === targetLanguage) {
+      restoreContainerElement(container, sourceLanguage);
+      setTranslatedLang(null);
+      return;
+    }
+
+    setIsTranslating(true);
+    setDownloadProgress(null);
+
+    try {
+      const translator = await getOrCreateTranslator(
+        sourceLanguage,
+        targetLanguage,
+        (pct) => setDownloadProgress(pct)
+      );
+      await translateContainerElement(
+        container,
+        translator,
+        targetLanguage,
+        sourceLanguage
+      );
+      setTranslatedLang(targetLanguage);
+      setAvailability('available');
+    } catch (err: any) {
+      setErrorMsg(err?.message || 'Translation unavailable');
+    } finally {
+      setIsTranslating(false);
+      setDownloadProgress(null);
+    }
+  };
+
+  const handleRestoreClick = (e: React.MouseEvent) => {
+    e.preventDefault();
+    e.stopPropagation();
+    const container = findTeaserContainer();
+    if (container) {
+      restoreContainerElement(container, sourceLanguage);
+    }
+    setTranslatedLang(null);
+    setErrorMsg(null);
+  };
+
+  const isDisabled =
+    apiSupported === false ||
+    availability === 'unavailable' ||
+    isTranslating ||
+    sourceLanguage === targetLanguage;
+
+  return (
+    <div
+      ref={rootRef}
+      className="inline-flex flex-wrap items-center gap-1.5 text-xs"
+      onClick={(e) => e.stopPropagation()}
+    >
+      <label htmlFor={selectId} className="sr-only">
+        Target translation language
+      </label>
+      <select
+        id={selectId}
+        value={targetLanguage}
+        onChange={(e) => setTargetLanguage(e.target.value)}
+        disabled={apiSupported === false || isTranslating}
+        aria-label="Target language for teaser translation"
+        title={
+          apiSupported === false
+            ? 'Client-side translation is currently unsupported in this browser'
+            : 'Select language to translate this teaser'
+        }
+        className="text-xs bg-gray-50 border border-gray-200 rounded px-1.5 py-0.5 text-gray-700 focus:outline-none focus:ring-1 focus:ring-amber-400 disabled:opacity-50 max-w-[115px] truncate"
+      >
+        {SUPPORTED_LANGUAGES.filter((l) => l.code !== sourceLanguage).map((lang) => (
+          <option key={lang.code} value={lang.code}>
+            {lang.name}
+          </option>
+        ))}
+      </select>
+
+      <button
+        type="button"
+        onClick={handleTranslateClick}
+        disabled={isDisabled}
+        title={
+          apiSupported === false
+            ? 'Client-side translation is currently unsupported in this browser'
+            : availability === 'unavailable'
+            ? `Translation to ${getLanguageName(targetLanguage)} is unavailable on this device`
+            : `Translate teaser to ${getLanguageName(targetLanguage)}`
+        }
+        className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-gray-100 hover:bg-amber-100 text-gray-700 hover:text-amber-900 font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
+      >
+        <LanguageIcon className="w-3.5 h-3.5 text-amber-700" />
+        <span>
+          {isTranslating
+            ? downloadProgress !== null && downloadProgress < 100
+              ? `${downloadProgress}%`
+              : '…'
+            : translatedLang === targetLanguage
+            ? 'Original'
+            : 'Translate'}
+        </span>
+      </button>
+
+      {translatedLang && translatedLang !== targetLanguage && (
+        <button
+          type="button"
+          onClick={handleRestoreClick}
+          className="text-[11px] text-amber-800 hover:underline px-1 cursor-pointer"
+        >
+          Reset
+        </button>
+      )}
+
+      {errorMsg && (
+        <span className="text-[11px] text-red-600" role="status">
+          {errorMsg}
+        </span>
+      )}
+    </div>
+  );
+}
