+import type {
+  AvailabilityStatus,
+  TranslatorInstance,
+  TranslatorLanguagePairOptions,
+  LanguageDetectorInstance,
+} from '../../global';
+
+export interface LanguageOption {
+  code: string;
+  name: string;
+}
+
+/**
+ * Supported BCP 47 language codes for Chrome's built-in Translator API.
+ */
+export const SUPPORTED_LANGUAGES: LanguageOption[] = [
+  { code: 'en', name: 'English' },
+  { code: 'es', name: 'Spanish (Español)' },
+  { code: 'fr', name: 'French (Français)' },
+  { code: 'de', name: 'German (Deutsch)' },
+  { code: 'it', name: 'Italian (Italiano)' },
+  { code: 'pt', name: 'Portuguese (Português)' },
+  { code: 'nl', name: 'Dutch (Nederlands)' },
+  { code: 'ja', name: 'Japanese (日本語)' },
+  { code: 'ko', name: 'Korean (한국어)' },
+  { code: 'zh', name: 'Chinese Simplified (简体中文)' },
+  { code: 'zh-Hant', name: 'Chinese Traditional (繁體中文)' },
+  { code: 'ar', name: 'Arabic (العربية)' },
+  { code: 'hi', name: 'Hindi (हिन्दी)' },
+  { code: 'ru', name: 'Russian (Русский)' },
+  { code: 'pl', name: 'Polish (Polski)' },
+  { code: 'tr', name: 'Turkish (Türkçe)' },
+  { code: 'vi', name: 'Vietnamese (Tiếng Việt)' },
+  { code: 'id', name: 'Indonesian (Bahasa Indonesia)' },
+  { code: 'th', name: 'Thai (ไทย)' },
+  { code: 'sv', name: 'Swedish (Svenska)' },
+  { code: 'da', name: 'Danish (Dansk)' },
+  { code: 'fi', name: 'Finnish (Suomi)' },
+  { code: 'no', name: 'Norwegian (Norsk)' },
+  { code: 'cs', name: 'Czech (Čeština)' },
+  { code: 'el', name: 'Greek (Ελληνικά)' },
+  { code: 'he', name: 'Hebrew (עברית)' },
+  { code: 'hu', name: 'Hungarian (Magyar)' },
+  { code: 'ro', name: 'Romanian (Română)' },
+  { code: 'sk', name: 'Slovak (Slovenčina)' },
+  { code: 'uk', name: 'Ukrainian (Українська)' },
+  { code: 'bg', name: 'Bulgarian (Български)' },
+  { code: 'hr', name: 'Croatian (Hrvatski)' },
+  { code: 'lt', name: 'Lithuanian (Lietuvių)' },
+  { code: 'sl', name: 'Slovenian (Slovenščina)' },
+  { code: 'bn', name: 'Bengali (বাংলা)' },
+  { code: 'kn', name: 'Kannada (ಕನ್ನಡ)' },
+  { code: 'mr', name: 'Marathi (मराठी)' },
+  { code: 'ta', name: 'Tamil (தமிழ்)' },
+  { code: 'te', name: 'Telugu (తెలుగు)' },
+];
+
+export function getLanguageName(code: string): string {
+  const found = SUPPORTED_LANGUAGES.find((l) => l.code === code);
+  return found ? found.name : code.toUpperCase();
+}
+
+/**
+ * Checks if the built-in Translator API is exposed on the global scope.
+ * Never checks deprecated namespaces like window.ai.translator.
+ */
+export function isTranslatorSupported(): boolean {
+  return typeof self !== 'undefined' && 'Translator' in self && Boolean(self.Translator);
+}
+
+/**
+ * Checks if the built-in LanguageDetector API is exposed on the global scope.
+ */
+export function isLanguageDetectorSupported(): boolean {
+  return (
+    typeof self !== 'undefined' &&
+    'LanguageDetector' in self &&
+    Boolean(self.LanguageDetector)
+  );
+}
+
+/**
+ * Checks availability for a given source and target language pair.
+ */
+export async function checkTranslatorAvailability(
+  options: TranslatorLanguagePairOptions
+): Promise<AvailabilityStatus> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    return 'unavailable';
+  }
+  if (options.sourceLanguage === options.targetLanguage) {
+    return 'available';
+  }
+  try {
+    return await self.Translator.availability(options);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+const translatorCache = new Map<string, TranslatorInstance>();
+
+/**
+ * Creates or retrieves a Translator instance for the language pair.
+ * Must be invoked from a user gesture (e.g. button click) when status is 'downloadable' or 'downloading'.
+ * Passes identical sourceLanguage/targetLanguage options to availability() and create().
+ */
+export async function getOrCreateTranslator(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onDownloadProgress?: (percent: number) => void
+): Promise<TranslatorInstance> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    throw new Error('Client-side translation is currently unsupported in this browser.');
+  }
+
+  const cacheKey = `${sourceLanguage}->${targetLanguage}`;
+  const cached = translatorCache.get(cacheKey);
+  if (cached) {
+    return cached;
+  }
+
+  // Pass identical language pair options to availability() and create()
+  const options: TranslatorLanguagePairOptions = {
+    sourceLanguage,
+    targetLanguage,
+  };
+
+  const availability = await self.Translator.availability(options);
+  if (availability === 'unavailable') {
+    throw new Error(
+      `Translation between ${getLanguageName(sourceLanguage)} and ${getLanguageName(
+        targetLanguage
+      )} is unavailable on this device.`
+    );
+  }
+
+  const translator = await self.Translator.create({
+    ...options,
+    monitor(m) {
+      m.addEventListener('downloadprogress', (e) => {
+        const percent = Math.round((e.loaded ?? 0) * 100);
+        onDownloadProgress?.(percent);
+      });
+    },
+  });
+
+  translatorCache.set(cacheKey, translator);
+  return translator;
+}
+
+/**
