+ */
+export async function translateText(
+  translator: TranslatorInstance,
+  text: string,
+  onStreamUpdate?: (partial: string) => void
+): Promise<string> {
+  const trimmed = text.trim();
+  if (!trimmed) return text;
+
+  // Use streaming translation for longer paragraphs when supported
+  if (
+    trimmed.length > 160 &&
+    typeof translator.translateStreaming === 'function'
+  ) {
+    try {
+      const stream = translator.translateStreaming(trimmed);
+      let accumulated = '';
+      for await (const chunk of stream) {
+        accumulated += chunk;
+        onStreamUpdate?.(accumulated);
+      }
+      if (accumulated) {
+        return accumulated;
+      }
+    } catch {
+      // Fall back to standard translate if streaming fails
+    }
+  }
+
+  const result = await translator.translate(trimmed);
+  onStreamUpdate?.(result);
+  return result;
+}
+
+let detectorInstance: LanguageDetectorInstance | null = null;
+
+/**
+ * Detects the language of a text sample using the on-device LanguageDetector API.
+ * Must be triggered by a user gesture (click) when the model needs to be downloaded.
+ */
+export async function detectTextLanguage(
+  sampleText: string,
+  onDownloadProgress?: (percent: number) => void
+): Promise<{ detectedLanguage: string; confidence: number } | null> {
+  if (!isLanguageDetectorSupported() || !self.LanguageDetector) {
+    throw new Error('Client-side language detection is currently unsupported in this browser.');
+  }
+
+  const cleanText = sampleText.trim();
+  // Avoid running detection on very short phrases or single words
+  if (cleanText.length < 20) {
+    return null;
+  }
+
+  const availability = await self.LanguageDetector.availability();
+  if (availability === 'unavailable') {
+    throw new Error('Language detection model is unavailable on this device.');
+  }
+
+  if (!detectorInstance) {
+    detectorInstance = await self.LanguageDetector.create({
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          const percent = Math.round((e.loaded ?? 0) * 100);
+          onDownloadProgress?.(percent);
+        });
+      },
+    });
+  }
+
+  const results = await detectorInstance.detect(cleanText);
+  if (!results || results.length === 0) {
+    return null;
+  }
+
+  const top = results[0];
+  return {
+    detectedLanguage: top.detectedLanguage,
+    confidence: top.confidence,
+  };
+}
+
+/**
+ * Translates all translatable text nodes inside a given container element and
+ * sets the container's `lang` attribute to the target BCP 47 language code.
+ */
+export async function translateContainerElement(
+  container: HTMLElement,
+  translator: TranslatorInstance,
+  targetLanguage: string,
+  sourceLanguage: string
+): Promise<void> {
+  const elements = Array.from(
+    container.querySelectorAll<HTMLElement>('[data-translatable]')
+  );
+
+  // Also include standard prose paragraphs/headings if inside an article body
+  const proseContainer = container.querySelector<HTMLElement>('[data-translatable-prose]');
+  if (proseContainer) {
+    const proseBlocks = Array.from(
+      proseContainer.querySelectorAll<HTMLElement>('p, h2, h3, h4, li, blockquote')
+    );
+    for (const block of proseBlocks) {
+      if (!elements.includes(block)) {
+        elements.push(block);
+      }
+    }
+  }
+
+  for (const el of elements) {
+    if (!el.dataset.originalText) {
+      el.dataset.originalText = el.textContent || '';
+    }
+    const sourceText = el.dataset.originalText;
+    if (!sourceText.trim()) continue;
+
+    await translateText(translator, sourceText, (partial) => {
+      el.textContent = partial;
+    });
+    el.setAttribute('lang', targetLanguage);
+  }
+
+  // Mandatory accessibility requirement: apply `lang` attribute matching target BCP 47 code
+  container.setAttribute('lang', targetLanguage);
+  container.dataset.translatedLang = targetLanguage;
+  container.dataset.sourceLang = sourceLanguage;
+}
+
+/**
+ * Restores a container element and all its translatable children back to their original text and language.
+ */
+export function restoreContainerElement(
+  container: HTMLElement,
+  originalLanguage = 'en'
+): void {
+  const elements = Array.from(
+    container.querySelectorAll<HTMLElement>('[data-original-text]')
+  );
+
+  for (const el of elements) {
+    if (el.dataset.originalText !== undefined) {
+      el.textContent = el.dataset.originalText;
+    }
+    el.removeAttribute('lang');
+  }
+
+  container.setAttribute('lang', originalLanguage);
+  delete container.dataset.translatedLang;
+}

