diff --git a/src/components/TeaserTranslateButton.tsx b/src/components/TeaserTranslateButton.tsx
new file mode 100644
index 0000000..9d98852
--- /dev/null
+++ b/src/components/TeaserTranslateButton.tsx
@@ -0,0 +1,143 @@
+import React, { useState, useEffect, useRef } from 'react';
+import {
+  TRANSLATION_STATE_EVENT,
+  getGlobalTranslationState,
+  getSavedLanguagePrefs,
+  isOnDeviceTranslatorSupported,
+  restoreElementsInContainer,
+  translateElementsInContainer,
+  type TranslationStateEventDetail,
+} from '../utils/translator';
+
+interface TeaserTranslateButtonProps {
+  articleId: string;
+}
+
+export default function TeaserTranslateButton({
+  articleId,
+}: TeaserTranslateButtonProps) {
+  const buttonRef = useRef<HTMLButtonElement | null>(null);
+  const [sourceLanguage, setSourceLanguage] = useState<string>('en');
+  const [targetLanguage, setTargetLanguage] = useState<string>('es');
+  const [isTranslated, setIsTranslated] = useState<boolean>(false);
+  const [isTranslating, setIsTranslating] = useState<boolean>(false);
+  const [apiSupported, setApiSupported] = useState<boolean>(true);
+
+  useEffect(() => {
+    const prefs = getSavedLanguagePrefs();
+    const globalState = getGlobalTranslationState();
+    setSourceLanguage(prefs.sourceLanguage || globalState.sourceLanguage || 'en');
+    setTargetLanguage(prefs.targetLanguage || globalState.targetLanguage || 'es');
+    setApiSupported(isOnDeviceTranslatorSupported());
+
+    const checkLocalState = () => {
+      const container = buttonRef.current?.closest('[data-translatable-teaser]');
+      if (container) {
+        const hasTranslated =
+          container.querySelectorAll('[data-translated-lang]').length > 0;
+        setIsTranslated(hasTranslated);
+      }
+    };
+
+    checkLocalState();
+
+    const handleStateChange = (e: Event) => {
+      const detail = (e as CustomEvent<TranslationStateEventDetail>).detail;
+      if (detail) {
+        setSourceLanguage(detail.sourceLanguage);
+        setTargetLanguage(detail.targetLanguage);
+      }
+      checkLocalState();
+    };
+
+    window.addEventListener(TRANSLATION_STATE_EVENT, handleStateChange);
+    return () => {
+      window.removeEventListener(TRANSLATION_STATE_EVENT, handleStateChange);
+    };
+  }, []);
+
+  const handleToggleTranslate = async (e: React.MouseEvent) => {
+    e.preventDefault();
+    e.stopPropagation();
+
+    const container =
+      buttonRef.current?.closest<HTMLElement>('[data-translatable-teaser]') ??
+      document.querySelector<HTMLElement>(
+        `[data-translatable-teaser="${articleId}"]`
+      );
+
+    if (!container || isTranslating) return;
+
+    if (isTranslated) {
+      restoreElementsInContainer(container, 'teasers', false);
+      setIsTranslated(false);
+      return;
+    }
+
+    setIsTranslating(true);
+    try {
+      await translateElementsInContainer({
+        root: container,
+        scope: 'teasers',
+        sourceLanguage,
+        targetLanguage,
+        updateGlobal: false,
+      });
+      setIsTranslated(true);
+    } catch (err) {
+      console.warn('Teaser on-device translation error:', err);
+    } finally {
+      setIsTranslating(false);
+    }
+  };
+
+  return (
+    <button
+      ref={buttonRef}
+      type="button"
+      onClick={handleToggleTranslate}
+      disabled={!apiSupported || isTranslating}
+      title={
+        !apiSupported
+          ? 'On-device Translator API unavailable in this browser'
+          : isTranslated
+          ? 'Show original teaser text'
+          : `Translate teaser to ${targetLanguage.toUpperCase()} on-device`
+      }
+      aria-label={
+        isTranslated
+          ? 'Show original teaser text'
+          : `Translate teaser to ${targetLanguage.toUpperCase()}`
+      }
+      data-testid={`teaser-translate-btn-${articleId}`}
+      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium transition-colors ${
+        isTranslated
+          ? 'bg-amber-100 text-amber-900 hover:bg-amber-200'
+          : 'text-gray-500 hover:text-amber-700 hover:bg-gray-100 disabled:opacity-40'
+      }`}
+    >
+      {isTranslating ? (
+        <span className="w-3 h-3 border-2 border-amber-500 border-t-transparent rounded-full animate-spin" />
+      ) : (
+        <svg
+          xmlns="http://www.w3.org/2000/svg"
+          viewBox="0 0 24 24"
+          fill="none"
+          stroke="currentColor"
+          strokeWidth={2}
+          className="w-3.5 h-3.5"
+          aria-hidden="true"
+        >
+          <path
+            strokeLinecap="round"
+            strokeLinejoin="round"
+            d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+          />
+        </svg>
+      )}
+      <span>
+        {isTranslated ? 'Original' : `Translate (${targetLanguage.toUpperCase()})`}
+      </span>
+    </button>
+  );
+}
