new file mode 100644
index 0000000..b5b3794
--- /dev/null
+++ b/src/components/TranslationControl.tsx
@@ -0,0 +1,623 @@
+import React, { useState, useEffect, useRef, useCallback } from 'react';
+import {
+  SUPPORTED_LANGUAGES,
+  TRANSLATION_STATE_EVENT,
+  checkLanguagePairAvailability,
+  getGlobalTranslationState,
+  getSavedLanguagePrefs,
+  isOnDeviceLanguageDetectorSupported,
+  isOnDeviceTranslatorSupported,
+  restoreElementsInContainer,
+  saveLanguagePrefs,
+  translateElementsInContainer,
+  updateGlobalTranslationState,
+  type NormalizedAvailability,
+  type TranslationScope,
+  type TranslationStateEventDetail,
+} from '../utils/translator';
+
+interface TranslationControlProps {
+  variant?: 'header' | 'article';
+}
+
+export default function TranslationControl({
+  variant = 'header',
+}: TranslationControlProps) {
+  const [sourceLanguage, setSourceLanguage] = useState<string>('en');
+  const [targetLanguage, setTargetLanguage] = useState<string>('es');
+  const [detectedLanguage, setDetectedLanguage] = useState<string | null>(null);
+  const [scope, setScope] = useState<TranslationScope>('all');
+  const [availability, setAvailability] =
+    useState<NormalizedAvailability>('available');
+  const [apiSupported, setApiSupported] = useState<boolean>(true);
+  const [detectorSupported, setDetectorSupported] = useState<boolean>(false);
+  const [isTranslating, setIsTranslating] = useState<boolean>(false);
+  const [isTranslated, setIsTranslated] = useState<boolean>(false);
+  const [progress, setProgress] = useState<{
+    completed: number;
+    total: number;
+  }>({ completed: 0, total: 0 });
+  const [downloadProgress, setDownloadProgress] = useState<number | null>(
+    null
+  );
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  const abortControllerRef = useRef<AbortController | null>(null);
+
+  // Initialize saved preferences and check API support on mount
+  useEffect(() => {
+    const prefs = getSavedLanguagePrefs();
+    const initialState = getGlobalTranslationState();
+    const initialSource = prefs.sourceLanguage || initialState.sourceLanguage || 'en';
+    const initialTarget = prefs.targetLanguage || initialState.targetLanguage || 'es';
+
+    setSourceLanguage(initialSource);
+    setTargetLanguage(initialTarget);
+    setApiSupported(isOnDeviceTranslatorSupported());
+    setDetectorSupported(isOnDeviceLanguageDetectorSupported());
+
+    updateGlobalTranslationState({
+      sourceLanguage: initialSource,
+      targetLanguage: initialTarget,
+    });
+  }, []);
+
+  // Refresh availability whenever source or target language changes
+  const refreshAvailability = useCallback(
+    async (src: string, tgt: string) => {
+      const supported = isOnDeviceTranslatorSupported();
+      setApiSupported(supported);
+      if (!supported) {
+        setAvailability('unsupported');
+        return;
+      }
+      const status = await checkLanguagePairAvailability(src, tgt);
+      setAvailability(status);
+    },
+    []
+  );
+
+  useEffect(() => {
+    refreshAvailability(sourceLanguage, targetLanguage);
+  }, [sourceLanguage, targetLanguage, refreshAvailability]);
+
+  // Synchronize state across multiple instances (Header + Article + Teaser buttons)
+  useEffect(() => {
+    const handleStateEvent = (e: Event) => {
+      const customEvent = e as CustomEvent<TranslationStateEventDetail>;
+      const detail = customEvent.detail;
+      if (!detail) return;
+
+      setSourceLanguage(detail.sourceLanguage);
+      setTargetLanguage(detail.targetLanguage);
+      setIsTranslated(detail.isTranslated);
+      setIsTranslating(detail.isTranslating);
+      setProgress({
+        completed: detail.translatedCount,
+        total: detail.totalCount,
+      });
+      setDownloadProgress(detail.downloadProgress);
+      setErrorMessage(detail.error);
+    };
+
+    const handlePageLoad = () => {
