+++ b/src/utils/translator.ts
@@ -0,0 +1,712 @@
+import type {
+  BrowserTranslatorInstance,
+  TranslatorCreateMonitor,
+} from '../../global';
+
+export interface LanguageOption {
+  code: string;
+  name: string;
+  nativeName: string;
+  dir: 'ltr' | 'rtl';
+}
+
+export const SUPPORTED_LANGUAGES: LanguageOption[] = [
+  { code: 'en', name: 'English', nativeName: 'English', dir: 'ltr' },
+  { code: 'es', name: 'Spanish', nativeName: 'Español', dir: 'ltr' },
+  { code: 'fr', name: 'French', nativeName: 'Français', dir: 'ltr' },
+  { code: 'de', name: 'German', nativeName: 'Deutsch', dir: 'ltr' },
+  { code: 'ja', name: 'Japanese', nativeName: '日本語', dir: 'ltr' },
+  { code: 'pt', name: 'Portuguese', nativeName: 'Português', dir: 'ltr' },
+  { code: 'it', name: 'Italian', nativeName: 'Italiano', dir: 'ltr' },
+  { code: 'zh', name: 'Chinese', nativeName: '中文', dir: 'ltr' },
+  { code: 'ko', name: 'Korean', nativeName: '한국어', dir: 'ltr' },
+  { code: 'nl', name: 'Dutch', nativeName: 'Nederlands', dir: 'ltr' },
+  { code: 'pl', name: 'Polish', nativeName: 'Polski', dir: 'ltr' },
+  { code: 'ru', name: 'Russian', nativeName: 'Русский', dir: 'ltr' },
+  { code: 'ar', name: 'Arabic', nativeName: 'العربية', dir: 'rtl' },
+  { code: 'hi', name: 'Hindi', nativeName: 'हिन्दी', dir: 'ltr' },
+  { code: 'tr', name: 'Turkish', nativeName: 'Türkçe', dir: 'ltr' },
+  { code: 'vi', name: 'Vietnamese', nativeName: 'Tiếng Việt', dir: 'ltr' },
+];
+
+export type NormalizedAvailability =
+  | 'available'
+  | 'downloadable'
+  | 'downloading'
+  | 'unavailable'
+  | 'unsupported';
+
+export type TranslationScope = 'all' | 'article' | 'teasers';
+
+export interface TranslationStateEventDetail {
+  sourceLanguage: string;
+  targetLanguage: string;
+  isTranslated: boolean;
+  isTranslating: boolean;
+  translatedCount: number;
+  totalCount: number;
+  downloadProgress: number | null;
+  error: string | null;
+}
+
+export const TRANSLATION_STATE_EVENT = 'devtools-times:translation-state';
+const STORAGE_KEY_SOURCE = 'dtt_translate_source_lang';
+const STORAGE_KEY_TARGET = 'dtt_translate_target_lang';
+
+const translatorCache = new Map<string, BrowserTranslatorInstance>();
+
+let globalTranslationState: TranslationStateEventDetail = {
+  sourceLanguage: 'en',
+  targetLanguage: 'es',
+  isTranslated: false,
+  isTranslating: false,
+  translatedCount: 0,
+  totalCount: 0,
+  downloadProgress: null,
+  error: null,
+};
+
+export function getSavedLanguagePrefs(): {
+  sourceLanguage: string;
+  targetLanguage: string;
+} {
+  if (typeof window === 'undefined') {
+    return { sourceLanguage: 'en', targetLanguage: 'es' };
+  }
+  try {
+    const savedSource = window.localStorage.getItem(STORAGE_KEY_SOURCE) || 'en';
+    const savedTarget = window.localStorage.getItem(STORAGE_KEY_TARGET) || 'es';
+    return { sourceLanguage: savedSource, targetLanguage: savedTarget };
+  } catch {
+    return { sourceLanguage: 'en', targetLanguage: 'es' };
+  }
+}
+
+export function saveLanguagePrefs(
+  sourceLanguage: string,
+  targetLanguage: string
+): void {
+  if (typeof window === 'undefined') return;
+  try {
+    window.localStorage.setItem(STORAGE_KEY_SOURCE, sourceLanguage);
+    window.localStorage.setItem(STORAGE_KEY_TARGET, targetLanguage);
+  } catch {
+    // Ignore storage errors in restricted contexts
+  }
+}
+
+export function getGlobalTranslationState(): TranslationStateEventDetail {
+  return globalTranslationState;
+}
+
+export function updateGlobalTranslationState(
+  partial: Partial<TranslationStateEventDetail>
+): void {
+  globalTranslationState = { ...globalTranslationState, ...partial };
+  if (typeof window !== 'undefined') {
+    window.dispatchEvent(
+      new CustomEvent<TranslationStateEventDetail>(TRANSLATION_STATE_EVENT, {
+        detail: globalTranslationState,
+      })
+    );
+  }
+}
+
+export function getLanguageOption(code: string): LanguageOption | undefined {
+  const baseCode = code.toLowerCase().split('-')[0];
+  return SUPPORTED_LANGUAGES.find((lang) => lang.code === baseCode);
+}
+
+export function getLanguageName(code: string): string {
+  if (code === 'auto') return 'Auto-detect';
+  const option = getLanguageOption(code);
+  return option ? `${option.name} (${option.nativeName})` : code.toUpperCase();
+}
+
+export function getLanguageDir(code: string): 'ltr' | 'rtl' {
+  return getLanguageOption(code)?.dir ?? 'ltr';
+}
+
+export function isOnDeviceTranslatorSupported(): boolean {
+  if (typeof window === 'undefined') return false;
+  return (
+    'Translator' in window ||
+    Boolean(window.ai?.translator) ||
+    Boolean(window.translation?.createTranslator)
+  );
+}
+
+export function isOnDeviceLanguageDetectorSupported(): boolean {
+  if (typeof window === 'undefined') return false;
+  return (
+    'LanguageDetector' in window ||
+    Boolean(window.ai?.languageDetector) ||
+    Boolean(window.translation?.createDetector)
+  );
+}
+
+function normalizeAvailabilityStatus(raw: string | undefined): NormalizedAvailability {
+  switch (raw) {
+    case 'available':
+    case 'readily':
+      return 'available';
+    case 'downloadable':
+    case 'after-download':
+      return 'downloadable';
+    case 'downloading':
+      return 'downloading';
+    case 'unavailable':
+    case 'no':
+      return 'unavailable';
+    default:
+      return 'unavailable';
+  }
+}
+
+export async function checkLanguagePairAvailability(
+  sourceLanguage: string,
+  targetLanguage: string
+): Promise<NormalizedAvailability> {
+  if (typeof window === 'undefined') return 'unsupported';
+  const effectiveSource = sourceLanguage === 'auto' ? 'en' : sourceLanguage;
+
+  if (effectiveSource === targetLanguage) {
+    return 'available';
+  }
+
+  try {
+    if (window.Translator && typeof window.Translator.availability === 'function') {
+      const status = await window.Translator.availability({
+        sourceLanguage: effectiveSource,
+        targetLanguage,
+      });
+      return normalizeAvailabilityStatus(status);
+    }
+
+    if (window.ai?.translator) {
+      if (typeof window.ai.translator.availability === 'function') {
+        const status = await window.ai.translator.availability({
+          sourceLanguage: effectiveSource,
+          targetLanguage,
+        });
+        return normalizeAvailabilityStatus(status);
+      }
+      if (typeof window.ai.translator.capabilities === 'function') {
+        const capabilities = await window.ai.translator.capabilities();
+        if (typeof capabilities.languagePairAvailable === 'function') {
+          return normalizeAvailabilityStatus(
+            capabilities.languagePairAvailable(effectiveSource, targetLanguage)
+          );
+        }
+        return normalizeAvailabilityStatus(capabilities.available);
+      }
+    }
+
+    if (window.translation && typeof window.translation.canTranslate === 'function') {
+      const status = await window.translation.canTranslate({
+        sourceLanguage: effectiveSource,
+        targetLanguage,
+      });
+      return normalizeAvailabilityStatus(status);
+    }
+  } catch (err) {
+    console.warn('Failed to check on-device translation availability:', err);
+    return 'unavailable';
+  }
+
+  return 'unsupported';
+}
+
+export async function detectLanguageOnDevice(
+  sampleText: string,
+  onDownloadProgress?: (progress: number) => void,
+  signal?: AbortSignal
+): Promise<string> {
+  const cleaned = sampleText.trim();
+  if (!cleaned || typeof window === 'undefined') return 'en';
+
+  const attachMonitor = (monitor: TranslatorCreateMonitor) => {
+    if (!onDownloadProgress) return;
+    monitor.addEventListener('downloadprogress', (event) => {
+      const ratio =
+        typeof event.total === 'number' && event.total > 0
+          ? event.loaded / event.total
+          : event.loaded;
+      onDownloadProgress(Math.min(100, Math.max(0, Math.round(ratio * 100))));
+    });
+  };
+
+  try {
+    if (window.LanguageDetector && typeof window.LanguageDetector.create === 'function') {
+      const detector = await window.LanguageDetector.create({
+        signal,
+        monitor: attachMonitor,
+      });
+      try {
+        const results = await detector.detect(cleaned.slice(0, 1000), { signal });
+        const top = results?.[0]?.detectedLanguage;
+        if (top && top !== 'und') {
+          return top.split('-')[0].toLowerCase();
+        }
+      } finally {
+        detector.destroy?.();
+      }
+    } else if (window.ai?.languageDetector?.create) {
+      const detector = await window.ai.languageDetector.create({
+        signal,
+        monitor: attachMonitor,
+      });
+      try {
+        const results = await detector.detect(cleaned.slice(0, 1000), { signal });
+        const top = results?.[0]?.detectedLanguage;
+        if (top && top !== 'und') {
+          return top.split('-')[0].toLowerCase();
+        }
+      } finally {
+        detector.destroy?.();
+      }
+    } else if (window.translation?.createDetector) {
+      const detector = await window.translation.createDetector();
+      try {
+        const results = await detector.detect(cleaned.slice(0, 1000), { signal });
+        const top = results?.[0]?.detectedLanguage;
+        if (top && top !== 'und') {
+          return top.split('-')[0].toLowerCase();
+        }
+      } finally {
+        detector.destroy?.();
+      }
+    }
+  } catch (err) {
+    console.warn('On-device language detection failed, defaulting to English:', err);
+  }
+
+  return 'en';
+}
+
+export async function getOrCreateTranslator(options: {
+  sourceLanguage: string;
+  targetLanguage: string;
+  onDownloadProgress?: (progress: number) => void;
+  signal?: AbortSignal;
+}): Promise<BrowserTranslatorInstance> {
+  const { sourceLanguage, targetLanguage, onDownloadProgress, signal } = options;
+  const cacheKey = `${sourceLanguage}->${targetLanguage}`;
+
+  const cached = translatorCache.get(cacheKey);
+  if (cached) {
+    return cached;
+  }
+
+  const monitor = (m: TranslatorCreateMonitor) => {
+    m.addEventListener('downloadprogress', (event) => {
+      const ratio =
+        typeof event.total === 'number' && event.total > 0
+          ? event.loaded / event.total
+          : event.loaded;
+      const percent = Math.min(100, Math.max(0, Math.round(ratio * 100)));
+      onDownloadProgress?.(percent);
+    });
+  };
+
+  let instance: BrowserTranslatorInstance | null = null;
+
+  if (typeof window !== 'undefined' && window.Translator?.create) {
+    instance = await window.Translator.create({
+      sourceLanguage,
+      targetLanguage,
+      monitor,
+      signal,
+    });
+  } else if (typeof window !== 'undefined' && window.ai?.translator?.create) {
+    instance = await window.ai.translator.create({
+      sourceLanguage,
+      targetLanguage,
+      monitor,
+      signal,
+    });
+  } else if (typeof window !== 'undefined' && window.translation?.createTranslator) {
+    instance = await window.translation.createTranslator({
+      sourceLanguage,
+      targetLanguage,
+      monitor,
+      signal,
+    });
+  }
+
+  if (!instance) {
+    throw new Error(
+      'The browser On-Device Translator API (window.Translator) is not available in this browser.'
+    );
+  }
+
+  translatorCache.set(cacheKey, instance);
+  return instance;
+}
+
+export function clearTranslatorCache(): void {
+  for (const translator of translatorCache.values()) {
+    try {
+      translator.destroy?.();
+    } catch {
+      // Ignore cleanup errors
+    }
+  }
+  translatorCache.clear();
+}
+
+export function collectTranslatableElements(
+  root: ParentNode = document,
+  scope: TranslationScope = 'all'
+): HTMLElement[] {
+  const elements = new Set<HTMLElement>();
+
+  const addElement = (el: Element | null) => {
+    if (!(el instanceof HTMLElement)) return;
+    if (el.tagName === 'SCRIPT' || el.tagName === 'STYLE') return;
+    const text = (el.getAttribute('data-original-text') ?? el.textContent ?? '').trim();
+    if (!text) return;
+    elements.add(el);
+  };
+
+  if (scope === 'all' || scope === 'article') {
+    const articleContainers = root.querySelectorAll('[data-translatable-article]');
+    articleContainers.forEach((articleEl) => {
+      articleEl
+        .querySelectorAll('[data-translate-role]')
+        .forEach((el) => addElement(el));
+      articleEl
+        .querySelectorAll(
+          '[data-translate-article-body] p, [data-translate-article-body] h1, [data-translate-article-body] h2, [data-translate-article-body] h3, [data-translate-article-body] h4, [data-translate-article-body] h5, [data-translate-article-body] h6, [data-translate-article-body] li, [data-translate-article-body] blockquote, [data-translate-article-body] figcaption'
+        )
+        .forEach((el) => addElement(el));
+    });
+  }
+
+  if (scope === 'all' || scope === 'teasers') {
+    if (
+      root instanceof HTMLElement &&
+      root.hasAttribute('data-translatable-teaser')
+    ) {
+      root
+        .querySelectorAll('[data-translate-role]')
+        .forEach((el) => addElement(el));
+    }
+
+    root
+      .querySelectorAll('[data-translatable-teaser] [data-translate-role]')
+      .forEach((el) => addElement(el));
+
+    if (scope === 'all') {
+      root
+        .querySelectorAll('[data-translate-role="section-title"]')
+        .forEach((el) => addElement(el));
+    }
+  }
+
+  // Also support translating directly inside a specific element passed as root
+  if (
+    elements.size === 0 &&
+    root instanceof HTMLElement &&
+    root !== document.body &&
+    root !== document.documentElement
+  ) {
+    root.querySelectorAll('[data-translate-role]').forEach((el) => addElement(el));
+  }
+
+  return Array.from(elements);
+}
+
+interface TextSegmentEntry {
+  node: Text;
+  original: string;
+}
+
+const elementTextSegmentsMap = new WeakMap<HTMLElement, TextSegmentEntry[]>();
+
+function getTextSegments(el: HTMLElement): TextSegmentEntry[] {
+  const existing = elementTextSegmentsMap.get(el);
+  if (existing && existing.every((entry) => el.contains(entry.node))) {
+    return existing;
+  }
+
+  const entries: TextSegmentEntry[] = [];
+  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const parent = node.parentElement;
+      if (!parent) return NodeFilter.FILTER_REJECT;
+      if (parent.tagName === 'SCRIPT' || parent.tagName === 'STYLE') {
+        return NodeFilter.FILTER_REJECT;
+      }
+      if (!(node.nodeValue ?? '').trim()) {
+        return NodeFilter.FILTER_REJECT;
+      }
+      return NodeFilter.FILTER_ACCEPT;
+    },
+  });
+
+  let current = walker.nextNode();
+  while (current) {
+    if (current instanceof Text) {
+      entries.push({
+        node: current,
+        original: current.nodeValue ?? '',
+      });
+    }
+    current = walker.nextNode();
+  }
+
+  elementTextSegmentsMap.set(el, entries);
+  return entries;
+}
+
+export async function translateSingleElement(
+  el: HTMLElement,
+  translator: BrowserTranslatorInstance,
+  sourceLanguage: string,
+  targetLanguage: string,
+  signal?: AbortSignal
+): Promise<void> {
+  if (!el.hasAttribute('data-original-text')) {
+    el.setAttribute('data-original-text', el.textContent ?? '');
+  }
+  if (!el.hasAttribute('data-original-lang')) {
+    el.setAttribute('data-original-lang', el.getAttribute('lang') || 'en');
+  }
+
+  const currentTranslatedLang = el.getAttribute('data-translated-lang') || 'en';
+  const useCurrentTextAsSource =
+    sourceLanguage !== 'en' && currentTranslatedLang === sourceLanguage;
+
+  const hasChildElements = el.children.length > 0;
+
+  if (!hasChildElements) {
+    const sourceText = useCurrentTextAsSource
+      ? (el.textContent ?? '').trim()
+      : (el.getAttribute('data-original-text') ?? el.textContent ?? '').trim();
+
+    if (!sourceText) return;
+
+    const translated = await translator.translate(sourceText, { signal });
+    if (signal?.aborted) return;
+
+    el.textContent = translated;
+  } else {
+    const segments = getTextSegments(el);
+    for (const seg of segments) {
+      const rawText = useCurrentTextAsSource
+        ? seg.node.nodeValue ?? ''
+        : seg.original;
+      const trimmed = rawText.trim();
+      if (!trimmed) continue;
+
+      const leadingWhitespace = rawText.match(/^\s*/)?.[0] ?? '';
+      const trailingWhitespace = rawText.match(/\s*$/)?.[0] ?? '';
+
+      const translated = await translator.translate(trimmed, { signal });
+      if (signal?.aborted) return;
+
+      seg.node.nodeValue = `${leadingWhitespace}${translated}${trailingWhitespace}`;
+    }
+  }
+
+  el.setAttribute('lang', targetLanguage);
+  el.setAttribute('dir', getLanguageDir(targetLanguage));
+  el.setAttribute('data-translated-lang', targetLanguage);
+}
+
+export function restoreElementToOriginal(el: HTMLElement): void {
+  const segments = elementTextSegmentsMap.get(el);
+  if (segments && el.children.length > 0) {
+    for (const seg of segments) {
+      seg.node.nodeValue = seg.original;
+    }
+  } else if (el.hasAttribute('data-original-text')) {
+    el.textContent = el.getAttribute('data-original-text') ?? '';
+  }
+
+  const originalLang = el.getAttribute('data-original-lang') || 'en';
+  if (originalLang === 'en') {
+    el.removeAttribute('lang');
+    el.removeAttribute('dir');
+  } else {
+    el.setAttribute('lang', originalLang);
+    el.setAttribute('dir', getLanguageDir(originalLang));
+  }
+  el.removeAttribute('data-translated-lang');
+}
+
+export function restoreElementsInContainer(
+  root: ParentNode = document,
+  scope: TranslationScope = 'all',
+  updateGlobal = true
+): void {
+  const elements = collectTranslatableElements(root, scope);
+  elements.forEach((el) => restoreElementToOriginal(el));
+
+  if (root === document && scope === 'all') {
+    document
+      .querySelectorAll<HTMLElement>('[data-translated-lang]')
+      .forEach((el) => restoreElementToOriginal(el));
+  }
+
+  if (updateGlobal) {
+    const remainingTranslated =
+      typeof document !== 'undefined'
+        ? document.querySelectorAll('[data-translated-lang]').length
+        : 0;
+    updateGlobalTranslationState({
+      isTranslated: remainingTranslated > 0,
+      isTranslating: false,
+      translatedCount: 0,
+      totalCount: 0,
+      downloadProgress: null,
+      error: null,
+    });
+  }
+}
+
+export async function translateElementsInContainer(options: {
+  root?: ParentNode;
+  scope?: TranslationScope;
+  sourceLanguage: string;
+  targetLanguage: string;
+  signal?: AbortSignal;
+  onProgress?: (completed: number, total: number) => void;
+  onDownloadProgress?: (progress: number) => void;
+  onDetectedLanguage?: (detectedCode: string) => void;
+  updateGlobal?: boolean;
+}): Promise<{ resolvedSourceLanguage: string; translatedCount: number }> {
+  const {
+    root = document,
+    scope = 'all',
+    sourceLanguage,
+    targetLanguage,
+    signal,
+    onProgress,
+    onDownloadProgress,
+    onDetectedLanguage,
+    updateGlobal = true,
+  } = options;
+
+  const elements = collectTranslatableElements(root, scope);
+  if (elements.length === 0) {
+    return {
+      resolvedSourceLanguage: sourceLanguage === 'auto' ? 'en' : sourceLanguage,
+      translatedCount: 0,
+    };
+  }
+
+  if (updateGlobal) {
+    updateGlobalTranslationState({
+      sourceLanguage,
+      targetLanguage,
+      isTranslating: true,
+      translatedCount: 0,
+      totalCount: elements.length,
+      downloadProgress: null,
+      error: null,
+    });
+  }
+
+  try {
+    let resolvedSource = sourceLanguage;
+    if (sourceLanguage === 'auto') {
+      const sampleEl = elements[0];
+      const sampleText =
+        sampleEl.getAttribute('data-original-text') ??
+        sampleEl.textContent ??
+        '';
+      resolvedSource = await detectLanguageOnDevice(
+        sampleText,
+        onDownloadProgress,
+        signal
+      );
+      onDetectedLanguage?.(resolvedSource);
+    }
+
+    if (resolvedSource === targetLanguage) {
+      restoreElementsInContainer(root, scope, updateGlobal);
+      return { resolvedSourceLanguage: resolvedSource, translatedCount: 0 };
+    }
+
+    const translator = await getOrCreateTranslator({
+      sourceLanguage: resolvedSource,
+      targetLanguage,
+      onDownloadProgress: (percent) => {
+        onDownloadProgress?.(percent);
+        if (updateGlobal) {
+          updateGlobalTranslationState({ downloadProgress: percent });
+        }
+      },
+      signal,
+    });
+
+    if (updateGlobal) {
+      updateGlobalTranslationState({ downloadProgress: null });
+    }
+
+    let completed = 0;
+    for (const el of elements) {
+      if (signal?.aborted) {
+        throw new DOMException('Translation aborted', 'AbortError');
+      }
+      await translateSingleElement(
+        el,
+        translator,
+        resolvedSource,
+        targetLanguage,
+        signal
+      );
+      completed += 1;
+      onProgress?.(completed, elements.length);
+      if (updateGlobal) {
+        updateGlobalTranslationState({
+          translatedCount: completed,
+          totalCount: elements.length,
+        });
+      }
+    }
+
+    if (updateGlobal) {
+      updateGlobalTranslationState({
+        sourceLanguage,
+        targetLanguage,
+        isTranslated: true,
+        isTranslating: false,
+        translatedCount: completed,
+        totalCount: elements.length,
+        downloadProgress: null,
+        error: null,
+      });
+    }
+
+    return {
+      resolvedSourceLanguage: resolvedSource,
+      translatedCount: completed,
+    };
+  } catch (err: any) {
+    if (err?.name === 'AbortError') {
+      if (updateGlobal) {
+        updateGlobalTranslationState({
+          isTranslating: false,
+          downloadProgress: null,
+        });
+      }
+      throw err;
+    }
+
+    const message =
+      err instanceof Error
+        ? err.message
+        : 'An unexpected error occurred during on-device translation.';
+    if (updateGlobal) {
+      updateGlobalTranslationState({
+        isTranslating: false,
+        downloadProgress: null,
+        error: message,
+      });
+    }
+    throw err;
+  }
+}

