+  --color-on-accent: #ffffff;
+  --color-text-default: #374151;
+  --color-border-subtle: #e5e7eb;
+  --surface-bg-default: #ffffff;
+  --radius-sm: 0.25rem;
+  --radius-md: 0.375rem;
+  --radius-pill: 9999px;
+  --space-2xs: 0.25rem;
+  --space-xs: 0.375rem;
+  --space-sm: 0.5rem;
+  --space-md: 0.75rem;
+  --space-lg: 1rem;
+  --text-xs: 0.75rem;
+  --text-sm: 0.875rem;
+  --border-thin: 1px;
