+}
+
 .font-brand {
   font-family: "Grenze", serif;
   font-weight: 500;
   font-style: normal;
-}
\ No newline at end of file
+}
+
+/* 1. Set the semantic context on featured layout containers (no container-type needed for style queries) */
+.featured,
+[data-surface="featured"] {
+  --surface: featured;
+}
+
+/* 2. Default subtle component presentation */
+.teaser-card {
+  background: var(--surface-bg-default);
+  border: var(--border-thin) solid var(--color-border-subtle);
+  border-radius: var(--radius-md);
+}
+
+.badge {
+  /* Default: Hidden — only revealed in featured surfaces */
+  display: none;
+  align-items: center;
+  gap: var(--space-2xs);
+  padding-block: var(--space-2xs);
+  padding-inline: var(--space-sm);
+  border-radius: var(--radius-pill);
+  background: var(--brand-accent);
+  color: var(--color-on-accent);
+  font-size: var(--text-xs);
+  font-weight: 700;
+  letter-spacing: 0.05em;
+  text-transform: uppercase;
+  width: fit-content;
+}
+
+.button {
+  /* Default: Outlined subtle style */
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: var(--space-xs);
+  padding-block: var(--space-xs);
+  padding-inline: var(--space-md);
+  border-radius: var(--radius-md);
+  background: transparent;
+  color: var(--color-text-default);
+  border: var(--border-thin) solid currentColor;
+  font-size: var(--text-xs);
+  font-weight: 600;
+  line-height: 1.25;
+  cursor: pointer;
+  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
+}
+
+.button:hover:not(:disabled) {
+  color: var(--brand-accent);
+  border-color: currentColor;
+}
+
+/* 3. Selector-based contextual fallback — broad browser support with zero added specificity on container */
+:where(.featured, [data-surface="featured"]) .teaser-card {
+  background: var(--brand-accent-subtle);
+  border-color: var(--brand-accent-border);
+}
+
+:where(.featured, [data-surface="featured"]) .badge {
+  display: inline-flex;
+}
+
+:where(.featured, [data-surface="featured"]) .button {
+  background: var(--brand-accent);
+  color: var(--color-on-accent);
+  border-color: transparent;
+}
+
+:where(.featured, [data-surface="featured"]) .button:hover:not(:disabled) {
+  background: var(--brand-accent-hover);
+  color: var(--color-on-accent);
+}
+
+/* 4. Progressive enhancement: container style queries override when supported */
+@container style(--surface: featured) {
+  .teaser-card {
+    background: var(--brand-accent-subtle);
+    border-color: var(--brand-accent-border);
+  }
+
+  .badge {
+    /* Reveal promotional badge only in featured context */
+    display: inline-flex;
+  }
+
+  .button {
+    /* Automatic switch to Filled promotional style */
+    background: var(--brand-accent);
+    color: var(--color-on-accent);
+    border-color: transparent;
+  }
+
+  .button:hover:not(:disabled) {
+    background: var(--brand-accent-hover);
+    color: var(--color-on-accent);
+  }
+}

