+}
+
+/* Semantic section contexts (Default / Standard vs. Featured) */
+section,
+.standard-section,
+.default-section,
+[data-context="default"],
+[data-context="standard"],
+[data-variant="default"],
+[data-variant="standard"],
+[data-section="standard"],
+[data-section="default"],
+[data-featured="false"] {
+  container-name: section;
+  --section-context: default;
+  --context: default;
+  --variant: default;
+  --theme: default;
+  --featured: false;
+}
+
+.featured-section,
+.section-featured,
+[data-context="featured"],
+[data-variant="featured"],
+[data-section="featured"],
+[data-theme="featured"],
+[data-featured="true"] {
+  container-name: section;
+  --section-context: featured;
+  --context: featured;
+  --variant: featured;
+  --theme: featured;
+  --featured: true;
+}
+
+/* Subtle default presentation for article teaser cards */
+.article-teaser,
+.teaser-card {
+  background-color: #ffffff;
+  border: 1px solid #e5e7eb;
+  border-radius: 0.5rem;
+  box-shadow: none;
+  padding: 1rem;
+  transition: background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
+}
+
+/* Promotional badge: hidden by default in standard sections */
+.promo-badge,
+.promotional-badge {
+  display: none;
+  align-items: center;
+  gap: 0.25rem;
+  width: fit-content;
+  padding: 0.125rem 0.625rem;
+  border-radius: 9999px;
+  font-size: 0.75rem;
+  line-height: 1.25rem;
+  font-weight: 700;
+  letter-spacing: 0.05em;
+  text-transform: uppercase;
+  background-color: #f59e0b;
+  color: #111827;
+}
+
+/* Action buttons: subtle outlined styling by default in standard sections */
+.action-button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 0.375rem;
+  padding: 0.375rem 0.75rem;
+  border-radius: 0.375rem;
+  font-size: 0.75rem;
+  line-height: 1rem;
+  font-weight: 600;
+  background-color: transparent;
