+  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
+}
+
+.action-button:hover {
+  background-color: #f3f4f6;
+  border-color: #4b5563;
+  color: #111827;
+}
+
+/* Prominent featured presentation via parent semantic context selectors */
+:where(
+  .featured-section,
+  .section-featured,
+  [data-context="featured"],
+  [data-variant="featured"],
+  [data-section="featured"],
+  [data-theme="featured"],
+  [data-featured="true"]
+) :is(.article-teaser, .teaser-card) {
