+    const key = pair.slice(0, idx).trim();
+    const val = pair.slice(idx + 1).trim();
+    if (key) cookies[key] = decodeURIComponent(val);
+  }
+  return cookies;
+}
+
+/**
+ * Atomically reads and deletes the single-use nonce from server-side session state.
+ */
+export async function consumeSessionNonce(requestOrHeaders) {
+  const cookieHeader =
+    typeof requestOrHeaders?.headers?.get === 'function'
+      ? requestOrHeaders.headers.get('cookie') || ''
+      : requestOrHeaders?.headers?.cookie || '';
+  const cookies = parseCookies(cookieHeader);
+  const sessionId = cookies[SESSION_COOKIE_NAME];
+  if (!sessionId) return null;
+
+  const entry = sessionNonceStore.get(sessionId);
+  // Immediately delete so an intercepted token cannot be replayed
+  sessionNonceStore.delete(sessionId);
+
+  if (!entry) return null;
+  if (Date.now() - entry.createdAt > NONCE_TTL_MS) {
+    return null;
+  }
+  return entry.nonce;
+}
+
+/**
+ * Verifies an Email Verification Protocol (EVP) SD-JWT presentation (`EVT + KB-JWT`)
+ * strictly on the server using `@sd-jwt/core` and `jose`.
+ */
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience = RP_ORIGIN,
+  dnsResolver = dns,
+  fetchImpl = fetch,
+  jwksLoader = createRemoteJWKSet,
+}) {
+  // Step 1: Parse the SD-JWT claims and validate the email address
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded?.jwt?.payload;
+  const iss = evtPayload?.iss;
+
+  if (!expectedNonce || !decoded?.kbJwt || !iss || evtPayload?.email_verified !== true) {
+    throw new Error('Missing nonce, KB-JWT, issuer, or email_verified !== true.');
+  }
+
+  // MANDATORY: Compare email addresses case-insensitively while preserving the submitted email string
+  if (evtPayload.email?.toLowerCase() !== submittedEmail.toLowerCase()) {
+    throw new Error('Submitted email does not match the EVT email claim.');
+  }
+
+  // Step 2: Validate DNS TXT delegation and load the issuer JWKS
+  const domain = submittedEmail.split('@')[1];
+  if (!domain) {
+    throw new Error('Submitted email is missing a valid domain.');
+  }
+
+  const txtRecords = (await dnsResolver.resolveTxt(`_email-verification.${domain}`)).map((r) =>
+    r.join('')
+  );
+  if (
+    !txtRecords.some(
+      (txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss
+    )
+  ) {
+    throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+  }
+
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  if (discoveryUrl.protocol !== 'https:') {
+    throw new Error('Issuer must use HTTPS.');
+  }
+
+  const metadataResponse = await fetchImpl(discoveryUrl);
+  if (!metadataResponse.ok) {
+    throw new Error(`Failed to fetch issuer metadata (${metadataResponse.status}).`);
+  }
+  const metadata = await metadataResponse.json();
+  if (metadata.issuer !== iss || !metadata.jwks_uri?.startsWith('https://')) {
+    throw new Error('Invalid issuer metadata or non-HTTPS jwks_uri.');
+  }
+
+  const issuerJwks = jwksLoader(new URL(metadata.jwks_uri));
+
+  // Step 3: Verify the EVT signature and Key Binding JWT (KB-JWT)
+  const evtOptions = {
+    typ: 'ev+sd-jwt',
+    issuer: iss,
+    algorithms: ALLOWED_ALGS,
+    maxTokenAge: '5m',
+    clockTolerance: '1m',
+  };
+
+  const sdJwt = new SDJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const compactEvt = `${data}.${sig}`;
+      try {
+        await jwtVerify(compactEvt, issuerJwks, evtOptions);
+      } catch (err) {
+        // When `kid` is omitted (e.g. Gmail) and multiple keys match in the JWKS,
+        // jose throws JWKSMultipleMatchingKeys, which yields each matching CryptoKey.
+        if (err?.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw err;
+        let matched = false;
+        for await (const publicKey of err) {
+          try {
+            await jwtVerify(compactEvt, publicKey, evtOptions);
+            matched = true;
+            break;
+          } catch {}
+        }
+        if (!matched) throw err;
+      }
+      return true;
+    },
+    kbVerifier: async (data, sig) => {
+      const holderJwk = evtPayload.cnf?.jwk;
+      const holderAlg = holderJwk?.alg;
+      const kbAlg = decoded.kbJwt.header.alg;
+      if (
+        !holderAlg ||
+        !kbAlg ||
+        !ALLOWED_ALGS.includes(holderAlg) ||
+        !ALLOWED_ALGS.includes(kbAlg) ||
+        normalizeAlg(kbAlg) !== normalizeAlg(holderAlg)
+      ) {
+        throw new Error('Missing, disallowed, or mismatched KB-JWT algorithm.');
+      }
+      const holderKey = await importJWK(holderJwk, kbAlg);
+      await jwtVerify(`${data}.${sig}`, holderKey, {
+        typ: 'kb+jwt',
+        audience: expectedAudience,
+        algorithms: [kbAlg],
+        maxTokenAge: '5m',
+        clockTolerance: '1m',
+      });
+      return true;
+    },
+  });
+
+  const verified = await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'],
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    keyBindingMaxAgeSeconds: 300,
+    skewSeconds: 60,
+  });
+
+  return verified;
+}
+
+/**
+ * Completes fast-path account creation when email ownership is cryptographically verified via EVP.
+ * Still queues a transactional welcome email (EVP proves account ownership, not inbox deliverability).
+ */
+export function completeAccountCreation(submittedEmail, submittedName = '') {
+  return {
+    ok: true,
+    verified: true,
+    verificationMethod: 'email-verification-protocol',
+    email: submittedEmail,
+    name: submittedName,
+    welcomeEmailQueued: true,
+    message: `Welcome to Daily Grind Rewards! Your email (${submittedEmail}) was verified instantly by your browser.`,
+  };
+}
+
+/**
+ * Fallback path when the browser does not provide an EVP token or verification fails:
+ * degrades gracefully to sending a standard verification email without blocking registration.
+ */
+export function sendTraditionalVerificationEmail(submittedEmail, submittedName = '') {
+  return {
+    ok: true,
+    verified: false,
+    verificationMethod: 'traditional-email-fallback',
+    email: submittedEmail,
+    name: submittedName,
+    message: `Almost done! We created your pending Daily Grind Rewards account and sent a confirmation email to ${submittedEmail}.`,
+  };
+}
+
+/**
+ * Standard Fetch API Request handler for form submission (compatible with Web Request / FormData).
+ */
+export async function handleSignupSubmission(request, options = {}) {
+  const formData = await request.formData();
+  const submittedName = String(formData.get('name') || '').trim();
+  const submittedEmail = String(formData.get('email') || '').trim();
+  const rawToken = String(formData.get('token') || '').trim();
+
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = await consumeSessionNonce(request);
+
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience: options.expectedAudience || RP_ORIGIN,
+        ...options,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      return completeAccountCreation(submittedEmail, submittedName);
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+    }
+  }
+
+  // Fallback path: send standard OTP code or magic link email to submittedEmail.
+  return sendTraditionalVerificationEmail(submittedEmail, submittedName);
+}
+
+/**
+ * Renders index.html with a freshly generated per-render cryptographic nonce.
+ */
+export async function renderHomepageWithNonce(nonce) {
+  const htmlPath = path.join(__dirname, 'index.html');
+  const template = await readFile(htmlPath, 'utf8');
+  return template
+    .replaceAll('SERVER_GENERATED_PER_FORM_NONCE', nonce)
+    .replaceAll('YOUR_ORIGIN_TRIAL_TOKEN', ORIGIN_TRIAL_TOKEN);
+}
+
+/**
+ * Parses URL-encoded or JSON body from a Node http.IncomingMessage.
+ */
+async function readRequestBody(req) {
+  const chunks = [];
+  for await (const chunk of req) {
+    chunks.push(chunk);
+  }
+  const raw = Buffer.concat(chunks).toString('utf8');
+  const contentType = req.headers['content-type'] || '';
+  if (contentType.includes('application/json')) {
+    try {
+      return JSON.parse(raw);
+    } catch {
+      return {};
+    }
+  }
+  const params = new URLSearchParams(raw);
+  return Object.fromEntries(params.entries());
+}
+
+/**
+ * Node HTTP server serving the homepage with per-render nonces and handling POST /api/verify-email.
+ */
+export function createAppServer() {
+  return http.createServer(async (req, res) => {
+    const url = new URL(req.url || '/', RP_ORIGIN);
+
+    // Issue a fresh nonce when the client requests one or loads the homepage
+    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+      const cookies = parseCookies(req.headers.cookie || '');
+      const { sessionId, nonce } = createSessionNonce(cookies[SESSION_COOKIE_NAME]);
+      const html = await renderHomepageWithNonce(nonce);
+
+      res.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-store',
+        'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        'Set-Cookie': `${SESSION_COOKIE_NAME}=${encodeURIComponent(
+          sessionId
+        )}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+      });
+      res.end(html);
+      return;
+    }
+
+    if (req.method === 'GET' && url.pathname === '/api/verify-email/nonce') {
+      const cookies = parseCookies(req.headers.cookie || '');
+      const { sessionId, nonce } = createSessionNonce(cookies[SESSION_COOKIE_NAME]);
+      res.writeHead(200, {
+        'Content-Type': 'application/json; charset=utf-8',
+        'Cache-Control': 'no-store',
+        'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        'Set-Cookie': `${SESSION_COOKIE_NAME}=${encodeURIComponent(
+          sessionId
+        )}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+      });
+      res.end(JSON.stringify({ nonce }));
+      return;
+    }
+
+    if (req.method === 'POST' && url.pathname === '/api/verify-email') {
+      const body = await readRequestBody(req);
+      const submittedName = String(body.name || '').trim();
+      const submittedEmail = String(body.email || '').trim();
+      const submittedPassword = String(body['new-password'] || '');
+      const rawToken = String(body.token || '').trim();
+
+      // Atomically consume the single-use session nonce even if input validation fails
+      const expectedNonce = await consumeSessionNonce(req);
+
+      if (!submittedEmail || !submittedEmail.includes('@') || submittedPassword.length < 8) {
+        res.writeHead(400, {
+          'Content-Type': 'application/json; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            error: 'Please provide a valid email address and a password of at least 8 characters.',
+          })
+        );
+        return;
+      }
+
+      const requestOrigin = req.headers.origin || RP_ORIGIN;
+      let result;
+
+      if (rawToken && expectedNonce) {
+        try {
+          await verifyEmailVerificationToken({
+            rawToken,
+            submittedEmail,
+            expectedNonce,
+            expectedAudience: requestOrigin,
+          });
+          result = completeAccountCreation(submittedEmail, submittedName);
+        } catch (err) {
+          console.error('Email verification token check failed:', err);
+          result = sendTraditionalVerificationEmail(submittedEmail, submittedName);
+        }
+      } else {
+        result = sendTraditionalVerificationEmail(submittedEmail, submittedName);
+      }
+
+      const accept = req.headers.accept || '';
+      if (accept.includes('application/json')) {
+        res.writeHead(200, {
+          'Content-Type': 'application/json; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+        res.end(JSON.stringify(result));
+      } else {
+        // Standard HTML response when submitted without AJAX
+        res.writeHead(200, {
+          'Content-Type': 'text/html; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+        res.end(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Rewards Registration | The Daily Grind</title>
+</head>
+<body style="font-family: system-ui, sans-serif; max-width: 600px; margin: 3rem auto; padding: 0 1.5rem; color: #3e2723;">
+  <h1>${result.verified ? 'Rewards Account Verified!' : 'Check Your Inbox'}</h1>
+  <p>${result.message.replace(/[<>&"']/g, '')}</p>
+  <p><a href="/" style="color: #4e342e; font-weight: 600;">Return to The Daily Grind homepage</a></p>
+</body>
+</html>`);
+      }
+      return;
+    }
+
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not Found');
+  });
+}
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  const server = createAppServer();
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on ${RP_ORIGIN}`);
+  });
+}

