1/visually-stable-mixed-fonts/task/guide:
diff --git a/index.html b/index.html
--- a/index.html
+++ b/index.html
@@ -0,0 +1,169 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Visually Stable Mixed Fonts &amp; Independent Theme Proportions</title>
+  <link rel="stylesheet" href="styles.css">
+  <style>
+    :root {
+      --bg-primary: #f8fafc;
+      --surface-bg: #ffffff;
+      --text-primary: #0f172a;
+      --text-muted: #475569;
+      --code-bg: #f1f5f9;
+      --code-border: #cbd5e1;
+      --code-text: #0f766e;
+      --theme-bg: #1e293b;
+      --theme-text: #f8fafc;
+      --theme-accent: #38bdf8;
+      --border-color: #e2e8f0;
+    }
+
+    *,
+    *::before,
+    *::after {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      padding: 2rem 1.25rem;
+      background-color: var(--bg-primary);
+      color: var(--text-primary);
+      font-family: Verdana, Geneva, Tahoma, sans-serif;
+      font-size: 1rem;
+      line-height: 1.6;
+      text-align: start;
+      overflow-wrap: break-word;
+    }
+
+    main {
+      max-width: 65ch;
+      margin-inline: auto;
+      display: flex;
+      flex-direction: column;
+      gap: 2rem;
+    }
+
+    h1,
+    h2 {
+      text-wrap: balance;
+      line-height: 1.25;
+      margin-block: 0 0.75rem;
+    }
+
+    h1 {
+      font-size: clamp(1.5rem, 1.2rem + 1.5vw, 2.25rem);
+    }
+
+    h2 {
+      font-size: clamp(1.2rem, 1rem + 0.8vw, 1.5rem);
+    }
+
+    p {
+      text-wrap: pretty;
+      margin-block: 0 1rem;
+    }
+
+    p:last-child {
+      margin-block-end: 0;
+    }
+
+    /* Mixed fonts container: automatically normalizes x-height across mixed font families */
+    #mixed-fonts-container {
+      font-family: Verdana, Geneva, Tahoma, sans-serif;
+      font-size: 1rem;
+      line-height: 1.6;
+      font-size-adjust: from-font;
+      background-color: var(--surface-bg);
+      border: 1px solid var(--border-color);
+      border-radius: 0.5rem;
+      padding: 1.5rem;
+    }
+
+    #mixed-fonts-container code {
+      font-family: "Courier New", Courier, monospace;
+      background-color: var(--code-bg);
+      color: var(--code-text);
+      border: 1px solid var(--code-border);
+      border-radius: 0.25rem;
+      padding: 0.1em 0.35em;
+    }
+
+    /* Independent theme container: locks down visual proportions with a specific numeric metric override */
+    #independent-theme-container {
+      font-family: "Times New Roman", Times, Georgia, serif;
+      font-size: 1rem;
+      line-height: 1.6;
+      font-size-adjust: 0.52;
+      background-color: var(--theme-bg);
+      color: var(--theme-text);
+      border: 1px solid var(--theme-accent);
+      border-radius: 0.5rem;
+      padding: 1.5rem;
+    }
+
+    #independent-theme-container code {
+      font-family: "Courier New", Courier, monospace;
+      background-color: rgba(56, 189, 248, 0.15);
+      color: var(--theme-accent);
+      border-radius: 0.25rem;
+      padding: 0.1em 0.35em;
+    }
+
+    /* Fallback for browsers that do not support font-size-adjust */
+    @supports not (font-size-adjust: from-font) {
+      #mixed-fonts-container {
+        font-size: 1rem;
+        line-height: 1.65;
+      }
+
+      #mixed-fonts-container code {
+        font-size: 1.12em;
+        line-height: 1.4;
+      }
+
+      #independent-theme-container {
+        font-size: 1.14rem;
+        line-height: 1.6;
+      }
+
+      #independent-theme-container code {
+        font-size: 0.98em;
+        line-height: 1.4;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <header>
+      <h1>Typography Metric Normalization</h1>
+      <p>
+        Demonstrating visually stable mixed font families and independent theme typography proportions using modern CSS <code>font-size-adjust</code>.
+      </p>
+    </header>
+
+    <section id="mixed-fonts-container" aria-labelledby="mixed-fonts-heading">
+      <h2 id="mixed-fonts-heading">Mixed Fonts Block (Automatic Normalization)</h2>
+      <p>
+        When mixing proportional body text with inline code such as <code>const ratio = getComputedStyle(el).fontSizeAdjust</code> or <code>font-size-adjust: from-font</code>, differences in lowercase x-height can make monospace spans look disproportionately small next to sans-serif text.
+      </p>
+      <p>
+        Applying <code>font-size-adjust: from-font</code> on <code>#mixed-fonts-container</code> instructs the browser to extract the primary font's x-height aspect ratio and automatically normalize nested <code>&lt;code&gt;</code> elements like <code>document.querySelector('#mixed-fonts-container')</code> to match its visual height.
+      </p>
+    </section>
+
+    <section id="independent-theme-container" aria-labelledby="independent-theme-heading">
+      <h2 id="independent-theme-heading">Independent Theme Container (Numeric Metric Override)</h2>
+      <p>
+        This standalone theme container uses a classical serif font stack (<code>Times New Roman</code>, <code>Georgia</code>, <code>serif</code>) that does not inherit its typographic metrics from the primary sans-serif container.
+      </p>
+      <p>
+        By specifying a numeric aspect-ratio override with <code>font-size-adjust: 0.52</code>, its lowercase x-height is explicitly locked to <code>0.52</code> of the font size, keeping visual proportions consistent across themes and fallback swaps.
+      </p>
+    </section>
+  </main>
+</body>
+</html>

