+        img.alt = `${drinkName} served fresh`;
+        img.hidden = false;
+      } else {
+        img.hidden = true;
+      }
+    }
+
+    if (roastPill) {
+      roastPill.textContent = `${this.roast} roast`;
+    }
+
+    if (caloriesDisplay) {
+      caloriesDisplay.textContent =
+        this.calories > 0 ? `${this.calories} cal` : 'Artisanal brew';
+    }
+
+    this.#updatePriceDisplay();
+
+    const isFav = this.favorited;
+    this.#setState('favorited', isFav);
+    if (favBtn) {
+      favBtn.setAttribute('aria-pressed', String(isFav));
+      favBtn.disabled = this.disabled;
+    }
+    if (favText) {
+      favText.textContent = isFav ? 'Saved' : 'Save';
+    }
+    if (favSrContext) {
+      favSrContext.textContent = ` ${drinkName}`;
+    }
+
+    if (orderBtn) {
+      orderBtn.disabled = this.disabled;
+    }
+    if (orderSrContext) {
