+
+export class CoffeeCart extends HTMLElement {
+  #internals;
+  #items = [];
+  #ecoDiscount = false;
+  #initialized = false;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals ? this.attachInternals() : null;
+    if (!this.shadowRoot) {
+      this.attachShadow({ mode: 'open' });
+      this.shadowRoot.append(cartTemplate.content.cloneNode(true));
+    }
+    this.shadowRoot.adoptedStyleSheets = [cartSheet];
+  }
+
+  connectedCallback() {
+    if (!this.#initialized) {
+      this.#bindEvents();
+      this.#initialized = true;
+    }
+    this.#render();
