+
+  connectedMoveCallback() {}
+
+  get items() {
+    return [...this.#items];
+  }
+
+  get ecoDiscount() {
+    return this.#ecoDiscount;
+  }
+  set ecoDiscount(val) {
+    this.#ecoDiscount = Boolean(val);
+    this.#render();
+  }
+
+  addItem(item) {
+    this.#items.push({
+      id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
+      name: item.name || 'Coffee',
+      size: item.size || 'M',
+      price: Number(item.price) || 0,
+    });
+    this.#render();
+  }
+
+  open() {
+    const dialog = this.shadowRoot.getElementById('cart-dialog');
+    if (dialog && typeof dialog.showModal === 'function' && !dialog.open) {
