+    if (dialog?.open) {
+      dialog.close();
+    }
+  }
+
+  #bindEvents() {
+    const openBtn = this.shadowRoot.getElementById('open-cart-btn');
+    const closeBtn = this.shadowRoot.getElementById('close-cart-btn');
+    const dialog = this.shadowRoot.getElementById('cart-dialog');
+    const list = this.shadowRoot.getElementById('cart-items');
