+      <button type="button" data-roast="dark" aria-pressed="false">Dark Roast</button>
+      <button type="button" data-roast="cold" aria-pressed="false">Cold Steeped</button>
+      <button type="button" data-roast="favorites" aria-pressed="false">Saved Favorites</button>
+    </div>
+    <div class="controls-right">
+      <div class="search-wrap">
+        <label for="drink-search">Filter menu</label>
+        <input id="drink-search" part="search-input" type="search" placeholder="e.g. Maple, Espresso">
+      </div>
+      <div id="filter-status" class="status" role="status" aria-live="polite">Showing all 3 drinks</div>
+    </div>
+  </div>
+`;
+
+export class CoffeeFilter extends HTMLElement {
+  static observedAttributes = ['active-filter', 'query'];
+
+  #internals;
+  #activeFilter = 'all';
+  #query = '';
+  #initialized = false;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals ? this.attachInternals() : null;
+    if (!this.shadowRoot) {
+      this.attachShadow({ mode: 'open' });
+      this.shadowRoot.append(filterTemplate.content.cloneNode(true));
+    }
+    this.shadowRoot.adoptedStyleSheets = [filterSheet];
+  }
+
+  connectedCallback() {
+    if (!this.#initialized) {
+      this.#bindEvents();
+      this.#initialized = true;
+    }
+    if (this.hasAttribute('active-filter')) {
+      this.#activeFilter = this.getAttribute('active-filter') || 'all';
+    }
+    if (this.hasAttribute('query')) {
+      this.#query = this.getAttribute('query') || '';
+    }
+    this.#syncButtons();
+  }
+
+  connectedMoveCallback() {}
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal === newVal) return;
+    if (name === 'active-filter') {
+      this.#activeFilter = newVal || 'all';
+      this.#syncButtons();
+      this.#emitFilter();
+    } else if (name === 'query') {
+      this.#query = newVal || '';
+      const input = this.shadowRoot.getElementById('drink-search');
+      if (input && input.value !== this.#query) {
+        input.value = this.#query;
+      }
+      this.#emitFilter();
+    }
+  }
+
+  get activeFilter() {
+    return this.#activeFilter;
+  }
+  set activeFilter(val) {
+    this.setAttribute('active-filter', String(val || 'all'));
+  }
+
+  get query() {
+    return this.#query;
+  }
+  set query(val) {
+    if (val) {
+      this.setAttribute('query', String(val));
+    } else {
+      this.removeAttribute('query');
+    }
+  }
+
+  updateStatus(visibleCount, totalCount) {
+    const status = this.shadowRoot.getElementById('filter-status');
+    if (status) {
+      status.textContent =
+        visibleCount === totalCount
+          ? `Showing all ${totalCount} drinks`
+          : `Showing ${visibleCount} of ${totalCount} drinks`;
+    }
+  }
+
+  #bindEvents() {
+    const pills = this.shadowRoot.querySelector('.pills');
+    const searchInput = this.shadowRoot.getElementById('drink-search');
+
+    pills?.addEventListener('click', (e) => {
+      const btn = e.target.closest('button[data-roast]');
+      if (!btn) return;
+      this.activeFilter = btn.dataset.roast || 'all';
+    });
+
+    searchInput?.addEventListener('input', (e) => {
+      this.#query = e.target.value;
+      this.#emitFilter();
+    });
+  }
+
+  #syncButtons() {
+    const buttons = this.shadowRoot.querySelectorAll('button[data-roast]');
+    for (const btn of buttons) {
+      const isMatch = btn.dataset.roast === this.#activeFilter;
+      btn.setAttribute('aria-pressed', String(isMatch));
+    }
+    if (this.#internals?.states) {
+      if (this.#activeFilter !== 'all' || this.#query.trim() !== '') {
+        this.#internals.states.add('filtering');
+      } else {
+        this.#internals.states.delete('filtering');
+      }
+    }
+  }
+
+  #emitFilter() {
+    this.dispatchEvent(
+      new CustomEvent('coffee-filter-change', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          roast: this.#activeFilter,
+          query: this.#query.trim().toLowerCase(),
+        },
+      })
+    );
+  }
+}
+
+if (!customElements.get('coffee-filter')) {
+  customElements.define('coffee-filter', CoffeeFilter);
+}
