diff --git a/components/index.js b/components/index.js
new file mode 100644
index 0000000..954f0da
--- /dev/null
+++ b/components/index.js
@@ -0,0 +1,84 @@
+import { CoffeeCard } from './coffee-card.js';
+import { CoffeeFilter } from './coffee-filter.js';
+import { GrindSelector } from './grind-selector.js';
+import { RefillSwitch } from './refill-switch.js';
+import { CoffeeCart } from './coffee-cart.js';
+
+function initHomepageInteractions() {
+  const filterBar = document.querySelector('coffee-filter');
+  const cards = Array.from(document.querySelectorAll('coffee-card'));
+  const cart = document.querySelector('coffee-cart');
+  const refillSwitch = document.querySelector('refill-switch');
+  const customizerForm = document.getElementById('bean-customizer-form');
+  const customizerStatus = document.getElementById('customizer-status');
+
+  const applyFilter = () => {
+    const activeRoast = filterBar?.activeFilter || 'all';
+    const query = (filterBar?.query || '').trim().toLowerCase();
+    let visibleCount = 0;
+
+    for (const card of cards) {
+      const cardRoast = (card.roast || '').toLowerCase();
+      const cardText = `${card.name} ${card.textContent || ''}`.toLowerCase();
+      const matchesRoast =
+        activeRoast === 'all' ||
+        (activeRoast === 'favorites' && card.favorited) ||
+        cardRoast === activeRoast;
+      const matchesQuery = !query || cardText.includes(query);
+      const isVisible = matchesRoast && matchesQuery;
+      card.hidden = !isVisible;
+      if (isVisible) visibleCount++;
+    }
+
+    filterBar?.updateStatus(visibleCount, cards.length);
+  };
+
+  document.addEventListener('coffee-filter-change', () => {
+    applyFilter();
+  });
+
+  document.addEventListener('coffee-favorite', () => {
+    if (filterBar?.activeFilter === 'favorites') {
+      applyFilter();
+    }
+  });
+
+  document.addEventListener('coffee-order', (e) => {
+    if (cart && e.detail) {
+      cart.addItem(e.detail);
+    }
+  });
+
+  refillSwitch?.addEventListener('change', () => {
+    if (cart) {
+      cart.ecoDiscount = refillSwitch.checked;
+    }
+  });
+
+  customizerForm?.addEventListener('submit', (e) => {
+    e.preventDefault();
+    const formData = new FormData(customizerForm);
+    const blend = formData.get('blend') || 'House Signature Blend';
+    const grind = formData.get('grind') || 'whole-bean';
+    const bagSize = formData.get('bagSize') || '12oz';
+    const price = bagSize === '2lb' ? 28.0 : 16.5;
+
+    cart?.addItem({
+      name: `${blend} (${grind})`,
+      size: String(bagSize),
+      price,
+    });
+
+    if (customizerStatus) {
+      customizerStatus.textContent = `Added ${bagSize} ${blend} (${grind.replace('-', ' ')}) to your order bag.`;
+    }
+  });
+}
+
+if (document.readyState === 'loading') {
+  document.addEventListener('DOMContentLoaded', initHomepageInteractions);
+} else {
+  initHomepageInteractions();
+}
+
+export { CoffeeCard, CoffeeFilter, GrindSelector, RefillSwitch, CoffeeCart };
