+  }
+
+  @layer states {
+    :host(:state(checked)) .track,
+    :host([checked]) .track {
+      background: var(--_switch-primary);
+    }
+
+    :host(:state(checked)) .thumb,
+    :host([checked]) .thumb {
+      transform: translateX(1.18rem);
+    }
+
+    :host([disabled]) {
+      opacity: 0.55;
+      pointer-events: none;
+      cursor: default;
+    }
+  }
+`);
+
+const switchTemplate = document.createElement('template');
+switchTemplate.innerHTML = `
+  <span class="track" part="track" aria-hidden="true">
+    <span class="thumb" part="thumb"></span>
+  </span>
+  <span class="label-wrap">
+    <span class="title"><slot>Bring Reusable Cup (-$0.50 &amp; +25 Stars)</slot></span>
+    <span id="state-text" class="state-text" aria-hidden="true">Off</span>
+  </span>
+`;
+
+export class RefillSwitch extends HTMLElement {
+  static observedAttributes = ['checked', 'disabled'];
+
+  #internals;
+  #initialized = false;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals ? this.attachInternals() : null;
+    if (this.#internals && 'role' in this.#internals) {
+      this.#internals.role = 'switch';
+      this.#internals.ariaChecked = 'false';
+    }
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.append(switchTemplate.content.cloneNode(true));
+    this.shadowRoot.adoptedStyleSheets = [switchSheet];
+  }
+
+  connectedCallback() {
+    if (!this.hasAttribute('tabindex')) {
+      this.tabIndex = 0;
+    }
+    if (!this.#internals || !('role' in this.#internals)) {
+      if (!this.hasAttribute('role')) this.setAttribute('role', 'switch');
+    }
+    if (!this.#initialized) {
+      this.#bindEvents();
+      this.#initialized = true;
+    }
+    this.#syncState();
+  }
+
+  connectedMoveCallback() {}
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal === newVal) return;
+    this.#syncState();
+  }
+
+  get checked() {
+    return this.hasAttribute('checked');
+  }
+  set checked(on) {
+    this.toggleAttribute('checked', Boolean(on));
+  }
+
+  get disabled() {
+    return this.hasAttribute('disabled');
+  }
+  set disabled(on) {
+    this.toggleAttribute('disabled', Boolean(on));
+  }
+
+  toggle() {
+    if (this.disabled) return;
+    this.checked = !this.checked;
+    this.dispatchEvent(
+      new Event('change', {
+        bubbles: true,
+      })
+    );
+  }
+
+  #bindEvents() {
+    this.addEventListener('click', () => this.toggle());
+    this.addEventListener('keydown', (e) => {
+      if (this.disabled) return;
+      if (e.key === 'Enter') {
+        e.preventDefault();
+        this.toggle();
+      } else if (e.key === ' ') {
+        // Prevent page scroll on keydown; toggle on keyup to match native button/switch feel
+        e.preventDefault();
+      }
+    });
+    this.addEventListener('keyup', (e) => {
+      if (this.disabled) return;
+      if (e.key === ' ') {
+        e.preventDefault();
+        this.toggle();
+      }
+    });
+  }
+
+  #syncState() {
+    const isChecked = this.checked;
+    const isDisabled = this.disabled;
+    const stateText = this.shadowRoot.getElementById('state-text');
+
+    if (this.#internals) {
+      if ('ariaChecked' in this.#internals) {
+        this.#internals.ariaChecked = String(isChecked);
+      } else {
+        this.setAttribute('aria-checked', String(isChecked));
+      }
+      if ('ariaDisabled' in this.#internals) {
+        this.#internals.ariaDisabled = String(isDisabled);
+      }
+      if (this.#internals.states) {
+        if (isChecked) {
+          this.#internals.states.add('checked');
+        } else {
+          this.#internals.states.delete('checked');
+        }
+      }
+    } else {
+      this.setAttribute('aria-checked', String(isChecked));
+    }
+
+    if (stateText) {
+      stateText.textContent = isChecked
+        ? 'Active: -$0.50 eco discount applied'
+        : 'Off';
+    }
+  }
+}
+
+if (!customElements.get('refill-switch')) {
+  customElements.define('refill-switch', RefillSwitch);
+}
