+        } else if (e.key === 'End') {
+          nextIndex = this._els.sizeBtns.length - 1;
+        }
+
+        if (nextIndex !== -1) {
+          e.preventDefault();
+          const targetBtn = this._els.sizeBtns[nextIndex];
+          this._selectedSize = targetBtn.dataset.size;
+          this._updateSizeSelection();
+          targetBtn.focus();
+          this._dispatchSizeChange();
+        }
+      });
+    });
+
+    // Expandable Tasting Notes toggle
+    this._els.detailsToggle.addEventListener('click', () => {
+      this._detailsOpen = !this._detailsOpen;
+      this._els.detailsToggle.setAttribute('aria-expanded', String(this._detailsOpen));
+      this._els.detailsPanel.hidden = !this._detailsOpen;
+
+      this.dispatchEvent(
+        new CustomEvent('coffee-details-toggle', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
+            expanded: this._detailsOpen,
+          },
+        })
+      );
+    });
+
+    this._els.detailsPanel.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape' && this._detailsOpen) {
+        e.stopPropagation();
+        this._detailsOpen = false;
+        this._els.detailsToggle.setAttribute('aria-expanded', 'false');
+        this._els.detailsPanel.hidden = true;
+        this._els.detailsToggle.focus();
+      }
+    });
+
+    // Add to Order button
+    this._els.orderBtn.addEventListener('click', () => {
+      const orderDetail = {
+        id: `${this.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${this._selectedSize.toLowerCase()}`,
+        name: this.name,
+        size: this._selectedSize,
+        price: Number(this.currentPrice.toFixed(2)),
+        formattedPrice: `$${this.currentPrice.toFixed(2)}`,
+        calories: this.currentCalories,
+        category: this.category,
+        roast: this.getAttribute('roast') || 'Medium Roast',
+        image: this.getAttribute('image') || DEFAULT_FALLBACK_IMAGE,
+        href: this.getAttribute('href') || '/menu',
+        quantity: 1,
+      };
+
+      this.dispatchEvent(
+        new CustomEvent('coffee-order', {
+          bubbles: true,
+          composed: true,
+          detail: orderDetail,
+        })
+      );
+
+      this.dispatchEvent(
+        new CustomEvent('add-to-cart', {
+          bubbles: true,
+          composed: true,
+          detail: orderDetail,
+        })
+      );
+
+      this._els.orderBtn.classList.add('added');
+      this._els.orderBtnText.textContent = 'Added \u2713';
+      this._els.announcer.textContent = `Added ${this._selectedSize} ${this.name} ($${this.currentPrice.toFixed(2)}) to your order.`;
+
+      if (this._feedbackTimer) clearTimeout(this._feedbackTimer);
+      this._feedbackTimer = setTimeout(() => {
+        this._els.orderBtn.classList.remove('added');
+        this._els.orderBtnText.textContent = 'Add to Order';
+      }, 1500);
+    });
+  }
+
+  _dispatchSizeChange() {
+    this.dispatchEvent(
+      new CustomEvent('coffee-size-change', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          name: this.name,
+          size: this._selectedSize,
+          price: Number(this.currentPrice.toFixed(2)),
+          calories: this.currentCalories,
+        },
+      })
+    );
+  }
+
+  _updateFavoriteState() {
+    this._els.favoriteBtn.setAttribute('aria-pressed', String(this._favorited));
+    this._els.favoriteBtn.setAttribute(
+      'aria-label',
+      this._favorited ? `Remove ${this.name} from favorites` : `Save ${this.name} to favorites`
+    );
+  }
+
+  _updateSizeSelection() {
+    this._els.sizeBtns.forEach((btn) => {
+      const isSelected = btn.dataset.size === this._selectedSize;
+      btn.setAttribute('aria-checked', String(isSelected));
+      btn.setAttribute('tabindex', isSelected ? '0' : '-1');
+    });
+    this._els.priceTag.textContent = `$${this.currentPrice.toFixed(2)}`;
+    this._els.caloriesBadge.textContent = `${this.currentCalories} cal`;
+  }
+
+  _render() {
+    const title = this.name;
+    const desc = this.description;
+    const image = this.getAttribute('image') || DEFAULT_FALLBACK_IMAGE;
+    const imageAlt = this.getAttribute('image-alt') || `${title} served in an artisan ceramic cup`;
+    const badgeText = this.getAttribute('badge') || '';
+    const roast = this.getAttribute('roast') || 'Artisan Roast';
+    const rating = this.getAttribute('rating') || '4.9';
+    const href = this.getAttribute('href') || '/menu';
+    const origin = this.getAttribute('origin') || 'Single-Origin Micro-Lot';
+    const caffeine = this.getAttribute('caffeine') || '150mg';
+    const dietary = this.getAttribute('dietary') || 'Crafted Fresh';
+    const notesRaw = this.getAttribute('tasting-notes') || 'Caramel, Toasted Nut, Smooth Finish';
+
+    this._els.card.setAttribute('aria-label', title);
+    this._els.title.textContent = title;
+    this._els.description.textContent = desc;
+    this._els.image.src = image;
+    this._els.image.alt = imageAlt;
+
+    // Sync slotted elements if dynamically updated via setAttribute
+    const slottedTitle = this.querySelector('[slot="title"]');
+    if (slottedTitle && this.hasAttribute('name')) {
+      slottedTitle.textContent = title;
+    }
+    const slottedDesc = this.querySelector('[slot="description"]');
+    if (slottedDesc && this.hasAttribute('description')) {
+      slottedDesc.textContent = desc;
+    }
+    const slottedCta = this.querySelector('[slot="cta"]');
+    if (slottedCta && this.hasAttribute('href')) {
+      slottedCta.setAttribute('href', href);
+    }
+
+    if (badgeText) {
+      this._els.badge.textContent = badgeText;
+      this._els.badge.hidden = false;
+    } else {
+      this._els.badge.hidden = true;
+    }
+
+    this._els.roastLabel.textContent = roast;
+    this._els.ratingPill.textContent = `\u2605 ${rating}`;
+    this._els.ratingPill.setAttribute('aria-label', `Rated ${rating} out of 5 stars`);
+
+    this._els.originValue.textContent = origin;
+    this._els.caffeineValue.textContent = caffeine;
+    this._els.dietaryValue.textContent = dietary;
+
+    // Render tasting note chips
+    this._els.notesList.innerHTML = '';
+    notesRaw
+      .split(',')
+      .map((s) => s.trim())
+      .filter(Boolean)
+      .forEach((note) => {
+        const chip = document.createElement('span');
+        chip.className = 'note-chip';
+        chip.textContent = note;
+        this._els.notesList.appendChild(chip);
+      });
+
+    this._els.detailsLink.href = href;
+    this._els.detailsLink.setAttribute('aria-label', `View details for ${title}`);
+
+    this._updateFavoriteState();
+    this._updateSizeSelection();
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
