+    if (name === 'heading') {
+      this._els.heading.textContent = newVal;
+    } else if (name === 'subtitle') {
+      this._els.subtitle.textContent = newVal;
+    } else if (name === 'active-category') {
+      this._activeCategory = newVal || 'all';
+      this._applyFilters();
+    }
+  }
+
+  _getCards() {
+    return Array.from(this.querySelectorAll('coffee-card'));
+  }
+
+  _bindEvents() {
+    if (this._eventsBound) return;
+    this._eventsBound = true;
+
+    this._els.slot.addEventListener('slotchange', () => {
+      this._applyFilters();
+    });
+
+    this._els.filterBtns.forEach((btn, idx) => {
+      btn.addEventListener('click', () => {
+        this._activeCategory = btn.dataset.category;
+        this._applyFilters();
+      });
+
+      btn.addEventListener('keydown', (e) => {
+        let targetIdx = -1;
+        if (e.key === 'ArrowRight') {
+          targetIdx = (idx + 1) % this._els.filterBtns.length;
+        } else if (e.key === 'ArrowLeft') {
+          targetIdx = (idx - 1 + this._els.filterBtns.length) % this._els.filterBtns.length;
+        }
+        if (targetIdx !== -1) {
+          e.preventDefault();
+          this._els.filterBtns[targetIdx].focus();
+          this._els.filterBtns[targetIdx].click();
+        }
+      });
+    });
+
+    this._els.searchInput.addEventListener('input', (e) => {
+      this._searchQuery = e.target.value.trim().toLowerCase();
+      this._applyFilters();
+    });
+
+    this._els.dietaryToggle.addEventListener('click', () => {
+      this._plantBasedOnly = !this._plantBasedOnly;
+      this._els.dietaryToggle.setAttribute('aria-pressed', String(this._plantBasedOnly));
+      this._applyFilters();
+    });
+
+    this._els.sortSelect.addEventListener('change', (e) => {
+      this._sortBy = e.target.value;
+      this._applyFilters();
+    });
+
+    this._els.resetBtn.addEventListener('click', () => {
+      this._activeCategory = 'all';
+      this._searchQuery = '';
+      this._plantBasedOnly = false;
+      this._sortBy = 'featured';
+      this._els.searchInput.value = '';
+      this._els.dietaryToggle.setAttribute('aria-pressed', 'false');
+      this._els.sortSelect.value = 'featured';
+      this._applyFilters();
+    });
+  }
+
+  _applyFilters() {
+    this._els.filterBtns.forEach((btn) => {
+      const active = btn.dataset.category === this._activeCategory;
+      btn.setAttribute('aria-pressed', String(active));
+    });
+
+    const cards = this._getCards();
+    let visibleCount = 0;
+
+    // Sort order computation
+    const sorted = [...cards].sort((a, b) => {
+      if (this._sortBy === 'price-asc') {
+        return a.basePrice - b.basePrice;
+      }
+      if (this._sortBy === 'price-desc') {
+        return b.basePrice - a.basePrice;
+      }
+      if (this._sortBy === 'rating-desc') {
+        const rA = parseFloat(a.getAttribute('rating') || '4.8');
+        const rB = parseFloat(b.getAttribute('rating') || '4.8');
+        return rB - rA;
+      }
+      return 0;
+    });
+
+    sorted.forEach((card, orderIndex) => {
+      card.style.order = String(orderIndex);
+
+      const category = (card.getAttribute('category') || '').toLowerCase();
+      const title = (card.getAttribute('name') || card.textContent || '').toLowerCase();
+      const desc = (card.getAttribute('description') || '').toLowerCase();
+      const notes = (card.getAttribute('tasting-notes') || '').toLowerCase();
+      const roast = (card.getAttribute('roast') || '').toLowerCase();
+      const dietary = (card.getAttribute('dietary') || '').toLowerCase();
+
+      const matchesCategory =
+        this._activeCategory === 'all' || category === this._activeCategory;
+      const matchesQuery =
+        !this._searchQuery ||
+        title.includes(this._searchQuery) ||
+        desc.includes(this._searchQuery) ||
+        notes.includes(this._searchQuery) ||
+        roast.includes(this._searchQuery);
+      const matchesDietary =
+        !this._plantBasedOnly ||
+        dietary.includes('vegan') ||
+        dietary.includes('plant') ||
+        dietary.includes('oat') ||
+        dietary.includes('dairy-free');
+
+      const isVisible = matchesCategory && matchesQuery && matchesDietary;
+      card.hidden = !isVisible;
+      if (isVisible) {
+        card.removeAttribute('aria-hidden');
+        visibleCount++;
+      } else {
+        card.setAttribute('aria-hidden', 'true');
+      }
+    });
+
+    this._els.emptyState.hidden = visibleCount > 0;
+    this._els.resultsCount.textContent = `Showing ${visibleCount} of ${cards.length} artisan coffees`;
+
+    this.dispatchEvent(
+      new CustomEvent('coffee-filter-change', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          category: this._activeCategory,
+          query: this._searchQuery,
+          plantBasedOnly: this._plantBasedOnly,
+          sortBy: this._sortBy,
+          visibleCount,
+          totalCount: cards.length,
+        },
+      })
+    );
+  }
+}
+
+if (!customElements.get('coffee-menu')) {
+  customElements.define('coffee-menu', CoffeeMenu);
+}
