+export class OrderDrawer extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(ORDER_DRAWER_TEMPLATE.content.cloneNode(true));
+
+    this._items = [];
+    this._open = false;
+
+    this._els = {
+      trigger: this.shadowRoot.querySelector('.floating-trigger'),
+      countBadge: this.shadowRoot.querySelector('.count-badge'),
+      backdrop: this.shadowRoot.querySelector('.backdrop'),
+      closeBtn: this.shadowRoot.querySelector('.close-btn'),
+      body: this.shadowRoot.querySelector('.drawer-body'),
+      rewardsPoints: this.shadowRoot.querySelector('.rewards-points'),
+      totalPrice: this.shadowRoot.querySelector('.total-price'),
+    };
+
+    this._onExternalOrder = this._onExternalOrder.bind(this);
+    this._onKeyDown = this._onKeyDown.bind(this);
+  }
+
+  connectedCallback() {
+    window.addEventListener('coffee-order', this._onExternalOrder);
+    window.addEventListener('keydown', this._onKeyDown);
+
+    this._els.trigger.addEventListener('click', () => this.open());
+    this._els.closeBtn.addEventListener('click', () => this.close());
+    this._els.backdrop.addEventListener('click', (e) => {
+      if (e.target === this._els.backdrop) {
+        this.close();
+      }
+    });
+
+    this._render();
+  }
+
+  disconnectedCallback() {
+    window.removeEventListener('coffee-order', this._onExternalOrder);
+    window.removeEventListener('keydown', this._onKeyDown);
+  }
+
+  open() {
+    this._open = true;
+    this._els.backdrop.hidden = false;
+    this._els.trigger.setAttribute('aria-expanded', 'true');
+    this._els.closeBtn.focus();
+  }
+
+  close() {
+    if (!this._open) return;
+    this._open = false;
+    this._els.backdrop.hidden = true;
+    this._els.trigger.setAttribute('aria-expanded', 'false');
+    this._els.trigger.focus();
+  }
+
+  get items() {
+    return [...this._items];
+  }
+
+  get totalQuantity() {
+    return this._items.reduce((sum, item) => sum + item.quantity, 0);
+  }
+
+  _onKeyDown(e) {
+    if (e.key === 'Escape' && this._open) {
+      this.close();
+    }
+  }
+
+  _onExternalOrder(e) {
+    const detail = e.detail;
+    if (!detail || !detail.name) return;
+
+    const existing = this._items.find(
+      (i) => i.name === detail.name && i.size === (detail.size || 'M')
+    );
+
+    if (existing) {
+      existing.quantity += detail.quantity || 1;
+    } else {
+      this._items.push({
+        id: detail.id || `${detail.name}-${detail.size || 'M'}`,
+        name: detail.name,
+        size: detail.size || 'M',
+        price: Number(detail.price) || 4.75,
+        quantity: detail.quantity || 1,
+      });
+    }
+
+    this._render();
+    this.dispatchEvent(
+      new CustomEvent('order-updated', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          items: this.items,
+          totalQuantity: this.totalQuantity,
+        },
+      })
+    );
+  }
+
+  _adjustQuantity(index, delta) {
+    const item = this._items[index];
+    if (!item) return;
+    item.quantity += delta;
+    if (item.quantity <= 0) {
+      this._items.splice(index, 1);
+    }
+    this._render();
+    this.dispatchEvent(
+      new CustomEvent('order-updated', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          items: this.items,
+          totalQuantity: this.totalQuantity,
+        },
+      })
+    );
+  }
+
+  _render() {
+    const totalQty = this.totalQuantity;
+    const totalCost = this._items.reduce((sum, i) => sum + i.price * i.quantity, 0);
+    const points = Math.round(totalCost * 10);
+
+    this._els.countBadge.textContent = String(totalQty);
+    this._els.trigger.setAttribute(
+      'aria-label',
+      `Open coffee order bag (${totalQty} ${totalQty === 1 ? 'item' : 'items'})`
+    );
+    this._els.totalPrice.textContent = `$${totalCost.toFixed(2)}`;
+    this._els.rewardsPoints.textContent = `${points} Beans`;
+
+    this._els.body.innerHTML = '';
+    if (this._items.length === 0) {
+      const empty = document.createElement('p');
+      empty.className = 'empty-msg';
+      empty.textContent = 'Your coffee bag is empty. Add a seasonal favorite or custom brew above!';
+      this._els.body.appendChild(empty);
+      return;
+    }
+
+    this._items.forEach((item, idx) => {
+      const row = document.createElement('div');
+      row.className = 'order-item';
+
+      const info = document.createElement('div');
+      info.className = 'item-info';
+
+      const h4 = document.createElement('h4');
+      h4.textContent = `${item.name} (${item.size})`;
+
+      const meta = document.createElement('span');
+      meta.className = 'item-meta';
+      meta.textContent = `$${(item.price * item.quantity).toFixed(2)} ($${item.price.toFixed(2)} each)`;
+
+      info.appendChild(h4);
+      info.appendChild(meta);
+
+      const controls = document.createElement('div');
+      controls.className = 'qty-controls';
+
+      const decBtn = document.createElement('button');
+      decBtn.type = 'button';
+      decBtn.className = 'qty-btn';
+      decBtn.textContent = '-';
+      decBtn.setAttribute('aria-label', `Decrease quantity of ${item.name}`);
+      decBtn.addEventListener('click', () => this._adjustQuantity(idx, -1));
+
+      const qtySpan = document.createElement('span');
+      qtySpan.textContent = String(item.quantity);
+
+      const incBtn = document.createElement('button');
+      incBtn.type = 'button';
+      incBtn.className = 'qty-btn';
+      incBtn.textContent = '+';
+      incBtn.setAttribute('aria-label', `Increase quantity of ${item.name}`);
+      incBtn.addEventListener('click', () => this._adjustQuantity(idx, 1));
+
+      controls.appendChild(decBtn);
+      controls.appendChild(qtySpan);
+      controls.appendChild(incBtn);
+
+      row.appendChild(info);
+      row.appendChild(controls);
+      this._els.body.appendChild(row);
+    });
+  }
+}
+
+if (!customElements.get('order-drawer')) {
+  customElements.define('order-drawer', OrderDrawer);
+}
