+export class RoastTabs extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(ROAST_TABS_TEMPLATE.content.cloneNode(true));
+
+    this._tabs = Array.from(this.shadowRoot.querySelectorAll('[role="tab"]'));
+    this._panels = Array.from(this.shadowRoot.querySelectorAll('[role="tabpanel"]'));
+
+    this._calcEls = {
+      methodSelect: this.shadowRoot.querySelector('#brew-method-select'),
+      cupsRange: this.shadowRoot.querySelector('#cups-range'),
+      cupsDisplay: this.shadowRoot.querySelector('.cups-display'),
+      coffeeGrams: this.shadowRoot.querySelector('.coffee-grams'),
+      waterMl: this.shadowRoot.querySelector('.water-ml'),
+      brewTemp: this.shadowRoot.querySelector('.brew-temp'),
+    };
+  }
+
+  connectedCallback() {
+    this._bindEvents();
+    this._updateCalculator();
+  }
+
+  _bindEvents() {
+    if (this._eventsBound) return;
+    this._eventsBound = true;
+
+    this._tabs.forEach((tab, idx) => {
+      tab.addEventListener('click', () => {
+        this._activateTab(idx, false);
+      });
+
+      tab.addEventListener('keydown', (e) => {
+        let nextIdx = -1;
+        if (e.key === 'ArrowRight') {
+          nextIdx = (idx + 1) % this._tabs.length;
+        } else if (e.key === 'ArrowLeft') {
+          nextIdx = (idx - 1 + this._tabs.length) % this._tabs.length;
+        } else if (e.key === 'Home') {
+          nextIdx = 0;
+        } else if (e.key === 'End') {
+          nextIdx = this._tabs.length - 1;
+        }
+
+        if (nextIdx !== -1) {
+          e.preventDefault();
+          this._activateTab(nextIdx, true);
+        }
+      });
+    });
+
+    this._calcEls.methodSelect.addEventListener('change', () => this._updateCalculator());
+    this._calcEls.cupsRange.addEventListener('input', () => this._updateCalculator());
+  }
+
+  _activateTab(activeIndex, focusTab = true) {
+    this._tabs.forEach((tab, i) => {
+      const selected = i === activeIndex;
+      tab.setAttribute('aria-selected', String(selected));
+      tab.setAttribute('tabindex', selected ? '0' : '-1');
+      if (selected && focusTab) {
+        tab.focus();
+      }
+    });
+
+    this._panels.forEach((panel, i) => {
+      panel.hidden = i !== activeIndex;
+    });
+
+    this.dispatchEvent(
+      new CustomEvent('roast-tab-change', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          index: activeIndex,
+          tabId: this._tabs[activeIndex].id,
+        },
+      })
+    );
+  }
+
+  _updateCalculator() {
+    const ratio = parseInt(this._calcEls.methodSelect.value, 10) || 16;
+    const cups = parseInt(this._calcEls.cupsRange.value, 10) || 2;
+    const waterPerCupMl = 240;
+    const totalWater = cups * waterPerCupMl;
+    const totalGrams = Math.round(totalWater / ratio);
+
+    this._calcEls.cupsDisplay.textContent = String(cups);
+    this._calcEls.coffeeGrams.textContent = `${totalGrams}g`;
+    this._calcEls.waterMl.textContent = `${totalWater}ml`;
+    this._calcEls.brewTemp.textContent = ratio === 8 ? 'Room / Cold' : '200\u00B0F';
+  }
+}
+
+if (!customElements.get('roast-tabs')) {
+  customElements.define('roast-tabs', RoastTabs);
+}
