+          priceSpan.textContent = `$${entry.lineTotal.toFixed(2)}`;
+
+          const removeBtn = document.createElement('button');
+          removeBtn.type = 'button';
+          removeBtn.className = 'remove-btn';
+          removeBtn.textContent = 'Remove';
+          removeBtn.addEventListener('click', () => {
+            orderState.items.splice(index, 1);
+            renderOrderSummary(`Removed ${entry.item} from your order.`);
+          });
+
+          actionsDiv.appendChild(priceSpan);
+          actionsDiv.appendChild(removeBtn);
+
+          li.appendChild(infoDiv);
+          li.appendChild(actionsDiv);
+          listEl.appendChild(li);
+        });
+      }
+
+      function syncFormFields(form, params) {
+        if (!form || !params) return;
+        if (params.size && form.elements['size']) {
+          const normalized = normalizeSize(params.size);
+          form.elements['size'].value = normalized;
+        }
+        if (params.milk && form.elements['milk']) {
+          const milkSelect = form.elements['milk'];
+          const match = Array.from(milkSelect.options).find(
+            opt => opt.value.toLowerCase() === String(params.milk).trim().toLowerCase()
+          );
+          if (match) {
+            milkSelect.value = match.value;
+          }
+        }
+        const tempOrIce = params.temperature || params.ice || params.iceLevel;
+        if (tempOrIce && form.elements['temperature']) {
+          const tempSelect = form.elements['temperature'];
+          const match = Array.from(tempSelect.options).find(
+            opt => opt.value.toLowerCase() === String(tempOrIce).trim().toLowerCase()
+          );
+          if (match) {
+            tempSelect.value = match.value;
+          }
+        }
+        if (params.quantity !== undefined && form.elements['quantity']) {
+          form.elements['quantity'].value = Math.max(1, Math.min(10, parseInt(params.quantity, 10) || 1));
+        }
+        if (params.notes !== undefined && form.elements['notes']) {
+          form.elements['notes'].value = String(params.notes);
+        }
+        updateFormButtonPrice(form);
+      }
+
+      function addOrderItem(itemKey, rawParams = {}) {
+        const config = MENU_CATALOG[itemKey];
+        if (!config) {
+          throw new Error(`Unknown seasonal item: ${itemKey}`);
+        }
+
+        const form = document.getElementById(config.formId);
+        if (form) {
+          syncFormFields(form, rawParams);
+        }
+
+        const size = normalizeSize(rawParams.size || (form && form.elements['size']?.value) || config.defaultSize);
+        const milk = String(rawParams.milk || (form && form.elements['milk']?.value) || config.defaultMilk).trim();
+        const temperature = String(
+          rawParams.temperature || rawParams.ice || (form && form.elements['temperature']?.value) || config.defaultTemperature
+        ).trim();
+        const quantity = Math.max(
+          1,
+          Math.min(10, parseInt(rawParams.quantity ?? (form && form.elements['quantity']?.value) ?? 1, 10) || 1)
+        );
+        const notes = String(rawParams.notes ?? (form && form.elements['notes']?.value) ?? '').trim();
+
+        const unitPrice = calculateUnitPrice(config.basePrice, size);
+        const lineTotal = Number((unitPrice * quantity).toFixed(2));
+        const orderItem = {
+          orderItemId: `ORD-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random() * 900 + 100)}`,
+          itemId: config.id,
+          item: config.name,
+          size,
+          milk,
+          temperature,
+          quantity,
+          notes,
+          unitPrice,
+          lineTotal,
+          timestamp: new Date().toISOString()
+        };
+
+        orderState.items.push(orderItem);
+
+        const message = `Added ${quantity}x ${size} ${config.name} (${milk}, ${temperature}${notes ? ', "' + notes + '"' : ''}) — $${lineTotal.toFixed(2)}. Order total: $${getOrderTotal().toFixed(2)}.`;
+        orderState.lastOrderConfirmation = {
+          success: true,
+          status: 'added_to_order',
+          message,
+          addedItem: orderItem,
+          totalItems: getTotalItemCount(),
+          orderTotal: getOrderTotal(),
+          content: [{ type: 'text', text: message }]
+        };
+
+        if (form) {
+          const feedbackEl = form.querySelector('.card-feedback');
+          if (feedbackEl) {
+            feedbackEl.textContent = `✓ Added ${quantity}x ${size} ${config.name} ($${lineTotal.toFixed(2)})`;
+            feedbackEl.classList.add('visible');
+          }
+        }
+
+        renderOrderSummary(message);
+        return orderState.lastOrderConfirmation;
+      }
+
+      // Wire up interactive forms for human users & declarative WebMCP agents
+      document.querySelectorAll('.order-form').forEach((form) => {
+        updateFormButtonPrice(form);
+
+        form.addEventListener('change', () => updateFormButtonPrice(form));
+        form.addEventListener('input', () => updateFormButtonPrice(form));
+
+        form.addEventListener('submit', (event) => {
+          event.preventDefault();
+          const itemId = form.dataset.itemId;
+          const formData = new FormData(form);
+          const result = addOrderItem(itemId, {
+            size: formData.get('size'),
+            milk: formData.get('milk'),
+            temperature: formData.get('temperature'),
+            quantity: formData.get('quantity'),
+            notes: formData.get('notes')
+          });
+
+          if (typeof event.respondWith === 'function') {
+            event.respondWith(Promise.resolve(result));
+          }
+        });
+      });
+
+      // Clear & Checkout buttons
+      const clearBtn = document.getElementById('clear-order-btn');
+      if (clearBtn) {
+        clearBtn.addEventListener('click', () => {
+          orderState.items = [];
+          renderOrderSummary('Your order has been cleared.');
+        });
+      }
+
+      const checkoutBtn = document.getElementById('checkout-order-btn');
+      if (checkoutBtn) {
+        checkoutBtn.addEventListener('click', () => {
+          if (orderState.items.length === 0) {
+            renderOrderSummary('Please add at least one seasonal coffee before completing your order.');
+            return;
+          }
+          const confirmationId = `DG-${Math.floor(100000 + Math.random() * 900000)}`;
+          const total = getOrderTotal().toFixed(2);
+          const count = getTotalItemCount();
+          orderState.items = [];
+          renderOrderSummary(`Order #${confirmationId} confirmed! Preparing ${count} drink(s) — Total paid: $${total}.`);
+        });
+      }
+
+      // Define client-side AI agent tools (WebMCP Imperative API + fallback discovery shim)
+      const seasonalTools = [
+        {
+          name: 'order_maple_oat_latte',
+          description: 'Order a Maple Oat Latte from the Seasonal Favorites menu with customizable size, milk option, temperature, quantity, and special instructions.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              size: {
+                type: 'string',
+                enum: ['Small', 'Medium', 'Large'],
+                default: 'Medium',
+                description: 'Cup size: Small (12oz), Medium (16oz, +$0.75), or Large (20oz, +$1.25)'
+              },
+              milk: {
+                type: 'string',
+                enum: ['Oat Milk', 'Whole Milk', 'Almond Milk', 'Coconut Milk'],
+                default: 'Oat Milk',
+                description: 'Milk option for the Maple Oat Latte'
+              },
+              temperature: {
+                type: 'string',
+                enum: ['Hot', 'Iced'],
+                default: 'Hot',
+                description: 'Whether the drink should be served Hot or Iced'
+              },
+              quantity: {
+                type: 'integer',
+                minimum: 1,
+                maximum: 10,
+                default: 1,
+                description: 'Number of Maple Oat Lattes to order (1-10)'
+              },
+              notes: {
+                type: 'string',
+                description: 'Optional special instructions or customizations'
+              }
+            }
+          },
+          execute: async (params = {}) => addOrderItem('maple-oat-latte', params)
+        },
+        {
+          name: 'order_dark_roast_espresso',
+          description: 'Order a Dark Roast Espresso from the Seasonal Favorites menu with customizable shot size, milk splash, temperature, quantity, and special instructions.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              size: {
+                type: 'string',
+                enum: ['Small', 'Medium', 'Large'],
+                default: 'Medium',
+                description: 'Shot size: Small (Single Shot), Medium (Double Shot, +$0.75), or Large (Triple Shot, +$1.25)'
+              },
+              milk: {
+                type: 'string',
+                enum: ['None', 'Oat Milk', 'Whole Milk', 'Almond Milk'],
+                default: 'None',
+                description: 'Optional splash of milk or None (Black)'
+              },
+              temperature: {
+                type: 'string',
+                enum: ['Hot', 'Iced'],
+                default: 'Hot',
+                description: 'Whether the espresso should be served Hot or Iced'
+              },
+              quantity: {
+                type: 'integer',
+                minimum: 1,
+                maximum: 10,
+                default: 1,
+                description: 'Number of Dark Roast Espressos to order (1-10)'
+              },
+              notes: {
+                type: 'string',
+                description: 'Optional special instructions or customizations'
+              }
+            }
+          },
+          execute: async (params = {}) => addOrderItem('dark-roast-espresso', params)
+        },
+        {
+          name: 'order_cold_brew',
+          description: 'Order a 18-hour steeped Cold Brew from the Seasonal Favorites menu with customizable size, milk/cream option, ice level, quantity, and special instructions.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              size: {
+                type: 'string',
+                enum: ['Small', 'Medium', 'Large'],
+                default: 'Medium',
+                description: 'Cup size: Small (12oz), Medium (16oz, +$0.75), or Large (20oz, +$1.25)'
+              },
+              milk: {
+                type: 'string',
+                enum: ['None', 'Sweet Cream Cold Foam', 'Oat Milk', 'Whole Milk', 'Almond Milk'],
+                default: 'None',
+                description: 'Milk or cream topping option for the Cold Brew'
+              },
+              temperature: {
+                type: 'string',
+                enum: ['Regular Ice', 'Light Ice', 'Extra Ice', 'No Ice'],
+                default: 'Regular Ice',
+                description: 'Ice preference for the Cold Brew'
+              },
+              quantity: {
+                type: 'integer',
+                minimum: 1,
+                maximum: 10,
+                default: 1,
+                description: 'Number of Cold Brews to order (1-10)'
+              },
+              notes: {
+                type: 'string',
+                description: 'Optional special instructions or customizations'
+              }
+            }
+          },
+          execute: async (params = {}) => addOrderItem('cold-brew', params)
+        },
+        {
+          name: 'order_seasonal_coffee',
+          description: 'Place an order for any Seasonal Favorites coffee (Maple Oat Latte, Dark Roast Espresso, or Cold Brew) with size, milk, temperature/ice, quantity, and special instructions.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              drink: {
+                type: 'string',
+                enum: ['Maple Oat Latte', 'Dark Roast Espresso', 'Cold Brew'],
+                description: 'Name of the seasonal drink to order'
+              },
+              size: {
+                type: 'string',
+                enum: ['Small', 'Medium', 'Large'],
+                default: 'Medium',
+                description: 'Cup or shot size'
+              },
+              milk: {
+                type: 'string',
+                description: 'Milk or cream preference'
+              },
+              temperature: {
+                type: 'string',
+                description: 'Temperature or ice level preference'
+              },
+              quantity: {
+                type: 'integer',
+                minimum: 1,
+                maximum: 10,
+                default: 1,
+                description: 'Number of drinks to order'
+              },
+              notes: {
+                type: 'string',
+                description: 'Special instructions'
+              }
+            },
+            required: ['drink']
+          },
+          execute: async (params = {}) => {
+            const rawDrink = String(params.drink || params.item || '').toLowerCase();
+            let key = 'maple-oat-latte';
+            if (rawDrink.includes('espresso') || rawDrink.includes('dark')) {
+              key = 'dark-roast-espresso';
+            } else if (rawDrink.includes('cold') || rawDrink.includes('brew')) {
+              key = 'cold-brew';
+            }
+            return addOrderItem(key, params);
+          }
+        },
+        {
+          name: 'get_seasonal_order_summary',
+          description: 'Retrieve the current coffee order items, quantities, and total price.',
+          inputSchema: {
+            type: 'object',
+            properties: {}
+          },
+          execute: async () => {
+            const summaryText = orderState.items.length
+              ? `Order contains ${getTotalItemCount()} item(s), total $${getOrderTotal().toFixed(2)}.`
+              : 'Your coffee order is currently empty.';
+            return {
+              success: true,
+              items: orderState.items.slice(),
+              totalItems: getTotalItemCount(),
+              orderTotal: getOrderTotal(),
+              content: [{ type: 'text', text: summaryText }]
+            };
+          }
+        }
+      ];
+
+      function registerAgentTools() {
+        const registryMap = new Map();
+        seasonalTools.forEach((t) => registryMap.set(t.name, t));
+
+        if (!('modelContext' in navigator) || !navigator.modelContext) {
+          const fallbackContext = {
+            tools: seasonalTools,
+            registerTool(toolDef) {
+              if (toolDef && toolDef.name) {
+                registryMap.set(toolDef.name, toolDef);
+                fallbackContext.tools = Array.from(registryMap.values());
+              }
+            },
+            provideContext(ctx) {
+              const list = Array.isArray(ctx) ? ctx : (ctx && Array.isArray(ctx.tools) ? ctx.tools : []);
+              list.forEach((toolDef) => {
+                if (toolDef && toolDef.name) {
+                  registryMap.set(toolDef.name, toolDef);
+                }
+              });
+              fallbackContext.tools = Array.from(registryMap.values());
+            },
+            unregisterTool(name) {
+              registryMap.delete(name);
+              fallbackContext.tools = Array.from(registryMap.values());
+            },
+            clearContext() {
+              registryMap.clear();
+              fallbackContext.tools = [];
+            },
+            getTools() {
+              return Array.from(registryMap.values());
+            },
+            async callTool(name, args) {
+              const tool = registryMap.get(name);
+              if (!tool || typeof tool.execute !== 'function') {
+                throw new Error(`Tool not found: ${name}`);
+              }
+              return await tool.execute(args || {});
+            }
+          };
+          try {
+            Object.defineProperty(navigator, 'modelContext', {
+              value: fallbackContext,
+              configurable: true,
+              writable: true
+            });
+          } catch (_) {
+            window.modelContext = fallbackContext;
+          }
+          return;
+        }
+
+        const mc = navigator.modelContext;
+        if (typeof mc.registerTool === 'function') {
+          seasonalTools.forEach((toolDef) => {
+            try {
+              mc.registerTool(toolDef);
+            } catch (_) {
+              // If already registered declaratively by the browser via <form toolname="...">, ignore duplicate error
+            }
+          });
+        } else if (typeof mc.provideContext === 'function') {
+          try {
+            mc.provideContext({ tools: seasonalTools });
+          } catch (_) {
+            // Ignore errors in unsupported contexts
+          }
+        }
+      }
+
+      registerAgentTools();
+    })();
+  </script>
